# -*- coding: utf-8 -*-
"""
Pool module for General Studies: Indian Polity & Constitution (Q111 to Q120).
10 authentic, unique bilingual questions per paper across 48 papers (480 total unique questions).
"""

def make_question(q_id, sec_en, sec_hi, u_en, u_hi, q_en, q_hi, c_en, c_hi, w_en, w_hi, exp_en, exp_hi, ans_idx):
    opts_en = list(w_en)
    opts_hi = list(w_hi)
    opts_en.insert(ans_idx, c_en)
    opts_hi.insert(ans_idx, c_hi)
    ans_letter = chr(ord("A") + ans_idx)
    return {
        "id": q_id,
        "section_en": sec_en,
        "section_hi": sec_hi,
        "unit_en": u_en,
        "unit_hi": u_hi,
        "q_en": q_en,
        "q_hi": q_hi,
        "options_en": opts_en,
        "options_hi": opts_hi,
        "answer": ans_letter,
        "exp_en": exp_en,
        "exp_hi": exp_hi
    }

SEC_EN = "Part 2: General Knowledge & General Studies"
SEC_HI = "भाग 2: सामान्य ज्ञान एवं सामान्य अध्ययन"
U_EN = "Indian Polity & Constitution"
U_HI = "भारतीय राजव्यवस्था एवं संविधान"

slot_q111_ca = [('The Constituent Assembly of India was constituted under the framework recommended by', 'भारत की संविधान सभा का गठन किस योजना के प्रस्तावों के आधार पर किया गया था?', 'Cabinet Mission Plan of 1946', 'कैबिनेट मिशन योजना (1946)', ['Cripps Mission 1942', 'Wavell Plan 1945', 'Mountbatten Plan 1947'], ['क्रिप्स मिशन (1942)', 'वेवेल योजना (1945)', 'माउंटबेटन योजना (1947)'], 'The Cabinet Mission arrived in India in March 1946 and proposed a Constituent Assembly of 389 members.', 'मार्च 1946 में भारत आए कैबिनेट मिशन के प्रस्तावों के तहत संविधान सभा का गठन किया गया था।'), ('The historic first inaugural meeting of the Constituent Assembly of India took place on', 'संविधान सभा की ऐतिहासिक प्रथम बैठक किस तिथि को आयोजित की गई थी?', '9 December 1946', '9 दिसंबर 1946', ['11 December 1946', '13 December 1946', '26 November 1949'], ['11 दिसंबर 1946', '13 दिसंबर 1946', '26 नवंबर 1949'], 'The first meeting was held in Constitution Hall (now Central Hall of Parliament House), New Delhi, attended by 211 members.', 'संविधान सभा की पहली बैठक 9 दिसंबर 1946 को नई दिल्ली में काउंसिल चैंबर के पुस्तकालय भवन में हुई थी।'), ('Who was elected as the temporary interim President of the Constituent Assembly on 9 December 1946?', '9 दिसंबर 1946 को संविधान सभा के अस्थायी अंतरिम अध्यक्ष कौन चुने गए थे?', 'Dr. Sachchidananda Sinha', 'डॉ. सच्चिदानंद सिन्हा', ['Dr. Rajendra Prasad', 'Dr. B.R. Ambedkar', 'H.C. Mukherjee'], ['डॉ. राजेंद्र प्रसाद', 'डॉ. बी.आर. आंबेडकर', 'एच.सी. मुखर्जी'], 'Following French practice, Dr. Sachchidananda Sinha, the oldest member, was elected temporary Chairman.', 'फ्रांसीसी परंपरा का अनुसरण करते हुए सभा के सबसे वरिष्ठ सदस्य डॉ. सच्चिदानंद सिन्हा को अस्थायी अध्यक्ष चुना गया।'), ('Who was elected as the permanent President of the Constituent Assembly on 11 December 1946?', '11 दिसंबर 1946 को संविधान सभा के स्थायी अध्यक्ष के रूप में किन्हें चुना गया था?', 'Dr. Rajendra Prasad', 'डॉ. राजेंद्र प्रसाद', ['Dr. Sachchidananda Sinha', 'Jawaharlal Nehru', 'Dr. B.R. Ambedkar'], ['डॉ. सच्चिदानंद सिन्हा', 'पंडित जवाहरलाल नेहरू', 'डॉ. बी.आर. आंबेडकर'], 'Dr. Rajendra Prasad was unanimously elected permanent President and guided deliberations until final adoption.', '11 दिसंबर 1946 को डॉ. राजेंद्र प्रसाद संविधान सभा के स्थायी अध्यक्ष सर्वसम्मति से निर्वाचित हुए।'), ('Who was appointed as the Constitutional Advisor to the Constituent Assembly of India?', 'भारतीय संविधान सभा के संवैधानिक सलाहकार (Constitutional Advisor) कौन नियुक्त हुए थे?', 'Sir Benegal Narsing Rau (B.N. Rau)', 'सर बी.एन. राव (Sir B.N. Rau)', ['K.M. Munshi', 'Alladi Krishnaswamy Iyer', 'H.V.R. Iengar'], ['के.एम. मुंशी', 'अल्लादि कृष्णास्वामी अय्यर', 'एच.वी.आर. आयंगर'], 'Sir B.N. Rau prepared the original draft of the Constitution after studying global democratic constitutions.', 'अंतर्राष्ट्रीय न्यायालय के न्यायाधीश सर बी.एन. राव को संविधान सभा का संवैधानिक सलाहकार नियुक्त किया गया था।'), ("Who moved the historic 'Objectives Resolution' in the Constituent Assembly on 13 December 1946?", "संविधान सभा में 13 दिसंबर 1946 को ऐतिहासिक 'उद्देश्य प्रस्ताव' किसने प्रस्तुत किया था?", 'Pandit Jawaharlal Nehru', 'पंडित जवाहरलाल नेहरू', ['Dr. B.R. Ambedkar', 'Sardar Vallabhbhai Patel', 'Dr. Rajendra Prasad'], ['डॉ. बी.आर. आंबेडकर', 'सरदार वल्लभभाई पटेल', 'डॉ. राजेंद्र प्रसाद'], 'The Objectives Resolution outlined the constitutional philosophy and became the basis of the Preamble.', 'नेहरू द्वारा प्रस्तुत उद्देश्य प्रस्ताव ही आगे चलकर भारतीय संविधान की उद्देशिका (प्रस्तावना) का आधार बना।'), ('On which date was the Objectives Resolution unanimously adopted by the Constituent Assembly?', "संविधान सभा द्वारा 'उद्देश्य प्रस्ताव' को सर्वसम्मति से किस तिथि को स्वीकार किया गया था?", '22 January 1947', '22 जनवरी 1947', ['13 December 1946', '15 August 1947', '26 November 1949'], ['13 दिसंबर 1946', '15 अगस्त 1947', '26 नवंबर 1949'], "Unanimously adopted on 22 January 1947, setting guiding principles for independent India's Constitution.", '22 जनवरी 1947 को उद्देश्य प्रस्ताव को सभा द्वारा पूर्ण सर्वसम्मति से पारित किया गया था।'), ('The Drafting Committee of the Indian Constitution was officially appointed on which date?', 'भारतीय संविधान की प्रारूप समिति (Drafting Committee) का गठन किस तिथि को किया गया था?', '29 August 1947', '29 अगस्त 1947', ['15 August 1947', '26 November 1949', '9 December 1946'], ['15 अगस्त 1947', '26 नवंबर 1949', '9 दिसंबर 1946'], 'Set up on 29 August 1947 under the chairmanship of Dr. B.R. Ambedkar to scrutinize the draft Constitution.', 'आजादी के तुरंत बाद 29 अगस्त 1947 को डॉ. आंबेडकर की अध्यक्षता में प्रारूप समिति बनाई गई थी।'), ('Who was the Chairman of the Drafting Committee of the Constituent Assembly?', 'संविधान सभा की प्रारूप समिति (मसौदा समिति) के अध्यक्ष कौन थे?', 'Dr. B.R. Ambedkar', 'डॉ. बी.आर. आंबेडकर', ['Dr. Rajendra Prasad', 'Jawaharlal Nehru', 'Sardar Vallabhbhai Patel'], ['डॉ. राजेंद्र प्रसाद', 'पंडित जवाहरलाल नेहरू', 'सरदार वल्लभभाई पटेल'], "Dr. Ambedkar, acclaimed as the 'Father of the Indian Constitution', steered the drafting process.", 'डॉ. भीमराव आंबेडकर प्रारूप समिति के अध्यक्ष थे और उन्हें भारतीय संविधान का जनक माना जाता है।'), ('How many members comprised the Drafting Committee headed by Dr. B.R. Ambedkar?', 'डॉ. बी.आर. आंबेडकर की अध्यक्षता वाली प्रारूप समिति में कुल कितने सदस्य थे?', '7 Members', '7 सदस्य', ['5 Members', '9 Members', '11 Members'], ['5 सदस्य', '9 सदस्य', '11 सदस्य'], 'The 7 members: Dr. Ambedkar (Chairman), N. Gopalaswami Ayyangar, Alladi Krishnaswamy Iyer, Dr. K.M. Munshi, Syed Mohammad Saadulla, N. Madhava Rau, and T.T. Krishnamachari.', 'प्रारूप समिति में अध्यक्ष सहित कुल 7 सदस्य शामिल थे।'), ('Who replaced B.L. Mitter in the Drafting Committee after he resigned due to ill-health?', 'स्वास्थ्य कारणों से बी.एल. मित्तर के त्यागपत्र देने के बाद प्रारूप समिति में कौन शामिल हुए थे?', 'N. Madhava Rau', 'एन. माधव राव', ['T.T. Krishnamachari', 'Dr. K.M. Munshi', 'D.P. Khaitan'], ['टी.टी. कृष्णमाचारी', 'डॉ. के.एम. मुंशी', 'डी.पी. खेतान'], 'N. Madhava Rau replaced B.L. Mitter, and T.T. Krishnamachari replaced D.P. Khaitan upon his death in 1948.', 'बी.एल. मित्तर के अस्वस्थ होने पर एन. माधव राव को प्रारूप समिति का सदस्य बनाया गया।'), ('Who joined the Drafting Committee following the death of D.P. Khaitan in 1948?', '1948 में डी.पी. खेतान के निधन के पश्चात प्रारूप समिति में किन्हें स्थान दिया गया था?', 'T.T. Krishnamachari', 'टी.टी. कृष्णमाचारी', ['N. Madhava Rau', 'H.C. Mukherjee', 'V.T. Krishnamachari'], ['एन. माधव राव', 'एच.सी. मुखर्जी', 'वी.टी. कृष्णमाचारी'], "T.T. Krishnamachari was inducted into the Drafting Committee in 1948 following Khaitan's demise.", 'डी.पी. खेतान की मृत्यु के बाद टी.टी. कृष्णमाचारी को समिति में शामिल किया गया था।'), ('The total time taken by the Constituent Assembly to draft the Constitution of India was', 'भारतीय संविधान के निर्माण में संविधान सभा को कुल कितना समय लगा था?', '2 years, 11 months, and 18 days', '2 वर्ष, 11 माह एवं 18 दिन', ['3 years, 2 months, and 15 days', '1 year, 11 months, and 28 days', '2 years, 6 months, and 10 days'], ['3 वर्ष, 2 माह एवं 15 दिन', '1 वर्ष, 11 माह एवं 28 दिन', '2 वर्ष, 6 माह एवं 10 दिन'], 'The Assembly held 11 plenary sessions over a span of 2 years, 11 months, and 18 days (165 sitting days).', 'संविधान निर्माण में कुल 2 वर्ष, 11 महीने और 18 दिन का समय लगा था।'), ('How many plenary sessions were held by the Constituent Assembly to frame the Constitution?', 'संविधान निर्माण के लिए संविधान सभा के कुल कितने अधिवेशन (सत्र) आयोजित किए गए थे?', '11 Sessions', '11 अधिवेशन', ['7 Sessions', '15 Sessions', '9 Sessions'], ['7 अधिवेशन', '15 अधिवेशन', '9 अधिवेशन'], 'The Assembly met for 11 formal sessions between 9 December 1946 and 26 November 1949.', 'संविधान सभा के कुल 11 सत्र आयोजित किए गए थे (24 जनवरी 1950 को अंतिम बैठक सहित 12वीं बैठक हुई)।'), ('On which date was the Constitution of India formally adopted and enacted by the Constituent Assembly?', 'संविधान सभा द्वारा भारत के संविधान को किस तिथि को अंगीकृत, अधिनियमित और आत्मार्पित किया गया?', '26 November 1949', '26 नवंबर 1949', ['26 January 1950', '15 August 1947', '24 January 1950'], ['26 जनवरी 1950', '15 अगस्त 1947', '24 जनवरी 1950'], 'Adopted on 26 November 1949, celebrated nationwide as Constitution Day (Samvidhan Divas).', '26 नवंबर 1949 को संविधान को पूर्ण रूप से अंगीकृत किया गया, जिसे संविधान दिवस के रूप में मनाया जाता है।'), ('On which historic date did the Constitution of India fully come into legal effect?', 'भारत का संविधान पूर्ण रूप से किस ऐतिहासिक तिथि को लागू (प्रभावी) हुआ था?', '26 January 1950', '26 जनवरी 1950', ['26 November 1949', '15 August 1947', '30 January 1950'], ['26 नवंबर 1949', '15 अगस्त 1947', '30 जनवरी 1950'], 'Commemorates the Declaration of Purna Swaraj (Complete Independence) resolution of 26 January 1930.', '1930 के पूर्ण स्वराज्य दिवस की स्मृति में 26 जनवरी 1950 को संविधान पूर्णतः लागू किया गया।'), ('How many members of the Constituent Assembly signed the original Constitution on 24 January 1950?', '24 जनवरी 1950 को संविधान सभा के कुल कितने सदस्यों ने मूल संविधान पर हस्ताक्षर किए थे?', '284 Members', '284 सदस्य', ['299 Members', '389 Members', '250 Members'], ['299 सदस्य', '389 सदस्य', '250 सदस्य'], 'Out of 299 members, exactly 284 members were present on 24 January 1950 and appended their signatures.', '24 जनवरी 1950 को उपस्थित कुल 284 सदस्यों ने संविधान की मूल हस्तलिखित प्रतियों पर हस्ताक्षर किए।'), ('Who was the calligrapher who penned the original English Constitution in flowing italic style?', 'भारतीय संविधान की मूल अंग्रेजी प्रति को अपनी सुंदर हस्तलिपि (Italic Calligraphy) में किसने लिखा था?', 'Prem Behari Narain Raizada', 'प्रेम बिहारी नारायण रायजादा', ['Nandalal Bose', 'Beohar Rammanohar Sinha', 'Vasant Krishna Vaidya'], ['नंदलाल बोस', 'ब्योहर राममनोहर सिन्हा', 'वसंत कृष्ण वैद्य'], 'Prem Behari Narain Raizada handwritten the English Constitution using 303 nibs without taking any fee.', 'प्रेम बिहारी नारायण रायजादा ने 303 नंबर की निब से पूरे संविधान को इटैलिक सुलेख में हस्तलिखित किया।'), ('Who executed the calligraphy for the official Hindi translation of the original Constitution?', 'मूल संविधान के हिंदी संस्करण का सुलेखन (Calligraphy) किस सुलेखक द्वारा किया गया था?', 'Vasant Krishnan Vaidya', 'वसंत कृष्णन वैद्य', ['Prem Behari Raizada', 'Nandalal Bose', 'Rammanohar Sinha'], ['प्रेम बिहारी रायजादा', 'नंदलाल बोस', 'राममनोहर सिन्हा'], 'Vasant Krishnan Vaidya handwritten the Hindi version, which was illuminated by artists of Santiniketan.', 'मूल संविधान के हिंदी अनुवाद का सुंदर हस्तलेखन वसंत कृष्णन वैद्य द्वारा किया गया था।'), ('The artistic decoration and illumination of the pages of original Constitution was executed by', 'संविधान की मूल प्रति के पृष्ठों पर कलात्मक चित्रों एवं सीमाओं का चित्रांकन किसने किया था?', 'Nandalal Bose and Santiniketan artists', 'नंदलाल बोस एवं शांतिनिकेतन के कलाकार', ['Prem Behari Raizada', 'M.F. Husain', 'Raja Ravi Varma'], ['प्रेम बिहारी रायजादा', 'एम.एफ. हुसैन', 'राजा रवि वर्मा'], 'Nandalal Bose and his pupils from Kala Bhavana, Santiniketan illuminated each page with Indian cultural motifs.', 'शांतिनिकेतन के प्रसिद्ध कलाकार नंदलाल बोस और उनके शिष्यों ने संविधान के पृष्ठों को अलंकृत किया।'), ('Which animal was adopted as the official seal and emblem of the Constituent Assembly?', 'संविधान सभा की आधिकारिक मुहर (प्रतीक) के रूप में किस पशु को अपनाया गया था?', 'Elephant', 'हाथी (Elephant)', ['Lion', 'Tiger', 'Horse'], ['सिंह (शेर)', 'बाघ', 'घोड़ा'], 'The Elephant was adopted as the seal of the Constituent Assembly, symbolizing strength and wisdom.', 'संविधान सभा के प्रतीक (मुहर) के रूप में हाथी को अपनाया गया था।'), ('Who served as the Secretary to the Constituent Assembly throughout its deliberations?', 'संविधान सभा के सचिव (Secretary to Constituent Assembly) के रूप में किसने सेवा दी थी?', 'H.V.R. Iengar', 'एच.वी.आर. आयंगर', ['S.N. Mukherjee', 'Sir B.N. Rau', 'K.M. Munshi'], ['एस.एन. मुखर्जी', 'सर बी.एन. राव', 'के.एम. मुंशी'], 'H.V.R. Iengar (ICS) was the Secretary to the Constituent Assembly.', 'एच.वी.आर. आयंगर संविधान सभा के मुख्य सचिव थे।'), ('Who was appointed as the Chief Draftsman of the Constitution in the Constituent Assembly?', 'संविधान सभा में संविधान के मुख्य प्रारूपकार (Chief Draftsman) कौन नियुक्त किए गए थे?', 'S.N. Mukherjee', 'एस.एन. मुखर्जी', ['H.V.R. Iengar', 'Sir B.N. Rau', 'Dr. B.R. Ambedkar'], ['एच.वी.आर. आयंगर', 'सर बी.एन. राव', 'डॉ. बी.आर. आंबेडकर'], 'Dr. Ambedkar praised S.N. Mukherjee for his extraordinary ability to put complex legal propositions into statutory language.', 'एस.एन. मुखर्जी संविधान सभा के मुख्य प्रारूपकार थे, जिनकी विधायी मसौदा क्षमता की प्रशंसा डॉ. आंबेडकर ने की।'), ('Who was the Chairman of the Union Powers Committee of the Constituent Assembly?', "संविधान सभा की 'संघ शक्ति समिति' (Union Powers Committee) के अध्यक्ष कौन थे?", 'Pandit Jawaharlal Nehru', 'पंडित जवाहरलाल नेहरू', ['Sardar Vallabhbhai Patel', 'Dr. B.R. Ambedkar', 'Dr. Rajendra Prasad'], ['सरदार वल्लभभाई पटेल', 'डॉ. बी.आर. आंबेडकर', 'डॉ. राजेंद्र प्रसाद'], 'Nehru headed both the Union Powers Committee and the Union Constitution Committee.', 'संघ शक्ति समिति तथा संघ संविधान समिति दोनों के अध्यक्ष पंडित जवाहरलाल नेहरू थे।'), ('Who was the Chairman of the Provincial Constitution Committee of the Constituent Assembly?', "संविधान सभा की 'प्रांतीय संविधान समिति' (Provincial Constitution Committee) के अध्यक्ष कौन थे?", 'Sardar Vallabhbhai Patel', 'सरदार वल्लभभाई पटेल', ['Pandit Jawaharlal Nehru', 'Dr. B.R. Ambedkar', 'Dr. Rajendra Prasad'], ['पंडित जवाहरलाल नेहरू', 'डॉ. बी.आर. आंबेडकर', 'डॉ. राजेंद्र प्रसाद'], 'Sardar Patel headed the Provincial Constitution Committee and the Advisory Committee on Fundamental Rights.', 'सरदार वल्लभभाई पटेल प्रांतीय संविधान समिति के अध्यक्ष थे।'), ('Who served as the Chairman of the Steering Committee of the Constituent Assembly?', "संविधान सभा की 'संचालन समिति' (Steering Committee) के अध्यक्ष कौन थे?", 'Dr. Rajendra Prasad', 'डॉ. राजेंद्र प्रसाद', ['Jawaharlal Nehru', 'Dr. K.M. Munshi', 'Sardar Patel'], ['जवाहरलाल नेहरू', 'डॉ. के.एम. मुंशी', 'सरदार पटेल'], 'Dr. Rajendra Prasad presided over the Steering Committee and the Rules of Procedure Committee.', 'संचालन समिति तथा नियम समिति के अध्यक्ष संविधान सभा के स्थायी अध्यक्ष डॉ. राजेंद्र प्रसाद थे।'), ('Who was the Chairman of the Fundamental Rights Sub-Committee of the Constituent Assembly?', "संविधान सभा की 'मूल अधिकार उप-समिति' के अध्यक्ष कौन थे?", 'Acharya J.B. Kripalani', 'आचार्य जे.बी. कृपलानी', ['Sardar Vallabhbhai Patel', 'Dr. B.R. Ambedkar', 'H.C. Mukherjee'], ['सरदार वल्लभभाई पटेल', 'डॉ. बी.आर. आंबेडकर', 'एच.सी. मुखर्जी'], "J.B. Kripalani chaired the Fundamental Rights Sub-Committee under Sardar Patel's main Advisory Committee.", 'सरदार पटेल की मुख्य समिति के अधीन मूल अधिकार उप-समिति के अध्यक्ष जे.बी. कृपलानी थे।'), ('Who chaired the Minorities Sub-Committee in the Constituent Assembly?', "संविधान सभा की 'अल्पसंख्यक उप-समिति' के अध्यक्ष कौन थे?", 'H.C. Mukherjee', 'एच.सी. मुखर्जी (H.C. Mukherjee)', ['J.B. Kripalani', 'Maulana Abul Kalam Azad', 'Dr. B.R. Ambedkar'], ['जे.बी. कृपलानी', 'मौलाना अबुल कलाम आजाद', 'डॉ. बी.आर. आंबेडकर'], 'H.C. Mukherjee chaired the Minorities Sub-Committee, ensuring constitutional safeguards for minorities.', 'अल्पसंख्यक उप-समिति के अध्यक्ष संविधान सभा के उपाध्यक्ष हरेंद्र कुमार (एच.सी.) मुखर्जी थे।'), ('The Order of Business Committee of the Constituent Assembly was chaired by', "संविधान सभा की 'कार्य संचालन समिति' (Order of Business Committee) के अध्यक्ष कौन थे?", 'Dr. K.M. Munshi', 'डॉ. के.एम. मुंशी', ['Dr. B.R. Ambedkar', 'Dr. Rajendra Prasad', 'Jawaharlal Nehru'], ['डॉ. बी.आर. आंबेडकर', 'डॉ. राजेंद्र प्रसाद', 'जवाहरलाल नेहरू'], 'Dr. K.M. Munshi headed the Order of Business Committee.', 'कार्य संचालन समिति की अध्यक्षता डॉ. कन्हैयालाल माणिकलाल मुंशी ने की थी।'), ('Who chaired the Ad-hoc Committee on the National Flag in the Constituent Assembly?', "संविधान सभा की 'तदर्थ राष्ट्रीय ध्वज समिति' (Ad-hoc Flag Committee) के अध्यक्ष कौन थे?", 'Dr. Rajendra Prasad', 'डॉ. राजेंद्र प्रसाद', ['Acharya J.B. Kripalani', 'Sardar Patel', 'Jawaharlal Nehru'], ['आचार्य जे.बी. कृपलानी', 'सरदार पटेल', 'जवाहरलाल नेहरू'], 'The Ad-hoc Committee on the National Flag was chaired by Dr. Rajendra Prasad.', 'तदर्थ राष्ट्रीय ध्वज समिति के अध्यक्ष डॉ. राजेंद्र प्रसाद थे (ध्वज 22 जुलाई 1947 को अपनाया गया)।'), ('On which date did the Constituent Assembly adopt the National Flag of India?', 'संविधान सभा द्वारा भारत के राष्ट्रीय ध्वज (तिरंगे) को किस तिथि को अपनाया गया था?', '22 July 1947', '22 जुलाई 1947', ['15 August 1947', '26 January 1950', '26 November 1949'], ['15 अगस्त 1947', '26 जनवरी 1950', '26 नवंबर 1949'], 'Adopted on 22 July 1947; designed by Pingali Venkayya with a 3:2 aspect ratio.', 'पिंगली वेंकैया द्वारा डिजाइन किए गए तिरंगे झंडे को 22 जुलाई 1947 को राष्ट्रीय ध्वज के रूप में स्वीकार किया गया।'), ("The Constituent Assembly officially adopted 'Jana Gana Mana' as the National Anthem on", "संविधान सभा ने 'जन गण मन' को भारत के राष्ट्रगान के रूप में किस तिथि को स्वीकार किया?", '24 January 1950', '24 जनवरी 1950', ['26 January 1950', '15 August 1947', '26 November 1949'], ['26 जनवरी 1950', '15 अगस्त 1947', '26 नवंबर 1949'], 'Both the National Anthem (Jana Gana Mana) and National Song (Vande Mataram) were adopted on 24 January 1950.', '24 जनवरी 1950 को संविधान सभा की अंतिम बैठक में राष्ट्रगान एवं राष्ट्रगीत को आधिकारिक रूप से अपनाया गया।'), ('Who was elected as the first President of Independent India by the Constituent Assembly on 24 Jan 1950?', '24 जनवरी 1950 को संविधान सभा द्वारा स्वतंत्र भारत के प्रथम राष्ट्रपति के रूप में किन्हें चुना गया था?', 'Dr. Rajendra Prasad', 'डॉ. राजेंद्र प्रसाद', ['Dr. S. Radhakrishnan', 'C. Rajagopalachari', 'Jawaharlal Nehru'], ['डॉ. एस. राधाकृष्णन', 'सी. राजगोपालाचारी', 'जवाहरलाल नेहरू'], 'Dr. Rajendra Prasad was unanimously elected first President by the Constituent Assembly acting as provisional Parliament.', 'संविधान सभा ने 24 जनवरी 1950 को डॉ. राजेंद्र प्रसाद को भारत का प्रथम राष्ट्रपति निर्वाचित किया।'), ('What was the total expenditure incurred in framing the Constitution of India?', 'भारतीय संविधान के निर्माण में कुल कितना अनुमानित सरकारी व्यय हुआ था?', 'Approximately ₹64 Lakhs', 'लगभग ₹64 लाख', ['Approximately ₹1 Crore', 'Approximately ₹25 Lakhs', 'Approximately ₹5 Crores'], ['लगभग ₹1 करोड़', 'लगभग ₹25 लाख', 'लगभग ₹5 करोड़'], 'The total expenditure incurred during the 2 years, 11 months, and 18 days was approximately ₹63,96,729.', 'संविधान निर्माण प्रक्रिया में कुल लगभग 64 लाख रुपये (₹63,96,729) का खर्च आया था।'), ('How many Articles, Parts, and Schedules were contained in the original Constitution in 1949?', '1949 में अपनाए गए मूल संविधान में कुल कितने अनुच्छेद, भाग एवं अनुसूचियां थीं?', '395 Articles, 22 Parts, and 8 Schedules', '395 अनुच्छेद, 22 भाग एवं 8 अनुसूचियां', ['448 Articles, 25 Parts, and 12 Schedules', '395 Articles, 20 Parts, and 10 Schedules', '400 Articles, 22 Parts, and 9 Schedules'], ['448 अनुच्छेद, 25 भाग एवं 12 अनुसूचियां', '395 अनुच्छेद, 20 भाग एवं 10 अनुसूचियां', '400 अनुच्छेद, 22 भाग एवं 9 अनुसूचियां'], 'The original 1949 text had 395 Articles divided into 22 Parts and 8 Schedules.', 'मूल संविधान में कुल 395 अनुच्छेद, 22 भाग तथा 8 अनुसूचियां शामिल थीं।'), ('Which prominent leader first put forward the idea of a Constituent Assembly for India in 1934?', '1934 में भारत के लिए संविधान सभा के गठन का विचार सर्वप्रथम किस नेता ने प्रस्तुत किया था?', 'M.N. Roy (Manabendra Nath Roy)', 'एम.एन. रॉय (मानवेंद्र नाथ रॉय)', ['Mahatma Gandhi', 'Jawaharlal Nehru', 'Subhas Chandra Bose'], ['महात्मा गांधी', 'जवाहरलाल नेहरू', 'सुभाष चंद्र बोस'], 'M.N. Roy, a pioneer of the communist movement in India, first mooted the idea in 1934.', 'भारत में वामपंथी आंदोलन के प्रणेता एम.एन. रॉय ने 1934 में सर्वप्रथम संविधान सभा का विचार रखा था।'), ('In which year did the Indian National Congress (INC) officially demand a Constituent Assembly?', 'भारतीय राष्ट्रीय कांग्रेस ने आधिकारिक रूप से किस वर्ष संविधान सभा के गठन की मांग रखी थी?', '1935', '1935 में', ['1929', '1942', '1946'], ['1929 में', '1942 में', '1946 में'], 'The Congress officially demanded a Constituent Assembly to frame the Constitution without outside interference in 1935.', 'कांग्रेस ने 1935 में पहली बार आधिकारिक रूप से संविधान निर्माण के लिए संविधान सभा की मांग की।'), ('The British government first accepted the demand for a Constituent Assembly in principle through the', 'ब्रिटिश सरकार ने भारतीयों द्वारा संविधान सभा की मांग को सैद्धांतिक रूप से पहली बार किस प्रस्ताव में स्वीकार किया?', 'August Offer of 1940', 'अगस्त प्रस्ताव (August Offer, 1940)', ['Cripps Mission 1942', 'Cabinet Mission 1946', 'Simon Commission 1927'], ['क्रिप्स मिशन (1942)', 'कैबिनेट मिशन (1946)', 'साइमन कमीशन (1927)'], "Viceroy Linlithgow's August Offer of 1940 acknowledged that the framing of the new Constitution should be primarily the responsibility of Indians.", 'वायसराय लिनलिथगो के 1940 के अगस्त प्रस्ताव में पहली बार संविधान सभा की मांग को सैद्धांतिक मंजूरी दी गई थी।'), ('What was the total strength of the Constituent Assembly originally envisaged by the Cabinet Mission?', 'कैबिनेट मिशन योजना के अनुसार संविधान सभा की कुल सदस्य संख्या कितनी निर्धारित की गई थी?', '389 Members', '389 सदस्य', ['299 Members', '300 Members', '450 Members'], ['299 सदस्य', '300 सदस्य', '450 सदस्य'], '389 total seats: 292 from British Provinces, 93 from Princely States, and 4 from Chief Commissioner Provinces.', 'कुल 389 सीटें थीं: 292 ब्रिटिश प्रांतों से, 93 देशी रियासतों से और 4 मुख्य आयुक्तों के प्रांतों से।'), ('How many seats in the Constituent Assembly were won by the Indian National Congress in July-August 1946 elections?', 'जुलाई-अगस्त 1946 में हुए चुनावों में कांग्रेस ने संविधान सभा की 296 सीटों में से कितनी सीटें जीती थीं?', '208 Seats', '208 सीटें', ['73 Seats', '15 Seats', '250 Seats'], ['73 सीटें', '15 सीटें', '250 सीटें'], 'Congress won 208 seats, Muslim League won 73 seats, and 15 seats went to independents/other parties.', 'कांग्रेस को 208 सीटें और मुस्लिम लीग को 73 सीटें प्राप्त हुई थीं।'), ('After partition in 1947, the membership of the Constituent Assembly of India was reduced to', '15 अगस्त 1947 को देश के विभाजन के पश्चात भारतीय संविधान सभा के सदस्यों की संख्या घटकर कितनी रह गई?', '299 Members', '299 सदस्य', ['389 Members', '284 Members', '250 Members'], ['389 सदस्य', '284 सदस्य', '250 सदस्य'], "Following Mountbatten's partition plan, the strength was reduced from 389 to 299 (229 provincial, 70 princely states).", 'विभाजन के पश्चात मुस्लिम लीग के सदस्यों के अलग होने पर भारतीय संविधान सभा में 299 सदस्य शेष रहे।'), ('Which Princely State initially refused to send representatives to the Constituent Assembly?', 'किस प्रमुख देशी रियासत ने प्रारंभ में संविधान सभा में शामिल होने से इनकार कर दिया था?', 'Hyderabad', 'हैदराबाद (Hyderabad)', ['Mysore', 'Baroda', 'Gwalior'], ['मैसूर', 'बड़ौदा', 'ग्वालियर'], 'Hyderabad initially boycotted the Constituent Assembly deliberations.', 'हैदराबाद रियासत ने आरंभ में संविधान सभा में अपना कोई प्रतिनिधि नहीं भेजा था।'), ('How were members from British Indian Provinces chosen for the Constituent Assembly in 1946?', '1946 में ब्रिटिश प्रांतों से संविधान सभा के सदस्यों का चुनाव किस पद्धति द्वारा हुआ था?', 'Indirect election by members of Provincial Legislative Assemblies via proportional representation', 'प्रांतीय विधान सभाओं के सदस्यों द्वारा एकल संक्रमणीय मत से अप्रत्यक्ष निर्वाचन', ['Direct universal adult suffrage election', 'Nomination by the British Viceroy', 'Appointed by local district collectors'], ['वयस्क मताधिकार द्वारा प्रत्यक्ष निर्वाचन', 'वायसराय द्वारा सीधा मनोनयन', 'जिला कलेक्टरों द्वारा चयन'], 'Members were elected indirectly by the Provincial Assemblies using single transferable vote proportional representation.', 'प्रांतीय विधानसभा के सदस्यों द्वारा आनुपातिक प्रतिनिधित्व प्रणाली के अनुसार अप्रत्यक्ष चुनाव किया गया।'), ('What was the population ratio adopted for allocating seats in the Constituent Assembly in 1946?', 'कैबिनेट मिशन के अनुसार संविधान सभा में प्रति कितने लाख की आबादी पर एक सीट आवंटित की गई थी?', '1 seat for every 10 Lakh (1 Million) population', 'प्रत्येक 10 लाख की जनसंख्या पर 1 सीट', ['1 seat for every 5 Lakh population', '1 seat for every 20 Lakh population', '1 seat for every 1 Lakh population'], ['प्रत्येक 5 लाख की जनसंख्या पर', 'प्रत्येक 20 लाख की जनसंख्या पर', 'प्रत्येक 1 लाख की जनसंख्या पर'], 'Roughly one seat was allocated for every one million (10 lakh) people.', 'मोटे तौर पर प्रत्येक 10 लाख की जनसंख्या पर एक प्रतिनिधि का अनुपात रखा गया था।'), ('Which articles of the Constitution came into immediate legal force on 26 November 1949?', '26 नवंबर 1949 को संविधान के कौन से प्रावधान तुरंत प्रभाव से लागू कर दिए गए थे?', 'Articles relating to Citizenship, Elections, Provisional Parliament, and Temporary Provisions', 'नागरिकता, निर्वाचन, अंतरिम संसद और अस्थायी प्रावधानों से संबंधित अनुच्छेद', ['Fundamental Rights and Directive Principles', 'Supreme Court and High Courts', 'Emergency Provisions and Union Executive'], ['मूल अधिकार एवं नीति निदेशक तत्व', 'सर्वोच्च न्यायालय एवं उच्च न्यायालय', 'आपातकालीन प्रावधान एवं राष्ट्रपति'], 'Articles 5, 6, 7, 8, 9, 60, 324, 366, 367, 379, 380, 388, 391, 392, and 393 took effect immediately on 26 Nov 1949.', 'अनुच्छेद 5 से 9 (नागरिकता), अनुच्छेद 324 (चुनाव आयोग) आदि 26 नवंबर 1949 को ही लागू हो गए थे।'), ('The Constituent Assembly functioned as the Provisional Parliament of India until', 'संविधान सभा ने प्रथम आम चुनावों के बाद नई संसद के गठन तक किस रूप में कार्य किया था?', 'Provisional Parliament of India (until May 1952)', 'भारत की अंतरिम संसद (मई 1952 तक)', ['Dissolved immediately on 26 January 1950', 'Continued until 1960', 'Replaced by British House of Commons'], ['26 जनवरी 1950 को भंग हो गई', '1960 तक अनवरत चली', 'ब्रिटिश संसद द्वारा संचालित'], 'Under Article 379, the Constituent Assembly acted as the Provisional Parliament until the first elected Lok Sabha took office in May 1952.', '1952 के पहले आम चुनावों के बाद पहली निर्वाचित संसद के गठन तक संविधान सभा ही अंतरिम संसद रही।'), ('Who was elected as the Speaker of the Constituent Assembly when it met as a legislative body?', 'जब संविधान सभा देश की पहली विधायिका (संसद) के रूप में बैठती थी, तब उसकी अध्यक्षता कौन करते थे?', 'G.V. Mavalankar (Ganesh Vasudev Mavalankar)', 'जी.वी. मावलंकर (G.V. Mavalankar)', ['Dr. Rajendra Prasad', 'Dr. B.R. Ambedkar', 'Sardar Patel'], ['डॉ. राजेंद्र प्रसाद', 'डॉ. बी.आर. आंबेडकर', 'सरदार पटेल'], 'When the Assembly met as a constitution-making body it was chaired by Dr. Rajendra Prasad; as a legislature, it was chaired by G.V. Mavalankar.', 'संविधान निर्माण के समय अध्यक्षता डॉ. राजेंद्र प्रसाद करते थे, जबकि विधायी संसद के रूप में जी.वी. मावलंकर अध्यक्षता करते थे।'), ('How many women members were elected to the Constituent Assembly of India in total?', 'भारतीय संविधान सभा में कुल कितनी महिला सदस्य निर्वाचित हुई थीं?', '15 Women Members', '15 महिला सदस्य', ['9 Women Members', '25 Women Members', '5 Women Members'], ['9 महिला सदस्य', '25 महिला सदस्य', '5 महिला सदस्य'], '15 prominent women served in the Assembly, including Sarojini Naidu, Rajkumari Amrit Kaur, Vijayalakshmi Pandit, and Hansa Mehta.', 'संविधान सभा में सरोजिनी नायडू, राजकुमारी अमृत कौर, हंसा मेहता सहित कुल 15 महिला सदस्य शामिल थीं।')]

slot_q112_preamble = [('The opening words of the Preamble to the Constitution of India are', 'भारतीय संविधान की प्रस्तावना के प्रारंभिक शब्द क्या हैं?', "'We, the People of India...'", "'हम, भारत के लोग...'", ["'In the Name of God...'", "'The Sovereign Assembly...'", "'The Parliament of India...'"], ["'ईश्वर के नाम पर...'", "'संप्रभु सभा...'", "'भारत की संसद...'"], 'Emphasizes that ultimate sovereignty rests with the people of India.', 'प्रस्तावना स्पष्ट करती है कि संविधान की संप्रभुता का अंतिम स्रोत भारत की जनता है।'), ('Which three words were inserted into the Preamble by the 42nd Constitutional Amendment Act of 1976?', '1976 के 42वें संविधान संशोधन द्वारा प्रस्तावना में कौन से तीन शब्द जोड़े गए थे?', "'Socialist', 'Secular', and 'Integrity'", "'समाजवादी', 'पंथनिरपेक्ष' एवं 'अखंडता'", ["'Federal', 'Democratic', 'Republic'", "'Sovereign', 'Fraternity', 'Liberty'", "'Justice', 'Equality', 'Secular'"], ["'संघीय', 'लोकतांत्रिक', 'गणराज्य'", "'संप्रभु', 'बंधुता', 'स्वतंत्रता'", "'न्याय', 'समानता', 'धर्मनिरपेक्ष'"], "Inserted during Indira Gandhi's prime ministership to articulate India's commitment to social justice and secularism.", "42वें संशोधन द्वारा प्रस्तावना में 'समाजवादी', 'पंथनिरपेक्ष' और 'अखंडता' शब्द जोड़े गए।"), ('In which landmark judgment of 1973 did the Supreme Court rule that the Preamble is an integral part of the Constitution?', 'किस ऐतिहासिक फैसले में सर्वोच्च न्यायालय ने माना कि प्रस्तावना संविधान का अभिन्न अंग है?', 'Kesavananda Bharati v. State of Kerala (1973)', 'केशवानंद भारती बनाम केरल राज्य (1973)', ['Golaknath case (1967)', 'Berubari Union case (1960)', 'Minerva Mills case (1980)'], ['गोलकनाथ मामला (1967)', 'बेरुबारी संघ मामला (1960)', 'मिनर्वा मिल्स मामला (1980)'], 'A 13-judge bench overruled Berubari (1960) and held Preamble is an integral part of Constitution subject to amendment without altering Basic Structure.', '13 न्यायाधीशों की पीठ ने बेरुबारी फैसले को पलटते हुए प्रस्तावना को संविधान का अभिन्न अंग घोषित किया।'), ('What three forms of Justice are promised in the Preamble to all Indian citizens?', 'प्रस्तावना में भारत के नागरिकों को किस प्रकार के न्याय का संकल्प दिया गया है?', 'Social, Economic, and Political Justice', 'सामाजिक, आर्थिक एवं राजनीतिक न्याय', ['Religious, Moral, and Legal Justice', 'Judicial, Civil, and Criminal Justice', 'Individual, Community, and National Justice'], ['धार्मिक, नैतिक एवं विधिक न्याय', 'न्यायिक, दीवानी एवं फौजदारी न्याय', 'व्यक्तिगत, सामुदायिक एवं राष्ट्रीय न्याय'], 'Borrowed from the Russian Revolution (1917) ideals of social equity and welfare.', '1917 की रूसी क्रांति से प्रेरित सामाजिक, आर्थिक और राजनीतिक न्याय की संकल्पना को अपनाया गया।'), ("The ideals of 'Liberty, Equality, and Fraternity' enshrined in the Preamble were inspired by the", "प्रस्तावना में उल्लिखित 'स्वतंत्रता, समानता एवं बंधुत्व' के आदर्श किस क्रांति से प्रेरित हैं?", 'French Revolution (1789)', 'फ्रांसीसी क्रांति (1789)', ['American Revolution', 'Russian Revolution', 'Industrial Revolution'], ['अमेरिकी क्रांति', 'रूसी क्रांति', 'औद्योगिक क्रांति'], 'Universal ideals of revolutionary France adopted to guarantee individual dignity and national unity.', "1789 की फ्रांसीसी क्रांति के प्रसिद्ध नारे 'स्वतंत्रता, समानता और बंधुत्व' को प्रस्तावना में शामिल किया गया।"), ('According to the Preamble, what is the exact nature of the Indian State?', 'प्रस्तावना के अनुसार भारतीय राज्य की प्रकृति का सही क्रम क्या है?', 'Sovereign, Socialist, Secular, Democratic Republic', 'संपूर्ण प्रभुत्व-संपन्न, समाजवादी, पंथनिरपेक्ष, लोकतंत्रात्मक गणराज्य', ['Sovereign, Democratic, Socialist, Republic', 'Democratic, Socialist, Secular, Sovereign', 'Federal, Socialist, Democratic, Republic'], ['संप्रभु, लोकतांत्रिक, समाजवादी, गणराज्य', 'लोकतांत्रिक, समाजवादी, धर्मनिरपेक्ष', 'संघीय, समाजवादी, गणराज्य'], 'The correct sequence in the Preamble is: Sovereign, Socialist, Secular, Democratic Republic.', "प्रस्तावना में भारत को 'संपूर्ण प्रभुत्व-संपन्न, समाजवादी, पंथनिरपेक्ष, लोकतंत्रात्मक गणराज्य' घोषित किया गया है।"), ("What does the word 'Republic' in the Preamble signify?", "प्रस्तावना में 'गणराज्य' (Republic) शब्द का क्या अर्थ है?", 'The Head of the State is elected, not hereditary', 'राज्य का प्रमुख (राष्ट्रपति) निर्वाचित होता है, वंशानुगत नहीं', ['The Prime Minister holds absolute executive power', 'Parliament is supreme over the courts', 'State has no official language'], ['प्रधानमंत्री के पास असीमित शक्तियां हैं', 'संसद न्यायपालिका से सर्वोच्च है', 'राज्य की कोई राजभाषा नहीं है'], 'A republic has an elected head of state for a fixed term, unlike a hereditary monarchy (such as Britain).', 'गणराज्य का तात्पर्य है कि भारत का राष्ट्राध्यक्ष (राष्ट्रपति) जनता द्वारा परोक्ष रूप से निर्वाचित होता है, वंशानुगत राजा नहीं होता।'), ('Article 1 of the Constitution declares India, that is Bharat, to be a', 'भारतीय संविधान का अनुच्छेद 1 भारत (अर्थात् भारत) को क्या घोषित करता है?', 'Union of States (राज्यों का संघ)', 'राज्यों का संघ (Union of States)', ['Federation of States', 'Confederation of States', 'Unitary State'], ['राज्यों का परिसंघ (Federation)', 'राज्यों का महासंघ (Confederation)', 'एकात्मक राज्य'], "Dr. Ambedkar explained 'Union of States' means the federation is not an agreement among states, and no state has the right to secede.", "अनुच्छेद 1 भारत को 'राज्यों का संघ' कहता है; किसी भी राज्य को भारत से अलग होने का अधिकार नहीं है।"), ('Under Article 2 of the Constitution, who is empowered to admit or establish new States into the Union?', 'संविधान के अनुच्छेद 2 के तहत नए राज्यों के प्रवेश या स्थापना की शक्ति किसे प्राप्त है?', 'Parliament of India by law', 'संसद को (विधि द्वारा)', ['President of India by decree', 'Supreme Court of India', 'NITI Aayog'], ['राष्ट्रपति के अध्यादेश द्वारा', 'सर्वोच्च न्यायालय को', 'नीति आयोग को'], 'Article 2 empowers Parliament to admit new states (from outside territories) on terms it thinks fit.', 'संसद विधि द्वारा नए राज्यों का भारतीय संघ में प्रवेश या उनकी स्थापना कर सकती है।'), ('Article 3 of the Constitution empowers Parliament to alter the boundaries or name of existing States by', 'संविधान के अनुच्छेद 3 के तहत किसी वर्तमान राज्य के क्षेत्र, सीमा या नाम में परिवर्तन करने के लिए किस बहुमत की आवश्यकता होती है?', 'A Simple Majority in Parliament', 'संसद में साधारण बहुमत', ['A Special Majority under Article 368', 'A Special Majority plus ratification by half of the states', 'A 3/4th majority of both Houses'], ['अनुच्छेद 368 के तहत विशेष बहुमत', 'विशेष बहुमत एवं आधे राज्यों की सहमति', 'दोनों सदनों का तीन-चौथाई बहुमत'], 'A bill under Article 3 requires only a simple majority; Article 4 specifies such laws are not constitutional amendments under Art 368.', 'अनुच्छेद 3 के तहत राज्यों के पुनर्गठन का विधेयक संसद के दोनों सदनों में साधारण बहुमत से पारित होता है।'), ('Before introducing a bill under Article 3 to alter the area or boundary of a State, whose prior recommendation is mandatory?', 'अनुच्छेद 3 के तहत किसी राज्य की सीमा या नाम बदलने वाले विधेयक को संसद में पेश करने से पूर्व किसकी पूर्व सहमति आवश्यक है?', 'President of India', 'भारत के राष्ट्रपति की', ['Chief Minister of the concerned State', 'Governor of the State', 'Chief Justice of India'], ['संबंधित राज्य के मुख्यमंत्री की', 'राज्य के राज्यपाल की', 'भारत के मुख्य न्यायाधीश की'], 'A bill under Article 3 can be introduced only on the recommendation of the President, who refers it to the state legislature for views.', 'राष्ट्रपति की पूर्व सिफारिश के बिना अनुच्छेद 3 से संबंधित कोई विधेयक संसद में पेश नहीं किया जा सकता।'), ('Which was the first State in independent India created on a linguistic basis in 1953?', 'स्वतंत्र भारत में भाषाई आधार पर गठित होने वाला पहला राज्य कौन सा था?', 'Andhra State (1953)', 'आंध्र प्रदेश (1953)', ['Kerala', 'Karnataka', 'Maharashtra'], ['केरल', 'कर्नाटक', 'महाराष्ट्र'], "Formed on 1 October 1953 separating Telugu-speaking areas from Madras State following Potti Sreeramulu's 56-day hunger strike.", 'पोट्टी श्रीरामुलु के बलिदान के बाद 1 अक्टूबर 1953 को मद्रास से अलग कर भाषाई आधार पर आंध्र राज्य का गठन हुआ।'), ('The States Reorganisation Commission (SRC) constituted in 1953 was headed by', '1953 में गठित राज्य पुनर्गठन आयोग (SRC) के अध्यक्ष कौन थे?', 'Justice Fazal Ali (with H.N. Kunzru and K.M. Panikkar)', 'न्यायमूर्ति फजल अली (Justice Fazal Ali)', ['Justice S.K. Dhar', 'Jawaharlal Nehru', 'Sardar Vallabhbhai Patel'], ['न्यायमूर्ति एस.के. धर', 'जवाहरलाल नेहरू', 'सरदार पटेल'], 'The Fazal Ali Commission submitted its report in 1955, leading to the States Reorganisation Act 1956.', 'फजल अली आयोग की सिफारिशों के आधार पर 1956 में 14 राज्य और 6 केंद्र शासित प्रदेश बनाए गए।'), ('The Dhar Commission (1948) appointed by the Constituent Assembly recommended reorganization of States based on', '1948 में संविधान सभा द्वारा नियुक्त धर आयोग ने राज्यों के पुनर्गठन का क्या आधार सुझाया था?', 'Administrative convenience rather than linguistic basis', 'भाषाई आधार के बजाय प्रशासनिक सुविधा', ['Strict linguistic homogeneity', 'Religious majority', 'Historical dynastic boundaries'], ['कठोर भाषाई एकरूपता', 'धार्मिक बहुसंख्या', 'ऐतिहासिक राजवंशीय सीमाएं'], 'The S.K. Dhar Commission advised against linguistic reorganization, favoring administrative convenience.', 'एस.के. धर आयोग ने भाषा के आधार पर राज्यों के पुनर्गठन को राष्ट्रीय एकता के लिए अनुपयुक्त माना और प्रशासनिक सुविधा का समर्थन किया।'), ('The JVP Committee (1948) appointed by the Congress consisted of which leaders?', "दिसंबर 1948 में कांग्रेस द्वारा गठित 'जेवीपी समिति' (JVP Committee) में कौन से नेता शामिल थे?", 'Jawaharlal Nehru, Vallabhbhai Patel, and Pattabhi Sitaramayya', 'जवाहरलाल नेहरू, वल्लभभाई पटेल एवं पट्टाभि सीतारमैया', ['Jawaharlal Nehru, V.P. Menon, and Patel', 'Jawaharlal, V.T. Krishnamachari, Pant', 'Jayaprakash, Vinoba, Patel'], ['नेहरू, वी.पी. मेनन एवं पटेल', 'नेहरू, वी.टी. कृष्णमाचारी, पंत', 'जयप्रकाश, विनोबा, पटेल'], 'The JVP committee formally rejected language as the basis for reorganization of states at that stage.', 'जेवीपी समिति ने उस समय भाषा के आधार पर राज्यों के पुनर्गठन के विचार को खारिज कर दिया था।'), ('By which Constitutional Amendment Act was the categorization of Part A, B, C, and D States abolished in 1956?', 'किस संविधान संशोधन अधिनियम द्वारा 1956 में भाग क, ख, ग एवं घ राज्यों का वर्गीकरण समाप्त किया गया?', '7th Constitutional Amendment Act, 1956', '7वां संविधान संशोधन अधिनियम (1956)', ['1st Constitutional Amendment Act, 1951', '4th Constitutional Amendment Act, 1955', '10th Constitutional Amendment Act, 1961'], ['पहला संशोधन (1951)', 'चौथा संशोधन (1955)', '10वां संशोधन (1961)'], 'The 7th Amendment implemented the States Reorganisation Act, replacing Part A, B, C, D states with 14 States and 6 Union Territories.', '7वें संविधान संशोधन (1956) द्वारा राज्यों के चार वर्गों को समाप्त कर 14 राज्य और 6 केंद्र शासित प्रदेश बनाए गए।'), ('Which Constitutional Amendment Act made Sikkim an Associate State, and which made it a full-fledged State?', "सिक्किम को किस संशोधन द्वारा 'सह-युक्त राज्य' और किस संशोधन द्वारा पूर्ण राज्य का दर्जा दिया गया?", '35th Amendment (Associate State) and 36th Amendment (Full-fledged State in 1975)', '35वां संशोधन (सह-युक्त राज्य) एवं 36वां संशोधन (पूर्ण राज्य - 1975)', ['34th and 35th Amendments', '36th and 37th Amendments', '42nd and 44th Amendments'], ['34वां और 35वां', '36वां और 37वां', '42वां और 44वां'], '35th Amendment (1974) introduced Article 2A; 36th Amendment (1975) made Sikkim the 22nd state of India.', '35वें संशोधन (1974) द्वारा सह-राज्य और 36वें संशोधन (1975) द्वारा सिक्किम भारत का 22वां पूर्ण राज्य बना।'), ('Provisions relating to Citizenship in the Constitution of India are embodied in', 'भारतीय संविधान में नागरिकता संबंधी प्रावधान किस भाग एवं अनुच्छेदों में दिए गए हैं?', 'Part II, Articles 5 to 11', 'भाग II, अनुच्छेद 5 से 11', ['Part I, Articles 1 to 4', 'Part III, Articles 12 to 35', 'Part IV, Articles 36 to 51'], ['भाग I, अनुच्छेद 1 से 4', 'भाग III, अनुच्छेद 12 से 35', 'भाग IV, अनुच्छेद 36 से 51'], 'Articles 5-11 deal with citizenship at the commencement of the Constitution; Parliament was given plenary power under Art 11.', 'संविधान के भाग 2 के अनुच्छेद 5 से 11 तक नागरिकता का उपबंध किया गया है।'), ('Under Article 11 of the Constitution, who is empowered to regulate the right of citizenship by law?', 'संविधान के अनुच्छेद 11 के तहत नागरिकता के अधिकार को विधि द्वारा विनियमित करने की शक्ति किसे दी गई है?', 'Parliament of India', 'भारत की संसद को', ['President of India', 'Supreme Court of India', 'Ministry of Home Affairs alone'], ['भारत के राष्ट्रपति को', 'सर्वोच्च न्यायालय को', 'केवल गृह मंत्रालय को'], 'Article 11 gives Parliament plenary power to make any provision with respect to acquisition and termination of citizenship.', 'अनुच्छेद 11 संसद को नागरिकता के अर्जन, समाप्ति और अन्य सभी मामलों में कानून बनाने का पूर्ण अधिकार देता है।'), ('In which year did the Parliament of India pass the first comprehensive Citizenship Act?', 'भारतीय संसद ने पहली बार व्यापक नागरिकता अधिनियम किस वर्ष पारित किया था?', '1955', '1955 में', ['1950', '1952', '1960'], ['1950 में', '1952 में', '1960 में'], 'The Citizenship Act, 1955 provides for acquisition and loss of citizenship after the commencement of the Constitution.', 'संसद ने 1955 में भारतीय नागरिकता अधिनियम पारित किया, जिसमें समय-समय पर संशोधन किए गए।'), ('Under the Citizenship Act 1955, in how many legal ways can Indian citizenship be acquired?', 'नागरिकता अधिनियम 1955 के तहत भारतीय नागरिकता कितने तरीकों से प्राप्त की जा सकती है?', '5 Ways (Birth, Descent, Registration, Naturalisation, Incorporation of Territory)', '5 प्रकार से (जन्म, वंश, पंजीकरण, देशीयकरण, भू-भाग विलय)', ['3 Ways', '4 Ways', '7 Ways'], ['3 प्रकार से', '4 प्रकार से', '7 प्रकार से'], 'Acquisition can occur by Birth (Jus soli), Descent (Jus sanguinis), Registration, Naturalisation, or Incorporation of territory.', 'भारतीय नागरिकता जन्म से, वंश परंपरा से, पंजीकरण से, देशीयकरण से अथवा नए भू-भाग के विलय द्वारा प्राप्त हो सकती है।'), ('Indian citizenship can be lost or terminated in how many ways under the Citizenship Act 1955?', 'नागरिकता अधिनियम 1955 के तहत भारतीय नागरिकता की समाप्ति कितने आधारों पर हो सकती है?', '3 Ways (Renunciation, Termination, and Deprivation)', '3 प्रकार से (त्याग, पर्यावसान, एवं वंचित किया जाना)', ['2 Ways', '4 Ways', '5 Ways'], ['2 प्रकार से', '4 प्रकार से', '5 प्रकार से'], 'Loss occurs by Renunciation (voluntary), Termination (acquiring another citizenship), or Deprivation (by central government on fraud/disloyalty).', 'स्वेच्छा से त्याग (Renunciation), विदेशी नागरिकता लेने पर स्वतः समाप्ति (Termination), या धोखाधड़ी पर सरकार द्वारा वंचित करने (Deprivation) से।'), ('What type of citizenship does the Indian Constitution provide for its citizens?', 'भारतीय संविधान अपने नागरिकों को किस प्रकार की नागरिकता प्रदान करता है?', 'Single Citizenship for the entire Union (borrowed from UK)', 'एकल नागरिकता (ब्रिटेन से प्रेरित)', ['Dual Citizenship (State and Federal like USA)', 'Plural Citizenship', 'Tiered Citizenship'], ['दोहरी नागरिकता (अमेरिका की भांति)', 'बहु-नागरिकता', 'श्रेणीबद्ध नागरिकता'], 'Unlike federal USA where individuals hold state and federal citizenships, India provides only one single Indian citizenship.', 'भारत में अमेरिका की तरह राज्यों की अलग नागरिकता नहीं है; पूरे देश में केवल एक ही भारतीय नागरिकता है।'), ('Which Article of the Constitution states that a person voluntarily acquiring citizenship of a foreign State loses Indian citizenship?', 'संविधान का कौन सा अनुच्छेद कहता है कि स्वेच्छा से विदेशी नागरिकता लेने पर भारतीय नागरिकता समाप्त हो जाती है?', 'Article 9', 'अनुच्छेद 9', ['Article 5', 'Article 8', 'Article 10'], ['अनुच्छेद 5', 'अनुच्छेद 8', 'अनुच्छेद 10'], 'Article 9 provides that no person shall be a citizen of India if he has voluntarily acquired the citizenship of any foreign State.', 'अनुच्छेद 9 के अनुसार कोई भी व्यक्ति यदि स्वेच्छा से किसी विदेशी राज्य की नागरिकता ग्रहण करता है, तो वह भारत का नागरिक नहीं रहेगा।'), ('The Overseas Citizen of India (OCI) scheme was introduced by amending the Citizenship Act in which year?', 'प्रवासी भारतीय नागरिक (OCI) योजना नागरिकता अधिनियम में किस वर्ष संशोधन करके लागू की गई थी?', '2005 (based on L.M. Singhvi Committee recommendations)', '2005 में (एल.एम. सिंघवी समिति की सिफारिश पर)', ['1999', '2000', '2015'], ['1999 में', '2000 में', '2015 में'], 'OCI scheme was launched in 2005 based on the L.M. Singhvi High-Level Committee on Indian Diaspora.', 'एल.एम. सिंघवी समिति की रिपोर्ट के आधार पर नागरिकता (संशोधन) अधिनियम 2005 द्वारा OCI कार्ड योजना शुरू की गई।'), ('In which year did the Government of India merge the PIO (Person of Indian Origin) card with the OCI card?', 'भारत सरकार ने किस वर्ष पीआईओ (PIO) कार्ड को ओसीआई (OCI) कार्ड में पूरी तरह समाहित कर दिया?', '2015', '2015 में', ['2010', '2018', '2020'], ['2010 में', '2018 में', '2020 में'], 'In 2015, the Citizenship (Amendment) Act merged PIO cards into OCI cards to provide a unified lifelong visa.', '2015 में नागरिकता संशोधन अधिनियम के तहत पीआईओ कार्ड धारकों को ओसीआई कार्ड धारक के रूप में परिवर्तित कर दिया गया।'), ('In the Berubari Union case (1960), the Supreme Court ruled that', '1960 के बेरुबारी संघ मामले में सर्वोच्च न्यायालय ने क्या निर्णय दिया था?', 'Ceding Indian territory to a foreign country requires an amendment under Article 368, and Preamble is not part of Constitution', 'भारतीय भू-भाग विदेशी देश को सौंपने के लिए अनुच्छेद 368 के तहत संशोधन जरूरी है, और प्रस्तावना संविधान का अंग नहीं है', ['Preamble is an integral part of the Constitution', 'Parliament cannot alter boundaries under Article 3', 'Article 368 cannot amend fundamental rights'], ['प्रस्तावना संविधान का अभिन्न अंग है', 'संसद सीमाओं में परिवर्तन नहीं कर सकती', 'मूल अधिकारों में संशोधन नहीं हो सकता'], 'The Supreme Court held that ceding territory requires an Art 368 amendment (9th Amendment 1960), and held Preamble was not part of Constitution.', 'बेरुबारी मामले में माना गया कि सीमा विवाद सुलझाने में भू-भाग सौंपने के लिए अनुच्छेद 368 के तहत संशोधन (9वां संशोधन) आवश्यक है।'), ('Which Constitutional Amendment Act was enacted in 2015 to give effect to the Land Boundary Agreement with Bangladesh?', 'बांग्लादेश के साथ भूमि सीमा समझौते (LBA) को लागू करने के लिए 2015 में कौन सा संविधान संशोधन पारित किया गया?', '100th Constitutional Amendment Act, 2015', '100वां संविधान संशोधन अधिनियम (2015)', ['99th Amendment Act', '101st Amendment Act', '98th Amendment Act'], ['99वां संशोधन', '101वां संशोधन', '98वां संशोधन'], 'The 100th Amendment Act 2015 ratified the exchange of 111 enclaves to Bangladesh and 51 enclaves to India.', '100वें संविधान संशोधन अधिनियम (2015) द्वारा भारत और बांग्लादेश के बीच अंतःक्षेत्रों (Enclaves) का आदान-प्रदान किया गया।'), ('Which Union Territory of India was elevated to statehood in 1987 as the 25th State?', '1987 में किस केंद्र शासित प्रदेश को पूर्ण राज्य का दर्जा देकर भारत का 25वां राज्य बनाया गया था?', 'Goa', 'गोवा (Goa)', ['Mizoram', 'Arunachal Pradesh', 'Puducherry'], ['मिजोरम', 'अरुणाचल प्रदेश', 'पुदुचेरी'], 'Goa was separated from Daman & Diu and made the 25th state in May 1987.', '1987 में गोवा को दमन और दीव से अलग कर भारत का 25वां पूर्ण राज्य बनाया गया।'), ('The Jammu and Kashmir Reorganisation Act 2019 bifurcated the State of Jammu and Kashmir into', 'जम्मू और कश्मीर पुनर्गठन अधिनियम 2019 ने राज्य को किन दो केंद्र शासित प्रदेशों में विभाजित किया?', 'Union Territory of Jammu & Kashmir and Union Territory of Ladakh', 'केंद्र शासित प्रदेश जम्मू-कश्मीर एवं केंद्र शासित प्रदेश लद्दाख', ['Jammu State and Kashmir State', 'UT of Kashmir and UT of Jammu', 'Three Union Territories'], ['जम्मू राज्य एवं कश्मीर राज्य', 'कश्मीर यूटी एवं जम्मू यूटी', 'तीन केंद्र शासित प्रदेशों में'], 'Effective 31 October 2019, J&K was reorganized into two UTs: J&K (with legislature) and Ladakh (without legislature).', '31 अक्टूबर 2019 से जम्मू-कश्मीर को दो केंद्र शासित प्रदेशों (जम्मू-कश्मीर तथा लद्दाख) में पुनर्गठित किया गया।'), ('Dadra and Nagar Haveli and Daman and Diu were merged into a single Union Territory in which year?', 'दादरा एवं नगर हवेली तथा दमन एवं दीव का विलय किस वर्ष एक ही केंद्र शासित प्रदेश के रूप में किया गया?', '2020 (effective 26 January 2020)', '2020 में (26 जनवरी 2020 से प्रभावी)', ['2018', '2019', '2021'], ['2018 में', '2019 में', '2021 में'], 'Parliament passed the merger Act in December 2019, coming into effect on 26 January 2020 with Daman as headquarters.', '26 जनवरी 2020 से दोनों केंद्र शासित प्रदेशों को मिलाकर एक केंद्र शासित प्रदेश बना दिया गया।'), ('How many States and Union Territories currently exist in the Republic of India?', 'वर्तमान समय में भारत गणराज्य में कुल कितने राज्य और केंद्र शासित प्रदेश हैं?', '28 States and 8 Union Territories', '28 राज्य एवं 8 केंद्र शासित प्रदेश', ['29 States and 7 Union Territories', '28 States and 9 Union Territories', '29 States and 8 Union Territories'], ['29 राज्य एवं 7 केंद्र शासित प्रदेश', '28 राज्य एवं 9 केंद्र शासित प्रदेश', '29 राज्य एवं 8 केंद्र शासित प्रदेश'], 'Following J&K reorganization (2019) and Dadra-Nagar Haveli & Daman-Diu merger (2020), there are 28 states and 8 UTs.', 'वर्तमान में भारत में कुल 28 राज्य और 8 केंद्र शासित प्रदेश विद्यमान हैं।'), ('Which Article of the Constitution guarantees that laws inconsistent with or in derogation of Fundamental Rights are void?', 'संविधान का कौन सा अनुच्छेद घोषित करता है कि मूल अधिकारों से असंगत या उनका अल्पीकरण करने वाली विधियां शून्य होंगी?', 'Article 13', 'अनुच्छेद 13', ['Article 12', 'Article 14', 'Article 32'], ['अनुच्छेद 12', 'अनुच्छेद 14', 'अनुच्छेद 32'], 'Article 13 provides the express constitutional foundation for Judicial Review in India.', 'अनुच्छेद 13 भारत में न्यायिक पुनरावलोकन (Judicial Review) का मूल आधार है।'), ("What does the 'Doctrine of Severability' under Article 13 mean?", "अनुच्छेद 13 के तहत 'पृथक्करणीयता का सिद्धांत' (Doctrine of Severability) क्या है?", 'Only the unconstitutional part of a law is invalid if it can be severed from the valid part', 'यदि असंवैधानिक भाग को वैध भाग से अलग किया जा सकता है, तो केवल असंवैधानिक भाग ही शून्य होगा', ['The entire statute is automatically void if any section is invalid', 'Courts cannot sever statutory provisions', 'Applies only to constitutional amendments'], ['संपूर्ण कानून स्वतः शून्य हो जाता है', 'न्यायालय अलग नहीं कर सकते', 'केवल संशोधनों पर लागू होता है'], 'If the offending part can be separated from the rest without destroying legislative intent, only that part is struck down (A.K. Gopalan case).', 'यदि किसी कानून का असंवैधानिक हिस्सा शेष कानून से अलग किया जा सके, तो केवल वही हिस्सा अवैध होता है, पूरा कानून नहीं।'), ("The 'Doctrine of Eclipse' under Article 13 applies to", "अनुच्छेद 13 के तहत 'आच्छादन का सिद्धांत' (Doctrine of Eclipse) मुख्य रूप से किन विधियों पर लागू होता है?", 'Pre-constitutional laws that violate fundamental rights remain dormant or shadowed', 'संविधान-पूर्व की विधियां जो मूल अधिकारों का उल्लंघन करती हैं, वे सुप्त या आच्छादित हो जाती हैं', ['Post-constitutional laws that are void ab initio', 'Treaties with foreign nations', 'Ordinances issued by Governors'], ['संविधान-उत्तर विधियां जो प्रारंभ से शून्य होती हैं', 'विदेशी संधियां', 'राज्यपाल के अध्यादेश'], 'Formulated in Bhikaji Narain Dhakras v. State of MP (1955): pre-constitutional laws violating Part III are shadowed, not dead; an amendment can revive them.', 'भीकाजी नारायण मामले में प्रतिपादित: संविधान-पूर्व विधियां समाप्त नहीं होतीं, बल्कि मूल अधिकारों की छाया में छिप जाती हैं।'), ("What is the definition of 'State' under Article 12 of the Constitution?", "संविधान के अनुच्छेद 12 के अनुसार 'राज्य' (State) की परिभाषा में क्या शामिल है?", 'Government and Parliament of India, Government and Legislature of States, and all local or other authorities within India', 'भारत की सरकार व संसद, राज्यों की सरकारें व विधानमंडल, तथा भारत के राज्यक्षेत्र के भीतर सभी स्थानीय व अन्य प्राधिकारी', ['Only the Central Cabinet and Supreme Court', 'Only the President of India', 'Only State Governors and Chief Ministers'], ['केवल केंद्रीय कैबिनेट और सुप्रीम कोर्ट', 'केवल राष्ट्रपति', 'केवल राज्यपाल और मुख्यमंत्री'], "Article 12 defines 'State' broadly to enforce Fundamental Rights against all governmental agencies, municipalities, panchayats, and statutory corporations (like LIC, ONGC).", "अनुच्छेद 12 के तहत केंद्र सरकार, संसद, राज्य सरकारें, विधानमंडल, नगरपालिकाएं, पंचायतें और वैधानिक संस्थाएं 'राज्य' के अंतर्गत आती हैं।"), ('Under Article 14, what two concepts of equality are guaranteed to all persons within the territory of India?', 'अनुच्छेद 14 के तहत भारत के राज्यक्षेत्र में सभी व्यक्तियों को कौन से दो समानता के अधिकार प्राप्त हैं?', "'Equality before the Law' (British) and 'Equal Protection of the Laws' (American)", "'विधि के समक्ष समता' (ब्रिटिश) एवं 'विधियों का समान संरक्षण' (अमेरिकी)", ['Equal economic status and equal wages', 'Absolute identical treatment and social parity', 'Equal political representation and equal rights'], ['समान आर्थिक स्थिति एवं समान वेतन', 'पूर्ण एकरूपता एवं सामाजिक बराबरी', 'समान राजनीतिक प्रतिनिधित्व'], "'Equality before the Law' is a negative concept borrowed from Britain; 'Equal Protection of the Laws' is a positive concept borrowed from USA.", 'विधि के समक्ष समता ब्रिटेन से ली गई नकारात्मक अवधारणा है, जबकि विधियों का समान संरक्षण अमेरिका से ली गई सकारात्मक अवधारणा है।'), ("The Supreme Court held that 'Rule of Law' embodied in Article 14 is part of the 'Basic Structure' in", "सर्वोच्च न्यायालय ने किस मामले में स्पष्ट किया कि अनुच्छेद 14 में निहित 'विधि का शासन' संविधान का मूल ढांचा है?", 'Indira Nehru Gandhi v. Raj Narain (1975)', 'इंदिरा नेहरू गांधी बनाम राज नारायण (1975)', ['A.K. Gopalan case', 'Shankari Prasad case', 'Golaknath case'], ['ए.के. गोपालन मामला', 'शंकरी प्रसाद मामला', 'गोलकनाथ मामला'], 'The Supreme Court ruled that equality and the Rule of Law are foundational principles that cannot be abrogated even by constitutional amendment.', 'इंदिरा गांधी चुनाव मामले (1975) में विधि के शासन और समता को संविधान का अपरिवर्तनीय मूल ढांचा घोषित किया गया।'), ('Article 15 prohibits discrimination against any citizen on grounds ONLY of', 'अनुच्छेद 15 केवल किन आधारों पर राज्य द्वारा नागरिकों के प्रति किसी भेदभाव का निषेध करता है?', 'Religion, race, caste, sex, place of birth, or any of them', 'धर्म, मूलवंश, जाति, लिंग, जन्मस्थान या इनमें से किसी के आधार पर', ['Language, residence, literacy, wealth', 'Profession, property, education, nationality', 'Political ideology, party, union membership'], ['भाषा, निवास, साक्षरता, धन', 'पेशा, संपत्ति, शिक्षा, राष्ट्रीयता', 'राजनीतिक विचारधारा, दल'], 'The five specified grounds in Article 15(1) are: Religion, Race, Caste, Sex, and Place of birth.', 'अनुच्छेद 15(1) में केवल 5 आधारों (धर्म, मूलवंश, जाति, लिंग और जन्मस्थान) पर भेदभाव को निषिद्ध किया गया है।'), ('Which clause was added to Article 15 by the 103rd Constitutional Amendment Act, 2019 to provide 10% reservation for EWS?', '103वें संविधान संशोधन (2019) द्वारा सामान्य वर्ग के गरीबों (EWS) को 10% आरक्षण देने हेतु कौन सा उपबंध जोड़ा गया?', 'Article 15(6) and Article 16(6)', 'अनुच्छेद 15(6) एवं अनुच्छेद 16(6)', ['Article 15(4) and 16(4)', 'Article 15(5) and 16(5)', 'Article 15(3) and 16(3)'], ['अनुच्छेद 15(4) और 16(4)', 'अनुच्छेद 15(5) और 16(5)', 'अनुच्छेद 15(3) और 16(3)'], 'The 103rd Amendment added Article 15(6) and 16(6) to provide up to 10% reservation for Economically Weaker Sections (EWS).', '103वें संशोधन अधिनियम 2019 द्वारा अनुच्छेद 15(6) और 16(6) जोड़कर 10% ईडब्ल्यूएस आरक्षण लागू किया गया।'), ('Article 16 guarantees equality of opportunity for all citizens in matters relating to', 'संविधान का अनुच्छेद 16 सभी नागरिकों को किस संदर्भ में अवसर की समता की गारंटी देता है?', 'Employment or appointment to any office under the State', 'राज्य के अधीन किसी पद पर नियोजन या नियुक्ति में', ['Admission to private educational institutions', 'Holding agricultural land', 'Commercial business transactions'], ['निजी शिक्षण संस्थानों में प्रवेश', 'कृषि भूमि धारण करने में', 'व्यापारिक सौदों में'], 'Article 16(1) guarantees equality of opportunity in public employment under the State.', 'अनुच्छेद 16(1) सार्वजनिक रोजगार और राज्य के अधीन पदों पर नियुक्ति में सभी नागरिकों को समान अवसर देता है।'), ('Under Article 16(4), on what criteria can the State make reservation in appointments for backward classes?', 'अनुच्छेद 16(4) के तहत राज्य किन पिछड़े वर्गों के लिए नौकरियों में आरक्षण का प्रावधान कर सकता है?', 'If the class is not adequately represented in the services under the State', 'यदि उस वर्ग का राज्य की सेवाओं में पर्याप्त प्रतिनिधित्व नहीं है', ['On the basis of religion or language', 'Solely on the basis of poverty line criteria', 'Only for candidates with rural schooling'], ['धर्म या भाषा के आधार पर', 'केवल गरीबी रेखा के आधार पर', 'केवल ग्रामीण शिक्षा के आधार पर'], 'Article 16(4) empowers the State to reserve posts for any backward class which, in the opinion of the State, is not adequately represented.', 'यदि राज्य की राय में किसी पिछड़े वर्ग का सरकारी सेवाओं में पर्याप्त प्रतिनिधित्व नहीं है, तो आरक्षण दिया जा सकता है।'), ('In which landmark judgment of 1992 did the Supreme Court uphold 27% OBC reservation and cap total reservations at 50%?', 'किस ऐतिहासिक फैसले (1992) में सर्वोच्च न्यायालय ने 27% ओबीसी आरक्षण को वैध ठहराया और 50% की सीमा तय की?', 'Indra Sawhney v. Union of India (Mandal Case, 1992)', 'इंदिरा साहनी बनाम भारत संघ (मंडल केस, 1992)', ['Champakam Dorairajan case', 'M. Nagaraj case', 'Jarnail Singh case'], ['चंपाकम दोराईराजन मामला', 'एम. नागराज मामला', 'जरनैल सिंह मामला'], "A 9-judge bench upheld OBC reservation, excluded the 'creamy layer', and ruled that total reservation cannot exceed 50%.", "9 न्यायाधीशों की पीठ ने मंडल आयोग की 27% आरक्षण सिफारिश को वैध माना और 'क्रीमी लेयर' को बाहर करने का निर्देश दिया।"), ('Article 17 of the Constitution of India provides for the absolute abolition of', 'भारतीय संविधान का अनुच्छेद 17 पूर्णतः किस कुप्रथा के उन्मूलन का प्रावधान करता है?', 'Untouchability (अस्पृश्यता)', 'अस्पृश्यता (Untouchability)', ['Titles of nobility', 'Begar and forced labor', 'Child labor in factories'], ['उपाधियों का अंत', 'बेगार एवं बंधुआ मजदूरी', 'कारखानों में बाल श्रम'], "Article 17 abolishes 'Untouchability' and forbids its practice in any form; enforcement of disability is punishable by law.", 'अनुच्छेद 17 अस्पृश्यता (छुआछूत) का पूर्ण अंत करता है और इसका किसी भी रूप में आचरण दंडनीय अपराध है।'), ('Which parliamentary legislation was enacted to enforce the abolition of untouchability under Article 17?', 'अनुच्छेद 17 को प्रभावी बनाने के लिए संसद द्वारा कौन सा कानून पारित किया गया?', 'Protection of Civil Rights Act, 1955 (originally Untouchability Offences Act)', 'नागरिक अधिकार संरक्षण अधिनियम, 1955 (सिविल अधिकार संरक्षण अधिनियम)', ['SC and ST Prevention of Atrocities Act, 1989', 'National Human Rights Act', 'Equal Remuneration Act'], ['एससी-एसटी अत्याचार निवारण अधिनियम 1989', 'राष्ट्रीय मानवाधिकार अधिनियम', 'समान पारिश्रमिक अधिनियम'], 'The Untouchability (Offences) Act, 1955 was amended and renamed in 1976 as the Protection of Civil Rights Act, 1955.', "1955 का अस्पृश्यता अपराध अधिनियम 1976 में संशोधित होकर 'नागरिक अधिकार संरक्षण अधिनियम 1955' बना।"), ('Article 18 of the Constitution abolishes all titles EXCEPT', 'संविधान का अनुच्छेद 18 किन उपाधियों को छोड़कर अन्य सभी उपाधियों का निषेध करता है?', 'Military and Academic distinctions', 'सैन्य एवं शैक्षणिक विशिष्टताएं (Military & Academic)', ['Hereditary aristocratic titles', 'Religious honorific titles', 'Titles conferred by foreign states'], ['वंशानुगत सामंती उपाधियां', 'धार्मिक उपाधियां', 'विदेशी राज्यों की उपाधियां'], 'Article 18(1) prohibits the State from conferring any title except military or academic distinctions.', 'अनुच्छेद 18 केवल सेना और विद्या (शैक्षणिक) संबंधी सम्मानों को छोड़कर अन्य सभी उपाधियों पर रोक लगाता है।'), ('In Balaji Raghavan v. Union of India (1996), the Supreme Court ruled that National Awards (Bharat Ratna, Padma Vibhushan) are', 'बालाजी राघवन मामले (1996) में सर्वोच्च न्यायालय ने भारत रत्न और पद्म पुरस्कारों के संबंध में क्या निर्णय दिया?', "Valid meritorious decorations that do NOT amount to 'titles' under Article 18", "ये वैध राष्ट्रीय अलंकरण हैं जो अनुच्छेद 18 के तहत 'उपाधि' नहीं हैं", ['Unconstitutional titles that must be banned', 'Only permissible for military personnel', 'Titles that can be used as prefix or suffix'], ['असंवैधानिक उपाधियां जिन्हें बंद किया जाए', 'केवल सैनिकों को दिए जा सकते हैं', 'नाम के आगे-पीछे प्रयुक्त हो सकते हैं'], "The Supreme Court upheld the constitutional validity of National Awards, noting they cannot be used as prefixes or suffixes to the recipient's name.", 'सर्वोच्च न्यायालय ने माना कि भारत रत्न व पद्म पुरस्कार अलंकरण हैं, उपाधि नहीं; किंतु प्राप्तकर्ता इन्हें नाम के आगे-पीछे नहीं लगा सकते।'), ('Can a citizen of India accept any title from any foreign State without Presidential consent?', 'क्या भारत का कोई नागरिक राष्ट्रपति की सहमति के बिना किसी विदेशी राज्य से कोई उपाधि स्वीकार कर सकता है?', 'No, strictly prohibited under Article 18(2)', 'नहीं, अनुच्छेद 18(2) के तहत पूर्णतः निषिद्ध है', ['Yes, if approved by the Prime Minister', 'Yes, with permission of the Governor', 'Yes, if it carries monetary cash'], ['हां, प्रधानमंत्री की अनुमति से', 'हां, राज्यपाल की स्वीकृति से', 'हां, यदि नकद पुरस्कार हो'], 'Article 18(2) explicitly provides that no citizen of India shall accept any title from any foreign State.', 'अनुच्छेद 18(2) के अनुसार भारत का कोई भी नागरिक किसी विदेशी राज्य से कोई उपाधि स्वीकार नहीं करेगा।')]

slot_q113_fr_part1 = [('How many Fundamental Freedoms are currently guaranteed to Indian citizens under Article 19(1)?', 'वर्तमान में संविधान के अनुच्छेद 19(1) के तहत भारतीय नागरिकों को कितनी मूल स्वतंत्रताएं प्राप्त हैं?', '6 Freedoms', '6 मूल स्वतंत्रताएं', ['7 Freedoms', '8 Freedoms', '5 Freedoms'], ['7 स्वतंत्रताएं', '8 स्वतंत्रताएं', '5 स्वतंत्रताएं'], 'Originally 7 freedoms; the Right to acquire, hold, and dispose of property [Art 19(1)(f)] was deleted by the 44th Amendment in 1978.', 'मूलतः 7 स्वतंत्रताएं थीं; 44वें संशोधन (1978) द्वारा संपत्ति की स्वतंत्रता [19(1)(च)] को हटाकर 6 स्वतंत्रताएं छोड़ी गईं।'), ('Which Constitutional Amendment deleted the Right to Property from the list of Fundamental Rights in 1978?', "किस संविधान संशोधन अधिनियम द्वारा 1978 में 'संपत्ति के अधिकार' को मूल अधिकारों की सूची से हटाया गया?", '44th Constitutional Amendment Act, 1978', '44वां संविधान संशोधन अधिनियम (1978)', ['42nd Amendment Act, 1976', '24th Amendment Act, 1971', '86th Amendment Act, 2002'], ['42वां संशोधन (1976)', '24वां संशोधन (1971)', '86वां संशोधन (2002)'], 'The Janata Party government under Morarji Desai enacted the 44th Amendment, making property a legal right under Article 300A in Part XII.', 'मोरारजी देसाई की जनता पार्टी सरकार द्वारा 44वें संशोधन के तहत संपत्ति के अधिकार को अनुच्छेद 300क में कानूनी अधिकार बनाया गया।'), ('Freedom of the Press in India is implicitly guaranteed under which clause of Article 19?', "भारत में 'प्रेस की स्वतंत्रता' संविधान के किस अनुच्छेद के तहत अप्रत्यक्ष रूप से समाहित है?", 'Article 19(1)(a) — Freedom of Speech and Expression', 'अनुच्छेद 19(1)(क) — वाक् एवं अभिव्यक्ति की स्वतंत्रता', ['Article 19(1)(b)', 'Article 19(1)(c)', 'Article 21'], ['अनुच्छेद 19(1)(ख)', 'अनुच्छेद 19(1)(ग)', 'अनुच्छेद 21'], 'In Romesh Thappar (1950) and Indian Express (1985), the Supreme Court held freedom of the press is an essential part of Art 19(1)(a).', 'सर्वोच्च न्यायालय ने रोमेश थापर मामले में माना कि प्रेस की स्वतंत्रता अनुच्छेद 19(1)(क) में अभिव्यक्ति की स्वतंत्रता का ही हिस्सा है।'), ("On which grounds can the State impose 'reasonable restrictions' on Freedom of Speech under Article 19(2)?", 'अनुच्छेद 19(2) के तहत वाक् एवं अभिव्यक्ति की स्वतंत्रता पर किन आधारों पर युक्तिसंगत प्रतिबंध लगाए जा सकते हैं?', 'Sovereignty and integrity of India, security of the State, public order, decency, morality, contempt of court, defamation', 'भारत की संप्रभुता व अखंडता, राज्य की सुरक्षा, लोक व्यवस्था, शिष्टाचार या सदाचार, न्यायालय अवमानना, मानहानि', ['Economic poverty and unemployment', 'Any administrative discretion of local police', 'Political criticism of ruling party'], ['आर्थिक निर्धनता एवं बेरोजगारी', 'स्थानीय पुलिस का विवेक', 'सत्तारूढ़ दल की राजनीतिक आलोचना'], 'Article 19(2) specifies 8 grounds on which speech can be reasonably restricted; political criticism is not a valid ground.', 'अनुच्छेद 19(2) में संप्रभुता, सुरक्षा, लोक व्यवस्था, शिष्टाचार, मानहानि, न्यायालय अवमानना आदि 8 स्पष्ट आधार दिए गए हैं।'), ('The right to form associations, unions, or co-operative societies is guaranteed under', 'संघ, संगठन या सहकारी समितियां बनाने का मूल अधिकार किस अनुच्छेद के तहत प्राप्त है?', 'Article 19(1)(c)', 'अनुच्छेद 19(1)(ग) [Article 19(1)(c)]', ['Article 19(1)(a)', 'Article 19(1)(b)', 'Article 19(1)(d)'], ['अनुच्छेद 19(1)(क)', 'अनुच्छेद 19(1)(ख)', 'अनुच्छेद 19(1)(घ)'], "Article 19(1)(c) guarantees freedom to form associations or unions; the word 'co-operative societies' was added by 97th Amendment 2011.", "अनुच्छेद 19(1)(ग) संघ बनाने का अधिकार देता है; 97वें संशोधन (2011) द्वारा इसमें 'सहकारी समितियां' शब्द जोड़ा गया।"), ('The right of citizens to move freely throughout the territory of India is guaranteed under', 'भारत के संपूर्ण राज्यक्षेत्र में सर्वत्र अबाध संचरण (घूमने) की स्वतंत्रता किस अनुच्छेद में है?', 'Article 19(1)(d)', 'अनुच्छेद 19(1)(घ) [Article 19(1)(d)]', ['Article 19(1)(c)', 'Article 19(1)(e)', 'Article 21'], ['अनुच्छेद 19(1)(ग)', 'अनुच्छेद 19(1)(ङ)', 'अनुच्छेद 21'], 'Article 19(1)(d) guarantees internal movement across India; foreign travel (leaving India) is protected under Article 21 (Maneka Gandhi case).', 'भारत के भीतर घूमने का अधिकार अनुच्छेद 19(1)(घ) में है, जबकि विदेश यात्रा का अधिकार अनुच्छेद 21 के तहत सुरक्षित है।'), ('The right to reside and settle in any part of the territory of India is protected under', 'भारत के राज्यक्षेत्र के किसी भी भाग में निवास करने और बस जाने का अधिकार किस अनुच्छेद में है?', 'Article 19(1)(e)', 'अनुच्छेद 19(1)(ङ) [Article 19(1)(e)]', ['Article 19(1)(d)', 'Article 19(1)(f)', 'Article 19(1)(g)'], ['अनुच्छेद 19(1)(घ)', 'अनुच्छेद 19(1)(च)', 'अनुच्छेद 19(1)(छ)'], 'Article 19(1)(e) guarantees right to reside and settle anywhere in India, subject to reasonable restrictions to protect Scheduled Tribes.', 'अनुच्छेद 19(1)(ङ) सभी नागरिकों को भारत के किसी भी भाग में बसने की स्वतंत्रता देता है।'), ('The right to practice any profession, or to carry on any occupation, trade, or business is guaranteed under', 'कोई भी वृत्ति, उपजीविका, व्यापार या कारोबार करने की स्वतंत्रता किस अनुच्छेद में है?', 'Article 19(1)(g)', 'अनुच्छेद 19(1)(छ) [Article 19(1)(g)]', ['Article 19(1)(e)', 'Article 19(1)(f)', 'Article 20'], ['अनुच्छेद 19(1)(ङ)', 'अनुच्छेद 19(1)(च)', 'अनुच्छेद 20'], 'Article 19(1)(g) protects lawful trade and occupation; does not include immoral or dangerous businesses (like trafficking).', 'अनुच्छेद 19(1)(छ) वैध व्यापार, व्यवसाय और आजीविका की स्वतंत्रता देता है।'), ('Article 20 provides protection in respect of conviction for offences through which three safeguards?', 'अनुच्छेद 20 अपराधों के लिए दोषसिद्धि के संबंध में कौन से तीन महत्वपूर्ण संरक्षण प्रदान करता है?', 'No ex-post facto law, No Double Jeopardy, and No Self-Incrimination', 'कार्य-उत्तर विधि से संरक्षण (Ex-post facto), दोहरे दंड से मुक्ति (Double Jeopardy), एवं आत्म-अभिशंसन से संरक्षण', ['Right to bail, right to parole, right to pardon', 'Right to appeal, right to jury, right to counsel', 'No arrest, no detention, no trial'], ['जमानत का अधिकार, पैरोल, क्षमादान', 'अपील का अधिकार, जूरी, वकील', 'गिरफ्तारी नहीं, हिरासत नहीं, मुकदमा नहीं'], 'Article 20(1) bans ex-post facto criminal laws; 20(2) prevents double jeopardy; 20(3) forbids compelling an accused to witness against himself.', 'अनुच्छेद 20 भूतलक्षी आपराधिक विधियों पर रोक, एक ही अपराध के लिए दो बार दंड से मुक्ति, और स्वयं के विरुद्ध गवाही देने से छूट देता है।'), ("What does 'Double Jeopardy' under Article 20(2) mean?", "अनुच्छेद 20(2) के तहत 'दोहरा दंड' (Double Jeopardy) का क्या अर्थ है?", 'No person shall be prosecuted and punished for the same offence more than once', 'किसी व्यक्ति को एक ही अपराध के लिए एक से अधिक बार अभियोजित और दंडित नहीं किया जाएगा', ['A person cannot be arrested twice in a lifetime', 'A person cannot be fined and jailed together', 'Applies to departmental inquiries as well as courts'], ['एक व्यक्ति को जीवन में दो बार गिरफ्तार नहीं किया जा सकता', 'जुर्माना और जेल एक साथ नहीं हो सकते', 'विभागीय जांच पर भी लागू होता है'], 'Article 20(2) applies only to proceedings before a court of law or judicial tribunal, not administrative departmental actions.', 'एक ही अपराध के लिए न्यायालय द्वारा किसी व्यक्ति को दोबारा मुकदमा चलाकर सजा नहीं दी जा सकती।'), ("Which Article of the Constitution guarantees the 'Protection of Life and Personal Liberty'?", "भारतीय संविधान का कौन सा अनुच्छेद 'प्राण एवं दैहिक स्वतंत्रता के संरक्षण' की गारंटी देता है?", 'Article 21', 'अनुच्छेद 21', ['Article 19', 'Article 20', 'Article 22'], ['अनुच्छेद 19', 'अनुच्छेद 20', 'अनुच्छेद 22'], 'Article 21 provides that no person shall be deprived of his life or personal liberty except according to procedure established by law.', 'अनुच्छेद 21 घोषित करता है कि किसी व्यक्ति को उसके प्राण या दैहिक स्वतंत्रता से विधि द्वारा स्थापित प्रक्रिया के अनुसार ही वंचित किया जाएगा।'), ("In which landmark judgment of 1978 did the Supreme Court expand Article 21 to include 'Due Process of Law'?", "किस ऐतिहासिक मामले (1978) में सर्वोच्च न्यायालय ने अनुच्छेद 21 की व्याख्या कर 'विधि की उचित प्रक्रिया' (Due Process) को शामिल किया?", 'Maneka Gandhi v. Union of India (1978)', 'मेनका गांधी बनाम भारत संघ (1978)', ['A.K. Gopalan case (1950)', 'Kharak Singh case (1963)', 'ADM Jabalpur case (1976)'], ['ए.के. गोपालन मामला (1950)', 'खड़क सिंह मामला (1963)', 'एडीएम जबलपुर मामला (1976)'], "Overruling A.K. Gopalan, the 7-judge bench held that procedure under Article 21 must be 'just, fair, and reasonable', incorporating due process.", 'मेनका गांधी मामले में सुप्रीम कोर्ट ने माना कि प्राण व स्वतंत्रता छीनने वाली विधि न्यायपूर्ण, निष्पक्ष और तार्किक (Just, Fair & Reasonable) होनी चाहिए।'), ('In K.S. Puttaswamy v. Union of India (2017), a 9-judge bench unanimously declared that', 'के.एस. पुट्टास्वामी बनाम भारत संघ मामले (2017) में 9 न्यायाधीशों की संविधान पीठ ने सर्वसम्मति से क्या फैसला दिया?', "The 'Right to Privacy' is a Fundamental Right intrinsically protected under Article 21", "'निजता का अधिकार' (Right to Privacy) अनुच्छेद 21 के तहत अंतर्निहित एक मौलिक अधिकार है", ['Privacy is only a common law right', 'Aadhaar card is unconstitutional in its entirety', 'Internet access is not a fundamental right'], ['निजता केवल एक सामान्य कानूनी अधिकार है', 'आधार कार्ड पूर्णतः असंवैधानिक है', 'इंटरनेट मौलिक अधिकार नहीं है'], 'All 9 judges unanimously held privacy is an intrinsic part of the Right to Life and Personal Liberty under Article 21.', 'सर्वोच्च न्यायालय की 9-न्यायाधीशों की पीठ ने ऐतिहासिक फैसला देते हुए निजता के अधिकार को अनुच्छेद 21 के तहत मूल अधिकार घोषित किया।'), ('By which Constitutional Amendment Act was Article 21A (Right to Education) inserted into the Constitution?', "किस संविधान संशोधन अधिनियम द्वारा संविधान में अनुच्छेद 21क जोड़कर 'शिक्षा का अधिकार' मूल अधिकार बनाया गया?", '86th Constitutional Amendment Act, 2002', '86वां संविधान संशोधन अधिनियम (2002)', ['44th Amendment Act, 1978', '91st Amendment Act, 2003', '93rd Amendment Act, 2005'], ['44वां संशोधन (1978)', '91वां संशोधन (2003)', '93वां संशोधन (2005)'], "Enacted under Atal Bihari Vajpayee's tenure, making free and compulsory education for children aged 6 to 14 a Fundamental Right.", '86वें संशोधन अधिनियम (2002) द्वारा 6 से 14 वर्ष के बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा को मौलिक अधिकार बनाया गया।'), ('Under Article 21A, free and compulsory education is guaranteed to children of which age group?', 'अनुच्छेद 21क के तहत किस आयु वर्ग के बच्चों के लिए निःशुल्क एवं अनिवार्य शिक्षा का प्रावधान है?', '6 to 14 years of age', '6 से 14 वर्ष की आयु के बच्चों के लिए', ['0 to 6 years of age', '6 to 18 years of age', '3 to 12 years of age'], ['0 से 6 वर्ष के बच्चों के लिए', '6 से 18 वर्ष के लिए', '3 से 12 वर्ष के लिए'], 'Article 21A guarantees free and compulsory education to all children of the age of six to fourteen years.', 'अनुच्छेद 21क के अनुसार राज्य 6 से 14 वर्ष तक की आयु के सभी बालकों के लिए अनिवार्य शिक्षा की व्यवस्था करेगा।'), ('On which date did the Right of Children to Free and Compulsory Education (RTE) Act, 2009 come into force?', 'निःशुल्क एवं अनिवार्य बाल शिक्षा का अधिकार अधिनियम (RTE Act, 2009) किस तिथि से देश में लागू हुआ था?', '1 April 2010', '1 अप्रैल 2010 से', ['1 April 2009', '26 January 2010', '15 August 2009'], ['1 अप्रैल 2009 से', '26 जनवरी 2010 से', '15 अगस्त 2009 से'], 'Enacted in 2009 to operationalize Article 21A, the RTE Act came into legal force across India on 1 April 2010.', 'शिक्षा का अधिकार कानून (RTE Act) पूरे देश में 1 अप्रैल 2010 से प्रभावी हुआ था।'), ('Article 22 of the Constitution provides protection against', 'भारतीय संविधान का अनुच्छेद 22 मुख्य रूप से किससे संरक्षण प्रदान करता है?', 'Arrest and Detention in certain cases', 'कुछ दशाओं में गिरफ्तारी और निरोध से संरक्षण', ['Double Jeopardy', 'Ex-post facto laws', 'Forced labor and trafficking'], ['दोहरा दंड', 'कार्य-उत्तर विधियां', 'बंधुआ मजदूरी व मानव तस्करी'], 'Article 22 grants rights to arrested persons under ordinary law and provides safeguards under preventive detention laws.', 'अनुच्छेद 22 सामान्य कानून में गिरफ्तार व्यक्ति के अधिकार और निवारक निरोध (Preventive Detention) से जुड़े संरक्षण देता है।'), ('Under Article 22(1), an arrested person must be produced before the nearest magistrate within what time limit?', 'अनुच्छेद 22(2) के अनुसार गिरफ्तार किए गए व्यक्ति को कितने समय के भीतर निकटतम मजिस्ट्रेट के समक्ष पेश करना अनिवार्य है?', 'Within 24 hours (excluding journey time)', '24 घंटे के भीतर (यात्रा का समय छोड़कर)', ['Within 12 hours', 'Within 48 hours', 'Within 7 days'], ['12 घंटे के भीतर', '48 घंटे के भीतर', '7 दिनों के भीतर'], 'Article 22(2) requires production before a magistrate within 24 hours of arrest, excluding time necessary for the journey.', 'गिरफ्तारी के 24 घंटे के अंदर (यात्रा समय को काटकर) व्यक्ति को मजिस्ट्रेट के समक्ष पेश किया जाना संवैधानिक अधिकार है।'), ('Under ordinary preventive detention laws, what is the maximum period a person can be detained without Advisory Board approval?', 'निवारक निरोध कानून के तहत किसी व्यक्ति को सलाहकार बोर्ड की सिफारिश के बिना अधिकतम कितने समय तक हिरासत में रखा जा सकता है?', '3 Months (reduced to 2 months by 44th Amendment, but not yet notified)', '3 माह (3 Months)', ['1 Month', '6 Months', '1 Year'], ['1 माह', '6 माह', '1 वर्ष'], 'Under Article 22(4), detention beyond 3 months requires approval of an Advisory Board consisting of High Court judges.', 'अनुच्छेद 22(4) के तहत बिना सलाहकार बोर्ड की मंजूरी के अधिकतम 3 महीने तक ही निवारक निरोध में रखा जा सकता है।'), ('Who heads the Advisory Board constituted to review preventive detention under Article 22?', 'अनुच्छेद 22 के तहत निवारक निरोध की समीक्षा करने वाले सलाहकार बोर्ड के सदस्य कौन होते हैं?', 'Persons who are, or have been, or are qualified to be appointed as Judges of a High Court', 'उच्च न्यायालय के न्यायाधीश, भूतपूर्व न्यायाधीश अथवा नियुक्त होने की योग्यता रखने वाले व्यक्ति', ['District Magistrates and Police Commissioners', 'Cabinet Ministers of State Government', 'Members of Parliament'], ['जिला मजिस्ट्रेट एवं पुलिस कमिश्नर', 'राज्य के कैबिनेट मंत्री', 'संसद सदस्य'], 'Article 22(4)(a) specifies the Advisory Board must consist of persons of High Court judicial caliber.', 'सलाहकार बोर्ड में उच्च न्यायालय के वर्तमान, पूर्व अथवा योग्य न्यायाधीश शामिल होते हैं।'), ('Article 23 of the Constitution of India prohibits', 'भारतीय संविधान का अनुच्छेद 23 किस पर पूर्ण प्रतिबंध लगाता है?', "Traffic in human beings, 'begar', and other similar forms of forced labor", 'मानव दुर्व्यापार, बेगार तथा इसी प्रकार का अन्य बलात श्रम', ['Employment of children in factories', 'Untouchability', 'Titles and honors'], ['कारखानों में बच्चों का नियोजन', 'छुआछूत', 'उपाधियां'], 'Article 23 prohibits human trafficking, beggar (unpaid forced work), and bonded labor, making violation an offence punishable by law.', 'अनुच्छेद 23 मानव तस्करी, बंधुआ मजदूरी और बिना पारिश्रमिक के बेगार कराने को पूर्णतः गैरकानूनी घोषित करता है।'), ('Which parliamentary legislation was enacted in 1976 to implement the prohibition of forced labor under Article 23?', 'अनुच्छेद 23 के तहत बलात श्रम के उन्मूलन हेतु 1976 में कौन सा महत्वपूर्ण कानून बनाया गया?', 'Bonded Labour System (Abolition) Act, 1976', 'बंधुआ श्रम प्रणाली (उन्मूलन) अधिनियम, 1976', ['Minimum Wages Act, 1948', 'Factories Act, 1948', 'Trade Unions Act, 1926'], ['न्यूनतम मजदूरी अधिनियम', 'कारखाना अधिनियम', 'ट्रेड यूनियन अधिनियम'], 'Enacted in 1976 to free bonded laborers, extinguish bonded debts, and rehabilitate victims.', '1976 में बंधुआ मजदूरी उन्मूलन कानून बनाकर सभी बंधुआ मजदूरों को ऋणमुक्त व आजाद कराया गया।'), ('Article 24 of the Constitution strictly prohibits the employment of children below what age in factories or hazardous employment?', 'संविधान का अनुच्छेद 24 कितने वर्ष से कम आयु के बच्चों को कारखानों, खानों या अन्य जोखिम भरे कार्यों में लगाने पर रोक लगाता है?', 'Below 14 years of age', '14 वर्ष से कम आयु के बालकों पर', ['Below 16 years of age', 'Below 18 years of age', 'Below 12 years of age'], ['16 वर्ष से कम', '18 वर्ष से कम', '12 वर्ष से कम'], 'Article 24 prohibits employment of children below the age of fourteen years in factories, mines, or hazardous jobs.', 'अनुच्छेद 24 के तहत 14 वर्ष से कम उम्र के किसी भी बालक को किसी कारखाने, खान या जोखिम भरे रोजगार में नहीं लगाया जा सकता।'), ('The Child and Adolescent Labour (Prohibition and Regulation) Amendment Act, 2016 completely prohibited employment of children below 14 in', 'बाल एवं किशोर श्रम (निषेध और विनियमन) संशोधन अधिनियम 2016 ने 14 वर्ष से कम आयु के बच्चों के नियोजन पर क्या प्रतिबंध लगाया?', 'All occupations and processes (with exceptions only for family businesses outside school hours)', 'सभी व्यवसायों और प्रक्रियाओं में पूर्ण प्रतिबंध (स्कूल समय के बाद पारिवारिक उद्यम को छोड़कर)', ['Only in nuclear plants and chemical factories', 'Only in deep underground mines', 'Allowed work during daytime hours'], ['केवल परमाणु व रासायनिक संयंत्रों में', 'केवल भूमिगत खदानों में', 'दिन के समय कार्य की अनुमति'], 'The 2016 Amendment banned all employment of children below 14 across all sectors and banned adolescents (14-18) in hazardous occupations.', '2016 के संशोधन द्वारा 14 वर्ष से कम उम्र के बच्चों से किसी भी प्रकार का काम करवाने पर पूर्ण प्रतिबंध लगा दिया गया।'), ('Can the State impose compulsory service for public purposes (like military conscription) under Article 23?', 'क्या राज्य अनुच्छेद 23 के तहत सार्वजनिक प्रयोजनों (जैसे सैन्य सेवा) के लिए अनिवार्य सेवा लागू कर सकता है?', 'Yes, provided no discrimination is made on grounds only of religion, race, caste, or class', 'हां, बशर्ते धर्म, मूलवंश, जाति या वर्ग के आधार पर कोई भेदभाव न किया जाए', ['No, absolutely prohibited under all circumstances', 'Yes, but only for private factory workers', 'Yes, but only during wartime emergencies'], ['नहीं, किसी भी स्थिति में नहीं', 'हां, केवल निजी कामगारों के लिए', 'हां, केवल आपातकाल में'], 'Article 23(2) permits the State to impose compulsory service for public purposes without discriminating on religion, race, caste, or class.', 'अनुच्छेद 23(2) राज्य को देशहित में अनिवार्य सैन्य या सामाजिक सेवा लेने की अनुमति देता है, यदि उसमें कोई भेदभाव न हो।'), ('Which Fundamental Rights cannot be suspended even during a National Emergency declared under Article 352?', 'अनुच्छेद 352 के तहत राष्ट्रीय आपातकाल के दौरान भी कौन से दो मूल अधिकार कभी निलंबित नहीं किए जा सकते?', 'Articles 20 and 21', 'अनुच्छेद 20 एवं अनुच्छेद 21', ['Articles 19 and 21', 'Articles 14 and 19', 'Articles 21 and 22'], ['अनुच्छेद 19 और 21', 'अनुच्छेद 14 और 19', 'अनुच्छेद 21 और 22'], 'The 44th Amendment Act 1978 amended Article 359 to provide that enforcement of Articles 20 and 21 can never be suspended.', '44वें संविधान संशोधन (1978) के बाद अनुच्छेद 20 और 21 को आपातकाल में भी निलंबित नहीं किया जा सकता।'), ("In which historic case did the Supreme Court hold that the 'Right to Clean Environment' and pollution-free water/air is part of Article 21?", "सर्वोच्च न्यायालय ने किस ऐतिहासिक मामले में 'स्वच्छ पर्यावरण एवं प्रदूषण-मुक्त जल/वायु के अधिकार' को अनुच्छेद 21 का अंग माना?", 'Subhash Kumar v. State of Bihar (1991) and M.C. Mehta cases', 'सुभाष कुमार बनाम बिहार राज्य (1991) एवं एम.सी. मेहता मामले', ['A.K. Gopalan case', 'Golaknath case', 'Bhanumati case'], ['ए.के. गोपालन मामला', 'गोलकनाथ मामला', 'भानुमति मामला'], 'The Supreme Court ruled that life under Article 21 means life of dignity in a wholesome, clean, and pollution-free environment.', 'सुप्रीम कोर्ट ने सुभाष कुमार बनाम बिहार राज्य मामले में स्वच्छ पर्यावरण के अधिकार को जीवन के अधिकार का अभिन्न अंग माना।'), ('The right to speedy trial in criminal proceedings is an implicit Fundamental Right under which Article?', "आपराधिक मामलों में 'त्वरित विचारण का अधिकार' (Right to Speedy Trial) किस अनुच्छेद के तहत एक मूल अधिकार है?", 'Article 21 (Hussainara Khatoon case, 1979)', 'अनुच्छेद 21 (हुसैनआरा खातून मामला, 1979)', ['Article 20', 'Article 22', 'Article 14'], ['अनुच्छेद 20', 'अनुच्छेद 22', 'अनुच्छेद 14'], 'Hussainara Khatoon v. Home Secretary, Bihar (1979) established the right to speedy trial for undertrial prisoners under Article 21.', 'हुसैनआरा खातून बनाम बिहार राज्य मामले में जेलों में बंद विचाराधीन कैदियों के लिए त्वरित सुनवाई को अनुच्छेद 21 का हिस्सा माना गया।'), ('The right to free legal aid for poor and indigent accused is a Fundamental Right flowing from Article 21 as held in', "निर्धन और असहाय अभियुक्तों के लिए 'निःशुल्क विधिक सहायता का अधिकार' अनुच्छेद 21 का हिस्सा किस मामले में ठहराया गया?", 'M.H. Hoskot v. State of Maharashtra (1978) and Khatri v. State of Bihar (1981)', 'एम.एच. होसकोट मामला (1978) एवं खत्री बनाम बिहार राज्य (भागलपुर अंखफोड़वा कांड, 1981)', ['Shankari Prasad case', 'Minerva Mills case', 'Berubari case'], ['शंकरी प्रसाद मामला', 'मिनर्वा मिल्स मामला', 'बेरुबारी मामला'], 'The Supreme Court declared state-funded free legal aid to indigent accused is an inalienable component of fair procedure under Article 21.', 'सर्वोच्च न्यायालय ने स्पष्ट किया कि गरीब अभियुक्त को वकील और कानूनी सहायता देना राज्य का संवैधानिक कर्तव्य है।'), ('In Sunil Batra v. Delhi Administration (1978), the Supreme Court ruled that solitary confinement and inhumane bar-fetters violate', 'सुनील बत्रा बनाम दिल्ली प्रशासन (1978) में सर्वोच्च न्यायालय ने एकांत कारावास और अमानवीय बेड़ियों को किस अनुच्छेद का उल्लंघन माना?', 'Article 21 and Article 14', 'अनुच्छेद 21 एवं अनुच्छेद 14', ['Article 19 only', 'Article 20 only', 'Article 22 only'], ['केवल अनुच्छेद 19', 'केवल अनुच्छेद 20', 'केवल अनुच्छेद 22'], 'Prisoners retain all fundamental rights not stripped by lawful incarceration; cruel prison torture violates Article 21.', 'जेल में बंद कैदियों के भी मानवीय अधिकार होते हैं; उन्हें अमानवीय यातना देना अनुच्छेद 21 का हनन है।'), ('Which landmark judgment decriminalized consensual same-sex relations by reading down Section 377 of IPC under Article 21?', 'किस ऐतिहासिक फैसले ने वयस्कों के बीच समलैंगिक संबंधों को अपराध की श्रेणी से बाहर कर अनुच्छेद 21 के तहत मान्यता दी?', 'Navtej Singh Johar v. Union of India (2018)', 'नवतेज सिंह जौहर बनाम भारत संघ (2018)', ['Suresh Kumar Koushal case', 'Shayara Bano case', 'Joseph Shine case'], ['सुरेश कौशल मामला', 'शायरा बानो मामला', 'जोसेफ शाइन मामला'], 'A 5-judge Constitution Bench unanimously struck down Section 377 IPC to the extent it criminalized consensual adult gay sex.', 'सर्वोच्च न्यायालय की संविधान पीठ ने नवतेज जौहर मामले में धारा 377 के दंडात्मक प्रावधानों को निरस्त कर दिया।'), ('In Shayara Bano v. Union of India (2017), the Supreme Court declared which practice unconstitutional for violating Articles 14 and 21?', 'शायरा बानो बनाम भारत संघ (2017) में सुप्रीम कोर्ट ने किस प्रथा को अनुच्छेद 14 और 21 का उल्लंघन मानकर असंवैधानिक घोषित किया?', 'Talaq-e-Biddat (Instant Triple Talaq)', 'तलाक-ए-बिद्दत (एक बार में तीन तलाक / Instant Triple Talaq)', ['Polygamy', 'Nikah Halala', 'Inheritance distribution'], ['बहुविवाह', 'निकाह हलाला', 'उत्तराधिकार बंटवारा'], 'A 5-judge bench held instant triple talaq is arbitrary and violates gender equality guaranteed under Article 14.', 'सर्वोच्च न्यायालय ने एक बार में तीन तलाक को मनमाना और मुस्लिम महिलाओं के समानता के अधिकार का उल्लंघन माना।'), ('The right to livelihood as an integral facet of the Right to Life under Article 21 was established in', 'आजीविका के अधिकार (Right to Livelihood) को अनुच्छेद 21 के तहत जीवन के अधिकार का अंग किस मामले में माना गया?', 'Olga Tellis v. Bombay Municipal Corporation (1985)', 'ओल्गा टेलिस बनाम बॉम्बे नगर निगम (1985)', ['A.K. Gopalan case', 'Maneka Gandhi case', 'Golaknath case'], ['ए.के. गोपालन मामला', 'मेनका गांधी मामला', 'गोलकनाथ मामला'], 'The Supreme Court held that the right to life includes the right to livelihood; without means of earning, life is reduced to mere existence.', 'ओल्गा टेलिस मामले में फुटपाथ और झुग्गीवासियों के संदर्भ में माना गया कि आजीविका छीनना जीवन छीनने के समान है।'), ('In Common Cause v. Union of India (2018), the Supreme Court recognized which right under Article 21?', 'कॉमन कॉज बनाम भारत संघ (2018) में सर्वोच्च न्यायालय ने अनुच्छेद 21 के तहत किस अधिकार को मान्यता दी?', 'Right to die with dignity through Passive Euthanasia and Living Wills', 'निष्क्रिय इच्छामृत्यु (Passive Euthanasia) और लिविंग विल के माध्यम से गरिमापूर्ण मृत्यु का अधिकार', ['Right to Active Euthanasia by lethal injection', 'Right to commit suicide without medical advice', 'Compulsory medical retirement'], ['घातक इंजेक्शन से सक्रिय इच्छामृत्यु', 'बिना सलाह आत्महत्या का अधिकार', 'अनिवार्य सेवानिवृत्ति'], 'A 5-judge bench recognized the right to die with dignity for terminally ill patients in permanent vegetative state via passive euthanasia.', 'सुप्रीम कोर्ट ने माना कि असाध्य रोग से पीड़ित मरणासन्न व्यक्ति को सम्मानपूर्वक मृत्यु व लाइफ-सपोर्ट हटाने का अधिकार है।'), ('Which Article prohibits the State from detaining a citizen without informing the grounds of arrest as soon as may be?', 'संविधान का कौन सा अनुच्छेद गिरफ्तारी के आधारों की शीघ्र सूचना दिए बिना किसी नागरिक को हिरासत में रखने पर रोक लगाता है?', 'Article 22(1)', 'अनुच्छेद 22(1)', ['Article 21', 'Article 20(1)', 'Article 19(2)'], ['अनुच्छेद 21', 'अनुच्छेद 20(1)', 'अनुच्छेद 19(2)'], 'Article 22(1) mandates that no person who is arrested shall be detained in custody without being informed of the grounds for such arrest.', 'अनुच्छेद 22(1) के अनुसार गिरफ्तार किए गए व्यक्ति को यथाशीघ्र गिरफ्तारी के कारण बताए बिना अभिरक्षा में निरुद्ध नहीं रखा जाएगा।'), ('Does a person arrested under preventive detention law have the right to consult and be defended by a legal practitioner under Art 22(1)?', 'क्या निवारक निरोध कानून के तहत गिरफ्तार व्यक्ति को अनुच्छेद 22(1) के तहत वकील से परामर्श का सामान्य अधिकार मिलता है?', 'No, Article 22(3) explicitly denies protection of clauses (1) and (2) to enemy aliens and preventive detainees', 'नहीं, अनुच्छेद 22(3) स्पष्ट रूप से शत्रु देश के नागरिकों और निवारक निरोध के बंदियों को यह संरक्षण नहीं देता', ['Yes, available to all individuals equally', 'Yes, with permission of the Home Minister', 'Only if the detained person is a woman'], ['हां, सभी को समान रूप से उपलब्ध है', 'हां, गृह मंत्री की अनुमति से', 'केवल महिला बंदियों के लिए'], 'Article 22(3) provides that nothing in clauses (1) and (2) shall apply to any person arrested under any law providing for preventive detention.', 'अनुच्छेद 22(3) के अनुसार निवारक निरोध कानून के अंतर्गत पकड़े गए व्यक्ति को 24 घंटे में मजिस्ट्रेट के सामने पेश करने का नियम लागू नहीं होता।'), ('The National Security Act (NSA) was enacted by Parliament in which year?', "भारतीय संसद द्वारा 'राष्ट्रीय सुरक्षा कानून' (NSA / रासुका) किस वर्ष पारित किया गया था?", '1980', '1980 में', ['1971', '1985', '2002'], ['1971 में', '1985 में', '2002 में'], 'The National Security Act 1980 provides for preventive detention to maintain defense, foreign relations, or public order.', 'देश की सुरक्षा और कानून-व्यवस्था बनाए रखने के लिए 1980 में राष्ट्रीय सुरक्षा कानून (रासुका) बनाया गया।'), ('The Conservation of Foreign Exchange and Prevention of Smuggling Activities Act (COFEPOSA) was passed in', 'तस्करी की रोकथाम और विदेशी मुद्रा संरक्षण अधिनियम (COFEPOSA) किस वर्ष बनाया गया था?', '1974', '1974 में', ['1968', '1980', '1999'], ['1968 में', '1980 में', '1999 में'], 'COFEPOSA 1974 is a preventive detention law used against smugglers and economic offenders.', 'आर्थिक अपराधों और विदेशी मुद्रा तस्करी पर रोक लगाने हेतु 1974 में कोफेपोसा (COFEPOSA) कानून लागू हुआ।'), ('The Terrorist and Disruptive Activities (Prevention) Act (TADA) of 1985 lapsed in which year?', "1985 में लागू किया गया विवादास्पद 'टाडा' (TADA) कानून किस वर्ष समाप्त (व्यपगत) हुआ था?", '1995', '1995 में', ['1990', '2000', '2004'], ['1990 में', '2000 में', '2004 में'], 'TADA lapsed in 1995 due to widespread criticism regarding human rights abuse and low conviction rates.', 'दुरुपयोग के आरोपों के कारण टाडा कानून को 1995 में आगे नहीं बढ़ाया गया और वह समाप्त हो गया।'), ('The Prevention of Terrorism Act (POTA) enacted in 2002 was repealed by Parliament in which year?', "2002 में संसद के संयुक्त अधिवेशन में पारित 'पोटा' (POTA) कानून को किस वर्ष निरस्त किया गया?", '2004', '2004 में', ['2006', '2008', '2014'], ['2006 में', '2008 में', '2014 में'], 'POTA was repealed in 2004 by the UPA government; anti-terror provisions were later strengthened in UAPA.', '2004 में नई सरकार द्वारा पोटा कानून को संसद में अधिनियम पारित कर निरस्त कर दिया गया।'), ('Under the Unlawful Activities (Prevention) Act (UAPA), as amended in 2019, the Central Government can designate', 'गैरकानूनी गतिविधियां (रोकथाम) अधिनियम (UAPA) में 2019 के संशोधन द्वारा केंद्र सरकार को क्या अधिकार मिला?', "An individual as a 'Terrorist' in addition to organizations", "संगठनों के साथ-साथ किसी व्यक्ति विशेष को भी 'आतंकवादी' घोषित करने का अधिकार", ['Confiscate all private bank accounts without court order', 'Impose death penalty without trial', 'Banish individuals from Indian territory'], ['बिना कोर्ट आदेश निजी खाते जब्त करना', 'बिना मुकदमे फांसी देना', 'देश से निष्कासित करना'], 'The 2019 amendment empowered the Union Government to designate individuals as terrorists if they commit or participate in terrorism.', '2019 के UAPA संशोधन द्वारा सरकार को किसी व्यक्ति विशेष को भी आतंकवादी घोषित करने की शक्ति प्रदान की गई।'), ('In D.K. Basu v. State of West Bengal (1997), the Supreme Court laid down mandatory guidelines regarding', 'डी.के. बसु बनाम पश्चिम बंगाल राज्य मामले (1997) में सर्वोच्च न्यायालय ने किसके संबंध में अनिवार्य दिशा-निर्देश जारी किए?', 'Arrest, custody, interrogation, and prevention of custodial violence and torture by police', 'पुलिस द्वारा गिरफ्तारी, हिरासत, पूछताछ और हिरासत में होने वाली हिंसा (कस्टोडियल टॉर्चर) की रोकथाम हेतु', ['Environmental air quality monitoring', 'Electoral campaign financing', 'School fee regulation'], ['वायु प्रदूषण की निगरानी', 'चुनावी चंदा विनियमन', 'स्कूल फीस नियमन'], 'Laid down 11 binding guidelines (memo of arrest, inspection memo, informing relatives, medical checkup every 48 hours).', 'डी.के. बसु दिशा-निर्देशों के तहत गिरफ्तारी मेमो बनाना, परिजनों को सूचना देना और 48 घंटे में मेडिकल जांच अनिवार्य है।'), ('Can the police extract involuntary narco-analysis, polygraph (lie-detector), or brain-mapping tests from an accused?', 'क्या पुलिस किसी अभियुक्त से उसकी सहमति के बिना नार्को-टेस्ट, पॉलीग्राफ या ब्रेन-मैपिंग करा सकती है?', 'No, strictly prohibited as a violation of Article 20(3) and Article 21', 'नहीं, अनुच्छेद 20(3) और 21 का उल्लंघन होने के कारण बिना सहमति पूर्णतः अवैध है', ['Yes, routinely permitted in all criminal investigations', 'Yes, with permission of an ACP or SP', 'Only if the accused is a non-citizen'], ['हां, सभी मामलों में अनुमति है', 'हां, एसपी की अनुमति से', 'केवल गैर-नागरिकों के लिए'], 'In Selvi v. State of Karnataka (2010), the Supreme Court held involuntary neuro-scientific techniques violate the right against self-incrimination.', 'सेल्वी मामले (2010) में सुप्रीम कोर्ट ने माना कि बिना सहमति नार्को या पॉलीग्राफ टेस्ट कराना आत्म-अभिशंसन और निजता का उल्लंघन है।'), ('In Arnesh Kumar v. State of Bihar (2014), the Supreme Court held that police should not automatically arrest an accused in offences punishable with', 'अर्णेश कुमार बनाम बिहार राज्य (2014) में सुप्रीम कोर्ट ने किन अपराधों में स्वतः गिरफ्तारी न करने का निर्देश दिया?', 'Imprisonment up to 7 years (without satisfying conditions under Section 41 CrPC)', '7 वर्ष तक की सजा वाले अपराधों में (धारा 41 CrPC की शर्तों को पूरा किए बिना)', ['Offences punishable with life imprisonment', 'Bailable civil infractions only', 'Offences punishable with death penalty'], ['आजीवन कारावास वाले अपराधों में', 'केवल जमानती मामलों में', 'मृत्युदंड वाले अपराधों में'], 'Mandated that for offences punishable with up to 7 years jail (like Section 498A IPC), notice under 41A CrPC should precede arrest.', 'दहेज उत्पीड़न (498A) जैसे 7 वर्ष तक की सजा वाले मामलों में अनावश्यक गिरफ्तारी रोकने के लिए नोटिस जारी करने का निर्देश दिया गया।'), ('Which Article prohibits child labor in all hazardous employments as an enforceable Fundamental Right?', 'कौन सा अनुच्छेद सभी खतरनाक उद्योगों में बाल श्रम को मौलिक अधिकार के रूप में पूर्णतः निषिद्ध करता है?', 'Article 24', 'अनुच्छेद 24', ['Article 23', 'Article 21A', 'Article 39(e)'], ['अनुच्छेद 23', 'अनुच्छेद 21क', 'अनुच्छेद 39(ङ)'], 'Article 24 forbids employing children below 14 in factories, mines, or other hazardous occupations.', 'अनुच्छेद 24 बच्चों के शोषण के विरुद्ध अधिकार प्रदान करता है।'), ('In M.C. Mehta v. State of Tamil Nadu (1996), the Supreme Court issued comprehensive directives to eliminate child labor in', 'एम.सी. मेहता बनाम तमिलनाडु राज्य (1996) में सुप्रीम कोर्ट ने कहां बाल श्रम समाप्त करने और पुनर्वास कोष बनाने का आदेश दिया?', 'Matchstick and fireworks factories of Sivakasi', 'शिवकाशी के पटाखा एवं माचिस कारखानों में', ['Diamond cutting units of Surat', 'Tea gardens of Assam', 'Shoe industries of Agra'], ['सूरत के हीरा उद्योग में', 'असम के चाय बागानों में', 'आगरा के जूता उद्योग में'], 'Ordered setting up the Child Labour Rehabilitation-cum-Welfare Fund with a penalty of ₹20,000 per child paid by offending employers.', 'शिवकाशी पटाखा उद्योग में बाल श्रम पर रोक लगाकर दोषी नियोक्ताओं पर ₹20,000 का जुर्माना लगाने का निर्देश दिया गया।'), ("The expression 'Procedure Established by Law' in Article 21 of the Constitution was borrowed from the Constitution of", "भारतीय संविधान के अनुच्छेद 21 में प्रयुक्त पदावली 'विधि द्वारा स्थापित प्रक्रिया' किस देश के संविधान से ली गई है?", 'Japan (Constitution of Japan, 1946)', 'जापान के संविधान से', ['United States of America', 'United Kingdom', 'Canada'], ['संयुक्त राज्य अमेरिका से', 'ब्रिटेन से', 'कनाडा से'], 'Borrowed from Article 31 of the Japanese Constitution of 1946 on the advice of US Supreme Court Justice Felix Frankfurter to Sir B.N. Rau.', "सर बी.एन. राव को अमेरिकी न्यायमूर्ति फ्रैंकफर्टर की सलाह पर जापान के संविधान से 'विधि द्वारा स्थापित प्रक्रिया' वाक्यांश लिया गया।"), ("The American concept of 'Due Process of Law' differs from 'Procedure Established by Law' primarily because", "अमेरिकी 'विधि की सम्यक प्रक्रिया' (Due Process) और 'विधि द्वारा स्थापित प्रक्रिया' में मुख्य अंतर क्या है?", 'Due Process examines both substantive fairness (whether the law is just) and procedural correctness', 'ड्यू प्रोसेस विधि के औचित्य (कानून न्यायसंगत है या नहीं) और प्रक्रिया दोनों की जांच करता है', ['Due Process applies only to property cases', 'Procedure Established by Law ignores statutes passed by Parliament', 'Due Process cannot be exercised by Supreme Court'], ['यह केवल संपत्ति पर लागू होता है', 'यह संसद के कानून को नजरअंदाज करता है', 'सुप्रीम कोर्ट लागू नहीं कर सकता'], 'Due Process checks whether a law is fair, just, and reasonable (substantive), whereas strict procedure checks only whether the law was formally enacted.', 'विधि द्वारा स्थापित प्रक्रिया केवल प्रक्रिया देखती है, जबकि विधि की सम्यक प्रक्रिया यह भी देखती है कि कानून मनमाना या अन्यायी तो नहीं है।')]

slot_q114_fr_part2 = [('Article 25 of the Constitution guarantees freedom of conscience and the right to', 'संविधान का अनुच्छेद 25 अंतःकरण की स्वतंत्रता और किस अधिकार की गारंटी देता है?', 'Freely profess, practice, and propagate religion', 'धर्म को अबाध रूप से मानने, आचरण करने और प्रचार करने का अधिकार', ['Convert others by force or financial inducement', 'Establish religious courts with criminal jurisdiction', 'Exempt religious properties from all taxes'], ['बलपूर्वक या प्रलोभन द्वारा धर्मांतरण', 'धार्मिक न्यायालय स्थापित करना', 'धार्मिक संपत्ति को सभी करों से छूट'], 'Article 25 guarantees freedom of conscience and the right to freely profess, practice, and propagate religion, subject to public order, morality, and health.', 'अनुच्छेद 25 लोक व्यवस्था, सदाचार और स्वास्थ्य के अधीन धर्म को मानने, आचरण करने और प्रचार करने की स्वतंत्रता देता है।'), ("Does the right to 'propagate' one's religion under Article 25 include the right to forcibly convert another person?", "क्या अनुच्छेद 25 के तहत धर्म के 'प्रचार' के अधिकार में किसी अन्य व्यक्ति का जबरन धर्मांतरण कराने का अधिकार शामिल है?", 'No, ruled by the Supreme Court in Rev. Stainislaus v. State of MP (1977)', 'नहीं, स्टेनिसलॉस बनाम मध्य प्रदेश राज्य (1977) में सर्वोच्च न्यायालय ने इसे स्पष्ट रूप से खारिज किया', ['Yes, an absolute constitutional right', 'Yes, if accompanied by financial aid', 'Only if approved by a local magistrate'], ['हां, यह पूर्ण अधिकार है', 'हां, यदि आर्थिक मदद दी जाए', 'केवल मजिस्ट्रेट की अनुमति से'], 'The Supreme Court held that freedom of conscience under Article 25 guarantees that every person has the freedom to hold their own religious views without coercion.', 'स्टेनिसलॉस मामले में सुप्रीम कोर्ट ने माना कि प्रचार का अर्थ अपने धर्म के सिद्धांतों को स्पष्ट करना है, किसी का जबरन धर्मांतरण कराना नहीं।'), ("Under Explanation II of Article 25, the reference to 'Hindus' is construed as including which other religious communities?", "अनुच्छेद 25 के स्पष्टीकरण II के अनुसार 'हिंदू' शब्द के अंतर्गत किन अन्य धार्मिक समुदायों को शामिल माना गया है?", 'Sikhs, Jains, and Buddhists', 'सिख, जैन एवं बौद्ध (Sikh, Jain, Buddhist)', ['Muslims, Christians, and Parsis', 'Jews, Zoroastrians, and Bahais', 'Only Sikhs and Jains'], ['मुस्लिम, ईसाई एवं पारसी', 'यहूदी, पारसी एवं बहाई', 'केवल सिख एवं जैन'], 'Explanation II to Article 25 states that reference to Hindus shall be construed as including persons professing Sikh, Jaina, or Buddhist religion.', 'अनुच्छेद 25 के स्पष्टीकरण में स्पष्ट किया गया है कि हिंदुओं के अंतर्गत सिख, जैन और बौद्ध धर्म के अनुयायी भी सम्मिलित हैं।'), ("The wearing and carrying of 'Kirpans' by Sikhs is deemed included in the profession of Sikhism under", "सिखों द्वारा 'कृपाण' धारण करना और लेकर चलना किस अनुच्छेद के स्पष्टीकरण के तहत धर्म का अंग माना गया है?", 'Explanation I to Article 25', 'अनुच्छेद 25 का स्पष्टीकरण I', ['Article 26(a)', 'Article 19(1)(b)', 'Article 28(2)'], ['अनुच्छेद 26(क)', 'अनुच्छेद 19(1)(ख)', 'अनुच्छेद 28(2)'], 'Explanation I to Article 25 explicitly states that the wearing and carrying of kirpans shall be deemed to be included in the profession of the Sikh religion.', 'अनुच्छेद 25(1) के स्पष्टीकरण I में सिखों द्वारा कृपाण धारण करने को धार्मिक स्वतंत्रता का अभिन्न अंग माना गया है।'), ('Article 26 guarantees freedom to manage religious affairs to every', 'अनुच्छेद 26 धार्मिक कार्यों के प्रबंध की स्वतंत्रता किसे प्रदान करता है?', 'Religious denomination or any section thereof', 'प्रत्येक धार्मिक संप्रदाय या उसके किसी अनुभाग को', ['Individual citizen only', 'Only recognized minority communities', 'Foreign religious organizations'], ['केवल व्यक्तिगत नागरिक को', 'केवल मान्यता प्राप्त अल्पसंख्यक समुदायों को', 'विदेशी धार्मिक संगठनों को'], 'Article 26 protects collective religious freedom: right to establish institutions, manage affairs in religion, and own property.', 'अनुच्छेद 26 सामूहिक धार्मिक स्वतंत्रता देता है: संप्रदाय को अपने धार्मिक मामलों का प्रबंध करने और संपत्ति अर्जित करने का अधिकार है।'), ("What criteria were laid down in the Shirur Mutt case (1954) to constitute a 'Religious Denomination' under Article 26?", "शिरूर मठ मामले (1954) में सर्वोच्च न्यायालय ने 'धार्मिक संप्रदाय' होने के लिए क्या शर्तें निर्धारित की थीं?", 'Collection of individuals with common faith, common organization, and designated by a distinctive name', 'समान विश्वास वाले व्यक्तियों का समूह, एक साझा संगठन, और एक विशिष्ट नाम से पहचान', ['Registration under the Companies Act', 'Holding at least one hundred acres of agricultural land', 'Approval by the President of India'], ['कंपनी कानून में पंजीकरण', 'कम से कम 100 एकड़ भूमि', 'राष्ट्रपति की स्वीकृति'], 'The Supreme Court in Commissioner, Hindu Religious Endowments v. Sri Lakshmindra Thirtha Swamiar (Shirur Mutt case) defined a denomination.', 'शिरूर मठ मामले में सुप्रीम कोर्ट ने माना कि एक साझा आस्था, विशिष्ट नाम और विशिष्ट संगठन होना संप्रदाय की पहचान है।'), ('In the Sabarimala Temple case (Indian Young Lawyers Association v. State of Kerala, 2018), the Supreme Court ruled that', 'सबरीमाला मंदिर मामले (2018) में सर्वोच्च न्यायालय ने किस नियम को असंवैधानिक घोषित किया?', 'Exclusion of women of menstruating age (10 to 50 years) violated Articles 14, 15, and 25', 'माहवारी आयु वर्ग (10 से 50 वर्ष) की महिलाओं के प्रवेश पर रोक अनुच्छेद 14, 15 और 25 का उल्लंघन है', ['The temple should be closed to all pilgrims', 'Only Kerala resident women could enter', 'Article 26 overrides Article 25'], ['मंदिर सभी के लिए बंद कर दिया जाए', 'केवल केरल की महिलाओं को अनुमति', 'अनुच्छेद 26 अनुच्छेद 25 पर हावी है'], 'A 4:1 majority held that biological characteristics cannot be grounds for barring women from worshipping.', 'सबरीमाला मामले में 4:1 के बहुमत से महिलाओं के प्रवेश पर प्रतिबंध को लैंगिक समानता और धार्मिक स्वतंत्रता का हनन माना गया।'), ('Article 27 of the Constitution prohibits the State from', 'भारतीय संविधान का अनुच्छेद 27 राज्य को किस बात से रोकता है?', 'Compelling any person to pay taxes for the promotion or maintenance of any particular religion', 'किसी विशिष्ट धर्म की उन्नति या पोषण हेतु कर (Tax) देने के लिए किसी व्यक्ति को बाध्य करने से', ['Charging entry fees at historical monuments', 'Providing security during religious pilgrimages', 'Levying service fees for civic arrangements'], ['स्मारकों पर प्रवेश शुल्क लेने से', 'धार्मिक यात्राओं में सुरक्षा देने से', 'नागरिक सुविधाओं हेतु शुल्क लगाने से'], 'Article 27 forbids taxes to promote a religion; however, fees (service charges) for pilgrim management are permissible.', "अनुच्छेद 27 किसी धर्म के प्रचार के लिए कर लगाने पर रोक लगाता है; किंतु व्यवस्था बनाए रखने हेतु 'शुल्क' (Fee) लगाया जा सकता है।"), ('Under Article 28, completely state-funded educational institutions are strictly prohibited from', 'अनुच्छेद 28 के तहत पूर्णतः राज्य-निधि से पोषित शिक्षण संस्थानों में किस पर पूर्ण प्रतिबंध है?', 'Providing any religious instruction', 'किसी भी प्रकार की धार्मिक शिक्षा देने पर', ['Teaching science and mathematics', 'Conducting extracurricular sports activities', 'Observing national holidays'], ['विज्ञान एवं गणित पढ़ाने पर', 'खेलकूद कराने पर', 'राष्ट्रीय अवकाश मनाने पर'], 'Article 28(1) mandates that no religious instruction shall be provided in any educational institution wholly maintained out of State funds.', 'अनुच्छेद 28(1) के अनुसार राज्य निधि से पूरी तरह चलने वाले किसी भी विद्यालय या कॉलेज में धार्मिक शिक्षा नहीं दी जाएगी।'), ('Under Article 28(2), religious instruction is permitted in an educational institution that is', 'अनुच्छेद 28(2) के अनुसार किन शिक्षण संस्थानों में धार्मिक शिक्षा दी जा सकती है?', 'Administered by the State but established under an endowment or trust requiring religious instruction', 'जो राज्य द्वारा प्रशासित हों किंतु किसी ऐसे विन्यास (न्यास/ट्रस्ट) के तहत स्थापित हुए हों जहां धार्मिक शिक्षा अनिवार्य हो', ['Any government school funded by municipal corporations', 'Any private coaching academy', 'Central government Kendriya Vidyalayas'], ['नगरपालिका के सरकारी स्कूल', 'निजी कोचिंग संस्थान', 'केंद्रीय विद्यालय'], 'Institutions like Aligarh Muslim University or Banaras Hindu University founded under historical trusts may provide religious instruction.', 'यदि कोई संस्था किसी धार्मिक ट्रस्ट या बंदोबस्त के तहत बनी हो और केवल उसका प्रशासन राज्य करता हो, तो वहां धार्मिक शिक्षा दी जा सकती है।'), ('Article 29(1) of the Constitution protects the right of any section of citizens residing in India having a distinct', 'संविधान का अनुच्छेद 29(1) भारत के नागरिकों के किसी भी वर्ग को किस अधिकार का संरक्षण देता है?', 'Language, script, or culture to conserve the same', 'अपनी विशिष्ट भाषा, लिपि या संस्कृति को बनाए रखने का अधिकार', ['Right to demand a separate statehood', 'Right to print their own currency', 'Right to establish separate criminal courts'], ['अलग राज्य की मांग का अधिकार', 'अपनी मुद्रा छापने का अधिकार', 'अलग आपराधिक न्यायालय बनाने का अधिकार'], 'Article 29(1) protects linguistic and cultural preservation of any group of citizens, both minorities and majorities.', 'अनुच्छेद 29(1) नागरिकों के किसी भी वर्ग को अपनी बोली, भाषा, लिपि या संस्कृति को सुरक्षित रखने का पूर्ण अधिकार देता है।'), ('Article 29(2) guarantees that no citizen shall be denied admission into any educational institution maintained by the State on grounds ONLY of', 'अनुच्छेद 29(2) के तहत राज्य द्वारा पोषित शिक्षण संस्थान में प्रवेश से केवल किन आधारों पर वंचित नहीं किया जा सकता?', 'Religion, race, caste, language, or any of them', 'धर्म, मूलवंश, जाति, भाषा या इनमें से किसी के आधार पर', ['Marks obtained in qualifying examinations', 'Residential address or city of origin', 'Non-payment of mandatory tuition fee'], ['परीक्षा के प्राप्तांकों के आधार पर', 'निवास स्थान या शहर', 'अनिवार्य फीस न देने पर'], 'Article 29(2) protects individual citizens from discrimination in admissions to state-aided educational institutions on 4 grounds: religion, race, caste, language.', 'राज्य द्वारा संचालित या सहायता प्राप्त किसी भी स्कूल/कॉलेज में धर्म, जाति, भाषा के आधार पर प्रवेश देने से मना नहीं किया जा सकता।'), ('Article 30 of the Constitution grants the right to establish and administer educational institutions to', 'संविधान का अनुच्छेद 30 किन वर्गों को अपनी रुचि के शिक्षण संस्थानों की स्थापना और प्रशासन का अधिकार देता है?', 'All Minorities, whether based on Religion or Language', 'धर्म या भाषा पर आधारित सभी अल्पसंख्यक वर्गों को', ['Linguistic and caste-based minorities', 'Religious, regional, and ideological minorities', 'Only political and ethnic minorities'], ['भाषाई एवं जातिगत अल्पसंख्यकों को', 'धार्मिक, क्षेत्रीय एवं वैचारिक अल्पसंख्यकों को', 'केवल राजनीतिक अल्पसंख्यकों को'], 'Article 30(1) specifically recognizes two categories of minorities: Religious minorities and Linguistic minorities.', 'अनुच्छेद 30 केवल दो प्रकार के अल्पसंख्यकों (धार्मिक और भाषाई) को शिक्षण संस्थाएं स्थापित करने का विशेष अधिकार देता है।'), ('In the landmark T.M.A. Pai Foundation case (2002), an 11-judge bench held that the unit for determining religious or linguistic minority is', 'टी.एम.ए. पाई फाउंडेशन मामले (2002) में 11 न्यायाधीशों की पीठ ने तय किया कि धार्मिक या भाषाई अल्पसंख्यक की पहचान किस स्तर पर होगी?', 'The State (State-wise determination), not the entire country', 'राज्य स्तर पर (संपूर्ण देश के स्तर पर नहीं)', ['The entire Nation as a single unit', 'The District or Tehsil level', 'The Municipal Ward level'], ['संपूर्ण राष्ट्र को एक इकाई मानकर', 'जिला या तहसील स्तर पर', 'नगरपालिका वार्ड स्तर पर'], 'An 11-judge bench held that since states were reorganized on linguistic lines, the unit for determining both linguistic and religious minorities under Article 30 is the State.', 'सर्वोच्च न्यायालय ने माना कि अल्पसंख्यक का निर्धारण पूरे देश की जनसंख्या के बजाय संबंधित राज्य की जनसंख्या के अनुपात में किया जाएगा।'), ('Are minority educational institutions exempted from the mandatory 25% quota for disadvantaged children under the RTE Act, 2009?', 'क्या अल्पसंख्यक शिक्षण संस्थानों को आरटीई (RTE) कानून के तहत 25% अनिवार्य गरीब कोटे से छूट प्राप्त है?', 'Yes, ruled by Supreme Court in Pramati Educational Trust v. Union of India (2014)', 'हां, प्रमति एजुकेशनल ट्रस्ट मामले (2014) में सुप्रीम कोर्ट ने इन्हें 25% कोटे से मुक्त रखा', ['No, RTE quota applies equally to all private institutions', 'Only linguistic minority schools are exempt', 'Only aided minority schools are exempt'], ['नहीं, सभी पर समान रूप से लागू है', 'केवल भाषाई स्कूलों को छूट', 'केवल सहायता प्राप्त स्कूलों को छूट'], 'A 5-judge Constitution Bench held that applying the 25% RTE reservation to aided and unaided minority institutions violates Article 30(1).', 'सुप्रीम कोर्ट ने फैसला दिया कि अनुच्छेद 30(1) के तहत अल्पसंख्यक स्कूलों पर 25% ईडब्ल्यूएस कोटा अनिवार्य रूप से लागू नहीं किया जा सकता।'), ("Who famously described Article 32 as the 'Heart and Soul of the Constitution'?", "संविधान के अनुच्छेद 32 को किसने 'संविधान का हृदय और उसकी आत्मा' (Heart and Soul of Constitution) कहा था?", 'Dr. B.R. Ambedkar', 'डॉ. बी.आर. आंबेडकर', ['Pandit Jawaharlal Nehru', 'Dr. Rajendra Prasad', 'Sardar Vallabhbhai Patel'], ['पंडित जवाहरलाल नेहरू', 'डॉ. राजेंद्र प्रसाद', 'सरदार वल्लभभाई पटेल'], 'Dr. Ambedkar stated that Article 32 is the most important article, without which the Constitution would be a nullity.', 'डॉ. आंबेडकर ने कहा था कि अनुच्छेद 32 के बिना संविधान अर्थहीन है; यह संविधान का हृदय और उसकी सबसे महत्वपूर्ण आत्मा है।'), ('Article 32 guarantees the right to move which court for the enforcement of Fundamental Rights?', 'मूल अधिकारों के प्रवर्तन (लागू कराने) हेतु अनुच्छेद 32 के तहत सीधे किस अदालत में जाने का अधिकार है?', 'Supreme Court of India', 'भारत के सर्वोच्च न्यायालय में', ['High Court of the State', 'District and Sessions Court', 'Central Administrative Tribunal'], ['राज्य के उच्च न्यायालय में', 'जिला एवं सत्र न्यायालय में', 'केंद्रीय प्रशासनिक न्यायाधिकरण में'], 'Article 32 guarantees the Right to Constitutional Remedies, making the right to approach the Supreme Court itself a Fundamental Right.', 'अनुच्छेद 32 स्वयं एक मौलिक अधिकार है, जो नागरिक को सीधे सुप्रीम कोर्ट जाकर अपने अधिकार लागू कराने की गारंटी देता है।'), ('Under Article 226, which court has the power to issue prerogative writs for Fundamental Rights and other legal rights?', 'संविधान के अनुच्छेद 226 के तहत मूल अधिकारों एवं अन्य विधिक अधिकारों के प्रवर्तन हेतु रिट जारी करने की शक्ति किसे है?', 'High Courts of the States', 'राज्यों के उच्च न्यायालयों को (High Courts)', ['Supreme Court of India only', 'District Courts', 'Sub-Divisional Courts'], ['केवल सर्वोच्च न्यायालय को', 'जिला अदालतों को', 'अनुमंडलीय अदालतों को'], "High Courts under Article 226 have broader writ jurisdiction than Supreme Court under Art 32 because High Courts can issue writs for 'any other purpose' (legal rights).", 'अनुच्छेद 226 के तहत उच्च न्यायालय की रिट शक्ति सुप्रीम कोर्ट से भी व्यापक है, क्योंकि वह कानूनी अधिकारों के लिए भी रिट जारी कर सकता है।'), ('How many types of Prerogative Writs can be issued by the Supreme Court and High Courts in India?', 'भारतीय संविधान के तहत सर्वोच्च न्यायालय और उच्च न्यायालय कुल कितने प्रकार की रिट (Writs) जारी कर सकते हैं?', '5 Types of Writs', '5 प्रकार की रिट', ['3 Types', '4 Types', '7 Types'], ['3 प्रकार की', '4 प्रकार की', '7 प्रकार की'], 'The 5 writs borrowed from English common law are: Habeas Corpus, Mandamus, Prohibition, Certiorari, and Quo-Warranto.', 'अंग्रेजी कानून से ली गई 5 रिट हैं: बंदी प्रत्यक्षीकरण, परमादेश, प्रतिषेध, उत्प्रेषण एवं अधिकार पृच्छा।'), ("What is the literal Latin meaning of the writ 'Habeas Corpus'?", "'बंदी प्रत्यक्षीकरण' (Habeas Corpus) रिट का शाब्दिक लैटिन अर्थ क्या है?", "'To have the body' (शरीर को प्रस्तुत किया जाए)", "'शरीर को प्रस्तुत किया जाए' (To have the body)", ["'We command'", "'To be certified'", "'By what authority'"], ["'हम आदेश देते हैं'", "'प्रमाणित किया जाए'", "'आपका प्राधिकार क्या है'"], 'Habeas Corpus is an order directing the detaining authority to produce the arrested person before court to test the legality of detention.', 'बंदी प्रत्यक्षीकरण का अर्थ है बंदी को न्यायालय के सामने पेश करना ताकि कोर्ट देख सके कि गिरफ्तारी वैध है या अवैध।'), ('Can the writ of Habeas Corpus be issued against both public authorities and private individuals?', 'क्या बंदी प्रत्यक्षीकरण (Habeas Corpus) की रिट सरकारी अधिकारियों के साथ-साथ निजी व्यक्तियों के विरुद्ध भी जारी हो सकती है?', 'Yes, it can be issued against both public authorities and private individuals', 'हां, यह सरकारी अधिकारियों एवं निजी व्यक्तियों दोनों के विरुद्ध जारी की जा सकती है', ['No, strictly against government officers only', 'No, only against the police department', 'Only against military authorities'], ['नहीं, केवल सरकारी अफसरों के विरुद्ध', 'नहीं, केवल पुलिस के विरुद्ध', 'केवल सैन्य अधिकारियों के विरुद्ध'], 'Unlike Mandamus, Habeas Corpus can be issued against private citizens who unlawfully detain another individual (e.g., in domestic confinement).', 'यदि कोई निजी व्यक्ति भी किसी को बंधक बनाकर रखे, तो उसके खिलाफ भी बंदी प्रत्यक्षीकरण रिट जारी की जा सकती है।'), ("What is the literal meaning of the writ of 'Mandamus'?", "'परमादेश' (Mandamus) रिट का शाब्दिक अर्थ क्या होता है?", "'We Command' (हम आदेश देते हैं)", "'हम आदेश देते हैं' (We Command)", ["'To have the body'", "'By what warrant'", "'To stay proceedings'"], ["'शरीर को प्रस्तुत करो'", "'किस अधिकार से'", "'कार्यवाही रोको'"], 'Mandamus is a judicial command issued to a public official or body to perform a mandatory statutory public duty they have failed or refused to perform.', 'परमादेश न्यायालय का वह आदेश है जिसके द्वारा किसी लोक अधिकारी को उसका कानूनी कर्तव्य निभाने का निर्देश दिया जाता है।'), ('Against whom can the writ of Mandamus NOT be issued?', 'परमादेश (Mandamus) की रिट निम्नलिखित में से किसके विरुद्ध जारी नहीं की जा सकती?', 'The President of India and State Governors for exercise of their official duties', 'भारत के राष्ट्रपति एवं राज्यों के राज्यपालों के शासकीय कार्यों के विरुद्ध', ['Municipal corporations', 'University examination controllers', 'Public sector undertakings'], ['नगर निगमों के विरुद्ध', 'विश्वविद्यालय परीक्षा नियंत्रक', 'सरकारी कंपनियों के विरुद्ध'], 'Article 361 grants official immunity; Mandamus cannot be issued against the President, Governors, private individuals, or to enforce contract.', 'अनुच्छेद 361 के तहत राष्ट्रपति और राज्यपाल को छूट है; निजी व्यक्तियों या संविदात्मक दायित्वों के खिलाफ परमादेश जारी नहीं हो सकता।'), ("What is the fundamental difference between the writ of 'Prohibition' and the writ of 'Certiorari'?", "'प्रतिषेध' (Prohibition) और 'उत्प्रेषण' (Certiorari) रिट में मुख्य अंतर क्या है?", 'Prohibition is preventive (issued during ongoing proceedings); Certiorari is curative (issued after order is pronounced)', 'प्रतिषेध निवारक है (कार्यवाही के दौरान जारी), जबकि उत्प्रेषण उपचारात्मक है (आदेश पारित होने के बाद रद्द करने हेतु)', ['Prohibition applies only to police; Certiorari applies only to schools', 'Certiorari is issued by President; Prohibition by Courts', 'There is no difference'], ['प्रतिषेध केवल पुलिस पर लागू होता है', 'उत्प्रेषण राष्ट्रपति जारी करते हैं', 'दोनों में कोई अंतर नहीं है'], 'Prohibition stops a lower tribunal from exceeding its jurisdiction while proceedings are pending; Certiorari quashes an illegal order already passed.', 'प्रतिषेध निचली अदालत को अधिकार क्षेत्र से बाहर जाने से रोकता है; उत्प्रेषण निचली अदालत के अवैध फैसले को निरस्त करता है।'), ('Against whom can the writs of Prohibition and Certiorari be issued?', 'प्रतिषेध और उत्प्रेषण की रिट मुख्य रूप से किन संस्थाओं के विरुद्ध जारी की जाती हैं?', 'Subordinate courts, judicial bodies, and quasi-judicial tribunals', 'अधीनस्थ न्यायालयों, न्यायिक निकायों एवं अर्ध-न्यायिक न्यायाधिकरणों के विरुद्ध', ['Legislative bodies passing statutes', 'Private companies in business disputes', 'Foreign embassies in New Delhi'], ['कानून बनाने वाली संसद के विरुद्ध', 'निजी व्यापारिक कंपनियों के विरुद्ध', 'विदेशी दूतावासों के विरुद्ध'], 'These writs supervise judicial and quasi-judicial bodies to ensure they act within statutory jurisdiction and observe natural justice.', 'ये रिट निचली अदालतों और ट्रिब्यूनलों को उनके अधिकार क्षेत्र में रखने और प्राकृतिक न्याय का पालन कराने के लिए हैं।'), ("What is the literal meaning of the writ of 'Quo-Warranto'?", "'अधिकार पृच्छा' (Quo-Warranto) रिट का शाब्दिक अर्थ क्या है?", "'By what authority or warrant?' (आपका क्या प्राधिकार है?)", "'आपका क्या प्राधिकार है?' (By what authority or warrant?)", ["'To produce the prisoner'", "'We command obedience'", "'To forbid action'"], ["'कैदी को पेश करो'", "'हम आज्ञा देते हैं'", "'कार्यवाही पर रोक'"], "Quo-Warranto challenges the legality of a person's claim to a substantive public office, preventing illegal usurpation.", 'अधिकार पृच्छा किसी सार्वजनिक पद पर अवैध रूप से आसीन व्यक्ति से पूछती है कि वह किस अधिकार से उस पद पर कार्य कर रहा है।'), ('Can a PIL (Public Interest Litigation) petitioner who is not personally aggrieved file for Quo-Warranto?', 'क्या कोई ऐसा नागरिक जो व्यक्तिगत रूप से पीड़ित नहीं है, अधिकार पृच्छा (Quo-Warranto) रिट दायर कर सकता है?', 'Yes, any interested citizen can file Quo-Warranto against usurpation of public office', 'हां, सार्वजनिक पद के दुरुपयोग के खिलाफ कोई भी जागरूक नागरिक यह रिट दायर कर सकता है', ['No, only the person eligible for that post can file', 'No, only the Attorney General can file', "Only with Governor's prior sanction"], ['नहीं, केवल उस पद का दावेदार ही दायर कर सकता है', 'केवल अटॉर्नी जनरल दायर कर सकते हैं', 'केवल राज्यपाल की मंजूरी से'], 'Unlike other private remedies, Quo-Warranto can be moved by any member of the public because public interest is involved.', 'सार्वजनिक पद की गरिमा बनाए रखने के लिए कोई भी नागरिक अधिकार पृच्छा रिट दायर कर सकता है।'), ('The concept of Public Interest Litigation (PIL) in India was pioneered in the late 1970s and 1980s by which Justices?', 'भारत में जनहित याचिका (PIL) की अवधारणा को 1970-80 के दशक में किन मुख्य न्यायाधीशों ने प्रारंभ किया था?', 'Justice P.N. Bhagwati and Justice V.R. Krishna Iyer', 'न्यायमूर्ति पी.एन. भगवती एवं न्यायमूर्ति वी.आर. कृष्णा अय्यर', ['Justice H.J. Kania and Justice Patanjali Sastri', 'Justice M.H. Beg and Justice Y.V. Chandrachud', 'Justice Dipak Misra and J.S. Khehar'], ['न्यायमूर्ति एच.जे. कानिया एवं शास्त्री', 'न्यायमूर्ति बेग एवं चंद्रचूड़', 'न्यायमूर्ति दीपक मिश्रा एवं खेहर'], "Justices Krishna Iyer and Bhagwati relaxed the traditional rule of 'Locus Standi', allowing public-spirited citizens to file petitions for marginalized victims.", 'न्यायमूर्ति वी.आर. कृष्णा अय्यर और पी.एन. भगवती ने लोकस स्टैंडाई (Locus Standi) के नियम को ढीला कर गरीबों हेतु पीआईएल की शुरुआत की।'), ('What procedural innovation was introduced in PILjurisprudence by Justice P.N. Bhagwati?', 'न्यायमूर्ति पी.एन. भगवती द्वारा पीआईएल के तहत कौन सी अनूठी प्रक्रियात्मक पहल (Epistolary Jurisdiction) शुरू की गई?', 'Epistolary Jurisdiction (treating simple letters or postcards from citizens as writ petitions)', 'पत्र क्षेत्राधिकार (नागरिकों के साधारण पत्रों या पोस्टकार्डों को ही रिट याचिका मान लेना)', ['Requiring ₹1 Lakh court fee deposit for every writ', 'Mandatory oral hearings inside prison cells', 'Direct appeals to international courts'], ['प्रत्येक याचिका पर ₹1 लाख का शुल्क', 'जेल में जाकर सुनवाई', 'सीधे अंतरराष्ट्रीय अदालत में अपील'], 'The Supreme Court accepted postcards and letters sent by social workers and undertrials as valid writ petitions under Article 32.', 'सर्वोच्च न्यायालय ने पोस्टकार्ड या साधारण पत्र पर लिखी गई शिकायतों को भी अनुच्छेद 32 के तहत रिट याचिका स्वीकार किया।'), ('Which was the first reported case of Public Interest Litigation (PIL) in India in 1979?', '1979 में भारत में जनहित याचिका (PIL) का पहला चर्चित मामला कौन सा था?', 'Hussainara Khatoon v. Home Secretary, State of Bihar (1979)', 'हुसैनआरा खातून बनाम गृह सचिव, बिहार राज्य (1979)', ['Vishaka case', 'Kesavananda Bharati case', 'Minerva Mills case'], ['विशाखा मामला', 'केशवानंद भारती मामला', 'मिनर्वा मिल्स मामला'], 'Advocate Pushpa Kapila Hingorani filed a habeas corpus PIL based on newspaper reports by K.F. Rustamji, securing release of 40,000 undertrials in Bihar.', 'कपिली हिंगोरानी द्वारा दायर इस याचिका से बिहार की जेलों में बरसों से बंद 40,000 से अधिक विचाराधीन कैदियों को मुक्ति मिली।'), ("Who is widely celebrated as the 'Mother of PILs' in Indian legal history?", "भारतीय न्यायशास्त्र में किसे 'जनहित याचिकाओं की जननी' (Mother of PILs) के रूप में जाना जाता है?", 'Pushpa Kapila Hingorani', 'पुष्पा कपिला हिंगोरानी (Pushpa Kapila Hingorani)', ['Cornelia Sorabji', 'Justice Anna Chandy', 'Justice Fathima Beevi'], ['कॉर्नेलिया सोराबजी', 'न्यायमूर्ति अन्ना चांडी', 'न्यायमूर्ति फातिमा बीवी'], 'Kapila Hingorani was the pioneering advocate who filed the Hussainara Khatoon petition in Supreme Court, igniting the PIL revolution.', 'वरिष्ठ अधिवक्ता कपिला हिंगोरानी ने बिहार के कैदियों की रिहाई के लिए पहली पीआईएल दायर कर इस आंदोलन की नींव रखी थी।'), ('The Vishaka Guidelines to prevent sexual harassment of women at workplace were laid down under Article 32 in', 'कार्यस्थल पर महिलाओं के यौन उत्पीड़न की रोकथाम हेतु विशाखा दिशा-निर्देश (1997) किस मामले में जारी किए गए?', 'Vishaka v. State of Rajasthan (1997)', 'विशाखा बनाम राजस्थान राज्य (1997)', ['Mary Roy case', 'Githa Hariharan case', 'Shah Bano case'], ['मैरी रॉय मामला', 'गीता हरिहरन मामला', 'शाह बानो मामला'], 'In the absence of enacted legislation, the Supreme Court laid down binding guidelines under Articles 14, 19, 21, and CEDAW, later codified in POSH Act 2013.', 'कानून के अभाव में सुप्रीम कोर्ट ने महिलाओं की सुरक्षा हेतु बाध्यकारी दिशा-निर्देश दिए, जिससे 2013 का POSH कानून बना।'), ('Article 33 of the Constitution empowers Parliament to restrict or abrogate Fundamental Rights in their application to', 'संविधान का अनुच्छेद 33 संसद को किन बलों के सदस्यों के मूल अधिकारों को सीमित या समाप्त करने की शक्ति देता है?', 'Armed Forces, paramilitary forces, police forces, and intelligence agencies', 'सशस्त्र बलों, अर्धसैनिक बलों, पुलिस बलों एवं खुफिया एजेंसियों के सदस्यों पर', ['All government civil school teachers', 'Municipal sweeper unions', 'Railway train drivers and conductors'], ['सरकारी स्कूल के अध्यापकों पर', 'सफाई कर्मचारियों के संघों पर', 'रेलवे ड्राइवरों पर'], 'Article 33 enables Parliament to restrict Part III rights of military and intelligence personnel to ensure discipline and proper discharge of duties.', 'अनुच्छेद 33 संसद को सेना, पुलिस और रॉ/आईबी जैसे खुफिया संगठनों के अनुशासन हेतु उनके मूल अधिकार सीमित करने की शक्ति देता है।'), ('Article 34 of the Constitution provides for restriction on Fundamental Rights while what is in force in any area?', 'संविधान का अनुच्छेद 34 किसी क्षेत्र में किस व्यवस्था के लागू होने पर मूल अधिकारों पर प्रतिबंध लगाने का प्रावधान करता है?', 'Martial Law (सैन्य शासन / Military Rule)', 'मार्शल लॉ (सैन्य शासन / Martial Law)', ["President's Rule under Article 356", 'Financial Emergency under Article 360', 'Model Code of Conduct during elections'], ['राष्ट्रपति शासन (अनुच्छेद 356)', 'वित्तीय आपातकाल (अनुच्छेद 360)', 'चुनाव आचार संहिता'], 'Article 34 empowers Parliament to indemnify any person in service of the Union or State for acts done during the maintenance of order under Martial Law.', 'अनुच्छेद 34 सेना के शासन (मार्शल लॉ) के दौरान व्यवस्था बनाए रखने के लिए किए गए कृत्यों को सुरक्षा और अधिकारों पर रोक का उपबंध करता है।'), ('Article 35 provides that the power to make laws to give effect to certain specified Fundamental Rights rests EXCLUSIVELY with', 'अनुच्छेद 35 के अनुसार कुछ विशिष्ट मूल अधिकारों को प्रभावी बनाने के लिए कानून बनाने की शक्ति अनन्य रूप से किसे प्राप्त है?', 'Parliament of India (not State Legislatures)', 'भारत की संसद को (राज्य विधानमंडलों को नहीं)', ['State Legislative Assemblies only', 'Supreme Court through judicial ordinances', 'President of India through decrees'], ['केवल राज्य विधानसभाओं को', 'सुप्रीम कोर्ट के अध्यादेशों को', 'राष्ट्रपति के सीधे आदेशों को'], 'Article 35 ensures that laws prescribing punishments for offences against Part III (like Art 17, Art 23) are uniform throughout India.', 'अनुच्छेद 35 सुनिश्चित करता है कि अस्पृश्यता, मानव तस्करी आदि अपराधों पर पूरे देश में एक समान कानून केवल संसद द्वारा बनाया जाए।'), ('Which Constitutional Amendment Act added Article 31C, protecting laws giving effect to DPSP Article 39(b) and (c) from Articles 14 and 19?', 'किस संविधान संशोधन अधिनियम द्वारा अनुच्छेद 31ग जोड़ा गया, जो नीति निदेशक तत्व 39(ख) व (ग) को मूल अधिकारों पर प्राथमिकता देता है?', '25th Constitutional Amendment Act, 1971', '25वां संविधान संशोधन अधिनियम (1971)', ['24th Amendment Act, 1971', '42nd Amendment Act, 1976', '44th Amendment Act, 1978'], ['24वां संशोधन (1971)', '42वां संशोधन (1976)', '44वां संशोधन (1978)'], 'The 25th Amendment inserted Article 31C, providing that no law giving effect to directive principles in Art 39(b) and (c) shall be void under Arts 14, 19, or 31.', '25वें संशोधन (1971) द्वारा अनुच्छेद 31ग जोड़ा गया ताकि धन के संकेंद्रण को रोकने वाले कानूनों को समानता के अधिकार के आधार पर चुनौती न दी जा सके।'), ('In Kesavananda Bharati (1973), which part of Article 31C was struck down by the Supreme Court as unconstitutional?', 'केशवानंद भारती मामले (1973) में अनुच्छेद 31ग के किस भाग को सुप्रीम कोर्ट ने असंवैधानिक घोषित कर दिया था?', "The second part declaring 'no such law shall be called in question in any court' (ousting judicial review)", "दूसरा भाग जो कहता था कि 'ऐसे कानून को न्यायालय में चुनौती नहीं दी जा सकती' (न्यायिक समीक्षा छीनने वाला अंश)", ['The entire Article 31C was struck down', 'The first part protecting economic reform laws', 'Article 31C was completely upheld without changes'], ['पूरा अनुच्छेद 31ग रद्द कर दिया गया', 'आर्थिक सुधार वाला पहला हिस्सा', 'बिना बदलाव पूरा मान्य रखा गया'], 'The Supreme Court held that Judicial Review is a basic feature of the Constitution and cannot be excluded by any constitutional amendment.', 'सुप्रीम कोर्ट ने स्पष्ट किया कि न्यायिक समीक्षा संविधान का मूल ढांचा है, अतः संसद कोर्ट का अधिकार क्षेत्र नहीं छीन सकती।'), ('In Minerva Mills v. Union of India (1980), the Supreme Court held that the Constitution is founded on the bedrock of balance between', 'मिनर्वा मिल्स मामले (1980) में सुप्रीम कोर्ट ने माना कि भारतीय संविधान की नींव किन दो भागों के संतुलन पर टिकी है?', 'Fundamental Rights (Part III) and Directive Principles (Part IV)', 'मूल अधिकार (भाग III) एवं नीति निदेशक तत्व (भाग IV) के संतुलन पर', ['Lok Sabha and Rajya Sabha', 'Prime Minister and President', 'Union Government and State Governments'], ['लोकसभा और राज्यसभा', 'प्रधानमंत्री और राष्ट्रपति', 'केंद्र और राज्य सरकारें'], 'Chief Justice Chandrachud poetically held that Parts III and IV are like the two wheels of a chariot; giving absolute primacy to one over the other tilts constitutional balance.', 'न्यायमूर्ति चंद्रचूड़ ने कहा कि मूल अधिकार और नीति निदेशक तत्व एक रथ के दो पहिए हैं; दोनों में सामंजस्य ही संविधान का मूल ढांचा है।'), ('Can the right to move the Supreme Court under Article 32 be suspended during a National Emergency?', 'क्या राष्ट्रीय आपातकाल के दौरान अनुच्छेद 32 के तहत सुप्रीम कोर्ट जाने का अधिकार निलंबित किया जा सकता है?', 'Yes, by a Presidential Order under Article 359, EXCEPT for Articles 20 and 21', 'हां, अनुच्छेद 359 के तहत राष्ट्रपति के आदेश द्वारा (किंतु अनुच्छेद 20 और 21 को छोड़कर)', ['No, Article 32 can never be touched under any circumstances', 'Yes, automatically without any Presidential order', 'Only if Parliament passes a resolution with 3/4th majority'], ['नहीं, किसी भी हाल में नहीं', 'हां, स्वतः बिना आदेश के', 'केवल तीन-चौथाई बहुमत से'], 'Article 359 empowers the President to suspend enforcement of specified fundamental rights, but the 44th Amendment prohibited suspending Articles 20 and 21.', 'अनुच्छेद 359 के तहत राष्ट्रपति आपातकाल में रिट अधिकारों को स्थगित कर सकते हैं, किंतु 44वें संशोधन के बाद अनुच्छेद 20 व 21 पर रोक नहीं लग सकती।'), ("In ADM Jabalpur v. Shivkant Shukla (1976), infamously known as the 'Habeas Corpus Case', the majority held that", "एडीएम जबलपुर बनाम शिवकांत शुक्ला (1976) जिसे 'बंदी प्रत्यक्षीकरण मामला' कहा जाता है, में बहुमत का विवादास्पद निर्णय क्या था?", 'During Emergency, no person has locus standi to move any court for a writ of habeas corpus to challenge illegal detention', 'आपातकाल में कोई भी व्यक्ति अवैध गिरफ्तारी के खिलाफ बंदी प्रत्यक्षीकरण रिट हेतु अदालत नहीं जा सकता', ['Fundamental rights remain fully enforceable during Emergency', 'Preventive detention without trial is unconstitutional', 'Only High Courts can hear habeas corpus'], ['आपातकाल में मूल अधिकार पूरी तरह लागू रहेंगे', 'बिना मुकदमे निरोध असंवैधानिक है', 'केवल हाईकोर्ट सुनवाई कर सकते हैं'], 'A 4:1 majority upheld total suspension of personal liberty. Justice H.R. Khanna gave a legendary dissent upholding Rule of Law.', '4 न्यायाधीशों ने नागरिकों के अधिकार छीनने का समर्थन किया, जबकि न्यायमूर्ति एच.आर. खन्ना ने ऐतिहासिक असहमति जताते हुए विधि के शासन का पक्ष लिया।'), ('Which brave Supreme Court judge authored the lone dissenting judgment in the ADM Jabalpur case upholding human liberty?', 'एडीएम जबलपुर मामले में आपातकाल के दबाव के बावजूद मानवाधिकारों के पक्ष में ऐतिहासिक असहमति का फैसला किस न्यायाधीश ने दिया था?', 'Justice Hans Raj Khanna (H.R. Khanna)', 'न्यायमूर्ति हंस राज खन्ना (H.R. Khanna)', ['Justice P.N. Bhagwati', 'Justice Y.V. Chandrachud', 'Justice A.N. Ray'], ['न्यायमूर्ति पी.एन. भगवती', 'न्यायमूर्ति वाई.वी. चंद्रचूड़', 'न्यायमूर्ति ए.एन. रे'], 'Justice H.R. Khanna sacrificed his seniority and Chief Justiceship to declare that the Right to Life exists independent of Article 21.', 'न्यायमूर्ति एच.आर. खन्ना ने मुख्य न्यायाधीश पद की वरिष्ठता गंवाकर भी संविधान और नागरिक स्वतंत्रता की रक्षा की।'), ('In which judgment did the Supreme Court formally overrule the ADM Jabalpur judgment, calling it deeply flawed?', "सर्वोच्च न्यायालय ने किस ऐतिहासिक फैसले में एडीएम जबलपुर निर्णय को 'गंभीर रूप से त्रुटिपूर्ण' मानते हुए औपचारिक रूप से खारिज कर दिया?", 'K.S. Puttaswamy v. Union of India (Right to Privacy case, 2017)', 'के.एस. पुट्टास्वामी बनाम भारत संघ (निजता का अधिकार, 2017)', ['Kesavananda Bharati case', 'Minerva Mills case', 'Navtej Johar case'], ['केशवानंद भारती मामला', 'मिनर्वा मिल्स मामला', 'नवतेज जौहर मामला'], 'In Puttaswamy (2017), Justice D.Y. Chandrachud overruled the majority opinion authored by his own father (Justice Y.V. Chandrachud) in ADM Jabalpur.', 'पुट्टास्वामी मामले में सुप्रीम कोर्ट की 9 जजों की पीठ ने एडीएम जबलपुर के फैसले को हमेशा के लिए दफन करते हुए असंवैधानिक माना।'), ('Can a law placed in the Ninth Schedule of the Constitution be challenged in court for violating Fundamental Rights?', 'क्या संविधान की 9वीं अनुसूची में डाले गए कानूनों को मूल अधिकारों के उल्लंघन के आधार पर अदालत में चुनौती दी जा सकती है?', 'Yes, laws placed after 24 April 1973 can be judicially reviewed if they violate the Basic Structure (I.R. Coelho case, 2007)', 'हां, 24 अप्रैल 1973 के बाद शामिल कानून यदि मूल ढांचे का उल्लंघन करते हैं तो उनकी न्यायिक समीक्षा हो सकती है (आई.आर. कोएल्हो मामला, 2007)', ['No, Ninth Schedule grants absolute immunity from all judicial review forever', 'Only if approved by the Lok Sabha Speaker', 'Only tax laws in Ninth Schedule can be challenged'], ['नहीं, 9वीं अनुसूची को पूर्ण उन्मुक्ति प्राप्त है', 'केवल लोकसभा अध्यक्ष की अनुमति से', 'केवल कर कानूनों को चुनौती'], 'A 9-judge bench in I.R. Coelho v. State of Tamil Nadu held that laws inserted in the 9th Schedule after Kesavananda Bharati (24 April 1973) are open to judicial review.', "आई.आर. कोएल्हो मामले (2007) में सुप्रीम कोर्ट ने स्पष्ट किया कि 9वीं अनुसूची कोई 'ब्लैंक चेक' नहीं है; 1973 के बाद के सभी कानून न्यायिक समीक्षा के अधीन हैं।"), ('What was the original purpose of inserting the Ninth Schedule and Article 31B by the 1st Amendment Act, 1951?', '1951 के पहले संशोधन द्वारा 9वीं अनुसूची और अनुच्छेद 31ख को संविधान में जोड़ने का मूल उद्देश्य क्या था?', 'To protect agrarian land reform and abolition of Zamindari laws from judicial challenge', 'कृषि भूमि सुधार और जमींदारी उन्मूलन कानूनों को अदालतों में चुनौती से बचाना', ['To prevent military takeovers in borders', 'To ban opposition political parties', 'To nationalize foreign-owned banks'], ['सीमावर्ती क्षेत्रों में सैन्य नियंत्रण', 'विपक्षी दलों पर प्रतिबंध', 'विदेशी बैंकों का राष्ट्रीयकरण'], 'Enacted by the Provisional Parliament under Nehru to implement zamindari abolition without getting stalled by Right to Property litigation.', 'नेहरू सरकार ने जमींदारी प्रथा को खत्म करने वाले कानूनों को संपत्ति के अधिकार के मुकदमों से बचाने के लिए 9वीं अनुसूची बनाई थी।'), ('Which Article prohibits religious instruction in schools wholly funded by the State?', 'कौन सा अनुच्छेद राज्य द्वारा पूर्णतः पोषित विद्यालयों में धार्मिक शिक्षा देने पर पूर्ण प्रतिबंध लगाता है?', 'Article 28(1)', 'अनुच्छेद 28(1)', ['Article 25(1)', 'Article 26(b)', 'Article 27'], ['अनुच्छेद 25(1)', 'अनुच्छेद 26(ख)', 'अनुच्छेद 27'], 'Article 28(1) strictly forbids religious instruction in wholly state-funded educational institutions.', 'अनुच्छेद 28(1) धर्मनिरपेक्ष शिक्षा की रक्षा करता है।'), ('Under Article 30(2), the State shall not discriminate in granting aid to educational institutions on the ground that it is', 'अनुच्छेद 30(2) के अनुसार राज्य शिक्षण संस्थानों को सहायता देने में किस आधार पर भेदभाव नहीं करेगा?', 'Under the management of a minority, whether based on religion or language', 'कि वह धर्म या भाषा पर आधारित किसी अल्पसंख्यक वर्ग के प्रबंध के अधीन है', ['Affiliated with a central university', 'Teaching modern science and computing', 'Located in a rural agricultural zone'], ['केंद्रीय विश्वविद्यालय से संबद्ध है', 'आधुनिक विज्ञान पढ़ाता है', 'ग्रामीण क्षेत्र में स्थित है'], 'Article 30(2) prevents financial discrimination against minority-run schools in state grants-in-aid.', 'अनुच्छेद 30(2) सुनिश्चित करता है कि सरकारी अनुदान देते समय अल्पसंख्यक स्कूलों के साथ कोई भेदभाव न हो।'), ("In Bijoe Emmanuel v. State of Kerala (1986), famously known as the 'National Anthem Case', the Supreme Court ruled that", "बिजो इमैनुएल बनाम केरल राज्य (1986) जिसे 'राष्ट्रगान मामला' कहा जाता है, में सुप्रीम कोर्ट ने क्या फैसला दिया?", 'Standing respectfully during the National Anthem without singing satisfies respect and does not violate the law', 'राष्ट्रगान के समय आदरपूर्वक शांत खड़े रहना सम्मान का परिचायक है, गाना न गाना धर्म की स्वतंत्रता का अंग है', ['All school children must compulsorily sing the Anthem aloud', 'Students refusing to sing can be permanently jailed', 'National Anthem is banned in Christian schools'], ['सभी बच्चों को गाना अनिवार्य है', 'गाना न गाने पर जेल होगी', 'ईसाई स्कूलों में राष्ट्रगान प्रतिबंधित'], "Three Jehovah's Witness children were expelled for not singing the anthem; Supreme Court ordered reinstatement, holding respectful silence violates no law.", 'सुप्रीम कोर्ट ने बच्चों को स्कूल से निकाले जाने को अवैध माना और कहा कि शांत खड़े रहना राष्ट्रगान का अनादर नहीं है।'), ("The writ of 'Certiorari' is issued by a superior court to quash an order on which grounds?", 'उत्प्रेषण (Certiorari) की रिट किसी वरिष्ठ न्यायालय द्वारा निचली अदालत के आदेश को किन आधारों पर रद्द करने हेतु जारी की जाती है?', 'Lack or excess of jurisdiction, violation of principles of natural justice, or an error of law apparent on the face of the record', 'अधिकारिता का अभाव या उसका अतिक्रमण, प्राकृतिक न्याय का उल्लंघन, अथवा अभिलेख पर प्रत्यक्ष रूप से प्रकट विधिक त्रुटि', ["Disagreement with the judge's personal opinion", 'Speeding up revenue tax collection', 'Appealing on political grounds'], ['न्यायाधीश के व्यक्तिगत विचार से असहमति', 'टैक्स वसूली तेज करने हेतु', 'राजनीतिक आधारों पर'], 'Certiorari quashes orders passed without jurisdiction or in flagrant breach of natural justice (Audi Alteram Partem).', 'यदि किसी ट्रिब्यूनल या कोर्ट ने बिना अधिकार क्षेत्र के या बिना दोनों पक्षों को सुने फैसला दिया हो, तो उत्प्रेषण द्वारा उसे निरस्त किया जाता है।')]

slot_q115_dpsp = [('The Directive Principles of State Policy (DPSP) are contained in which Part of the Indian Constitution?', 'राज्य के नीति निदेशक तत्व (DPSP) भारतीय संविधान के किस भाग में वर्णित हैं?', 'Part IV, Articles 36 to 51', 'भाग IV, अनुच्छेद 36 से 51', ['Part III, Articles 12 to 35', 'Part IVA, Article 51A', 'Part V, Articles 52 to 151'], ['भाग III, अनुच्छेद 12 से 35', 'भाग IVक, अनुच्छेद 51क', 'भाग V, अनुच्छेद 52 से 151'], 'Directive Principles of State Policy are enumerated in Part IV of the Constitution, spanning Articles 36 to 51.', 'नीति निदेशक तत्व संविधान के भाग 4 में अनुच्छेद 36 से 51 तक वर्णित हैं।'), ("From which country's Constitution were the Directive Principles of State Policy borrowed?", 'भारतीय संविधान में राज्य के नीति निदेशक तत्व किस देश के संविधान से प्रेरित होकर लिए गए हैं?', 'Constitution of Ireland (Irish Constitution, 1937)', 'आयरलैंड के संविधान से (1937)', ['Constitution of USA', 'Constitution of USSR', 'Weimar Constitution of Germany'], ['संयुक्त राज्य अमेरिका से', 'सोवियत संघ से', 'जर्मनी के वाइमर संविधान से'], 'The framers borrowed the Directive Principles from the 1937 Constitution of Ireland, which had copied them from Spain.', 'भारतीय संविधान निर्माताओं ने नीति निदेशक तत्वों का विचार आयरलैंड के संविधान से ग्रहण किया था।'), ('Under Article 37, the Directive Principles of State Policy are explicitly declared to be', 'अनुच्छेद 37 के अनुसार राज्य के नीति निदेशक तत्वों की विधिक प्रकृति क्या है?', 'Non-justiciable (not enforceable by any court), but fundamental in governance', 'अदालतों द्वारा गैर-प्रवर्तनीय (गैर-वादयोग्य), किंतु शासन में मूलभूत', ['Directly enforceable by High Courts under Article 226', 'Superior to Fundamental Rights under all circumstances', 'Binding statutory laws'], ['उच्च न्यायालय द्वारा सीधे लागू करने योग्य', 'सभी परिस्थितियों में मूल अधिकारों से ऊपर', 'बाध्यकारी कानूनी विधियां'], 'Article 37 explicitly states that DPSPs shall not be enforceable by any court, but they are fundamental in the governance of the country.', 'अनुच्छेद 37 स्पष्ट करता है कि निदेशक तत्व न्यायालय द्वारा लागू नहीं कराए जा सकते, फिर भी देश के शासन में ये मूलभूत हैं।'), ('Dr. B.R. Ambedkar described the Directive Principles of State Policy as a', 'डॉ. बी.आर. आंबेडकर ने राज्य के नीति निदेशक तत्वों को क्या कहकर पुकारा था?', "'Novel Feature of the Indian Constitution'", "'भारतीय संविधान की अनूठी विशेषता' (Novel Feature)", ["'Poetic surplus of ideals'", "'Dead letter of Constitution'", "'Mere political manifesto'"], ["'आदर्शों की काव्यात्मक बहुलता'", "'संविधान का मृत पत्र'", "'केवल चुनावी घोषणापत्र'"], "Dr. Ambedkar praised DPSPs as a 'novel feature' aiming to establish economic and social democracy.", "डॉ. आंबेडकर ने नीति निदेशक तत्वों को भारतीय संविधान की एक 'अनूठी विशेषता' (Novel Feature) बताया था।"), ("Who famously remarked that Directive Principles of State Policy are like 'a cheque on a bank, payable at the convenience of the bank'?", "किसने नीति निदेशक तत्वों की तुलना 'एक ऐसे चेक से की जो बैंक की सुविधानुसार ही भुनाया जा सकता है'?", 'Prof. K.T. Shah', 'प्रो. के.टी. शाह (Prof. K.T. Shah)', ['Dr. B.R. Ambedkar', 'Granville Austin', 'Sir Ivor Jennings'], ['डॉ. बी.आर. आंबेडकर', 'ग्रैनविल ऑस्टिन', 'सर आइवर जेनिंग्स'], "Prof. K.T. Shah criticized their non-enforceability by comparing them to a bank cheque payable only at the bank's convenience.", 'प्रो. के.टी. शाह ने गैर-प्रवर्तनीयता पर तंज कसते हुए कहा था कि यह ऐसा चेक है जिसका भुगतान बैंक अपनी इच्छा से करता है।'), ('Granville Austin described Fundamental Rights and Directive Principles together as the', 'प्रसिद्ध संविधानविद ग्रैनविल ऑस्टिन ने मूल अधिकारों और नीति निदेशक तत्वों को संयुक्त रूप से क्या कहा?', "'Conscience of the Indian Constitution'", "'भारतीय संविधान की अंतरात्मा' (Conscience of Constitution)", ["'Skeleton of governance'", "'Mirror of colonial rule'", "'Administrative appendix'"], ["'शासन का कंकाल'", "'औपनिवेशिक शासन का दर्पण'", "'प्रशासनिक परिशिष्ट'"], "Austin observed that Fundamental Rights and DPSPs together form the 'Conscience of the Constitution', fostering social revolution.", "ग्रैनविल ऑस्टिन ने मूल अधिकारों और निदेशक तत्वों को मिलकर 'संविधान की अंतरात्मा' कहा था।"), ('Which Article of the Constitution directs the State to secure a social order for the promotion of welfare of the people?', 'संविधान का कौन सा अनुच्छेद राज्य को लोक कल्याण की अभिवृद्धि के लिए सामाजिक व्यवस्था बनाने का निर्देश देता है?', 'Article 38', 'अनुच्छेद 38', ['Article 36', 'Article 37', 'Article 39'], ['अनुच्छेद 36', 'अनुच्छेद 37', 'अनुच्छेद 39'], 'Article 38 directs the State to minimize inequalities in income, status, facilities, and opportunities.', 'अनुच्छेद 38 राज्य को कल्याणकारी राज्य (Welfare State) की स्थापना और असमानता कम करने का निर्देश देता है।'), ('Article 39(b) and Article 39(c) are famous socialistic principles directing the State to', 'अनुच्छेद 39(ख) और 39(ग) राज्य को किन समाजवादी लक्ष्यों को प्राप्त करने का निर्देश देते हैं?', 'Distribute material resources of the community for common good, and prevent concentration of wealth', 'सामूहिक हित के लिए भौतिक संसाधनों का उचित वितरण, तथा धन के संकेंद्रण पर रोक', ['Establish state-owned factories only', 'Abolish all private commercial properties', 'Enforce equal bank savings for all'], ['केवल सरकारी कारखाने स्थापित करना', 'सभी निजी संपत्तियों को खत्म करना', 'सभी के बैंक खाते समान करना'], 'Article 39(b) and (c) prevent economic monopolies and promote equitable distribution, given special protection under Article 31C.', '39(ख) व (ग) भौतिक संसाधनों के जनहित में वितरण और उत्पादन के साधनों के अहितकारी संकेंद्रण को रोकने पर बल देते हैं।'), ('Equal pay for equal work for both men and women is a Directive Principle provided under', "पुरुषों और स्त्रियों दोनों के लिए 'समान कार्य के लिए समान वेतन' किस अनुच्छेद के तहत एक नीति निदेशक तत्व है?", 'Article 39(d)', 'अनुच्छेद 39(घ) [Article 39(d)]', ['Article 14', 'Article 16(1)', 'Article 42'], ['अनुच्छेद 14', 'अनुच्छेद 16(1)', 'अनुच्छेद 42'], 'Article 39(d) mandates that the State shall direct its policy towards securing equal pay for equal work for both men and women.', 'अनुच्छेद 39(घ) राज्य को निर्देश देता है कि वह महिला एवं पुरुष दोनों के लिए समान कार्य हेतु समान वेतन सुनिश्चित करे।'), ('Article 39A was inserted by the 42nd Amendment Act 1976 to provide for', '42वें संशोधन (1976) द्वारा जोड़े गए अनुच्छेद 39क (39A) में किस बात का प्रावधान है?', 'Equal justice and free legal aid to the poor and indigent', 'समान न्याय एवं गरीबों को निःशुल्क विधिक सहायता', ['Compulsory free education up to secondary level', 'Universal old-age pensions', 'State health insurance for farmers'], ['माध्यमिक स्तर तक अनिवार्य शिक्षा', 'सार्वभौमिक वृद्धावस्था पेंशन', 'किसानों हेतु स्वास्थ्य बीमा'], 'Article 39A directs the State to secure that opportunities for securing justice are not denied to any citizen by reason of economic disability; led to NALSA Act 1987.', 'अनुच्छेद 39क समान न्याय और गरीबों को मुफ्त कानूनी सहायता (Free Legal Aid) देने का निर्देश देता है, जिससे नालसा (NALSA) बना।'), ('Article 40 of the Constitution directs the State to take steps to organize', 'संविधान का अनुच्छेद 40 राज्य को किसके गठन के लिए कदम उठाने का निर्देश देता है?', 'Village Panchayats as units of local self-government', 'ग्राम पंचायतों का गठन (Village Panchayats)', ['District cooperative banks', 'Agricultural credit societies', 'Municipal corporations in metro cities'], ['जिला सहकारी बैंक', 'कृषि साख समितियां', 'महानगरों में नगर निगम'], 'Article 40 embodies the Gandhian dream of Gram Swaraj, empowering village panchayats as units of self-government; implemented by 73rd Amendment.', 'अनुच्छेद 40 गांधीवादी विचार पर आधारित है, जो ग्राम पंचायतों को स्वशासन की इकाइयों के रूप में संगठित करने का निर्देश देता है।'), ('Article 41 directs the State to secure the right to work, to education, and to public assistance in cases of', 'अनुच्छेद 41 किन दशाओं में काम पाने, शिक्षा पाने और लोक सहायता पाने के अधिकार का उपबंध करता है?', 'Unemployment, old age, sickness, and disablement', 'बेरोजगारी, बुढ़ापा, बीमारी और निःशक्तता (दिव्यांगता) की दशा में', ['Natural floods and drought only', 'Foreign invasion emergencies', 'Political imprisonment only'], ['केवल बाढ़ और सूखे में', 'विदेशी आक्रमण के समय', 'केवल राजनीतिक बंदियों के लिए'], 'Article 41 provides for social security (pensions, MNREGA, disability schemes) within the economic capacity of the State.', 'अनुच्छेद 41 वृद्धावस्था पेंशन, विकलांग सहायता और मनरेगा (काम का अधिकार) जैसी सामाजिक सुरक्षा योजनाओं का आधार है।'), ('Article 42 directs the State to make provision for securing just and humane conditions of work and for', 'अनुच्छेद 42 काम की न्यायसंगत और मानवोचित दशाओं को सुनिश्चित करने के साथ-साथ किसके लिए उपबंध करता है?', 'Maternity Relief (प्रसूति सहायता)', 'प्रसूति सहायता (Maternity Relief)', ['Universal minimum pension', 'Free medical surgeries for workers', 'Free residential housing'], ['न्यूनतम पेंशन', 'मुफ्त शल्य चिकित्सा', 'मुफ्त आवास'], 'Article 42 is the constitutional basis for the Maternity Benefit Act, 1961 (and 2017 amendment granting 26 weeks paid leave).', 'अनुच्छेद 42 प्रसूति सहायता का निर्देश देता है, जिसके आधार पर मातृत्व लाभ अधिनियम (26 सप्ताह का सवेतन अवकाश) बनाया गया।'), ('Article 43 directs the State to secure by legislation or economic organization a', 'अनुच्छेद 43 राज्य को सभी कामगारों के लिए क्या सुनिश्चित करने का प्रयास करने का निर्देश देता है?', 'Living Wage, decent standard of life, and cottage industries in rural areas', 'निर्वाह मजदूरी (Living Wage), शिष्ट जीवन स्तर, एवं ग्रामीण कुटीर उद्योग', ['Maximum wealth ceiling', 'Compulsory industrial profit sharing', 'Abolition of private factories'], ['अधिकतम संपत्ति सीमा', 'अनिवार्य औद्योगिक मुनाफा बंटवारा', 'निजी कारखानों की समाप्ति'], "Article 43 aims for a 'living wage' (which covers education, health, and comfort, higher than minimum wage) and promotes cottage industries.", 'अनुच्छेद 43 जीवन निर्वाह योग्य वेतन और ग्रामीण क्षेत्रों में कुटीर उद्योगों को बढ़ावा देने का निर्देश देता है।'), ('Article 43A was inserted by the 42nd Amendment Act, 1976 to provide for', '42वें संशोधन (1976) द्वारा शामिल किया गया अनुच्छेद 43क (43A) किससे संबंधित है?', 'Participation of workers in the management of industries', 'उद्योगों के प्रबंध में कर्मकारों (श्रमिकों) की भागीदारी', ['Compulsory trade union membership', 'State ownership of all textile mills', 'Minimum 8-hour work shift'], ['ट्रेड यूनियन की अनिवार्य सदस्यता', 'कपड़ा मिलों का राष्ट्रीयकरण', 'काम का 8 घंटे का समय'], 'Article 43A directs the State to secure participation of workers in the management of undertakings and establishments.', 'अनुच्छेद 43क औद्योगिक लोकतंत्र की स्थापना हेतु कारखानों के प्रबंधन में श्रमिकों की भागीदारी का प्रावधान करता है।'), ('Which Article was inserted by the 97th Constitutional Amendment Act, 2011 to promote voluntary formation of Co-operative Societies?', '97वें संविधान संशोधन (2011) द्वारा सहकारी समितियों के संवर्धन हेतु कौन सा अनुच्छेद जोड़ा गया?', 'Article 43B', 'अनुच्छेद 43ख [Article 43B]', ['Article 42A', 'Article 44A', 'Article 45A'], ['अनुच्छेद 42क', 'अनुच्छेद 44क', 'अनुच्छेद 45क'], 'Article 43B directs the State to promote voluntary formation, autonomous functioning, and professional management of co-operative societies.', 'अनुच्छेद 43ख राज्य को सहकारी समितियों के गठन, स्वायत्तता और पेशेवर प्रबंधन को बढ़ावा देने का निर्देश देता है।'), ('Article 44 of the Constitution of India directs the State to secure for the citizens a', 'भारतीय संविधान का अनुच्छेद 44 नागरिकों के लिए क्या सुनिश्चित करने का निर्देश देता है?', 'Uniform Civil Code (समान नागरिक संहिता) throughout India', 'समान नागरिक संहिता (Uniform Civil Code - UCC)', ['Uniform criminal code across all states', 'Uniform agricultural land ceiling', 'Uniform national education curriculum'], ['समान आपराधिक कानून', 'समान कृषि भूमि सीमा', 'समान राष्ट्रीय पाठ्यक्रम'], 'Article 44 directs that the State shall endeavor to secure for the citizens a Uniform Civil Code throughout the territory of India.', 'अनुच्छेद 44 पूरे देश में विवाह, तलाक, उत्तराधिकार आदि में सभी नागरिकों के लिए एक समान नागरिक संहिता लागू करने का निर्देश देता है।'), ('Which is the only State in India that historically had a functioning Uniform Civil Code from the Portuguese era?', 'भारत का एकमात्र राज्य कौन सा है जहां पुर्तगाली काल से ही एक समान नागरिक संहिता (Civil Code) लागू रही है?', 'Goa', 'गोवा (Goa)', ['Kerala', 'Sikkim', 'Nagaland'], ['केरल', 'सिक्किम', 'नागालैंड'], 'Goa has retained the Portuguese Civil Code of 1867, under which all communities follow common family and succession laws.', 'गोवा में 1867 का पुर्तगाली नागरिक संहिता लागू है, जहां सभी धर्मों के लोग समान पारिवारिक कानून मानते हैं।'), ('Which was the first State in independent India to pass a Uniform Civil Code (UCC) Bill in its legislative assembly in 2024?', '2024 में अपनी विधानसभा से समान नागरिक संहिता (UCC) विधेयक पारित करने वाला स्वतंत्र भारत का पहला राज्य कौन बना?', 'Uttarakhand', 'उत्तराखंड (Uttarakhand)', ['Gujarat', 'Assam', 'Madhya Pradesh'], ['गुजरात', 'असम', 'मध्य प्रदेश'], 'Uttarakhand passed the Uniform Civil Code Bill in February 2024, becoming the first state in independent India to enact modern UCC legislation.', 'उत्तराखंड विधानसभा ने फरवरी 2024 में ऐतिहासिक समान नागरिक संहिता (UCC) कानून पारित किया।'), ('Article 45 was amended by the 86th Constitutional Amendment Act, 2002 to direct the State to provide', '86वें संशोधन (2002) के बाद संशोधित अनुच्छेद 45 राज्य को किसके लिए प्रयास करने का निर्देश देता है?', 'Early childhood care and education for all children until they complete the age of six years', '6 वर्ष से कम आयु के सभी बच्चों के लिए प्रारंभिक बाल्यावस्था देखरेख और शिक्षा (0 से 6 वर्ष)', ['Free laptop computers for college graduates', 'Universal creche facilities in all offices', 'Compulsory mid-day meals up to class 12'], ['कॉलेज स्नातकों को लैपटॉप', 'सभी दफ्तरों में पालनाघर', '12वीं तक मिड-डे मील'], 'After 6-14 education became a Fundamental Right (Art 21A), Article 45 was rephrased to focus on early childhood care (0-6 years).', '6 से 14 वर्ष की शिक्षा अनुच्छेद 21क में जाने के बाद अनुच्छेद 45 में 6 वर्ष तक के शिशुओं के पोषण और आंगनवाड़ी शिक्षा का लक्ष्य रखा गया।'), ('Article 46 directs the State to promote with special care the educational and economic interests of', 'संविधान का अनुच्छेद 46 राज्य को विशेष सावधानी से किन वर्गों के शैक्षणिक और आर्थिक हितों की अभिवृद्धि का निर्देश देता है?', 'Scheduled Castes, Scheduled Tribes, and other weaker sections', 'अनुसूचित जातियों, अनुसूचित जनजातियों एवं अन्य दुर्बल वर्गों के', ['Industrial business entrepreneurs', 'Government civil servants', 'Commercial trading exporters'], ['औद्योगिक व्यापारियों के', 'सरकारी अधिकारियों के', 'व्यापारिक निर्यातकों के'], 'Article 46 directs the State to protect SCs, STs, and weaker sections from social injustice and all forms of exploitation.', 'अनुच्छेद 46 अनुसूचित जातियों, जनजातियों और कमजोर वर्गों को सामाजिक अन्याय और सभी प्रकार के शोषण से बचाने का निर्देश देता है।'), ('Article 47 directs the State to regard which duties as among its primary duties?', 'अनुच्छेद 47 किन लक्ष्यों को राज्य के प्राथमिक कर्तव्यों में से एक मानता है?', 'Raising level of nutrition, standard of living, and prohibiting intoxicating drinks and drugs', 'पोषाहार स्तर और जीवन स्तर को ऊंचा करना, तथा नशीले पेय और मादक द्रव्यों पर प्रतिबंध लगाना', ['Providing free foreign air travel', 'Establishing state-run liquor breweries', 'Compulsory private gym memberships'], ['मुफ्त विदेश यात्रा', 'सरकारी शराब कारखाने बनाना', 'अनिवार्य जिम सदस्यता'], 'Article 47 provides the constitutional foundation for prohibition of intoxicating liquor (enacted in states like Bihar and Gujarat).', 'अनुच्छेद 47 शराबबंदी और लोक स्वास्थ्य सुधार का आधार है, जिसके तहत बिहार और गुजरात में मद्यनिषेध लागू किया गया।'), ('Article 48 of the Constitution directs the State to organize agriculture and animal husbandry, and specifically to prohibit the slaughter of', 'अनुच्छेद 48 कृषि और पशुपालन को आधुनिक बनाने के साथ-साथ विशेष रूप से किसके वध पर रोक लगाने का निर्देश देता है?', 'Cows, calves, and other milch and draught cattle', 'गायों, बछड़ों तथा अन्य दुधारू और वाहक पशुओं के वध पर', ['Poultry chickens and sheep only', 'Wild boars and stray animals', 'Horses and race camels'], ['मुर्गियों और भेड़ों पर', 'जंगली सुअर व आवारा पशुओं पर', 'घोड़ों और ऊंटों पर'], 'Article 48 embodies Gandhian and scientific principles: modernizing agriculture and preserving breeds of cattle and draught animals.', 'अनुच्छेद 48 वैज्ञानिक कृषि के साथ-साथ गायों और दुधारू पशुओं के वध पर प्रतिबंध लगाने का निर्देश देता है।'), ('Article 48A was inserted by the 42nd Amendment Act, 1976 to direct the State to', '42वें संशोधन (1976) द्वारा संविधान में जोड़ा गया अनुच्छेद 48क (48A) राज्य को क्या निर्देश देता है?', 'Protect and improve the environment, and safeguard forests and wild life', 'पर्यावरण का संरक्षण तथा संवर्धन, और वन तथा वन्य जीवों की रक्षा करना', ['Nationalize all private timber plantations', 'Abolish all national parks', 'Compulsory tree cutting for road widening'], ['निजी लकड़ी बागानों का राष्ट्रीयकरण', 'राष्ट्रीय उद्यान बंद करना', 'सड़क चौड़ीकरण हेतु पेड़ काटना'], 'Article 48A directs the State to protect environment and wildlife; constitutional basis for Wildlife Protection Act and Forest Conservation Act.', 'अनुच्छेद 48क पर्यावरण संरक्षण और वनों एवं वन्यजीवों की रक्षा का राज्य पर संवैधानिक दायित्व डालता है।'), ('Article 49 of the Constitution directs the State to protect', 'संविधान का अनुच्छेद 49 राज्य को किसके संरक्षण का दायित्व सौंपता है?', 'Monuments, places, and objects of national importance and historic interest', 'राष्ट्रीय महत्व के घोषित किए गए स्मारकों, स्थानों एवं कलात्मक व ऐतिहासिक वस्तुओं का', ['Modern commercial shopping malls', 'Private modern skyscraper apartments', 'Local political party office buildings'], ['शॉपिंग मॉल और प्लाजा', 'निजी गगनचुंबी इमारतें', 'राजनीतिक दलों के दफ्तर'], 'Article 49 obligates the State to protect historic monuments against spoliation, disfigurement, destruction, or export.', 'अनुच्छेद 49 भारतीय पुरातत्व सर्वेक्षण (ASI) और ऐतिहासिक धरोहरों के संरक्षण का संवैधानिक आधार है।'), ('Article 50 of the Constitution directs the State to separate', 'संविधान का अनुच्छेद 50 राज्य को क्या अलग करने का निर्देश देता है?', 'The Judiciary from the Executive in the public services of the State', 'राज्य की लोक सेवाओं में न्यायपालिका को कार्यपालिका से अलग करना', ['The Prime Minister from the President', 'The Armed Forces from the Police', 'The Union Government from States'], ['प्रधानमंत्री को राष्ट्रपति से', 'सेना को नागरिक पुलिस से', 'केंद्र सरकार को राज्यों से'], 'Article 50 ensures independence of the judiciary by taking judicial powers away from executive officers (District Magistrates).', 'अनुच्छेद 50 कार्यपालिका से न्यायिक कार्यों को अलग कर स्वतंत्र और निष्पक्ष न्यायपालिका की स्थापना सुनिश्चित करता है।'), ('Article 51 directs the State to promote', 'संविधान का अनुच्छेद 51 राज्य को किसके संवर्धन का निर्देश देता है?', 'International peace and security, and respect for international law and treaty obligations', 'अंतर्राष्ट्रीय शांति और सुरक्षा की अभिवृद्धि, तथा अंतर्राष्ट्रीय विधि और संधियों का आदर', ['Military annexation of neighboring territories', 'Withdrawal from the United Nations', 'Establishment of nuclear defense bases'], ['पड़ोसी क्षेत्रों का सैन्य अधिग्रहण', 'संयुक्त राष्ट्र से हटना', 'परमाणु सैन्य ठिकानों की स्थापना'], "Article 51 serves as the constitutional foundation of India's non-aligned, peaceful, and rules-based foreign policy.", 'अनुच्छेद 51 भारत की विदेश नीति का पथ-प्रदर्शक है, जो विश्व शांति और संधियों के सम्मान पर जोर देता है।'), ('In Champakam Dorairajan v. State of Madras (1951), the Supreme Court ruled on the conflict between Fundamental Rights and DPSPs that', 'चंपाकम दोराईराजन मामले (1951) में सुप्रीम कोर्ट ने मूल अधिकारों और नीति निदेशक तत्वों के टकराव में क्या व्यवस्था दी थी?', 'Fundamental Rights are superior, and DPSPs must run as subsidiary to Fundamental Rights', 'मूल अधिकार सर्वोच्च हैं और नीति निदेशक तत्व उनके अधीन (सहायक) रहकर ही लागू होंगे', ['DPSPs override Fundamental Rights under all conditions', 'Both have exactly identical legal enforceability', 'DPSPs are unconstitutional'], ['निदेशक तत्व हमेशा मूल अधिकारों पर हावी हैं', 'दोनों की कानूनी शक्ति बिल्कुल समान है', 'निदेशक तत्व असंवैधानिक हैं'], 'The Supreme Court held that Directive Principles cannot override Fundamental Rights; led Parliament to pass 1st Constitutional Amendment.', 'सुप्रीम कोर्ट ने कहा कि मूल अधिकार प्राथमिक हैं और निदेशक तत्व उनके सहायक हैं, जिससे पहला संविधान संशोधन हुआ।'), ('Which Constitutional Amendment Act added Part IVA and Article 51A (Fundamental Duties) to the Constitution?', "किस संविधान संशोधन अधिनियम द्वारा संविधान में भाग IVक और अनुच्छेद 51क जोड़कर 'मौलिक कर्तव्य' शामिल किए गए?", '42nd Constitutional Amendment Act, 1976', '42वां संविधान संशोधन अधिनियम (1976)', ['44th Amendment Act, 1978', '24th Amendment Act, 1971', '86th Amendment Act, 2002'], ['44वां संशोधन (1978)', '24वां संशोधन (1971)', '86वां संशोधन (2002)'], 'Added during the Internal Emergency in 1976 based on the recommendations of the Swaran Singh Committee.', 'सरदार स्वर्ण सिंह समिति की सिफारिशों के आधार पर 42वें संशोधन (1976) द्वारा नागरिकों के मौलिक कर्तव्य जोड़े गए।'), ('On the recommendations of which Committee were Fundamental Duties incorporated into the Indian Constitution?', 'किस समिति की सिफारिश पर भारतीय संविधान में मौलिक कर्तव्यों को शामिल किया गया था?', 'Sardar Swaran Singh Committee (1976)', 'सरदार स्वर्ण सिंह समिति (1976)', ['Verma Committee', 'Kothari Commission', 'Sarkaria Commission'], ['वर्मा समिति', 'कोठारी आयोग', 'सरकारिया आयोग'], 'The Swaran Singh Committee recommended 8 duties; the 42nd Amendment incorporated 10 Fundamental Duties in 1976.', 'स्वर्ण सिंह समिति ने 8 कर्तव्यों की सिफारिश की थी, किंतु सरकार ने 42वें संशोधन में 10 कर्तव्य जोड़े।'), ("From which country's Constitution did India borrow the concept of Fundamental Duties?", 'भारतीय संविधान में मौलिक कर्तव्यों का विचार किस देश के संविधान से लिया गया था?', 'Former USSR (Soviet Constitution)', 'पूर्व सोवियत संघ (USSR) के संविधान से', ['United States Constitution', 'Constitution of Canada', 'Constitution of Australia'], ['संयुक्त राज्य अमेरिका से', 'कनाडा से', 'ऑस्ट्रेलिया से'], 'Borrowing from the socialist Soviet Constitution, India became one of the few major democracies with codified duties.', 'सोवियत संघ के संविधान से प्रेरित होकर भारत ने अपने नागरिकों के लिए संवैधानिक कर्तव्यों को अंगीकार किया।'), ('How many Fundamental Duties were originally inserted into Article 51A by the 42nd Amendment in 1976?', '1976 में 42वें संविधान संशोधन द्वारा अनुच्छेद 51क में मूलतः कितने मौलिक कर्तव्य जोड़े गए थे?', '10 Fundamental Duties', '10 मौलिक कर्तव्य', ['8 Duties', '11 Duties', '12 Duties'], ['8 कर्तव्य', '11 कर्तव्य', '12 कर्तव्य'], 'The 42nd Amendment added 10 duties; the 11th duty was added in 2002 by the 86th Amendment.', '42वें संशोधन द्वारा प्रारंभ में 10 कर्तव्य जोड़े गए थे; 11वां कर्तव्य 2002 में जोड़ा गया।'), ('How many Fundamental Duties are currently listed in Article 51A of the Indian Constitution?', 'वर्तमान समय में भारतीय संविधान के अनुच्छेद 51क में कुल कितने मौलिक कर्तव्य वर्णित हैं?', '11 Fundamental Duties', '11 मौलिक कर्तव्य', ['10 Duties', '12 Duties', '9 Duties'], ['10 कर्तव्य', '12 कर्तव्य', '9 कर्तव्य'], 'There are 11 duties labeled (a) to (k) in Article 51A.', 'वर्तमान में अनुच्छेद 51क के अंतर्गत कुल 11 मौलिक कर्तव्य हैं।'), ('Which 11th Fundamental Duty was added to Article 51A(k) by the 86th Constitutional Amendment Act, 2002?', '86वें संशोधन अधिनियम (2002) द्वारा अनुच्छेद 51क(ट) [51A(k)] में कौन सा 11वां कर्तव्य जोड़ा गया?', 'Duty of a parent or guardian to provide educational opportunities to his child between ages 6 and 14', 'माता-पिता या संरक्षक का कर्तव्य कि वे 6 से 14 वर्ष तक की आयु के अपने बच्चे को शिक्षा के अवसर प्रदान करें', ['Duty to pay income taxes punctually', 'Duty to vote in general elections', 'Duty to plant ten trees every year'], ['समय पर आयकर चुकाने का कर्तव्य', 'चुनाव में मतदान का कर्तव्य', 'हर वर्ष पेड़ लगाने का कर्तव्य'], 'Clause (k) was added alongside Article 21A, creating a civic parental duty to educate children aged 6 to 14.', '86वें संशोधन ने माता-पिता पर यह कर्तव्य डाला कि वे अपने 6 से 14 वर्ष के बच्चों को स्कूल भेजें।'), ('Which of the following was recommended by the Swaran Singh Committee but NOT accepted by the Government?', 'स्वर्ण सिंह समिति ने कौन सी सिफारिश की थी जिसे सरकार द्वारा स्वीकार नहीं किया गया था?', 'Duty to pay taxes, and penalties/punishment for non-compliance with duties', 'कर (Tax) अदा करने का कर्तव्य, तथा कर्तव्यों का पालन न करने पर दंड का प्रावधान', ['Respect for the National Flag', 'Protection of public property', 'Defending the country'], ['राष्ट्रीय ध्वज का सम्मान', 'सार्वजनिक संपत्ति की रक्षा', 'देश की रक्षा करना'], "Swaran Singh recommended making duties enforceable with punishment and adding a duty to pay taxes, both rejected by Indira Gandhi's government.", 'स्वर्ण सिंह समिति ने टैक्स भरने के कर्तव्य और कर्तव्य न मानने पर सजा की सिफारिश की थी, जिसे सरकार ने नहीं माना।'), ('Are the Fundamental Duties under Article 51A directly legally enforceable by courts on their own?', 'क्या अनुच्छेद 51क में दिए गए मौलिक कर्तव्य न्यायालयों द्वारा सीधे स्वतः प्रवर्तनीय (Enforceable) हैं?', 'Non-justiciable like DPSPs (not directly enforceable unless backed by specific statute)', 'नीति निदेशक तत्वों की भांति गैर-न्यायसंगत (जब तक उनके पीछे कोई विशिष्ट कानून न हो)', ['Directly enforceable with criminal fines by Supreme Court under Art 32', 'Enforceable only by President of India', 'Enforceable only during war emergencies'], ['सुप्रीम कोर्ट द्वारा सीधे दंडनीय', 'केवल राष्ट्रपति द्वारा लागू', 'केवल युद्ध के समय लागू'], 'Duties are moral and civic obligations; however, Parliament has enacted statutes (Prevention of Insults to National Honour Act, Wildlife Act) to punish specific breaches.', 'कर्तव्य स्वतः दंडनीय नहीं हैं, किंतु संसद ने उनके पालन हेतु कानून (राष्ट्रीय गौरव अपमान निवारण कानून आदि) बनाए हैं।'), ('Which Committee was appointed by the Government of India in 1998 to identify legal provisions for the enforcement of Fundamental Duties?', 'मौलिक कर्तव्यों के क्रियान्वयन हेतु कानूनी प्रावधानों की पहचान के लिए 1998 में कौन सी समिति गठित की गई थी?', 'Justice J.S. Verma Committee', 'न्यायमूर्ति जे.एस. वर्मा समिति (Justice J.S. Verma Committee)', ['Sarkaria Commission', 'Punchhi Commission', 'Venkatachaliah Commission'], ['सरकारिया आयोग', 'पुंछी आयोग', 'वेंकटचलैया आयोग'], 'The Justice Verma Committee (1999) identified existing legal provisions (IPC, Representation of People Act) enforcing various duties.', 'न्यायमूर्ति जे.एस. वर्मा समिति ने 1999 में उन कानूनों की सूची बनाई जो विभिन्न मौलिक कर्तव्यों को लागू कराते हैं।'), ('According to Article 51A(a), it is the duty of every citizen to abide by the Constitution and respect its ideals and institutions, the', 'अनुच्छेद 51क(क) के अनुसार प्रत्येक नागरिक का कर्तव्य है कि वह संविधान का पालन करे और उसके आदर्शों, संस्थाओं तथा किसका आदर करे?', 'National Flag and the National Anthem', 'राष्ट्रीय ध्वज एवं राष्ट्रगान (National Flag and National Anthem)', ['National Flower and National Animal', 'State political parties and legislatures', 'Presidential administrative orders'], ['राष्ट्रीय पुष्प एवं राष्ट्रीय पशु', 'राजनीतिक दल एवं विधानमंडल', 'राष्ट्रपति के प्रशासनिक आदेश'], 'Article 51A(a) mandates respect for the Constitution, its institutions, the National Flag, and the National Anthem (National Song is not explicitly mentioned here).', 'अनुच्छेद 51क(क) संविधान, उसके संस्थानों, राष्ट्रीय ध्वज और राष्ट्रगान के सम्मान का निर्देश देता है।'), ('Article 51A(b) mandates that citizens should cherish and follow the noble ideals that inspired our', 'अनुच्छेद 51क(ख) के अनुसार नागरिकों का कर्तव्य है कि वे उन उदात्त आदर्शों को संजोएं और उनका पालन करें जिन्होंने किसे प्रेरित किया?', 'National struggle for freedom', 'हमारे स्वतंत्रता के लिए राष्ट्रीय आंदोलन को (National Struggle for Freedom)', ['Industrial revolution in urban cities', 'Commercial foreign trade expansion', 'Ancient dynastic expansions'], ['शहरी औद्योगिक क्रांति को', 'विदेशी व्यापारिक विस्तार को', 'प्राचीन राजवंशीय विजयों को'], 'Article 51A(b) urges citizens to cherish the noble ideals of the Indian freedom movement.', 'अनुच्छेद 51क(ख) स्वतंत्रता आंदोलन के महान आदर्शों को हृदय में संजोए रखने का आह्वान करता है।'), ('Article 51A(c) calls upon every citizen to uphold and protect the', 'अनुच्छेद 51क(ग) प्रत्येक नागरिक से किसकी रक्षा करने और उसे अक्षुण्ण रखने का आह्वान करता है?', 'Sovereignty, unity, and integrity of India', 'भारत की संप्रभुता, एकता और अखंडता को', ['Privileges of members of Parliament', 'Monopoly of public sector industries', 'Jurisdiction of administrative tribunals'], ['सांसदों के विशेषाधिकारों को', 'सरकारी कंपनियों के एकाधिकार को', 'प्रशासनिक पंचाटों के अधिकार को'], 'Article 51A(c) enjoins every citizen to uphold and protect the sovereignty, unity, and integrity of India.', 'अनुच्छेद 51क(ग) भारत की संप्रभुता, एकता और अखंडता की रक्षा करने का कर्तव्य सौंपता है।'), ('Article 51A(d) calls upon citizens to defend the country and render national service when', 'अनुच्छेद 51क(घ) नागरिकों से देश की रक्षा करने और राष्ट्रसेवा करने का आह्वान कब करता है?', 'Called upon to do so', 'आह्वान किए जाने पर (When called upon to do so)', ['During civil court holidays only', 'Only after attaining sixty years of age', 'Only if paid executive salaries'], ['केवल अदालती छुट्टियों में', 'केवल 60 वर्ष की आयु के बाद', 'केवल वेतन मिलने पर'], 'Article 51A(d) directs citizens to defend the country and render national service when called upon to do so.', 'अनुच्छेद 51क(घ) देश की रक्षा करने और राष्ट्र की सेवा के लिए तत्पर रहने का निर्देश देता है।'), ('Article 51A(e) directs citizens to promote harmony and the spirit of common brotherhood, and to renounce practices derogatory to', 'अनुच्छेद 51क(ङ) समरसता और भ्रातृत्व की भावना बढ़ाने के साथ-साथ किसके सम्मान के विरुद्ध प्रथाओं के त्याग का निर्देश देता है?', 'The dignity of women', 'स्त्रियों के सम्मान के विरुद्ध (Dignity of Women)', ['Foreign diplomatic tourists', 'Local municipal administrative officers', 'Private corporate shareholders'], ['विदेशी पर्यटकों के विरुद्ध', 'नगरपालिका अफसरों के विरुद्ध', 'निजी शेयरधारकों के विरुद्ध'], 'Article 51A(e) mandates transcending religious, linguistic, and regional diversities and renouncing practices derogatory to women.', 'अनुच्छेद 51क(ङ) महिलाओं के सम्मान को ठेस पहुंचाने वाली सभी कुरीतियों का त्याग करने का निर्देश देता है।'), ('Article 51A(f) enjoins citizens to value and preserve the rich heritage of our', 'अनुच्छेद 51क(च) नागरिकों को हमारी किस धरोहर के महत्व को समझने और उसका परिरक्षण करने का निर्देश देता है?', 'Composite culture (सामासिक संस्कृति / Ganga-Jamuni Tehzeeb)', 'सामासिक संस्कृति (Composite Culture)', ['Monolithic religious orthodoxy', 'Colonial military architecture', 'Commercial foreign brands'], ['कट्टरपंथी धार्मिक रूढ़ियों', 'औपनिवेशिक सैन्य इमारतों', 'विदेशी व्यापारिक ब्रांडों'], "Article 51A(f) celebrates India's pluralist composite culture.", 'अनुच्छेद 51क(च) भारत की मिली-जुली सामासिक संस्कृति की समृद्ध विरासत की रक्षा का संदेश देता है।'), ('Article 51A(g) directs every citizen to protect and improve the natural environment, including', 'अनुच्छेद 51क(छ) प्रत्येक नागरिक को प्राकृतिक पर्यावरण की रक्षा करने का निर्देश देता है, जिसके अंतर्गत क्या शामिल हैं?', 'Forests, lakes, rivers, and wild life, and to have compassion for living creatures', 'वन, झील, नदी और वन्य जीव, तथा जीवित प्राणियों के प्रति दयाभाव रखना', ['Agricultural factories and fertilizers', 'Commercial poultry meat export units', 'Automobile highways'], ['खाद कारखाने', 'व्यापारिक बूचड़खाने', 'राजमार्ग'], 'Article 51A(g) imposes a civic duty to protect lakes, rivers, forests, wildlife, and show compassion to animals.', 'अनुच्छेद 51क(छ) वनों, झीलों, नदियों तथा वन्यजीवों की रक्षा और सभी जीवधारियों के प्रति दयाभाव का कर्तव्य देता है।'), ('Article 51A(h) directs citizens to develop the', 'अनुच्छेद 51क(ज) नागरिकों में किसका विकास करने का कर्तव्य तय करता है?', 'Scientific temper, humanism, and the spirit of inquiry and reform', 'वैज्ञानिक दृष्टिकोण, मानववाद और ज्ञानार्जन तथा सुधार की भावना', ['Blind superstitious beliefs', 'Religious fatalism and dogma', 'Traditional astrological predictions'], ['अंधविश्वास और रूढ़ियां', 'भाग्यवादिता', 'पारंपरिक भविष्यवाणियां'], 'Article 51A(h) urges developing a scientific temper and spirit of reform, rare among global constitutions.', 'अनुच्छेद 51क(ज) वैज्ञानिक दृष्टिकोण (Scientific Temper) और मानववाद विकसित करने का अनूठा कर्तव्य है।'), ('Article 51A(i) mandates citizens to safeguard public property and to', 'अनुच्छेद 51क(झ) नागरिकों को सार्वजनिक संपत्ति को सुरक्षित रखने और किससे दूर रहने का निर्देश देता है?', 'Abjure violence (हिंसा से दूर रहें)', 'हिंसा से दूर रहना (Abjure Violence)', ['Boycott all public buses', 'Refuse paying electricity bills', 'Demand private security escorts'], ['सरकारी बसों का बहिष्कार', 'बिजली बिल न भरना', 'निजी सुरक्षा की मांग'], 'Article 51A(i) explicitly directs citizens to safeguard public property and abjure violence.', 'अनुच्छेद 51क(झ) सार्वजनिक संपत्ति को नुकसान न पहुंचाने और हिंसा का त्याग करने का कर्तव्य तय करता है।'), ('Article 51A(j) directs citizens to strive towards excellence in all spheres of individual and collective activity so that', 'अनुच्छेद 51क(ञ) नागरिकों को व्यक्तिगत और सामूहिक गतिविधियों के सभी क्षेत्रों में उत्कर्ष की ओर बढ़ने का निर्देश क्यों देता है?', 'The nation constantly rises to higher levels of endeavor and achievement', 'जिससे राष्ट्र निरंतर बढ़ते हुए प्रयत्न और उपलब्धि की नई ऊंचाइयों को छू सके', ['Individuals can earn higher private corporate salaries', 'Government can reduce public sector recruitment', 'State can export luxury goods'], ['व्यक्तिगत वेतन बढ़ सके', 'सरकारी भर्तियां घटें', 'विलासिता का निर्यात हो'], "Article 51A(j) encourages excellence in all walks of life for the nation's constant progress.", 'अनुच्छेद 51क(ञ) देश को प्रगति की नई ऊंचाइयों पर ले जाने हेतु सभी क्षेत्रों में उत्कृष्टता का आह्वान करता है।'), ('Which Article serves as the directive principle for organizing agricultural animal husbandry and banning cow slaughter?', 'कृषि और पशुपालन को वैज्ञानिक ढंग से संगठित करने और गोवध पर प्रतिबंध लगाने वाला अनुच्छेद कौन सा है?', 'Article 48', 'अनुच्छेद 48', ['Article 46', 'Article 47', 'Article 49'], ['अनुच्छेद 46', 'अनुच्छेद 47', 'अनुच्छेद 49'], 'Article 48 directs modern organization of agriculture and animal husbandry, prohibiting the slaughter of cows and calves.', 'अनुच्छेद 48 कृषि सुधार और गोवंश संरक्षण का निर्देश देता है।')]

slot_q116_exec = [('Article 52 of the Constitution of India provides that', 'भारतीय संविधान का अनुच्छेद 52 क्या उपबंध करता है?', 'There shall be a President of India', 'भारत का एक राष्ट्रपति होगा (There shall be a President of India)', ['There shall be a Prime Minister of India', 'There shall be a Supreme Court of India', 'There shall be a Parliament of India'], ['भारत का एक प्रधानमंत्री होगा', 'भारत का एक सर्वोच्च न्यायालय होगा', 'भारत की एक संसद होगी'], 'Article 52 establishes the office of the President, the formal head of state and first citizen of India.', 'अनुच्छेद 52 भारत के राष्ट्राध्यक्ष एवं प्रथम नागरिक के रूप में राष्ट्रपति पद की स्थापना करता है।'), ('Under Article 53, the executive power of the Union is vested in the', 'अनुच्छेद 53 के अनुसार संघ की कार्यपालिका शक्ति किसमें निहित है?', 'President of India (exercised directly or through subordinate officers)', 'भारत के राष्ट्रपति में (स्वयं या अपने अधीनस्थ अधिकारियों के माध्यम से)', ['Prime Minister of India alone', 'Union Cabinet alone', 'Chief Justice of India'], ['केवल प्रधानमंत्री में', 'केवल केंद्रीय कैबिनेट में', 'भारत के मुख्य न्यायाधीश में'], 'Article 53 vests executive power in the President, exercised in accordance with the Constitution (on advice of Council of Ministers under Art 74).', 'संघ की कार्यपालिका शक्ति राष्ट्रपति में निहित है, जिसका प्रयोग वे मंत्रिपरिषद की सलाह से करते हैं।'), ('Who comprises the Electoral College for the election of the President of India under Article 54?', 'अनुच्छेद 54 के अनुसार राष्ट्रपति के निर्वाचक मंडल (Electoral College) में कौन शामिल होते हैं?', 'Elected members of both Houses of Parliament and elected members of Legislative Assemblies of all States (including Delhi and Puducherry)', 'संसद के दोनों सदनों के निर्वाचित सदस्य तथा राज्यों की विधान सभाओं (दिल्ली व पुदुचेरी सहित) के निर्वाचित सदस्य', ['All members of Parliament including nominated members', 'Elected members of Parliament and State Legislative Councils', 'Only Lok Sabha members and Governors'], ['मनोनीत सदस्यों सहित संसद के सभी सदस्य', 'संसद और विधान परिषदों के सदस्य', 'केवल लोकसभा सदस्य और राज्यपाल'], 'Nominated members of Parliament and members of State Legislative Councils (MLCs) do NOT participate in the Presidential election.', 'संसद के मनोनीत सदस्य और विधान परिषदों के सदस्य राष्ट्रपति चुनाव में भाग नहीं लेते।'), ('Which Constitutional Amendment Act included the elected members of the Legislative Assemblies of Delhi and Puducherry in the Presidential Electoral College?', 'किस संविधान संशोधन अधिनियम द्वारा दिल्ली और पुदुचेरी की विधानसभाओं के निर्वाचित सदस्यों को राष्ट्रपति के निर्वाचक मंडल में शामिल किया गया?', '70th Constitutional Amendment Act, 1992', '70वां संविधान संशोधन अधिनियम (1992)', ['69th Amendment Act, 1991', '61st Amendment Act, 1988', '42nd Amendment Act, 1976'], ['69वां संशोधन (1991)', '61वां संशोधन (1988)', '42वां संशोधन (1976)'], 'The 70th Amendment Act 1992 amended the Explanation to Article 54, including Delhi and Puducherry MLAs.', '70वें संविधान संशोधन (1992) द्वारा दिल्ली और पुदुचेरी के विधायकों को राष्ट्रपति चुनाव में मतदान का अधिकार मिला।'), ('What system of voting is used in the election of the President of India under Article 55?', 'अनुच्छेद 55 के तहत राष्ट्रपति का चुनाव किस मतदान प्रणाली द्वारा संपन्न होता है?', 'System of proportional representation by means of the single transferable vote and secret ballot', 'आनुपातिक प्रतिनिधित्व पद्धति के अनुसार एकल संक्रमणीय मत और गुप्त मतदान द्वारा', ['First-past-the-post system by open show of hands', 'Direct universal adult suffrage by electronic voting machines', 'Simple majority system of MPs only'], ['हाथ उठाकर प्रत्यक्ष मतदान', 'ईवीएम द्वारा सीधा जनता द्वारा मतदान', 'केवल सांसदों का साधारण बहुमत'], 'Article 55(3) mandates proportional representation by single transferable vote, ensuring uniform representation of states and parity between Union and States.', 'राष्ट्रपति का चुनाव एकल संक्रमणीय मत द्वारा आनुपातिक प्रतिनिधित्व प्रणाली और गुप्त मतपत्र से होता है।'), ('Under Article 56, what is the normal term of office of the President of India?', 'अनुच्छेद 56 के अनुसार भारत के राष्ट्रपति का सामान्य कार्यकाल कितना होता है?', '5 Years from the date on which he enters upon his office', 'पद ग्रहण करने की तिथि से 5 वर्ष तक', ['6 Years', '4 Years', 'Until the age of 65 years'], ['6 वर्ष', '4 वर्ष', '65 वर्ष की आयु तक'], 'The President holds office for five years, but continues until his successor enters upon office.', 'राष्ट्रपति का कार्यकाल पद ग्रहण करने की तारीख से 5 वर्ष का होता है; नया राष्ट्रपति आने तक वे पद पर बने रहते हैं।'), ('To whom does the President of India address his resignation letter under Article 56(1)(a)?', 'अनुच्छेद 56(1)(क) के अनुसार भारत के राष्ट्रपति अपना त्यागपत्र किसे संबोधित करते हैं?', 'Vice-President of India', 'भारत के उपराष्ट्रपति को', ['Chief Justice of India', 'Prime Minister of India', 'Speaker of Lok Sabha'], ['भारत के मुख्य न्यायाधीश को', 'भारत के प्रधानमंत्री को', 'लोकसभा अध्यक्ष को'], 'The President resigns by writing to the Vice-President, who immediately communicates it to the Speaker of Lok Sabha under Art 56(2).', 'राष्ट्रपति अपना त्यागपत्र उपराष्ट्रपति को सौंपते हैं, जिसकी सूचना उपराष्ट्रपति तुरंत लोकसभा अध्यक्ष को देते हैं।'), ('Is an incumbent President eligible for re-election to the office of President under Article 57?', 'अनुच्छेद 57 के अनुसार क्या कोई व्यक्ति भारत में पुनः राष्ट्रपति पद पर निर्वाचित हो सकता है?', 'Yes, eligible for re-election any number of times', 'हां, कितनी भी बार पुनः निर्वाचित हो सकते हैं', ['No, strictly barred from second term', 'Eligible for a maximum of two terms only (like USA)', 'Only after a gap of five years'], ['नहीं, दोबारा चुनाव पर रोक है', 'अधिकतम केवल दो बार (अमेरिका की तरह)', 'केवल 5 वर्ष के अंतराल के बाद'], 'Unlike the US Constitution (22nd Amendment capping at 2 terms), Article 57 imposes no term limit; Dr. Rajendra Prasad served twice.', 'भारतीय संविधान में राष्ट्रपति पद के लिए कोई अधिकतम सीमा नहीं है; डॉ. राजेंद्र प्रसाद दो बार निर्वाचित हुए थे।'), ('What is the minimum age qualification for election as President of India under Article 58?', 'अनुच्छेद 58 के अनुसार राष्ट्रपति पद का प्रत्याशी होने के लिए न्यूनतम आयु कितनी होनी चाहिए?', '35 Years of age', '35 वर्ष की आयु', ['25 Years', '30 Years', '40 Years'], ['25 वर्ष', '30 वर्ष', '40 वर्ष'], 'A presidential candidate must be a citizen of India, at least 35 years of age, and qualified for election as a member of Lok Sabha.', 'प्रत्याशी भारत का नागरिक हो, कम से कम 35 वर्ष की आयु पूरी कर चुका हो, तथा लोकसभा सदस्य बनने की योग्यता रखता हो।'), ('Under the Presidential and Vice-Presidential Elections Act 1952, how many proposers and seconders are required for a Presidential nomination?', 'राष्ट्रपति चुनाव के नामांकन हेतु कितने प्रस्तावकों और कितने अनुमोदकों के हस्ताक्षर अनिवार्य हैं?', '50 Proposers and 50 Seconders (Electors)', '50 प्रस्तावक एवं 50 अनुमोदक (मतदाता)', ['10 Proposers and 10 Seconders', '20 Proposers and 20 Seconders', '100 Proposers and 100 Seconders'], ['10 प्रस्तावक एवं 10 अनुमोदक', '20 प्रस्तावक एवं 20 अनुमोदक', '100 प्रस्तावक एवं 100 अनुमोदक'], 'To discourage non-serious candidates, amended in 1997 to require 50 proposers and 50 seconders from the Electoral College, plus ₹15,000 security deposit.', '1997 में नियमों को कड़ा कर 50 प्रस्तावक, 50 अनुमोदक तथा ₹15,000 की जमानत राशि अनिवार्य की गई।'), ('Who administers the Oath of Office to the President of India under Article 60?', 'अनुच्छेद 60 के तहत भारत के राष्ट्रपति को पद एवं गोपनीयता की शपथ कौन दिलाते हैं?', 'Chief Justice of India (or seniormost available Supreme Court Judge)', 'भारत के मुख्य न्यायाधीश (CJI) या उनकी अनुपस्थिति में वरिष्ठतम न्यायाधीश', ['Vice-President of India', 'Prime Minister of India', 'Speaker of Lok Sabha'], ['भारत के उपराष्ट्रपति', 'भारत के प्रधानमंत्री', 'लोकसभा अध्यक्ष'], 'Article 60 mandates the oath to preserve, protect, and defend the Constitution, administered by the Chief Justice of India.', 'राष्ट्रपति को संविधान के संरक्षण की शपथ भारत के मुख्य न्यायाधीश (या वरिष्ठतम न्यायाधीश) द्वारा दिलाई जाती है।'), ('Under Article 61, on what sole ground can the President of India be impeached?', 'अनुच्छेद 61 के अनुसार राष्ट्रपति पर महाभियोग (Impeachment) केवल किस एक आधार पर चलाया जा सकता है?', "'Violation of the Constitution' (संविधान का अतिक्रमण)", "'संविधान का अतिक्रमण / उल्लंघन' (Violation of Constitution)", ['Incompetence and corruption', 'Refusing to sign a cabinet bill', 'Criminal misbehavior outside office'], ['अक्षमता एवं भ्रष्टाचार', 'कैबिनेट का बिल न मानना', 'कार्यालय के बाहर अपराध'], "The only constitutional ground for impeaching the President is 'Violation of the Constitution' under Article 61(1).", "संविधान में राष्ट्रपति पर महाभियोग चलाने का एकमात्र आधार 'संविधान का अतिक्रमण' (उल्लंघन) बताया गया है।"), ('What majority is required in both Houses of Parliament to pass an impeachment resolution against the President under Article 61?', 'अनुच्छेद 61 के तहत राष्ट्रपति पर महाभियोग प्रस्ताव पारित करने के लिए दोनों सदनों में किस बहुमत की आवश्यकता होती है?', 'A majority of not less than 2/3rds of the TOTAL MEMBERSHIP of each House', 'प्रत्येक सदन की कुल सदस्य संख्या का कम से कम दो-तिहाई (2/3) बहुमत', ['2/3rd majority of members present and voting', 'Simple majority of total membership', 'Absolute majority plus state ratification'], ['उपस्थित और मतदान करने वालों का 2/3', 'कुल सदस्यों का साधारण बहुमत', 'राज्यों की सहमति सहित बहुमत'], 'Impeachment requires a special majority of two-thirds of the total membership of the House (the highest threshold in the Constitution).', 'महाभियोग के लिए सदन की कुल सदस्य संख्या का दो-तिहाई बहुमत आवश्यक है; भारत में अब तक किसी राष्ट्रपति पर महाभियोग नहीं चला।'), ('How many days advance written notice signed by at least 1/4th members of the House is required to introduce an impeachment motion?', 'राष्ट्रपति पर महाभियोग प्रस्ताव लाने के लिए कम से कम 1/4 सदस्यों के हस्ताक्षर सहित कितने दिन की पूर्व लिखित सूचना आवश्यक है?', '14 Days advance notice', '14 दिन की पूर्व लिखित सूचना', ['7 Days notice', '21 Days notice', '30 Days notice'], ['7 दिन की सूचना', '21 दिन की सूचना', '30 दिन की सूचना'], 'Article 61(2) requires at least 14 days written notice signed by not less than one-fourth of the total members of the House.', 'सदन के कम से कम एक-चौथाई सदस्यों के हस्ताक्षर से 14 दिन पहले लिखित नोटिस देना अनिवार्य होता है।'), ('Do nominated members of Parliament participate in the impeachment of the President?', 'क्या संसद के दोनों सदनों के मनोनीत सदस्य राष्ट्रपति पर महाभियोग की प्रक्रिया में भाग लेते हैं?', 'Yes, nominated members of Parliament participate in impeachment, but State MLAs do not', 'हां, संसद के मनोनीत सदस्य महाभियोग में भाग लेते हैं, किंतु राज्य विधानसभाओं के विधायक भाग नहीं लेते', ['No, nominated members cannot vote in impeachment', 'Only Rajya Sabha nominated members vote', 'State MLAs must ratify the impeachment'], ['नहीं, मनोनीत सदस्य वोट नहीं दे सकते', 'केवल राज्यसभा के मनोनीत सदस्य', 'विधायकों की मंजूरी जरूरी है'], 'Nominated MPs can vote in impeachment (though they cannot vote in election); conversely, State MLAs vote in election but not in impeachment.', 'संसद के मनोनीत सांसद महाभियोग में मतदान कर सकते हैं, जबकि राज्यों के विधायक महाभियोग प्रक्रिया से बाहर रहते हैं।'), ('Article 63 of the Constitution provides that', 'भारतीय संविधान का अनुच्छेद 63 क्या उपबंध करता है?', 'There shall be a Vice-President of India', 'भारत का एक उपराष्ट्रपति होगा (There shall be a Vice-President of India)', ['The Vice-President shall be the Chief of Defence Staff', 'The Vice-President shall head the Planning Commission', 'The Vice-President holds office for six years'], ['उपराष्ट्रपति रक्षा प्रमुख होंगे', 'उपराष्ट्रपति योजना आयोग प्रमुख होंगे', 'उपराष्ट्रपति 6 वर्ष तक रहेंगे'], 'Article 63 establishes the office of the Vice-President, the second-highest constitutional dignitary in India.', 'अनुच्छेद 63 देश के दूसरे सर्वोच्च संवैधानिक पद के रूप में उपराष्ट्रपति पद की स्थापना करता है।'), ('Under Article 64, the Vice-President of India is the Ex-Officio Chairman of which House?', 'अनुच्छेद 64 के अनुसार भारत के उपराष्ट्रपति किस सदन के पदेन सभापति (Ex-Officio Chairman) होते हैं?', 'Council of States (Rajya Sabha)', 'राज्यसभा (Council of States)', ['House of the People (Lok Sabha)', 'NITI Aayog Governing Council', 'National Development Council'], ['लोकसभा', 'नीति आयोग गवर्निंग काउंसिल', 'राष्ट्रीय विकास परिषद'], 'Like the American Vice President who presides over the Senate, the Indian Vice-President is ex-officio Chairman of Rajya Sabha.', 'अमेरिकी उपराष्ट्रपति की तरह भारत के उपराष्ट्रपति राज्यसभा के पदेन सभापति होते हैं और उन्हें सभापति के रूप में ही वेतन मिलता है।'), ('Who elects the Vice-President of India under Article 66?', 'अनुच्छेद 66 के अनुसार भारत के उपराष्ट्रपति का निर्वाचन किसके द्वारा किया जाता है?', 'An Electoral College consisting of members of BOTH Houses of Parliament (both elected and nominated)', 'संसद के दोनों सदनों के सदस्यों (निर्वाचित एवं मनोनीत दोनों) से मिलकर बने निर्वाचक मंडल द्वारा', ['Only elected members of Lok Sabha', 'Elected members of Parliament and State Assemblies', 'Only Rajya Sabha members'], ['केवल लोकसभा के निर्वाचित सदस्यों द्वारा', 'सांसदों और विधायकों दोनों द्वारा', 'केवल राज्यसभा सदस्यों द्वारा'], 'The Vice-President is elected by all MPs (both elected and nominated); State Assemblies have no role in Vice-Presidential elections.', 'उपराष्ट्रपति चुनाव में संसद के दोनों सदनों के सभी सांसद (निर्वाचित और मनोनीत) भाग लेते हैं; राज्य विधानसभाओं की इसमें कोई भूमिका नहीं होती।'), ('How can the Vice-President of India be removed from office under Article 67(b)?', 'अनुच्छेद 67(ख) के अनुसार भारत के उपराष्ट्रपति को पद से कैसे हटाया जा सकता है?', 'By a resolution of the Rajya Sabha passed by an effective majority and agreed to by the Lok Sabha by simple majority', 'राज्यसभा द्वारा प्रभावी बहुमत से पारित प्रस्ताव द्वारा जिसे लोकसभा साधारण बहुमत से स्वीकार करे', ['By formal impeachment in Supreme Court', 'By Presidential dismissal order on Cabinet advice', 'By a joint sitting of both Houses of Parliament'], ['सुप्रीम कोर्ट में महाभियोग द्वारा', 'कैबिनेट की सलाह पर राष्ट्रपति द्वारा', 'संसद की संयुक्त बैठक द्वारा'], 'Removal requires a 14-day notice, resolution passed by effective majority in Rajya Sabha, and agreed to by Lok Sabha.', 'उपराष्ट्रपति को हटाने का प्रस्ताव केवल राज्यसभा में ही लाया जा सकता है, जिसे लोकसभा का साधारण बहुमत से सहमत होना जरूरी है।'), ('Under Article 65, when the Vice-President acts as President during a vacancy, what is the maximum duration he can so act?', 'अनुच्छेद 65 के तहत जब उपराष्ट्रपति कार्यवाहक राष्ट्रपति के रूप में कार्य करते हैं, तो वे अधिकतम कितने समय तक इस पद पर रह सकते हैं?', 'Maximum 6 Months (new President must be elected within 6 months under Art 62)', 'अधिकतम 6 माह (क्योंकि अनुच्छेद 62 के तहत 6 माह में चुनाव अनिवार्य है)', ['Maximum 1 Year', 'For the remaining unexpired term of the predecessor', 'Maximum 3 Months'], ['अधिकतम 1 वर्ष', 'पूर्व राष्ट्रपति का बचा हुआ पूरा कार्यकाल', 'अधिकतम 3 माह'], 'Article 62(2) mandates that an election to fill a vacancy caused by death/resignation must be held within six months.', 'राष्ट्रपति की मृत्यु या इस्तीफे की स्थिति में उपराष्ट्रपति अधिकतम 6 महीने तक ही कार्यवाहक राष्ट्रपति रह सकते हैं।'), ('Who was the only Chief Justice of India who acted as the President of India in 1969?', '1969 में भारत के कार्यवाहक राष्ट्रपति के रूप में कार्य करने वाले एकमात्र मुख्य न्यायाधीश कौन थे?', 'Justice Mohammad Hidayatullah', 'न्यायमूर्ति मोहम्मद हिदायतुल्लाह', ['Justice P.N. Bhagwati', 'Justice H.J. Kania', 'Justice Mehr Chand Mahajan'], ['न्यायमूर्ति पी.एन. भगवती', 'न्यायमूर्ति एच.जे. कानिया', 'न्यायमूर्ति मेहरचंद महाजन'], 'When President Zakir Husain died and VP V.V. Giri resigned to contest elections, CJI Hidayatullah discharged presidential duties.', 'राष्ट्रपति जाकिर हुसैन के निधन और उपराष्ट्रपति वी.वी. गिरि के इस्तीफे के बाद मुख्य न्यायाधीश एम. हिदायतुल्लाह कार्यवाहक राष्ट्रपति बने।'), ('Under Article 71, who has the exclusive jurisdiction to inquire into and decide all doubts and disputes relating to the election of President or Vice-President?', 'अनुच्छेद 71 के अनुसार राष्ट्रपति या उपराष्ट्रपति के चुनाव संबंधी सभी विवादों की जांच और अंतिम फैसला करने का अनन्य अधिकार किसे है?', 'Supreme Court of India (decision is final)', 'सर्वोच्च न्यायालय (Supreme Court) — जिसका निर्णय अंतिम होगा', ['Election Commission of India', 'Parliamentary Privileges Committee', 'A special Tribunal headed by the Lok Sabha Speaker'], ['भारत निर्वाचन आयोग को', 'संसदीय विशेषाधिकार समिति को', 'लोकसभा अध्यक्ष की अध्यक्षता वाले विशेष ट्रिब्यूनल को'], 'Article 71 vests original and exclusive jurisdiction over presidential and vice-presidential election disputes in the Supreme Court.', 'राष्ट्रपति या उपराष्ट्रपति चुनाव को केवल सर्वोच्च न्यायालय में ही चुनौती दी जा सकती है, चुनाव आयोग में नहीं।'), ('Article 72 of the Constitution empowers the President to grant', 'संविधान का अनुच्छेद 72 राष्ट्रपति को कौन सी महत्वपूर्ण शक्ति प्रदान करता है?', 'Pardons, reprieves, respites, or remissions of punishment, or to suspend, remit, or commute sentences', 'क्षमादान, प्रविलंबन, विराम या परिहार, अथवा दंडादेश के निलंबन, परिहार या लघुकरण की शक्ति', ['Issue war declarations without Cabinet approval', 'Veto constitutional amendments passed by Parliament', 'Appoint state governors without consulting anyone'], ['बिना कैबिनेट युद्ध की घोषणा', 'संविधान संशोधनों को वीटो करना', 'बिना सलाह राज्यपाल नियुक्त करना'], 'Article 72 grants extensive pardoning powers in court-martial cases, Union law offences, and death sentences.', 'अनुच्छेद 72 राष्ट्रपति को मृत्युदंड, सैन्य अदालत (कोर्ट मार्शल) की सजा तथा केंद्रीय कानूनों के उल्लंघन में क्षमादान की शक्ति देता है।'), ('Can the Governor of a State grant pardon in case of a death sentence under Article 161?', 'क्या किसी राज्य के राज्यपाल को अनुच्छेद 161 के तहत मृत्युदंड (फांसी) की सजा को पूर्णतः क्षमा (Pardon) करने की शक्ति प्राप्त है?', 'No, only the President can pardon a death sentence (Governor can only suspend, remit, or commute)', 'नहीं, मृत्युदंड को पूर्ण क्षमा केवल राष्ट्रपति कर सकते हैं (राज्यपाल केवल सजा को कम या बदल सकते हैं)', ['Yes, Governor and President have identical death pardon powers', 'Yes, if the murder occurred within the State territory', 'Only if the Chief Minister recommends'], ['हां, दोनों की शक्तियां समान हैं', 'हां, यदि राज्य में अपराध हुआ हो', 'केवल मुख्यमंत्री की सिफारिश पर'], 'The power to grant absolute pardon in capital punishment (death penalty) belongs exclusively to the President of India.', 'फांसी की सजा को पूरी तरह माफ करने (Pardon) का अधिकार केवल राष्ट्रपति को है; राज्यपाल मृत्युदंड को बदल या स्थगित कर सकते हैं, पूर्ण क्षमा नहीं कर सकते।'), ('In Kehar Singh v. Union of India (1989), the Supreme Court ruled that the pardoning power of the President under Article 72 is', 'केहर सिंह बनाम भारत संघ (1989) में सर्वोच्च न्यायालय ने राष्ट्रपति की क्षमादान शक्ति के संबंध में क्या निर्णय दिया?', 'An executive action exercised on the aid and advice of the Council of Ministers, subject to limited judicial review against arbitrariness', 'मंत्रिपरिषद की सलाह पर प्रयुक्त कार्यपालिका शक्ति, जो मनमानेपन या दुर्भावना के विरुद्ध सीमित न्यायिक समीक्षा के अधीन है', ['Absolute and unchallengeable personal discretion', "Exercised solely at the President's personal conscience", 'Subject to approval by the Chief Justice of India'], ['पूर्णतः व्यक्तिगत और गैर-चुनौतीपूर्ण शक्ति', 'केवल व्यक्तिगत अंतःकरण से प्रयुक्त', 'मुख्य न्यायाधीश की मंजूरी के अधीन'], 'The President acts on cabinet advice; in Epuru Sudhakar (2006), the Supreme Court held pardon is open to judicial review if mala fide or arbitrary.', 'क्षमादान की शक्ति राष्ट्रपति मंत्रिपरिषद की सलाह से प्रयोग करते हैं; दुर्भावनापूर्ण या राजनीतिक कारणों से दी गई क्षमा की कोर्ट समीक्षा कर सकता है।'), ('Article 74(1) mandates that there shall be a Council of Ministers with the Prime Minister at the head to', 'अनुच्छेद 74(1) के अनुसार राष्ट्रपति को उनके कार्यों के संपादन में सहायता और सलाह देने के लिए कौन होगा?', 'Aid and advice the President, who SHALL act in accordance with such advice', 'एक मंत्रिपरिषद होगी जिसका प्रधान प्रधानमंत्री होगा, और राष्ट्रपति ऐसी सलाह के अनुसार कार्य करेंगे', ['Submit quarterly economic reports to Parliament', 'Audit state government expenditures', 'Supervise elections across union territories'], ['त्रैमासिक आर्थिक रिपोर्ट देना', 'राज्य खर्चों का ऑडिट करना', 'केंद्र शासित प्रदेशों के चुनावों की निगरानी'], 'By the 42nd Amendment (1976), cabinet advice was made binding; the 44th Amendment (1978) allowed the President to return advice once for reconsideration.', '42वें संशोधन द्वारा कैबिनेट की सलाह राष्ट्रपति पर बाध्यकारी की गई; 44वें संशोधन ने राष्ट्रपति को सलाह एक बार पुनर्विचार हेतु लौटाने का अधिकार दिया।'), ('Which Constitutional Amendment Act permitted the President of India to send back the advice of the Council of Ministers ONCE for reconsideration?', 'किस संविधान संशोधन द्वारा राष्ट्रपति को मंत्रिपरिषद की सलाह को एक बार पुनर्विचार हेतु वापस भेजने का अधिकार दिया गया?', '44th Constitutional Amendment Act, 1978', '44वां संविधान संशोधन अधिनियम (1978)', ['42nd Amendment Act, 1976', '52nd Amendment Act, 1985', '91st Amendment Act, 2003'], ['42वां संशोधन (1976)', '52वां संशोधन (1985)', '91वां संशोधन (2003)'], 'The 44th Amendment added the proviso to Article 74(1): the President may require the Council of Ministers to reconsider advice, but must accept reconsidered advice.', '44वें संशोधन (1978) ने व्यवस्था दी कि राष्ट्रपति सलाह को एक बार लौटा सकते हैं, किंतु पुनर्विचार के बाद दी गई सलाह को मानने के लिए वे बाध्य हैं।'), ('Can the advice tendered by Ministers to the President be inquired into in any court of law under Article 74(2)?', 'क्या अनुच्छेद 74(2) के तहत मंत्रियों द्वारा राष्ट्रपति को दी गई सलाह की किसी न्यायालय में जांच की जा सकती है?', 'No, strictly barred from inquiry in any court', 'नहीं, किसी भी न्यायालय में इसकी जांच पर पूर्ण प्रतिबंध है', ['Yes, routinely examined by High Courts', 'Yes, with permission of the Attorney General', 'Only during presidential election petitions'], ['हां, हाईकोर्ट जांच कर सकते हैं', 'हां, अटॉर्नी जनरल की अनुमति से', 'केवल चुनाव याचिकाओं में'], 'Article 74(2) bars courts from inquiring into the advice tendered by ministers; however, courts can examine the factual material on which advice was based (S.R. Bommai case).', 'अनुच्छेद 74(2) स्पष्ट करता है कि मंत्रियों ने राष्ट्रपति को क्या सलाह दी, इसकी किसी कोर्ट में जांच नहीं होगी (किंतु सलाह के आधारभूत दस्तावेजों की जांच हो सकती है)।'), ('Under Article 75(1), who appoints the Prime Minister and other Ministers of the Union?', 'अनुच्छेद 75(1) के अनुसार प्रधानमंत्री और अन्य मंत्रियों की नियुक्ति किसके द्वारा की जाती है?', 'Prime Minister is appointed by President; other Ministers are appointed by President on the ADVICE of the Prime Minister', 'प्रधानमंत्री की नियुक्ति राष्ट्रपति करेंगे तथा अन्य मंत्रियों की नियुक्ति राष्ट्रपति प्रधानमंत्री की सलाह पर करेंगे', ['All ministers are directly elected by the public', 'Speaker of Lok Sabha appoints the Cabinet', 'Chief Justice of India appoints the Prime Minister'], ['सभी मंत्रियों का जनता द्वारा सीधा चुनाव', 'लोकसभा अध्यक्ष कैबिनेट नियुक्त करते हैं', 'मुख्य न्यायाधीश प्रधानमंत्री नियुक्त करते हैं'], 'The President appoints the leader of the majority party in Lok Sabha as PM, and other ministers strictly on the recommendation of the PM.', 'राष्ट्रपति लोकसभा में बहुमत दल के नेता को प्रधानमंत्री बनाते हैं और प्रधानमंत्री की सिफारिश पर ही अन्य मंत्रियों को पद सौंपते हैं।'), ('Article 75(3) embodies the core principle of parliamentary democracy by declaring that the Council of Ministers shall be collectively responsible to', 'अनुच्छेद 75(3) संसदीय लोकतंत्र के मूल सिद्धांत के तहत मंत्रिपरिषद को सामूहिक रूप से किसके प्रति उत्तरदायी बनाता है?', 'The House of the People (Lok Sabha)', 'लोकसभा के प्रति (House of the People)', ['The Parliament as a whole (both Houses)', 'The President of India', 'The Supreme Court of India'], ['पूरी संसद (दोनों सदनों) के प्रति', 'भारत के राष्ट्रपति के प्रति', 'सर्वोच्च न्यायालय के प्रति'], 'Ministers swim and sink together; they are collectively responsible only to the directly elected lower House (Lok Sabha), not Rajya Sabha.', 'मंत्रिपरिषद सामूहिक रूप से केवल जनता द्वारा चुनी गई लोकसभा के प्रति उत्तरदायी होती है; लोकसभा में अविश्वास प्रस्ताव पास होते ही पूरी सरकार गिर जाती है।'), ('Under Article 75(2), ministers hold office during the pleasure of the', 'अनुच्छेद 75(2) के अनुसार केंद्रीय मंत्री व्यक्तिगत रूप से किसके प्रसादपर्यंत (During the pleasure) पद धारण करते हैं?', 'President of India (exercised on advice of the Prime Minister)', 'भारत के राष्ट्रपति के प्रसादपर्यंत (प्रधानमंत्री की सलाह पर)', ['Speaker of Lok Sabha', 'Chief Justice of India', 'Chairman of Rajya Sabha'], ['लोकसभा अध्यक्ष के', 'भारत के मुख्य न्यायाधीश के', 'राज्यसभा के सभापति के'], 'Individual ministers hold office during the pleasure of the President; the Prime Minister can dismiss an individual minister by advising the President.', 'मंत्री व्यक्तिगत रूप से राष्ट्रपति के प्रसादपर्यंत पद पर रहते हैं, जिसका अर्थ है कि प्रधानमंत्री की सलाह पर किसी भी मंत्री को कभी भी हटाया जा सकता है।'), ('What is the maximum time a person who is not a member of either House of Parliament can remain a Minister under Article 75(5)?', 'अनुच्छेद 75(5) के अनुसार जो व्यक्ति संसद के किसी सदन का सदस्य नहीं है, वह अधिकतम कितने समय तक मंत्री पद पर रह सकता है?', '6 Consecutive Months', 'लगातार 6 माह तक (6 Months)', ['3 Months', '1 Year', 'Indefinitely until next general election'], ['3 माह', '1 वर्ष', 'अगले आम चुनाव तक अनिश्चितकाल'], 'A non-MP minister must get elected to either Lok Sabha or Rajya Sabha within six consecutive months, failing which he ceases to be a minister.', 'कोई भी व्यक्ति बिना सांसद बने अधिकतम 6 महीने तक ही मंत्री रह सकता है; 6 माह में संसद का सदस्य न बनने पर पद समाप्त हो जाता है।'), ('Which Constitutional Amendment Act capped the size of the Council of Ministers at 15% of the total strength of the Lok Sabha?', 'किस संविधान संशोधन अधिनियम द्वारा मंत्रिपरिषद का आकार लोकसभा की कुल सदस्य संख्या के 15% तक सीमित किया गया?', '91st Constitutional Amendment Act, 2003', '91वां संविधान संशोधन अधिनियम (2003)', ['44th Amendment Act, 1978', '86th Amendment Act, 2002', '52nd Amendment Act, 1985'], ['44वां संशोधन (1978)', '86वां संशोधन (2002)', '52वां संशोधन (1985)'], 'The 91st Amendment inserted Article 75(1A), capping the Council of Ministers (including PM) at 15% of Lok Sabha strength (approx. 82 ministers).', '91वें संशोधन (2003) द्वारा अनुच्छेद 75(1क) जोड़कर प्रधानमंत्री सहित मंत्रियों की अधिकतम संख्या लोकसभा का 15% तय की गई।'), ('Article 76 of the Constitution of India provides for the office of the', 'भारतीय संविधान का अनुच्छेद 76 किस महत्वपूर्ण पद का उपबंध करता है?', 'Attorney General for India (भारत का महान्यायवादी)', 'भारत का महान्यायवादी (Attorney General for India)', ['Comptroller and Auditor General', 'Advocate General of the State', 'Solicitor General of India'], ['नियंत्रक एवं महालेखापरीक्षक (CAG)', 'राज्य का महाधिवक्ता', 'सॉलिसिटर जनरल'], 'Article 76 establishes the Attorney General as the highest law officer in the country, advising the Government of India on legal matters.', 'अनुच्छेद 76 देश के सर्वोच्च विधि अधिकारी के रूप में भारत के महान्यायवादी (Attorney General) के पद का सृजन करता है।'), ('What qualification is required for appointment as the Attorney General for India under Article 76(1)?', 'अनुच्छेद 76(1) के अनुसार महान्यायवादी नियुक्त होने के लिए क्या योग्यता होनी चाहिए?', 'Qualified to be appointed a Judge of the Supreme Court', 'सर्वोच्च न्यायालय का न्यायाधीश नियुक्त होने की योग्यता', ['Senior Advocate of High Court for 5 years', 'Member of Parliament with law degree', 'Retired Chief Justice of a High Court'], ['हाईकोर्ट में 5 साल वकालत', 'कानून की डिग्री वाला सांसद', 'हाईकोर्ट के सेवानिवृत्त मुख्य न्यायाधीश'], 'A candidate must be qualified to be a Supreme Court judge (citizen, 5 years High Court judge or 10 years HC advocate, or distinguished jurist).', 'महान्यायवादी बनने के लिए वही योग्यताएं जरूरी हैं जो सुप्रीम कोर्ट का न्यायाधीश बनने के लिए आवश्यक होती हैं।'), ('Under Article 76(4), what is the term of office of the Attorney General for India?', 'अनुच्छेद 76(4) के अनुसार भारत के महान्यायवादी का कार्यकाल कितना होता है?', 'Holds office during the pleasure of the President (no fixed tenure)', 'राष्ट्रपति के प्रसादपर्यंत (कोई निश्चित कार्यकाल निर्धारित नहीं)', ['5 Years fixed tenure', '6 Years or up to 65 years of age', 'Until the dissolution of Lok Sabha'], ['5 वर्ष का निश्चित कार्यकाल', '6 वर्ष या 65 वर्ष की आयु तक', 'लोकसभा भंग होने तक'], 'The Attorney General holds office during the pleasure of the President, receiving such remuneration as the President determines (conventionally resigns with the government).', 'महान्यायवादी का कोई निश्चित कार्यकाल नहीं होता; वे राष्ट्रपति के प्रसादपर्यंत पद पर रहते हैं और सरकार बदलने पर त्यागपत्र दे देते हैं।'), ('Under Article 88, what unique privilege does the Attorney General enjoy in Parliament?', 'अनुच्छेद 88 के तहत महान्यायवादी को संसद के संदर्भ में कौन सा अनूठा विशेषाधिकार प्राप्त है?', 'Right to speak and take part in proceedings of both Houses and committees, but WITHOUT the right to vote', 'संसद के दोनों सदनों की कार्यवाही और समितियों में बोलने व भाग लेने का अधिकार, किंतु मतदान का अधिकार नहीं', ['Right to vote on all legislative bills', 'Right to preside over joint sittings of Parliament', 'Exemption from all parliamentary inquiries'], ['सभी विधेयकों पर मतदान का अधिकार', 'संसद की संयुक्त बैठक की अध्यक्षता', 'संसदीय जांच से पूर्ण छूट'], 'Article 88 allows the AG to participate in debates in Lok Sabha, Rajya Sabha, and joint sittings, but Article 88 explicitly denies the right to vote.', 'महान्यायवादी संसद में बैठ सकते हैं और भाषण दे सकते हैं, किंतु वे मतदान (वोट) नहीं कर सकते क्योंकि वे संसद के सदस्य नहीं होते।'), ('Article 77 mandates that all executive action of the Government of India shall be expressed to be taken in the name of', 'संविधान के अनुच्छेद 77 के अनुसार भारत सरकार की समस्त कार्यपालिका कार्रवाई किसके नाम से की हुई कही जाएगी?', 'The President of India', 'भारत के राष्ट्रपति के नाम से', ['The Prime Minister of India', 'The Union Cabinet', 'The Parliament of India'], ['भारत के प्रधानमंत्री के नाम से', 'केंद्रीय कैबिनेट के नाम से', 'भारत की संसद के नाम से'], 'Article 77(1) provides that all executive action of the Government of India shall be expressed to be taken in the name of the President.', 'देश के सभी अंतरराष्ट्रीय समझौते, संधियां और सरकारी आदेश राष्ट्रपति के नाम से ही जारी किए जाते हैं।'), ('Article 78 outlines the duties of the Prime Minister regarding furnishing of information to the', 'संविधान का अनुच्छेद 78 सरकार के कार्यों की जानकारी देने के संदर्भ में प्रधानमंत्री का कर्तव्य किसके प्रति तय करता है?', 'President of India', 'भारत के राष्ट्रपति के प्रति', ['Speaker of Lok Sabha', 'Chief Justice of India', 'Chairman of Rajya Sabha'], ['लोकसभा अध्यक्ष के प्रति', 'भारत के मुख्य न्यायाधीश के प्रति', 'राज्यसभा के सभापति के प्रति'], 'Article 78 makes it the duty of the PM to communicate to the President all decisions of the Council of Ministers and legislative proposals.', 'अनुच्छेद 78 प्रधानमंत्री का यह संवैधानिक कर्तव्य बनाता है कि वे सरकार के सभी फैसलों की सूचना राष्ट्रपति को दें।'), ('Article 123 of the Constitution empowers the President to promulgate', 'भारतीय संविधान का अनुच्छेद 123 राष्ट्रपति को किस असाधारण विधायी शक्ति का प्रयोग करने का अधिकार देता है?', 'Ordinances during recess of Parliament (अध्यादेश जारी करने की शक्ति)', 'अध्यादेश प्रख्यापित करने की शक्ति (Promulgate Ordinances)', ['Financial Budgets without parliamentary vote', 'Constitutional Amendments by decree', 'Declarations of War'], ['बिना संसद मतदान के बजट पारित करना', 'सीधे संविधान संशोधन करना', 'युद्ध की सीधी घोषणा'], 'When either House is not in session and immediate action is required, the President can issue an Ordinance having the force of an Act of Parliament.', 'संसद के सत्र में न होने पर आपातकालीन स्थिति से निपटने के लिए राष्ट्रपति अनुच्छेद 123 के तहत अध्यादेश जारी कर सकते हैं।'), ('An Ordinance promulgated by the President under Article 123 must be laid before Parliament and ceases to operate after', 'अनुच्छेद 123 के तहत राष्ट्रपति द्वारा जारी अध्यादेश संसद सत्र शुरू होने के कितने समय बाद स्वतः समाप्त हो जाता है?', '6 Weeks from the reassembly of Parliament (unless approved earlier)', 'संसद के पुनः संवेद (सत्र शुरू) होने के 6 सप्ताह के भीतर', ['6 Months from the date of promulgation', '30 Days from reassembly', '3 Months from reassembly'], ['जारी होने की तिथि से 6 माह', 'सत्र शुरू होने से 30 दिन', 'सत्र शुरू होने से 3 माह'], 'Article 123(2)(a) mandates that an Ordinance must be approved by Parliament within 6 weeks of reassembly, or it lapses.', 'संसद का सत्र शुरू होने के 6 सप्ताह के भीतर यदि संसद अध्यादेश को पारित नहीं करती, तो वह स्वतः प्रभावहीन (रद्द) हो जाता है।'), ('What is the maximum theoretical lifespan of a Presidential Ordinance without parliamentary approval?', 'संसद की मंजूरी न मिलने पर किसी अध्यादेश की अधिकतम संभावित समयावधि कितनी हो सकती है?', '6 Months and 6 Weeks (since maximum gap between two parliamentary sessions is 6 months)', '6 माह और 6 सप्ताह (क्योंकि दो सत्रों के बीच अधिकतम अंतर 6 माह हो सकता है)', ['Exactly 6 Months', 'Exactly 1 Year', '3 Months'], ['सटीक 6 माह', 'सटीक 1 वर्ष', '3 माह'], 'Under Article 85, maximum gap between two parliamentary sessions is 6 months; adding 6 weeks from reassembly gives 6 months and 6 weeks.', 'दो सत्रों के बीच अधिकतम 6 माह का अंतर हो सकता है, और सत्र शुरू होने पर 6 सप्ताह; अतः अधिकतम जीवन 6 माह 6 सप्ताह होता है।'), ('In D.C. Wadhwa v. State of Bihar (1987), the Supreme Court ruled that re-promulgating ordinances repeatedly without placing them before legislature is', 'डी.सी. वाधवा बनाम बिहार राज्य (1987) में सुप्रीम कोर्ट ने बिना विधानसभा में रखे अध्यादेशों को बार-बार पुनः प्रख्यापित करने को क्या माना?', 'A subversion of the democratic process and a fraud on the Constitution', 'लोकतांत्रिक प्रक्रिया का हनन तथा संविधान के साथ किया गया एक धोखा (Fraud on Constitution)', ['A valid exercise of emergency powers', 'Permissible if approved by the Governor', 'Immune from judicial review'], ['आपातकालीन शक्ति का वैध प्रयोग', 'राज्यपाल की सहमति से वैध', 'न्यायिक समीक्षा से मुक्त'], "The Supreme Court struck down the Bihar government's practice of keeping ordinances alive for up to 14 years through repeated re-promulgation.", 'बिहार सरकार द्वारा 14 वर्षों तक अध्यादेशों को बिना कानून बनाए बार-बार जारी रखने को सुप्रीम कोर्ट ने असंवैधानिक और फर्जीवाड़ा ठहराया।'), ('What three types of Veto Powers does the President of India possess over ordinary bills passed by Parliament?', 'संसद द्वारा पारित सामान्य विधेयकों पर भारत के राष्ट्रपति के पास कौन से तीन प्रकार के वीटो अधिकार होते हैं?', 'Absolute Veto, Suspensive Veto, and Pocket Veto', 'आत्यंतिक वीटो (Absolute), निलंबनकारी वीटो (Suspensive), एवं पॉकेट वीटो (Pocket Veto)', ['Qualified Veto, Absolute Veto, Pocket Veto', 'Executive Veto, Legislative Veto, Judicial Veto', 'Financial Veto, Discretionary Veto, Moral Veto'], ['विशेषित वीटो, आत्यंतिक, पॉकेट', 'कार्यपालिका, विधायी, न्यायिक वीटो', 'वित्तीय, विवेकाधीन, नैतिक वीटो'], 'Unlike the US President who has Qualified Veto, the Indian President possesses Absolute, Suspensive, and Pocket Veto.', 'भारत के राष्ट्रपति के पास आत्यंतिक वीटो (मंजूरी रोकना), निलंबनकारी वीटो (पुनर्विचार हेतु लौटाना) और पॉकेट वीटो (अनिश्चितकाल लंबित रखना) हैं।'), ("In 1986, which President of India exercised 'Pocket Veto' by taking no action on the controversial Indian Post Office (Amendment) Bill?", "1986 में किस राष्ट्रपति ने डाकघर संशोधन विधेयक पर कोई निर्णय न लेकर ऐतिहासिक 'पॉकेट वीटो' (Pocket Veto) का प्रयोग किया था?", 'Gyani Zail Singh', 'ज्ञानी जैल सिंह (Gyani Zail Singh)', ['Dr. A.P.J. Abdul Kalam', 'Dr. S. Radhakrishnan', 'R. Venkataraman'], ['डॉ. ए.पी.जे. अब्दुल कलाम', 'डॉ. एस. राधाकृष्णन', 'आर. वेंकटरमण'], 'President Gyani Zail Singh pocketed the Post Office Bill, which sought to intercept personal postal communications, allowing it to lapse quietly.', 'डाकघर विधेयक में नागरिकों की चिट्ठियों की निगरानी का प्रावधान था, जिसे राष्ट्रपति ज्ञानी जैल सिंह ने पॉकेट वीटो कर रोक दिया था।'), ("Can the President of India exercise 'Suspensive Veto' in the case of a Money Bill under Article 111?", 'क्या अनुच्छेद 111 के तहत राष्ट्रपति धन विधेयक (Money Bill) पर निलंबनकारी वीटो (पुनर्विचार हेतु लौटाना) का प्रयोग कर सकते हैं?', 'No, the President can either give assent or withhold assent, but CANNOT return a Money Bill for reconsideration', 'नहीं, राष्ट्रपति धन विधेयक को स्वीकृति दे सकते हैं या रोक सकते हैं, किंतु पुनर्विचार के लिए लौटा नहीं सकते', ['Yes, can return a Money Bill once', 'Yes, with permission of the Finance Minister', 'Only if passed during budget session'], ['हां, एक बार लौटा सकते हैं', 'हां, वित्त मंत्री की अनुमति से', 'केवल बजट सत्र में'], 'Under Article 111 proviso, the President cannot return a Money Bill, because it was already introduced on his prior recommendation.', 'धन विधेयक राष्ट्रपति की पूर्व अनुमति से ही संसद में आता है, अतः राष्ट्रपति इसे पुनर्विचार के लिए वापस नहीं भेज सकते।'), ('Can the President of India exercise any veto power over a Constitutional Amendment Bill passed under Article 368?', 'क्या अनुच्छेद 368 के तहत संसद द्वारा पारित संविधान संशोधन विधेयक पर राष्ट्रपति कोई वीटो लगा सकते हैं?', 'No, the 24th Amendment Act 1971 made it OBLIGATORY for the President to give his assent', 'नहीं, 24वें संशोधन (1971) द्वारा राष्ट्रपति के लिए संविधान संशोधन विधेयक पर अपनी सहमति देना बाध्यकारी बना दिया गया', ['Yes, can exercise Suspensive Veto once', 'Yes, can exercise Pocket Veto indefinitely', 'Yes, with approval of Supreme Court'], ['हां, एक बार पुनर्विचार हेतु भेज सकते हैं', 'हां, पॉकेट वीटो कर सकते हैं', 'सुप्रीम कोर्ट की सलाह से वीटो कर सकते हैं'], "The 24th Constitutional Amendment Act 1971 amended Article 368(2), stating the President 'shall give his assent', eliminating all veto discretion.", 'संविधान संशोधन विधेयक पर राष्ट्रपति के पास कोई वीटो नहीं होता; उन्हें उस पर अनिवार्य रूप से अपनी सहमति देनी ही होती है।'), ('Who was the only President of India elected unopposed in 1977?', '1977 में निर्विरोध निर्वाचित होने वाले भारत के एकमात्र राष्ट्रपति कौन थे?', 'Neelam Sanjiva Reddy', 'नीलम संजीव रेड्डी (Neelam Sanjiva Reddy)', ['V.V. Giri', 'Fakhruddin Ali Ahmed', 'Dr. Zakir Husain'], ['वी.वी. गिरि', 'फखरुद्दीन अली अहमद', 'डॉ. जाकिर हुसैन'], 'Neelam Sanjiva Reddy was elected unopposed as President in July 1977 after all other nomination papers were rejected or withdrawn.', '1977 में जनता पार्टी शासन के दौरान नीलम संजीव रेड्डी सर्वसम्मति से निर्विरोध राष्ट्रपति चुने गए थे।')]

slot_q117_parl = [('Under Article 79 of the Constitution of India, what constitutes the Parliament of the Union?', 'भारतीय संविधान के अनुच्छेद 79 के अनुसार संघ की संसद में कौन-कौन शामिल होते हैं?', 'The President of India and the Two Houses (Council of States and House of the People)', 'भारत के राष्ट्रपति तथा दोनों सदन (राज्यसभा एवं लोकसभा)', ['Only the Lok Sabha and Rajya Sabha', 'Prime Minister, Lok Sabha, and Rajya Sabha', 'Supreme Court, Lok Sabha, and Rajya Sabha'], ['केवल लोकसभा और राज्यसभा', 'प्रधानमंत्री, लोकसभा और राज्यसभा', 'सर्वोच्च न्यायालय, लोकसभा और राज्यसभा'], 'Article 79 explicitly defines Parliament as consisting of the President and two Houses: Rajya Sabha and Lok Sabha.', 'संसद के तीन अभिन्न अंग हैं: राष्ट्रपति, राज्यसभा (उच्च सदन) तथा लोकसभा (निम्न सदन)।'), ('What is the maximum sanctioned strength of the Council of States (Rajya Sabha) under Article 80?', 'अनुच्छेद 80 के अनुसार राज्यसभा की अधिकतम निर्धारित सदस्य संख्या कितनी हो सकती है?', '250 Members (238 elected from States/UTs and 12 nominated by the President)', '250 सदस्य (238 राज्यों व केंद्र शासित प्रदेशों से, एवं 12 राष्ट्रपति द्वारा मनोनीत)', ['245 Members', '252 Members', '260 Members'], ['245 सदस्य', '252 सदस्य', '260 सदस्य'], 'Article 80 caps Rajya Sabha at 250 members: 238 representing States/UTs, and 12 nominated for excellence in Literature, Science, Art, and Social Service.', 'अधिकतम संख्या 250 है; वर्तमान में 245 सदस्य हैं, जिनमें 12 सदस्य साहित्य, विज्ञान, कला और समाज सेवा से मनोनीत होते हैं।'), ('In which four fields must a person have special knowledge or practical experience to be nominated to Rajya Sabha under Article 80(3)?', 'अनुच्छेद 80(3) के अनुसार राष्ट्रपति किन 4 क्षेत्रों में विशेष ज्ञान या व्यावहारिक अनुभव रखने वाले 12 व्यक्तियों को राज्यसभा में मनोनीत करते हैं?', 'Literature, Science, Art, and Social Service', 'साहित्य, विज्ञान, कला एवं समाज सेवा (Literature, Science, Art, Social Service)', ['Sports, Cinema, Journalism, Business', 'Politics, Economics, Law, Commerce', 'Military defense, Education, Agriculture, Trade'], ['खेल, सिनेमा, पत्रकारिता, व्यापार', 'राजनीति, अर्थशास्त्र, विधि, वाणिज्य', 'सैन्य रक्षा, शिक्षा, कृषि, व्यापार'], "The four fields specified in Article 80(3) are Literature, Science, Art, and Social Service (Sachin Tendulkar was nominated under 'Art').", 'संविधान के अनुच्छेद 80(3) में केवल 4 क्षेत्र उल्लिखित हैं: साहित्य, विज्ञान, कला तथा समाज सेवा।'), ('What is the maximum sanctioned strength of the House of the People (Lok Sabha) under Article 81?', 'अनुच्छेद 81 के अनुसार लोकसभा की अधिकतम अनुमत सदस्य संख्या कितनी निर्धारित की गई है?', '550 Members (530 from States and 20 from Union Territories)', '550 सदस्य (530 राज्यों से एवं 20 केंद्र शासित प्रदेशों से)', ['552 Members', '545 Members', '543 Members'], ['552 सदस्य', '545 सदस्य', '543 सदस्य'], 'Following the 104th Amendment Act 2019 which ended nomination of 2 Anglo-Indians, the maximum strength of Lok Sabha is 550 (543 currently elected).', '104वें संशोधन (2019) द्वारा 2 एंग्लो-इंडियन का मनोनयन समाप्त होने के बाद अधिकतम संख्या 550 (530 राज्य + 20 यूटी) है।'), ('Which Constitutional Amendment Act discontinued the nomination of 2 Anglo-Indian members to Lok Sabha and State Assemblies?', 'किस संविधान संशोधन अधिनियम द्वारा लोकसभा और राज्य विधानसभाओं में 2 एंग्लो-इंडियन सदस्यों का मनोनयन समाप्त कर दिया गया?', '104th Constitutional Amendment Act, 2019', '104वां संविधान संशोधन अधिनियम (2019)', ['101st Amendment Act, 2016', '103rd Amendment Act, 2019', '102nd Amendment Act, 2018'], ['101वां संशोधन (2016)', '103वां संशोधन (2019)', '102वां संशोधन (2018)'], 'The 104th Amendment Act 2019 extended SC/ST reservation in legislatures for 10 years, but chose not to extend Anglo-Indian nominations under Art 331 and 333.', '104वें संशोधन अधिनियम 2019 ने अनुसूचित जाति/जनजाति आरक्षण 2030 तक बढ़ाया, किंतु एंग्लो-इंडियन का कोटा समाप्त कर दिया।'), ('Under Article 83(1), is the Rajya Sabha subject to dissolution by the President?', 'अनुच्छेद 83(1) के अनुसार क्या राज्यसभा को राष्ट्रपति द्वारा कभी भंग किया जा सकता है?', 'No, Rajya Sabha is a Permanent House not subject to dissolution', 'नहीं, राज्यसभा एक स्थायी सदन (Permanent House) है जो कभी भंग नहीं होता', ['Yes, dissolved every six years', 'Yes, dissolved on advice of the Prime Minister', 'Dissolved during National Emergency only'], ['हां, हर 6 साल में भंग होता है', 'हां, प्रधानमंत्री की सलाह पर भंग होता है', 'केवल आपातकाल में भंग होता है'], 'Rajya Sabha is a permanent body not subject to dissolution; one-third of its members retire every second year.', 'राज्यसभा कभी भंग नहीं होती; इसके एक-तिहाई सदस्य प्रत्येक दो वर्ष में सेवानिवृत्त होते हैं।'), ('What is the tenure of an individual member of the Rajya Sabha?', 'राज्यसभा के एक व्यक्तिगत सदस्य (सांसद) का कार्यकाल कितना होता है?', '6 Years', '6 वर्ष (6 Years)', ['5 Years', '4 Years', 'Permanent life tenure'], ['5 वर्ष', '4 वर्ष', 'आजीवन स्थायी'], 'Under Section 154 of Representation of the People Act 1951, the term of office of a member of the Rajya Sabha is 6 years.', 'जनप्रतिनिधित्व कानून 1951 के अनुसार राज्यसभा सदस्य का कार्यकाल 6 वर्ष का होता है।'), ('What is the normal term of the House of the People (Lok Sabha) under Article 83(2)?', 'अनुच्छेद 83(2) के अनुसार लोकसभा का सामान्य कार्यकाल कितना होता है?', '5 Years from the date appointed for its first meeting', 'अपनी पहली बैठक की नियत तिथि से 5 वर्ष तक', ['6 Years', '4 Years', '3 Years'], ['6 वर्ष', '4 वर्ष', '3 वर्ष'], 'Lok Sabha operates for 5 years unless dissolved earlier by the President on the advice of the Prime Minister.', 'लोकसभा का सामान्य जीवन 5 वर्ष होता है, किंतु इसे प्रधानमंत्री की सलाह पर 5 वर्ष से पहले भी भंग किया जा सकता है।'), ('During a National Emergency under Article 352, by how much can Parliament extend the life of the Lok Sabha at a time?', 'राष्ट्रीय आपातकाल के दौरान संसद कानून बनाकर लोकसभा के कार्यकाल को एक बार में अधिकतम कितने समय के लिए बढ़ा सकती है?', 'By 1 Year at a time (and not extending beyond 6 months after Emergency ceases)', 'एक बार में 1 वर्ष के लिए (तथा आपातकाल समाप्त होने पर अधिकतम 6 माह तक)', ['By 6 Months at a time', 'By 2 Years at a time', 'Indefinitely without any limit'], ['एक बार में 6 माह', 'एक बार में 2 वर्ष', 'अनिश्चितकाल तक'], 'Under the proviso to Article 83(2), Parliament can extend Lok Sabha for 1 year at a time; in 1976 (5th Lok Sabha), it was extended twice.', 'आपातकाल के समय संसद कानून बनाकर लोकसभा का कार्यकाल एक बार में 1 साल के लिए बढ़ा सकती है (जैसा 1976 में हुआ था)।'), ('What is the minimum age qualification to become a member of the Lok Sabha and Rajya Sabha respectively under Article 84?', 'अनुच्छेद 84 के अनुसार लोकसभा तथा राज्यसभा का सदस्य बनने के लिए न्यूनतम आयु क्रमशः कितनी होनी चाहिए?', '25 Years for Lok Sabha, and 30 Years for Rajya Sabha', 'लोकसभा हेतु 25 वर्ष, तथा राज्यसभा हेतु 30 वर्ष', ['21 Years and 25 Years', '25 Years and 35 Years', '30 Years and 35 Years'], ['21 वर्ष एवं 25 वर्ष', '25 वर्ष एवं 35 वर्ष', '30 वर्ष एवं 35 वर्ष'], 'Article 84(b) prescribes a minimum age of 25 years for Lok Sabha (House of the People) and 30 years for Rajya Sabha (Council of States).', 'लोकसभा का चुनाव लड़ने के लिए न्यूनतम आयु 25 वर्ष और राज्यसभा के लिए न्यूनतम आयु 30 वर्ष होनी चाहिए।'), ('Under Article 85(1), what is the maximum permissible interval between two consecutive sessions of Parliament?', 'अनुच्छेद 85(1) के अनुसार संसद के दो क्रमिक सत्रों के बीच अधिकतम कितना अंतराल (अवधि) हो सकता है?', '6 Months', '6 माह (6 Months)', ['3 Months', '4 Months', '1 Year'], ['3 माह', '4 माह', '1 वर्ष'], 'Article 85 mandates that six months shall not intervene between the last sitting in one session and the date appointed for its first sitting in the next session.', 'संसद के एक सत्र की अंतिम बैठक और अगले सत्र की पहली बैठक के बीच 6 महीने से अधिक का अंतर नहीं हो सकता।'), ('By convention, how many parliamentary sessions are normally conducted in India in a calendar year?', 'संसदीय परंपरा के अनुसार भारत में सामान्यतः एक वर्ष में कुल कितने सत्र आयोजित किए जाते हैं?', '3 Sessions (Budget Session, Monsoon Session, and Winter Session)', '3 सत्र (बजट सत्र, मानसून सत्र, एवं शीतकालीन सत्र)', ['2 Sessions', '4 Sessions', 'Only 1 Session'], ['2 सत्र', '4 सत्र', 'केवल 1 सत्र'], 'Normally 3 sessions: Budget Session (Feb-May, longest), Monsoon Session (July-Aug), and Winter Session (Nov-Dec, shortest).', 'भारत में तीन मुख्य सत्र होते हैं: बजट सत्र (सबसे लंबा), मानसून सत्र और शीतकालीन सत्र।'), ('Who has the constitutional power to summon, prorogue either House of Parliament, and dissolve the Lok Sabha under Article 85?', 'अनुच्छेद 85 के तहत संसद के सदनों को आहूत करने, सत्रावसान करने और लोकसभा को भंग करने की शक्ति किसे है?', 'The President of India (acting on the advice of the Prime Minister/Cabinet)', 'भारत के राष्ट्रपति को (प्रधानमंत्री/मंत्रिमंडल की सलाह पर)', ['The Speaker of Lok Sabha', 'The Vice-President of India', 'The Chief Justice of India'], ['लोकसभा अध्यक्ष को', 'भारत के उपराष्ट्रपति को', 'मुख्य न्यायाधीश को'], 'The President summons and prorogues sessions of Parliament and dissolves the Lok Sabha on cabinet advice.', 'संसद का सत्र बुलाने (आहूत), समाप्त करने (सत्रावसान) और लोकसभा को भंग करने का अधिकार राष्ट्रपति को है।'), ("What is the difference between 'Adjournment' and 'Prorogation' of a House of Parliament?", "संसद के 'स्थगन' (Adjournment) और 'सत्रावसान' (Prorogation) में मुख्य अंतर क्या है?", 'Adjournment suspends the sitting for hours/days by Presiding Officer; Prorogation terminates the entire session by the President', 'स्थगन पीठासीन अधिकारी द्वारा बैठक को कुछ घंटों/दिनों के लिए रोकता है; सत्रावसान राष्ट्रपति द्वारा पूरे सत्र को समाप्त करता है', ['Prorogation is done by Speaker; Adjournment by President', 'Adjournment dissolves Lok Sabha; Prorogation dissolves Rajya Sabha', 'There is no constitutional difference'], ['सत्रावसान अध्यक्ष करते हैं; स्थगन राष्ट्रपति', 'स्थगन से लोकसभा भंग होती है', 'दोनों में कोई अंतर नहीं है'], 'Adjournment terminates a daily sitting and is done by Speaker/Chairman; Prorogation terminates the session and is done by President under Art 85.', 'सदन की दैनिक कार्यवाही का स्थगन अध्यक्ष/सभापति करते हैं; जबकि पूरे सत्र का सत्रावसान राष्ट्रपति के आदेश से होता है।'), ("What is 'Adjournment Sine Die' in parliamentary procedure?", "संसदीय प्रक्रिया में 'अनिश्चितकाल के लिए स्थगन' (Adjournment Sine Die) का क्या अर्थ है?", 'Terminating a sitting of Parliament without naming a day for its reassembly', 'सदन की बैठक को पुनः संवेद होने की तिथि बताए बिना अनिश्चितकाल के लिए स्थगित करना', ['Permanently dissolving the Lok Sabha', 'Suspending a member for disciplinary misconduct', 'Passing all bills without debate'], ['लोकसभा को स्थायी रूप से भंग करना', 'सांसद को निलंबित करना', 'बिना बहस सभी बिल पास करना'], 'Adjournment sine die means terminating the sitting of Parliament indefinitely, usually done by Speaker at session close before presidential prorogation.', "जब सदन के अध्यक्ष बैठक को अगली कोई तारीख तय किए बिना स्थगित कर देते हैं, तो उसे 'अनिश्चितकाल के लिए स्थगन' कहते हैं।"), ('Under Article 93, the Speaker and Deputy Speaker of the Lok Sabha are elected by', 'अनुच्छेद 93 के अनुसार लोकसभा के अध्यक्ष (Speaker) तथा उपाध्यक्ष का चुनाव किसके द्वारा किया जाता है?', 'The members of the Lok Sabha from amongst themselves by a simple majority', 'लोकसभा के सदस्यों द्वारा अपने ही सदस्यों में से साधारण बहुमत द्वारा', ['The President of India on Cabinet advice', 'A joint sitting of both Houses of Parliament', 'Electoral College of all MPs and MLAs'], ['कैबिनेट की सलाह पर राष्ट्रपति द्वारा', 'संसद के दोनों सदनों की संयुक्त बैठक द्वारा', 'सभी सांसदों और विधायकों द्वारा'], 'The Lok Sabha elects a Speaker and Deputy Speaker from among its members as soon as may be after its constitution.', 'लोकसभा के सदस्य अपने बीच में से ही एक सदस्य को अध्यक्ष और एक को उपाध्यक्ष चुनते हैं।'), ('To whom does the Speaker of the Lok Sabha address his resignation letter under Article 94(b)?', 'अनुच्छेद 94(ख) के अनुसार लोकसभा अध्यक्ष अपना त्यागपत्र किसे सौंपते हैं?', 'Deputy Speaker of the Lok Sabha', 'लोकसभा के उपाध्यक्ष (Deputy Speaker) को', ['President of India', 'Prime Minister of India', 'Chief Justice of India'], ['भारत के राष्ट्रपति को', 'भारत के प्रधानमंत्री को', 'भारत के मुख्य न्यायाधीश को'], 'The Speaker submits resignation to the Deputy Speaker, and the Deputy Speaker submits resignation to the Speaker.', 'लोकसभा अध्यक्ष अपना त्यागपत्र उपाध्यक्ष को और उपाध्यक्ष अपना त्यागपत्र अध्यक्ष को सौंपते हैं।'), ('Does the Speaker of the Lok Sabha vacate office immediately upon the dissolution of the Lok Sabha?', 'क्या लोकसभा के भंग होते ही लोकसभा अध्यक्ष का पद तुरंत रिक्त हो जाता है?', 'No, the Speaker holds office until immediately before the first meeting of the new Lok Sabha', 'नहीं, अध्यक्ष नई लोकसभा की पहली बैठक के ठीक पहले तक अपने पद पर बने रहते हैं', ['Yes, office becomes vacant instantly on dissolution', 'Holds office until the Prime Minister resigns', 'Holds office for 6 months after dissolution'], ['हां, भंग होते ही पद खाली हो जाता है', 'प्रधानमंत्री के हटने तक रहते हैं', 'भंग होने के 6 माह तक रहते हैं'], 'Under the proviso to Article 94, whenever Lok Sabha is dissolved, the Speaker shall not vacate office until immediately before the first sitting of new House.', 'अनुच्छेद 94 के अनुसार लोकसभा भंग होने के बावजूद अध्यक्ष तब तक पद पर रहते हैं जब तक नई लोकसभा की पहली बैठक न हो जाए।'), ("Who appoints the 'Pro-tem Speaker' of the newly elected Lok Sabha to administer oaths to new members?", "नवनिर्वाचित लोकसभा के सांसदों को शपथ दिलाने हेतु 'प्रोटेम स्पीकर' (सामयिक अध्यक्ष) की नियुक्ति कौन करता है?", 'President of India (conventionally the seniormost elected member)', 'भारत के राष्ट्रपति (परंपरागत रूप से सदन के सबसे वरिष्ठ सदस्य)', ['Retiring Speaker of previous Lok Sabha', 'Prime Minister of India', 'Chief Election Commissioner'], ['पिछली लोकसभा के निवर्तमान अध्यक्ष', 'भारत के प्रधानमंत्री', 'मुख्य चुनाव आयुक्त'], 'The President appoints a senior MP as Speaker Pro-tem to administer oaths under Article 99 and preside over election of permanent Speaker.', 'राष्ट्रपति नवनिर्वाचित सांसदों को शपथ दिलाने और नए अध्यक्ष के चुनाव के संचालन हेतु प्रोटेम स्पीकर की नियुक्ति करते हैं।'), ('Who was the first Speaker of the Lok Sabha of independent India?', 'स्वतंत्र भारत की प्रथम लोकसभा के पहले अध्यक्ष (Speaker) कौन थे?', "Ganesh Vasudev Mavalankar (G.V. Mavalankar, fondly called 'Dadasaheb')", 'गणेश वासुदेव मावलंकर (G.V. Mavalankar)', ['M.A. Ayyangar', 'Hukam Singh', 'K.S. Hegde'], ['एम.ए. अय्यंगार', 'हुकम सिंह', 'के.एस. हेगड़े'], 'G.V. Mavalankar served as Speaker from 1952 until his death in 1956; M.A. Ayyangar succeeded him.', "जी.वी. मावलंकर प्रथम लोकसभा अध्यक्ष थे; पंडित नेहरू ने उन्हें 'लोकसभा का जनक' कहा था।"), ('Who was the first female Speaker of the Lok Sabha?', 'भारत की पहली महिला लोकसभा अध्यक्ष कौन थीं?', 'Meira Kumar (2009-2014)', 'मीरा कुमार (2009-2014)', ['Sumitra Mahajan', 'Najma Heptulla', 'Pratibha Patil'], ['सुमित्रा महाजन', 'नजमा हेपतुल्ला', 'प्रतिभा पाटिल'], 'Meira Kumar served as Speaker of the 15th Lok Sabha from 2009 to 2014; Sumitra Mahajan was the second woman Speaker.', 'मीरा कुमार 2009 में 15वीं लोकसभा में पहली महिला स्पीकर चुनी गई थीं।'), ('Under Article 100(1), when does the Speaker of the Lok Sabha exercise a vote in parliamentary proceedings?', 'अनुच्छेद 100(1) के अनुसार लोकसभा अध्यक्ष सदन में अपने मताधिकार का प्रयोग कब करते हैं?', 'Only in the case of an equality of votes (Casting Vote / निर्णायक मत)', 'केवल मत बराबर (टाई) होने की दशा में (निर्णायक मत / Casting Vote)', ['On all bills during the first round of voting', 'Whenever a constitutional amendment bill is voted', 'Never votes under any circumstance'], ['पहले दौर के मतदान में सभी बिलों पर', 'संविधान संशोधन के समय हमेशा', 'कभी भी वोट नहीं देते'], 'The Speaker does not vote in the first instance, but exercises a casting vote to break a deadlock in case of an equality of votes.', 'अध्यक्ष सामान्यतः मतदान नहीं करते; वे केवल पक्ष और विपक्ष के मत बराबर (50-50) होने पर निर्णायक मत (Casting Vote) देते हैं।'), ("What is the 'Quorum' required to constitute a meeting of either House of Parliament under Article 100(3)?", "अनुच्छेद 100(3) के अनुसार संसद के किसी सदन की बैठक के लिए अनिवार्य 'गणपूर्ति' (Quorum) कितनी है?", 'One-tenth (1/10th) of the total number of members of the House', 'सदन की कुल सदस्य संख्या का दसवां भाग (1/10th या 10%)', ['One-fifth (1/5th) of the total members', 'One-third (1/3rd) of the total members', '50 members fixed in all Houses'], ['कुल सदस्यों का पांचवां भाग', 'कुल सदस्यों का एक-तिहाई', 'सभी सदनों में 50 सदस्य तय'], 'Quorum is 10% of total strength: 55 members for Lok Sabha, and 25 members for Rajya Sabha. Without quorum, presiding officer must suspend or adjourn.', 'गणपूर्ति कुल सदस्यों का 1/10 (लोकसभा में 55 और राज्यसभा में 25 सदस्य) है, जिसके बिना सदन की कार्यवाही नहीं चल सकती।'), ('Under Article 108, who summons a Joint Sitting of both Houses of Parliament in case of a legislative deadlock?', 'अनुच्छेद 108 के अनुसार दोनों सदनों के बीच गतिरोध होने पर संसद की संयुक्त बैठक (Joint Sitting) कौन आहूत करता है?', 'The President of India', 'भारत के राष्ट्रपति (President of India)', ['The Speaker of Lok Sabha', 'The Prime Minister of India', 'The Chairman of Rajya Sabha'], ['लोकसभा अध्यक्ष', 'भारत के प्रधानमंत्री', 'राज्यसभा के सभापति'], 'The President summons a Joint Sitting when a bill passed by one House is rejected, disagreed, or delayed over 6 months by the other House.', 'साधारण विधेयक पर दोनों सदनों में विवाद होने पर राष्ट्रपति संयुक्त बैठक बुलाते हैं।'), ('Who presides over a Joint Sitting of both Houses of Parliament under Article 118(4)?', 'अनुच्छेद 118(4) के अनुसार संसद के दोनों सदनों की संयुक्त बैठक की अध्यक्षता कौन करता है?', 'The Speaker of the Lok Sabha (or in absence, Deputy Speaker; then Deputy Chairman of Rajya Sabha)', 'लोकसभा का अध्यक्ष (उनकी अनुपस्थिति में उपाध्यक्ष, फिर राज्यसभा के उपसभापति)', ['The Chairman of Rajya Sabha (Vice-President of India)', 'The Prime Minister of India', 'The Union Minister of Parliamentary Affairs'], ['राज्यसभा के सभापति (उपराष्ट्रपति)', 'भारत के प्रधानमंत्री', 'संसदीय कार्य मंत्री'], 'The Speaker presides; if absent, the Deputy Speaker presides; then Deputy Chairman RS. Note: Chairman RS (Vice-President) NEVER presides as he is not an MP.', 'संयुक्त बैठक की अध्यक्षता हमेशा लोकसभा अध्यक्ष करते हैं; उपराष्ट्रपति राज्यसभा के सभापति होते हुए भी कभी इसकी अध्यक्षता नहीं करते क्योंकि वे सांसद नहीं होते।'), ('On which two categories of Bills can a Joint Sitting of Parliament NEVER be called?', 'किन दो प्रकार के विधेयकों पर संसद की संयुक्त बैठक (Joint Sitting) कभी नहीं बुलाई जा सकती?', 'Money Bills (Article 110) and Constitutional Amendment Bills (Article 368)', 'धन विधेयक (Money Bill) एवं संविधान संशोधन विधेयक (Constitutional Amendment Bill)', ['Ordinary Bills and Financial Bills Class I', 'Bills altering state boundaries', 'Private member bills'], ['साधारण विधेयक और वित्तीय विधेयक', 'राज्यों की सीमा बदलने वाले बिल', 'गैर-सरकारी विधेयक'], 'Money Bills give Lok Sabha supremacy (RS has only 14 days); Constitutional Amendments must be passed by each House separately by special majority under Art 368.', 'धन विधेयक और संविधान संशोधन विधेयक पर संयुक्त बैठक का कोई प्रावधान नहीं है; दोनों सदनों का अलग-अलग पास करना अनिवार्य है।'), ('How many times have Joint Sittings of Parliament been convened in the legislative history of independent India?', 'स्वतंत्र भारत के संसदीय इतिहास में अब तक कुल कितनी बार दोनों सदनों की संयुक्त बैठक आयोजित की गई है?', '3 Times (Dowry Prohibition 1961, Banking Commission Repeal 1978, and POTA 2002)', '3 बार (दहेज निषेध 1961, बैंकिंग सेवा आयोग निरसन 1978, एवं पोटा 2002)', ['Never convened', '5 Times', '10 Times'], ['कभी नहीं बुलाई गई', '5 बार', '10 बार'], 'Convened only 3 times: 1961 (Dowry Prohibition Bill), 1978 (Banking Services Commission Bill), and 2002 (Prevention of Terrorism Bill - POTA).', 'भारत में केवल 3 बार संयुक्त बैठक हुई है: 1961 में दहेज कानून, 1978 में बैंकिंग आयोग बिल और 2002 में आतंकवाद निरोधक कानून (POTA) पर।'), ('Article 109 provides special procedure in respect of Money Bills, stating that a Money Bill shall NOT be introduced in', 'अनुच्छेद 109 के अनुसार धन विधेयक (Money Bill) किस सदन में प्रस्तुत (पेश) नहीं किया जा सकता?', 'The Council of States (Rajya Sabha)', 'राज्यसभा में (Council of States)', ['The House of the People (Lok Sabha)', "Either House without Governor's consent", 'Any House during monsoon session'], ['लोकसभा में', 'राज्यपाल की सहमति के बिना', 'मानसून सत्र में'], 'Article 109(1) explicitly states: A Money Bill shall not be introduced in the Council of States. It can originate ONLY in Lok Sabha.', 'धन विधेयक केवल लोकसभा में ही पेश किया जा सकता है, राज्यसभा में इसे कभी पेश नहीं किया जा सकता।'), ('Under Article 109, what is the maximum time within which the Rajya Sabha must return a Money Bill to the Lok Sabha?', 'अनुच्छेद 109 के तहत राज्यसभा को धन विधेयक कितने दिनों के भीतर लोकसभा को वापस लौटाना अनिवार्य होता है?', '14 Days from the date of its receipt', 'प्राप्ति की तिथि से 14 दिन के भीतर (14 Days)', ['30 Days', '6 Months', '21 Days'], ['30 दिन के भीतर', '6 माह के भीतर', '21 दिन के भीतर'], 'If Rajya Sabha does not return the Money Bill within 14 days, it is deemed to have been passed by both Houses in the form passed by Lok Sabha.', 'यदि राज्यसभा 14 दिनों के भीतर धन विधेयक वापस नहीं भेजती, तो वह स्वतः दोनों सदनों द्वारा पारित मान लिया जाता है।'), ('Article 110 of the Constitution defines which important legislative category?', 'संविधान का अनुच्छेद 110 किस महत्वपूर्ण विधेयक की परिभाषा देता है?', 'Money Bill (धन विधेयक)', 'धन विधेयक (Money Bill)', ['Financial Bill Class I', 'Ordinary Bill', 'Constitutional Amendment Bill'], ['वित्तीय विधेयक श्रेणी-1', 'साधारण विधेयक', 'संविधान संशोधन विधेयक'], 'Article 110 defines Money Bill: imposition, abolition, remission, alteration, or regulation of taxes, borrowing by the Union, Consolidated Fund custody.', "अनुच्छेद 110 कर लगाने, ऋण लेने, भारत की संचित निधि से धन निकालने आदि से संबंधित 'धन विधेयक' को परिभाषित करता है।"), ('Under Article 110(3), whose decision is FINAL on whether a bill is a Money Bill or not?', 'अनुच्छेद 110(3) के अनुसार कोई विधेयक धन विधेयक है या नहीं, इस पर अंतिम निर्णय किसका होता है?', 'The Speaker of the Lok Sabha (endorsed with his signed certificate)', 'लोकसभा अध्यक्ष का (उनके हस्ताक्षर वाले प्रमाण पत्र के साथ)', ['The Finance Minister of India', 'The President of India', 'The Chairman of Rajya Sabha'], ['भारत के वित्त मंत्री का', 'भारत के राष्ट्रपति का', 'राज्यसभा के सभापति का'], 'Article 110(3) states that if any question arises whether a Bill is a Money Bill or not, the decision of the Speaker of the Lok Sabha thereon shall be final.', 'लोकसभा अध्यक्ष का यह प्रमाण पत्र अंतिम होता है कि कौन सा बिल धन विधेयक है; इस पर कोई अपील नहीं हो सकती।'), ("Under Article 112, the President shall cause to be laid before Parliament an 'Annual Financial Statement', commonly known as the", "संविधान के अनुच्छेद 112 के तहत राष्ट्रपति संसद के समक्ष 'वार्षिक वित्तीय विवरण' रखवाते हैं, जिसे सामान्यतः क्या कहा जाता है?", 'Union Budget (केंद्रीय बजट)', 'केंद्रीय बजट (Union Budget)', ['Economic Survey', 'Fiscal Responsibility Report', 'CAG Audit Report'], ['आर्थिक सर्वेक्षण', 'राजकोषीय रिपोर्ट', 'कैग ऑडिट रिपोर्ट'], "The term 'Budget' is not found in the Constitution; Article 112 refers to it as the 'Annual Financial Statement'.", "संविधान में 'बजट' शब्द नहीं है; अनुच्छेद 112 में इसे 'वार्षिक वित्तीय विवरण' (Annual Financial Statement) कहा गया है।"), ('Article 114 provides that no money shall be withdrawn from the Consolidated Fund of India except under appropriation made by', "अनुच्छेद 114 के अनुसार भारत की संचित निधि में से कोई धन किसके द्वारा पारित 'विनियोग अधिनियम' के बिना नहीं निकाला जा सकता?", 'An Appropriation Act passed by Parliament', 'संसद द्वारा पारित विनियोग अधिनियम (Appropriation Act)', ['An executive decree of the Finance Ministry', 'An Ordinance of the President', 'A resolution of the NITI Aayog'], ['वित्त मंत्रालय के आदेश द्वारा', 'राष्ट्रपति के अध्यादेश द्वारा', 'नीति आयोग के संकल्प द्वारा'], 'Article 114(3) mandates an Appropriation Act; government cannot spend a single rupee from the Consolidated Fund without parliamentary appropriation.', 'संचित निधि से सरकारी खर्च करने के लिए संसद से विनियोग विधेयक (Appropriation Bill) पास कराना संवैधानिक अनिवार्यता है।'), ("What is a 'Vote on Account' under Article 116(a)?", "अनुच्छेद 116(क) के तहत 'लेखाअनुदान' (Vote on Account) क्या होता है?", 'An advance grant made by Parliament to cover expenditure for a part of the financial year pending the passage of the main Budget', 'पूर्ण बजट पारित होने तक वित्तीय वर्ष के आरंभिक भाग के खर्च को चलाने हेतु संसद द्वारा दी गई अग्रिम मंजूरी', ['A grant to meet an unexpected national disaster', 'A supplementary budget presented during winter session', 'An audit sanction granted by CAG'], ['राष्ट्रीय आपदा हेतु दी गई राशि', 'शीतकालीन सत्र का पूरक बजट', 'कैग द्वारा दी गई ऑडिट मंजूरी'], 'Vote on Account provides interim supply (usually for 2 months) so administrative machinery can operate before the Appropriation Act is enacted.', "बजट प्रक्रिया पूरी होने में समय लगता है; अतः 2 महीने के सरकारी खर्च के लिए संसद से अग्रिम 'लेखाअनुदान' लिया जाता है।"), ("What is a 'Cut Motion' in parliamentary budget proceedings?", "संसदीय बजट कार्यवाही में 'कटौती प्रस्ताव' (Cut Motion) क्या होता है?", 'A motion moved by opposition members to reduce the amount of a demand for grant', 'विपक्ष द्वारा अनुदान की मांगों में कमी करने के लिए लाया गया प्रस्ताव', ['A motion to cut short parliamentary session duration', "A motion to reduce MPs' monthly salaries", 'A motion to reduce the number of ministries'], ['सत्र की अवधि घटाने का प्रस्ताव', 'सांसदों का वेतन काटने का प्रस्ताव', 'मंत्रालयों की संख्या घटाने का प्रस्ताव'], 'Three types: Policy Cut (reduce demand to Re 1), Economy Cut (reduce by specified amount), and Token Cut (reduce by ₹100 to air grievance).', 'कटौती प्रस्ताव तीन प्रकार के होते हैं: नीतिगत कटौती (मांग को ₹1 करना), आर्थिक कटौती, और सांकेतिक कटौती (₹100 की कटौती)।'), ('What is the consequence if a Cut Motion or Money Bill is defeated by the Government in Lok Sabha?', 'यदि लोकसभा में सरकार द्वारा पेश बजट, धन विधेयक या विपक्ष का कटौती प्रस्ताव पास हो जाए, तो इसका क्या परिणाम होता है?', 'The Council of Ministers must resign, as it signifies loss of majority confidence', 'मंत्रिपरिषद को त्यागपत्र देना पड़ता है, क्योंकि यह सरकार के बहुमत खोने का स्पष्ट प्रमाण है', ['The Finance Minister alone is dismissed', 'The bill is sent to Supreme Court for arbitration', 'The Speaker calls a joint sitting'], ['केवल वित्त मंत्री बर्खास्त होते हैं', 'बिल सुप्रीम कोर्ट जाता है', 'स्पीकर संयुक्त बैठक बुलाते हैं'], 'Money defeat in Lok Sabha is fatal; it amounts to a vote of no-confidence against the government.', 'लोकसभा में धन विधेयक का गिरना या कटौती प्रस्ताव का पास होना सरकार का पतन माना जाता है; प्रधानमंत्री को इस्तीफा देना होता है।'), ("What is 'Guillotine' in parliamentary budget procedure?", "संसदीय बजट प्रक्रिया में 'गिलोटिन' (Guillotine) का क्या तात्पर्य है?", 'Putting all outstanding demands for grants to vote immediately without further discussion on the last day allotted', 'आवंटित समय समाप्त होने पर अंतिम दिन सभी बची हुई अनुदान मांगों पर बिना चर्चा के सीधे मतदान करा देना', ['Punishing a member for unparliamentary speech', 'Permanently expelling an MP from the House', 'Physical beheading in historical times'], ['सांसद को भाषण हेतु दंडित करना', 'सदन से हमेशा के लिए निष्कासन', 'ऐतिहासिक फांसी की सजा'], 'When the time limit for voting on demands for grants expires, the Speaker applies Guillotine, putting all un-debated demands to a vote at once.', 'बजट पर चर्चा का समय खत्म होने पर स्पीकर बची हुई सभी मांगों को बिना बहस एक साथ वोटिंग के लिए रख देते हैं, जिसे गिलोटिन कहते हैं।'), ("What is the 'Question Hour' in parliamentary sittings?", "संसदीय कार्यप्रणाली में 'प्रश्नकाल' (Question Hour) क्या होता है?", 'The first hour of every parliamentary sitting devoted to asking and answering questions to ministers', 'संसद की बैठक का पहला घंटा (11 से 12 बजे) जिसमें सांसद मंत्रियों से प्रश्न पूछते हैं', ['The last hour of the sitting devoted to passing bills', "The hour reserved for President's address", 'The lunch recess hour'], ['बैठक का अंतिम घंटा', 'राष्ट्रपति के अभिभाषण का घंटा', 'दोपहर का भोजनावकाश'], 'Question Hour (normally 11 AM to 12 PM) holds the government accountable; questions can be Starred, Unstarred, or Short Notice.', 'प्रश्नकाल संसद की कार्यवाही का पहला घंटा होता है, जिसमें सांसद सरकार से नीतियों और कार्यों पर सीधे सवाल पूछते हैं।'), ("What is the difference between a 'Starred Question' and an 'Unstarred Question' in Parliament?", "संसद में 'तारांकित प्रश्न' (Starred) और 'अतारांकित प्रश्न' (Unstarred) में क्या अंतर होता है?", 'Starred question is distinguished by an asterisk and requires an oral answer, allowing supplementary questions; Unstarred requires written answer', 'तारांकित प्रश्न पर तारा लगा होता है और इसका मौखिक उत्तर दिया जाता है (पूरक प्रश्न पूछे जा सकते हैं); अतारांकित का लिखित उत्तर मिलता है', ['Starred question is confidential; Unstarred is public', 'Starred is asked only by ministers; Unstarred by opposition', 'Starred question carries cash awards'], ['तारांकित गोपनीय होता है', 'तारांकित केवल मंत्री पूछते हैं', 'तारांकित में नकद इनाम मिलता है'], 'Starred questions (green paper in Lok Sabha) receive oral replies on the floor, allowing follow-up supplementary queries.', 'तारांकित प्रश्नों का मौखिक उत्तर सदन में दिया जाता है और पूरक प्रश्न (Cross-questions) पूछे जा सकते हैं; अतारांकित का लिखित उत्तर दिया जाता है।'), ("What is the 'Zero Hour' in Indian parliamentary practice?", "भारतीय संसदीय परंपरा में 'शून्यकाल' (Zero Hour) क्या होता है?", 'An informal Indian procedural innovation immediately following Question Hour (at 12 noon) to raise matters of urgent public importance without notice', 'प्रश्नकाल के ठीक बाद (दोपहर 12 बजे) बिना पूर्व सूचना के अविलंबनीय लोक महत्व के मुद्दे उठाने की भारतीय नवाचार प्रक्रिया', ['The midnight session of Parliament', 'The hour when no lights are turned on', 'The zero-budget audit session'], ['संसद का आधी रात का सत्र', 'बिजली बंद करने का समय', 'शून्य-बजट ऑडिट सत्र'], 'Zero Hour is an Indian innovation developed since 1962 (not mentioned in Rules of Procedure), starting at 12 noon immediately after Question Hour.', 'शून्यकाल भारतीय संसद की 1962 से शुरू हुई अनूठी देन है (नियमों में नहीं है); दोपहर 12 बजे इसमें अविलंबनीय मुद्दे उठाए जाते हैं।'), ("What is a 'Calling Attention Motion' in Parliament?", "संसद में 'ध्यानाकर्षण प्रस्ताव' (Calling Attention Motion) क्या होता है?", 'An Indian innovation to call the attention of a minister to an urgent matter of public importance and seek an authoritative statement', 'किसी अविलंबनीय लोक महत्व के मामले पर मंत्री का ध्यान आकर्षित करने और उनका प्रामाणिक वक्तव्य मांगने का भारतीय नवाचार प्रस्ताव', ['A motion to impeach the President', 'A motion to call new general elections', 'A motion to increase defense budget'], ['राष्ट्रपति पर महाभियोग का प्रस्ताव', 'नए चुनाव कराने का प्रस्ताव', 'रक्षा बजट बढ़ाने का प्रस्ताव'], 'Introduced in 1954; like Zero Hour, Calling Attention is an Indian procedural innovation to elicit government response on pressing events.', 'ध्यानाकर्षण प्रस्ताव 1954 से शुरू भारतीय नवाचार है, जिसके द्वारा मंत्री का ध्यान गंभीर विषय पर खींचा जाता है।'), ("What is an 'Adjournment Motion' (काम रोको प्रस्ताव) in Lok Sabha?", "लोकसभा में 'स्थगन प्रस्ताव / काम रोको प्रस्ताव' (Adjournment Motion) क्या होता है?", 'An extraordinary device to draw attention to a definite matter of urgent public importance, interrupting normal business with an element of censure', 'सदन की सामान्य कार्यवाही रोककर निश्चित अविलंबनीय लोक महत्व के मुद्दे पर बहस कराने का असाधारण प्रस्ताव, जिसमें सरकार की निंदा निहित होती है', ['A routine motion to close the House for weekend', 'A motion to adjourn during rainfall', 'A motion available only in Rajya Sabha'], ['सप्ताहांत पर छुट्टी का सामान्य प्रस्ताव', 'बारिश में छुट्टी का प्रस्ताव', 'केवल राज्यसभा में उपलब्ध प्रस्ताव'], 'Requires support of 50 members to be admitted; involves censure of government policy, so it is allowed ONLY in Lok Sabha, not Rajya Sabha.', 'यह केवल लोकसभा में ही लाया जा सकता है (कम से कम 50 सांसदों का समर्थन जरूरी); इसमें सरकार की निंदा समाहित होती है।'), ("What is a 'No-Confidence Motion' (अविश्वास प्रस्ताव) in Lok Sabha?", "लोकसभा में 'अविश्वास प्रस्ताव' (No-Confidence Motion) क्या होता है?", 'A motion moved under Rule 198 expressing lack of confidence in the entire Council of Ministers, requiring support of 50 members to be admitted', 'नियम 198 के तहत संपूर्ण मंत्रिपरिषद में अविश्वास व्यक्त करने वाला प्रस्ताव, जिसे स्वीकार होने के लिए कम से कम 50 सांसदों का समर्थन चाहिए', ['A motion against an individual minister for misconduct', 'A motion moved by the Prime Minister against opposition', 'A motion admitted in Rajya Sabha'], ['किसी एक मंत्री के खिलाफ प्रस्ताव', 'प्रधानमंत्री द्वारा विपक्ष के खिलाफ', 'राज्यसभा में पेश प्रस्ताव'], 'Under Article 75(3), government is responsible to Lok Sabha; if a No-Confidence Motion passes by simple majority, the government falls.', 'अविश्वास प्रस्ताव केवल लोकसभा में लाया जाता है; यदि यह पारित हो जाता है तो सरकार को तुरंत त्यागपत्र देना पड़ता है।'), ('What is the oldest and most prestigious Financial Committee of Parliament, established in 1921?', '1921 में मोंटेग्यू-चेम्सफोर्ड सुधारों के तहत गठित संसद की सबसे पुरानी और प्रतिष्ठित वित्तीय समिति कौन सी है?', 'Public Accounts Committee (PAC / लोक लेखा समिति)', 'लोक लेखा समिति (Public Accounts Committee - PAC)', ['Estimates Committee', 'Committee on Public Undertakings', 'Departmental Standing Committee'], ['प्राकलन समिति', 'सार्वजनिक उपक्रम समिति', 'विभागीय स्थायी समिति'], 'Set up in 1921; examines the appropriation accounts and the annual audit reports submitted by the CAG.', 'लोक लेखा समिति (PAC) 1921 में बनी थी; यह नियंत्रक एवं महालेखापरीक्षक (CAG) की रिपोर्टों की गहन जांच करती है।'), ('How many members comprise the Public Accounts Committee (PAC), and what is their distribution?', 'लोक लेखा समिति (PAC) में कुल कितने सदस्य होते हैं, और उनका सदन-वार वितरण क्या है?', '22 Members (15 from Lok Sabha and 7 from Rajya Sabha)', '22 सदस्य (15 लोकसभा से एवं 7 राज्यसभा से)', ['30 Members (all from Lok Sabha)', '15 Members (10 LS and 5 RS)', '25 Members (20 LS and 5 RS)'], ['30 सदस्य (सभी लोकसभा से)', '15 सदस्य (10 लोकसभा + 5 राज्यसभा)', '25 सदस्य (20 लोकसभा + 5 राज्यसभा)'], 'Elected annually by proportional representation by single transferable vote. Ministers cannot be elected as members.', 'पीएसी में 22 सदस्य (15 लोकसभा + 7 राज्यसभा) होते हैं; कोई भी मंत्री इसका सदस्य नहीं बन सकता।'), ('By parliamentary convention established since 1967, who is appointed as the Chairman of the Public Accounts Committee?', '1967 से स्थापित संसदीय परंपरा के अनुसार लोक लेखा समिति (PAC) का अध्यक्ष किसे नियुक्त किया जाता है?', 'A leader of the Opposition in the Lok Sabha (appointed by the Speaker)', 'लोकसभा में विपक्ष के किसी प्रमुख नेता को (लोकसभा अध्यक्ष द्वारा)', ['The Union Finance Minister', 'The Prime Minister of India', 'The Deputy Speaker of Lok Sabha'], ['केंद्रीय वित्त मंत्री को', 'भारत के प्रधानमंत्री को', 'लोकसभा के उपाध्यक्ष को'], 'The Speaker appoints the Chairman; since 1967 (starting with Minoo Masani), the PAC Chairman is drawn from the opposition party.', '1967 से परंपरा है कि पीएसी का अध्यक्ष विपक्ष के नेता को ही बनाया जाता है ताकि सरकारी खर्चों की निष्पक्ष जांच हो सके।'), ('Which is the largest Committee of the Indian Parliament in terms of membership?', 'सदस्य संख्या की दृष्टि से भारतीय संसद की सबसे बड़ी समिति कौन सी है?', 'Estimates Committee (प्राकलन समिति - 30 members, ALL from Lok Sabha)', 'प्राकलन समिति (Estimates Committee — 30 सदस्य, सभी केवल लोकसभा से)', ['Public Accounts Committee (22 members)', 'Committee on Public Undertakings (22 members)', 'Petitions Committee (15 members)'], ['लोक लेखा समिति (22 सदस्य)', 'सार्वजनिक उपक्रम समिति (22 सदस्य)', 'याचिका समिति (15 सदस्य)'], 'Created in 1950 on the recommendation of Finance Minister John Mathai; consists of 30 members, all elected from Lok Sabha only (no RS member).', 'जॉन मथाई की सिफारिश पर 1950 में गठित प्राकलन समिति में 30 सदस्य होते हैं और सभी केवल लोकसभा से चुने जाते हैं।'), ('Under Article 249, which House has the exclusive power to authorize Parliament to make laws on a State List subject in national interest?', 'अनुच्छेद 249 के अनुसार राष्ट्रीय हित में राज्य सूची के विषय पर संसद को कानून बनाने का अधिकार देने की विशेष शक्ति किस सदन को है?', 'The Council of States (Rajya Sabha) by a 2/3rd majority of members present and voting', 'राज्यसभा को (उपस्थित और मतदान करने वाले सदस्यों के दो-तिहाई बहुमत द्वारा)', ['The House of the People (Lok Sabha) alone', 'A joint sitting of both Houses', 'State Legislative Assemblies by resolution'], ['केवल लोकसभा को', 'दोनों सदनों की संयुक्त बैठक को', 'राज्य विधानसभाओं के संकल्प को'], 'Article 249 gives Rajya Sabha exclusive federal power: it can pass a resolution declaring a State List matter of national importance, valid for 1 year.', 'अनुच्छेद 249 राज्यसभा का विशेष विशेषाधिकार है; वह 2/3 बहुमत से प्रस्ताव पारित कर राज्य सूची के विषय पर संसद को कानून बनाने की शक्ति दे सकती है।')]

slot_q118_jud = [('The Supreme Court of India was inaugurated on which historic date?', 'भारत के सर्वोच्च न्यायालय (Supreme Court) का उद्घाटन किस ऐतिहासिक तिथि को हुआ था?', '28 January 1950', '28 जनवरी 1950 को', ['26 January 1950', '15 August 1947', '26 November 1949'], ['26 जनवरी 1950', '15 अगस्त 1947', '26 नवंबर 1949'], 'Inaugurated on 28 January 1950, replacing both the Federal Court of India (set up under 1935 Act) and the Privy Council in London.', '28 जनवरी 1950 को भारत के सर्वोच्च न्यायालय का उद्घाटन हुआ, जिसने फेडरल कोर्ट और लंदन की प्रिवी काउंसिल का स्थान लिया।'), ('Who was the first Chief Justice of India (CJI) of the Supreme Court of India?', 'भारत के सर्वोच्च न्यायालय के प्रथम मुख्य न्यायाधीश (CJI) कौन थे?', 'Justice Harilal Jekisundas Kania (H.J. Kania)', 'न्यायमूर्ति हीरालाल जे. कानिया (H.J. Kania)', ['Justice M. Patanjali Sastri', 'Justice Mehr Chand Mahajan', 'Justice Sudhi Ranjan Das'], ['न्यायमूर्ति शास्त्री', 'न्यायमूर्ति महाजन', 'न्यायमूर्ति एस.आर. दास'], 'Justice H.J. Kania served as the first Chief Justice of independent India from 1950 until his untimely death in November 1951.', 'न्यायमूर्ति एच.जे. कानिया भारत के पहले मुख्य न्यायाधीश थे।'), ('What is the current sanctioned judicial strength of the Supreme Court of India (including the CJI)?', 'वर्तमान समय में सर्वोच्च न्यायालय में मुख्य न्यायाधीश सहित कुल स्वीकृत न्यायाधीशों की संख्या कितनी है?', '34 Judges (1 CJI + 33 Judges)', '34 न्यायाधीश (1 मुख्य न्यायाधीश + 33 अन्य न्यायाधीश)', ['31 Judges', '26 Judges', '35 Judges'], ['31 न्यायाधीश', '26 न्यायाधीश', '35 न्यायाधीश'], 'Originally 8 judges (1+7) in 1950; increased by Parliament in 2019 to 34 judges (1 Chief Justice + 33 Puisne Judges).', 'मूल संविधान में 1+7 (कुल 8) थे; 2019 के संशोधन के बाद अब 1 मुख्य न्यायाधीश और 33 अन्य न्यायाधीश (कुल 34) हैं।'), ('Under Article 124(1), who has the power to increase the number of judges in the Supreme Court?', 'अनुच्छेद 124(1) के तहत सर्वोच्च न्यायालय में न्यायाधीशों की संख्या बढ़ाने का अधिकार किसे है?', 'Parliament of India by law', 'संसद को (विधि द्वारा)', ['The President of India by executive decree', 'The Chief Justice of India', 'The Bar Council of India'], ['राष्ट्रपति के अध्यादेश द्वारा', 'भारत के मुख्य न्यायाधीश को', 'बार काउंसिल ऑफ इंडिया को'], 'Article 124(1) provides that Parliament may by law prescribe a larger number of judges.', 'सुप्रीम कोर्ट में जजों की संख्या बढ़ाने का अधिकार केवल संसद को कानून बनाकर है।'), ('What is the retirement age of a Judge of the Supreme Court of India under Article 124(2)?', 'अनुच्छेद 124(2) के अनुसार सर्वोच्च न्यायालय के न्यायाधीश की सेवानिवृत्ति आयु कितनी है?', '65 Years of age', '65 वर्ष की आयु', ['62 Years', '60 Years', '70 Years'], ['62 वर्ष', '60 वर्ष', '70 वर्ष'], 'Supreme Court judges retire at age 65; High Court judges retire at age 62.', 'सर्वोच्च न्यायालय के न्यायाधीश 65 वर्ष की आयु में सेवानिवृत्त होते हैं (जबकि हाईकोर्ट के जज 62 वर्ष में)।'), ('What is the retirement age of a Judge of a High Court under Article 217(1)?', 'अनुच्छेद 217(1) के अनुसार उच्च न्यायालय (High Court) के न्यायाधीश की सेवानिवृत्ति आयु कितनी है?', '62 Years of age (raised from 60 to 62 by 15th Amendment, 1963)', '62 वर्ष की आयु (15वें संशोधन 1963 द्वारा 60 से बढ़ाकर 62 की गई)', ['65 Years', '60 Years', '58 Years'], ['65 वर्ष', '60 वर्ष', '58 वर्ष'], 'High Court judges retire at 62 years; the 15th Constitutional Amendment Act 1963 raised it from 60 to 62.', 'उच्च न्यायालय के न्यायाधीशों की सेवानिवृत्ति आयु 62 वर्ष है।'), ('What qualifications are required to be appointed as a Judge of the Supreme Court under Article 124(3)?', 'अनुच्छेद 124(3) के अनुसार सर्वोच्च न्यायालय का न्यायाधीश बनने के लिए क्या न्यूनतम योग्यताएं होनी चाहिए?', 'Citizen of India, and either 5 years as High Court Judge, or 10 years as High Court Advocate, or a distinguished jurist in the opinion of the President', 'भारत का नागरिक हो, तथा कम से कम 5 वर्ष हाईकोर्ट का जज रहा हो, या 10 वर्ष हाईकोर्ट में वकील रहा हो, या राष्ट्रपति की राय में पारंगत विधिवेत्ता हो', ['Master of Laws degree with 15 years practice', 'Retired civil district judge of 20 years', 'Member of Parliament with law degree'], ['एलएलएम डिग्री व 15 साल प्रैक्टिस', '20 साल का जिला जज', 'कानून डिग्री वाला सांसद'], 'Article 124(3) specifies: Citizen of India, plus either 5 years HC judge, 10 years HC advocate, or a distinguished jurist.', 'नागरिक हो, और 5 साल हाईकोर्ट जज या 10 साल हाईकोर्ट में वकालत या राष्ट्रपति की नजर में प्रतिष्ठित विधिवेत्ता (Distinguished Jurist) हो।'), ("Has any person ever been appointed directly to the Supreme Court as a 'distinguished jurist' under Article 124(3)(c)?", "क्या आज तक किसी व्यक्ति को 'पारंगत विधिवेत्ता' (Distinguished Jurist) श्रेणी के तहत सीधे सुप्रीम कोर्ट में नियुक्त किया गया है?", 'No, no person has ever been appointed under this provision so far', 'नहीं, आज तक इस प्रावधान के तहत किसी को नियुक्त नहीं किया गया है', ['Yes, Nani Palkhivala was appointed in 1975', 'Yes, Dr. B.R. Ambedkar was appointed in 1950', 'Yes, Sir B.N. Rau was appointed in 1952'], ['हां, नानी पालकीवाला को 1975 में', 'हां, डॉ. आंबेडकर को 1950 में', 'हां, सर बी.एन. राव को 1952 में'], 'Though inspired by the US Supreme Court practice, no academic jurist has ever been appointed to the Supreme Court under this clause.', 'अमेरिकी परंपरा से लिए गए इस प्रावधान के तहत भारत में अब तक किसी अकादमिक विधिवेत्ता की सीधी नियुक्ति नहीं हुई है।'), ('Under Article 124(4), on what grounds can a Judge of the Supreme Court or High Court be removed from office?', 'अनुच्छेद 124(4) के अनुसार सर्वोच्च या उच्च न्यायालय के न्यायाधीश को किन आधारों पर पद से हटाया जा सकता है?', "'Proved misbehaviour or incapacity' (सिद्ध कदाचार या असमर्थता)", "'सिद्ध कदाचार या असमर्थता' (Proved Misbehaviour or Incapacity)", ['Bribery and moral turpitude alone', 'Violating political code of conduct', "Disobeying the Law Minister's instructions"], ['केवल रिश्वतखोरी', 'आचार संहिता का उल्लंघन', 'विधि मंत्री के आदेश की अवहेलना'], "The two constitutional grounds are 'proved misbehaviour' or 'incapacity', established through an inquiry under the Judges (Inquiry) Act, 1968.", "न्यायाधीशों को केवल 'सिद्ध कदाचार' या 'असमर्थता' के आधार पर संसद द्वारा विशेष बहुमत से पारित प्रस्ताव पर राष्ट्रपति द्वारा हटाया जा सकता है।"), ('What majority in Parliament is required to remove a Judge of the Supreme Court under Article 124(4)?', 'सर्वोच्च न्यायालय के किसी न्यायाधीश को पद से हटाने के लिए संसद में किस बहुमत की आवश्यकता होती है?', 'A majority of the total membership of each House AND a majority of not less than 2/3rds of members present and voting', 'प्रत्येक सदन की कुल सदस्य संख्या का बहुमत तथा उपस्थित व मतदान करने वाले सदस्यों का दो-तिहाई (2/3) बहुमत', ['Simple majority of members present and voting', 'Unanimous vote of both Houses', '3/4th majority of total membership'], ['उपस्थित सदस्यों का साधारण बहुमत', 'दोनों सदनों की सर्वसम्मति', 'कुल सदस्यों का 3/4 बहुमत'], 'Requires an address by both Houses in the same session supported by an absolute majority of total strength and 2/3rd majority of members present and voting.', 'संसद के दोनों सदनों में कुल सदस्यों के बहुमत तथा उपस्थित व मतदान करने वालों के दो-तिहाई विशेष बहुमत से ही न्यायाधीश को हटाया जा सकता है।'), ('Who was the first Supreme Court judge against whom an impeachment motion was introduced in Parliament in 1993?', '1993 में संसद में महाभियोग की प्रक्रिया का सामना करने वाले पहले सर्वोच्च न्यायालय के न्यायाधीश कौन थे?', 'Justice V. Ramaswami', 'न्यायमूर्ति वी. रामास्वामी (Justice V. Ramaswami)', ['Justice Soumitra Sen', 'Justice P.D. Dinakaran', 'Justice Dipak Misra'], ['न्यायमूर्ति सौमित्र सेन', 'न्यायमूर्ति पी.डी. दिनकरन', 'न्यायमूर्ति दीपक मिश्रा'], 'Justice V. Ramaswami faced impeachment in May 1993; the inquiry committee found him guilty, but the motion fell in Lok Sabha because Congress abstained.', 'न्यायमूर्ति वी. रामास्वामी पहले जज थे जिन पर महाभियोग लाया गया; किंतु कांग्रेस के मतदान से अनुपस्थित रहने के कारण प्रस्ताव आवश्यक दो-तिहाई बहुमत नहीं पा सका।'), ("Under the 'Collegium System' evolved through the Second and Third Judges Cases, who recommends appointments to the Supreme Court?", "दूसरे और तीसरे जजेस केस से विकसित 'कॉलेजियम प्रणाली' के तहत सुप्रीम कोर्ट में जजों की नियुक्ति की सिफारिश कौन करता है?", 'Chief Justice of India (CJI) and the four seniormost Puisne Judges of the Supreme Court', 'भारत के मुख्य न्यायाधीश (CJI) तथा सर्वोच्च न्यायालय के चार वरिष्ठतम न्यायाधीश (1+4)', ['CJI and the Union Law Minister', 'President of India and Prime Minister', 'CJI and two seniormost Judges'], ['CJI एवं केंद्रीय विधि मंत्री', 'राष्ट्रपति एवं प्रधानमंत्री', 'CJI एवं दो वरिष्ठतम जज'], 'In the Third Judges Case (1998 Special Reference), a 9-judge bench clarified the Collegium consists of the CJI and 4 seniormost judges.', 'तीसरे जजेस केस (1998) में तय हुआ कि सुप्रीम कोर्ट के लिए कॉलेजियम में CJI और 4 वरिष्ठतम जज होंगे, जिनकी राय से ही नियुक्ति होगी।'), ('Which Constitutional Amendment Act sought to replace the Collegium System with the National Judicial Appointments Commission (NJAC)?', "किस संविधान संशोधन अधिनियम द्वारा कॉलेजियम प्रणाली को समाप्त कर 'राष्ट्रीय न्यायिक नियुक्ति आयोग' (NJAC) बनाने का प्रयास किया गया था?", '99th Constitutional Amendment Act, 2014', '99वां संविधान संशोधन अधिनियम (2014)', ['98th Amendment Act', '100th Amendment Act', '97th Amendment Act'], ['98वां संशोधन', '100वां संशोधन', '97वां संशोधन'], 'The 99th Amendment Act 2014 and NJAC Act set up a 6-member commission including the Law Minister and eminent persons to appoint judges.', '99वें संशोधन (2014) द्वारा न्यायपालिका में जजों की नियुक्ति हेतु NJAC कानून बनाया गया था।'), ('In the Fourth Judges Case (2015), a 5-judge Constitution bench struck down the 99th Amendment and NJAC as unconstitutional because it violated', 'चौथे जजेस केस (2015) में 5 जजों की संविधान पीठ ने NJAC और 99वें संशोधन को असंवैधानिक घोषित करते हुए किस आधार पर रद्द कर दिया?', 'The Independence of the Judiciary, which is part of the Basic Structure of the Constitution', 'न्यायपालिका की स्वतंत्रता (Independence of Judiciary), जो संविधान का मूल ढांचा है', ['The executive supremacy of the Prime Minister', 'The federal rights of State Governors', 'The jurisdiction of the Bar Council'], ['प्रधानमंत्री की कार्यपालिका सर्वोच्चता', 'राज्यपालों के संघीय अधिकार', 'बार काउंसिल का अधिकार क्षेत्र'], 'By a 4:1 majority in Supreme Court Advocates-on-Record Association (2015), the court struck down NJAC, reviving the Collegium system.', 'सुप्रीम कोर्ट ने 4:1 के बहुमत से माना कि कानून मंत्री की मौजूदगी न्यायपालिका की स्वतंत्रता (मूल ढांचे) को नुकसान पहुंचाती है, अतः कॉलेजियम व्यवस्था बहाल रही।'), ('Article 129 of the Constitution declares the Supreme Court of India to be a', 'संविधान का अनुच्छेद 129 सर्वोच्च न्यायालय को क्या घोषित करता है?', 'Court of Record (अभिलेख न्यायालय) with power to punish for its contempt', 'अभिलेख न्यायालय (Court of Record) — अवमानना हेतु दंड देने की शक्ति सहित', ['Statutory Administrative Tribunal', 'Civil Advisory Board', 'Arbitration Council'], ['वैधानिक प्रशासनिक न्यायाधिकरण', 'दीवानी सलाहकार बोर्ड', 'मध्यस्थता परिषद'], 'As a Court of Record, its judgments have evidentiary value and cannot be questioned in subordinate courts; it has summary power to punish for contempt.', 'अनुच्छेद 129 के अनुसार सर्वोच्च न्यायालय के फैसले नजीर (साक्ष्य) के रूप में माने जाएंगे और उसे अपनी अवमानना (Contempt) के लिए दंड देने का अधिकार है।'), ('Under Article 131, the Supreme Court of India has EXCLUSIVE Original Jurisdiction in disputes between', 'अनुच्छेद 131 के तहत सर्वोच्च न्यायालय को किन विवादों में अनन्य प्रारंभिक क्षेत्राधिकार (Exclusive Original Jurisdiction) प्राप्त है?', 'The Government of India and one or more States, or disputes between two or more States', 'भारत सरकार और एक या अधिक राज्यों के बीच, अथवा दो या अधिक राज्यों के बीच के विवादों में', ['Private commercial disputes between corporate companies', 'Divorce and matrimonial cases of citizens', 'Criminal appeals against district sessions courts'], ['निजी कंपनियों के व्यापारिक विवाद', 'पारिवारिक व तलाक के मामले', 'जिला अदालतों के खिलाफ आपराधिक अपील'], 'Article 131 provides federal original jurisdiction over legal disputes between Union vs States or State vs State.', 'अनुच्छेद 131 केंद्र और राज्यों या राज्यों के आपसी कानूनी विवादों को सीधे सुप्रीम कोर्ट में सुनने का अनन्य अधिकार देता है।'), ("Under Article 136, the Supreme Court may grant 'Special Leave to Appeal' (SLP) from", "अनुच्छेद 136 के तहत सर्वोच्च न्यायालय 'विशेष अनुमति याचिका' (SLP) द्वारा किसके फैसले के विरुद्ध अपील स्वीकार कर सकता है?", 'Any judgment, decree, or sentence in any cause or matter passed by any court or tribunal in India (except Armed Forces tribunals)', 'भारत के किसी भी न्यायालय या न्यायाधिकरण द्वारा दिए गए किसी भी निर्णय या दंडादेश के विरुद्ध (सैन्य अदालत को छोड़कर)', ['High Courts in constitutional matters only', 'District Sessions Courts in murder trials only', 'Only civil disputes exceeding ₹10 Lakhs'], ['केवल संवैधानिक मामलों में हाईकोर्ट से', 'केवल हत्या के मामलों में जिला कोर्ट से', 'केवल ₹10 लाख से अधिक के मामलों में'], 'Article 136 is an extraordinary discretionary appellate power exercisable against any court or tribunal, except military courts-martial under Art 136(2).', 'अनुच्छेद 136 सुप्रीम कोर्ट का असाधारण विवेकाधीन अधिकार है, जिसके तहत वह सैन्य अदालतों को छोड़कर किसी भी ट्रिब्यूनल या कोर्ट के फैसले की अपील सुन सकता है।'), ('Article 141 of the Constitution provides that the law declared by the Supreme Court shall be', 'संविधान के अनुच्छेद 141 के अनुसार सर्वोच्च न्यायालय द्वारा घोषित विधि किसके लिए बाध्यकारी होती है?', 'Binding on all courts within the territory of India', 'भारत के राज्यक्षेत्र के भीतर सभी न्यायालयों पर आबद्धकर (Binding)', ['Binding only on the Central Government', 'Binding only on High Courts of North India', 'Persuasive advice without legal force'], ['केवल केंद्र सरकार पर', 'केवल उत्तर भारत के न्यायालयों पर', 'केवल सलाहकारी'], 'Article 141 establishes judicial precedent (Stare Decisis); Supreme Court rulings are the law of the land binding on all subordinate courts.', 'अनुच्छेद 141 के अनुसार सुप्रीम कोर्ट का फैसला देश के सभी न्यायालयों के लिए कानून की तरह बाध्यकारी होता है।'), ('Article 142 empowers the Supreme Court to pass any decree or order necessary for doing', 'संविधान का अनुच्छेद 142 सर्वोच्च न्यायालय को किसके लिए आवश्यक कोई भी आदेश या डिक्री पारित करने की असाधारण शक्ति देता है?', "'Complete Justice' in any cause or matter pending before it", "अपने समक्ष लंबित किसी मामले में 'पूर्ण न्याय' (Complete Justice) करने के लिए", ['Declaring war against foreign nations', 'Dismissing the Lok Sabha Speaker', 'Abolishing state legislative assemblies'], ['विदेशी राष्ट्र से युद्ध की घोषणा', 'लोकसभा अध्यक्ष को हटाना', 'विधानसभाओं को समाप्त करना'], 'Article 142 grants plenary equitable power to do complete justice; used in Union Carbide (Bhopal gas), Ayodhya title dispute, and coal block de-allocation.', "अनुच्छेद 142 सुप्रीम कोर्ट को 'पूर्ण न्याय' करने की असीम अंतर्निहित शक्ति देता है, जिसका प्रयोग भोपाल गैस कांड, अयोध्या विवाद आदि में किया गया।"), ("Under Article 143, who can seek an 'Advisory Opinion' from the Supreme Court on questions of law or public importance?", "अनुच्छेद 143 के तहत विधि या सार्वजनिक महत्व के तथ्य पर सर्वोच्च न्यायालय से 'परामर्श' (सलाह) मांगने की शक्ति किसे है?", 'The President of India', 'भारत के राष्ट्रपति को (The President of India)', ['The Prime Minister of India', 'The Attorney General for India', 'The Speaker of Lok Sabha'], ['भारत के प्रधानमंत्री को', 'भारत के महान्यायवादी को', 'लोकसभा अध्यक्ष को'], "The President may refer questions under Article 143; the Supreme Court's opinion is advisory and not binding on the President.", 'अनुच्छेद 143 के तहत राष्ट्रपति सुप्रीम कोर्ट से कानूनी सलाह मांग सकते हैं; यह सलाह परामर्शकारी होती है, राष्ट्रपति पर बाध्यकारी नहीं होती।'), ('In which landmark Presidential Reference under Article 143 did the Supreme Court examine the acquisition of religious land in Ayodhya in 1994?', 'अनुच्छेद 143 के तहत किस प्रसिद्ध राष्ट्रपति संदर्भ में सुप्रीम कोर्ट ने 1994 में अयोध्या में धार्मिक भूमि अधिग्रहण की समीक्षा की थी?', 'Special Reference No. 1 of 1993 (Ismail Faruqui case, 1994)', 'विशेष संदर्भ 1993 (इस्माइल फारूकी मामला, 1994)', ['Berubari Reference (1960)', 'Sea Customs Reference (1963)', 'Delhi Laws Act Reference (1951)'], ['बेरुबारी संदर्भ (1960)', 'सी कस्टम्स संदर्भ (1963)', 'दिल्ली लॉज एक्ट संदर्भ (1951)'], 'The Supreme Court declined to answer the historical question whether a temple stood beneath Babri Masjid, while upholding the land acquisition.', 'सुप्रीम कोर्ट ने ऐतिहासिक तथ्य के सवाल पर राय देने से मना करते हुए भूमि अधिग्रहण कानून को वैध ठहराया था।'), ('How many High Courts currently exist across the Republic of India?', 'वर्तमान समय में भारत गणराज्य में कुल कितने उच्च न्यायालय (High Courts) कार्यरत हैं?', '25 High Courts', '25 उच्च न्यायालय (25 High Courts)', ['24 High Courts', '28 High Courts', '21 High Courts'], ['24 उच्च न्यायालय', '28 उच्च न्यायालय', '21 उच्च न्यायालय'], 'With the establishment of the Andhra Pradesh High Court at Amaravati on 1 January 2019, there are currently 25 High Courts in India.', '1 जनवरी 2019 को अमरावती में आंध्र प्रदेश उच्च न्यायालय की स्थापना के बाद भारत में अब कुल 25 उच्च न्यायालय हैं।'), ('Which was the 25th High Court established in India in January 2019?', 'जनवरी 2019 में स्थापित होने वाला भारत का 25वां उच्च न्यायालय कौन सा था?', 'Andhra Pradesh High Court (at Amaravati)', 'आंध्र प्रदेश उच्च न्यायालय (अमरावती)', ['Telangana High Court', 'Tripura High Court', 'Meghalaya High Court'], ['तेलंगाना उच्च न्यायालय', 'त्रिपुरा उच्च न्यायालय', 'मेघालय उच्च न्यायालय'], 'Bifurcated from the Hyderabad High Court, the Andhra Pradesh High Court at Amaravati began functioning on 1 January 2019.', 'हैदराबाद हाईकोर्ट से अलग होकर 1 जनवरी 2019 से अमरावती में आंध्र प्रदेश का नया 25वां हाईकोर्ट शुरू हुआ।'), ('Which were the first three High Courts established in British India under the Indian High Courts Act of 1861?', '1861 के भारतीय उच्च न्यायालय अधिनियम के तहत ब्रिटिश भारत में स्थापित होने वाले पहले तीन उच्च न्यायालय कौन से थे?', 'Calcutta, Bombay, and Madras High Courts (established in 1862)', 'कलकत्ता, बॉम्बे एवं मद्रास उच्च न्यायालय (1862 में स्थापित)', ['Allahabad, Patna, and Delhi High Courts', 'Lahore, Nagpur, and Patna High Courts', 'Calcutta, Delhi, and Rangoon High Courts'], ['इलाहाबाद, पटना एवं दिल्ली हाईकोर्ट', 'लाहौर, नागपुर एवं पटना हाईकोर्ट', 'कलकत्ता, दिल्ली एवं रंगून हाईकोर्ट'], 'Queen Victoria issued Letters Patent in 1862 setting up Calcutta (oldest, July 1862), Bombay (August 1862), and Madras (August 1862).', '1862 में कलकत्ता (सबसे पुराना), बॉम्बे और मद्रास में प्रेसीडेंसी उच्च न्यायालयों की स्थापना हुई थी।'), ('Which was the fourth High Court established in India in 1866 (originally at Agra, shifted to Allahabad in 1869)?', '1866 में स्थापित होने वाला भारत का चौथा उच्च न्यायालय कौन सा था (जो 1869 में इलाहाबाद स्थानांतरित हुआ)?', 'Allahabad High Court (High Court of Judicature at Allahabad)', 'इलाहाबाद उच्च न्यायालय (Allahabad High Court)', ['Patna High Court', 'Punjab and Haryana High Court', 'Karnataka High Court'], ['पटना उच्च न्यायालय', 'पंजाब एवं हरियाणा हाईकोर्ट', 'कर्नाटक उच्च न्यायालय'], 'Established at Agra in 1866 as High Court of the North-Western Provinces and shifted to Allahabad in 1869; today the largest in judge strength (160).', '1866 में आगरा में बना चौथा हाईकोर्ट 1869 में इलाहाबाद लाया गया; यह आज जजों की संख्या (160) में देश का सबसे बड़ा हाईकोर्ट है।'), ('In which year was the Patna High Court established with jurisdiction over Bihar and Orissa?', "बिहार और उड़ीसा के लिए 'पटना उच्च न्यायालय' की स्थापना किस वर्ष की गई थी?", '1916 (inaugurated on 3 February 1916 by Viceroy Lord Hardinge)', '1916 में (3 फरवरी 1916 को वायसराय लॉर्ड हार्डिंग द्वारा उद्घाटित)', ['1912', '1919', '1925'], ['1912 में', '1919 में', '1925 में'], 'Patna High Court began functioning on 1 March 1916 under Chief Justice Sir Edward Maynard Des Champs Chamier.', 'पटना हाईकोर्ट का उद्घाटन 3 फरवरी 1916 को हुआ था और सर एडवर्ड चामियर इसके पहले मुख्य न्यायाधीश बने थे।'), ('Who was the first Indian Chief Justice of the Patna High Court in 1946?', '1946 में पटना उच्च न्यायालय के पहले भारतीय मुख्य न्यायाधीश कौन बने थे?', 'Sir Syed Fazal Ali', 'सर सैयद फजल अली (Sir Syed Fazal Ali)', ['Dr. Sachchidananda Sinha', 'Justice B.P. Sinha', 'Justice K.B.N. Singh'], ['डॉ. सच्चिदानंद सिन्हा', 'न्यायमूर्ति बी.पी. सिन्हा', 'न्यायमूर्ति के.बी.एन. सिंह'], 'Sir Syed Fazal Ali served as Chief Justice of Patna High Court from 1943 to 1947, and later served on the Supreme Court and States Reorganisation Commission.', 'सर सैयद फजल अली पटना हाईकोर्ट के पहले भारतीय मुख्य न्यायाधीश थे।'), ('Which two Union Territories currently have their own separate High Courts?', 'वर्तमान में किन दो केंद्र शासित प्रदेशों के पास अपने स्वयं के अलग उच्च न्यायालय हैं?', 'Delhi and Jammu & Kashmir (Common HC with Ladakh)', 'दिल्ली एवं जम्मू-कश्मीर (लद्दाख के साथ साझा हाईकोर्ट)', ['Delhi and Puducherry', 'Chandigarh and Andaman', 'Dadra & Nagar Haveli and Lakshadweep'], ['दिल्ली एवं पुदुचेरी', 'चंडीगढ़ एवं अंडमान', 'दादरा एवं लक्षद्वीप'], 'Delhi established its own High Court in 1966; J&K High Court serves J&K and Ladakh.', 'दिल्ली 1966 से अपना अलग हाईकोर्ट रखता है; तथा जम्मू-कश्मीर हाईकोर्ट जम्मू-कश्मीर व लद्दाख के लिए है।'), ('Under the jurisdiction of which High Court do the Andaman and Nicobar Islands fall?', 'अंडमान और निकोबार द्वीप समूह किस उच्च न्यायालय के क्षेत्राधिकार के अंतर्गत आते हैं?', 'Calcutta High Court (Circuit Bench at Port Blair)', 'कलकत्ता उच्च न्यायालय (पोर्ट ब्लेयर सर्किट बेंच)', ['Madras High Court', 'Orissa High Court', 'Andhra Pradesh High Court'], ['मद्रास उच्च न्यायालय', 'उड़ीसा उच्च न्यायालय', 'आंध्र प्रदेश उच्च न्यायालय'], 'Under Section 4 of the Calcutta High Court (Extension of Jurisdiction) Act 1953, Andaman & Nicobar falls under Calcutta HC with a permanent circuit bench at Port Blair.', 'अंडमान-निकोबार द्वीप समूह का न्यायिक क्षेत्राधिकार कलकत्ता हाईकोर्ट के अधीन है, जिसकी सर्किट बेंच पोर्ट ब्लेयर में है।'), ('Under the jurisdiction of which High Court does the Union Territory of Lakshadweep fall?', 'केंद्र शासित प्रदेश लक्षद्वीप किस उच्च न्यायालय के क्षेत्राधिकार के अधीन आता है?', 'Kerala High Court (at Ernakulam)', 'केरल उच्च न्यायालय (एर्नाकुलम)', ['Madras High Court', 'Bombay High Court', 'Karnataka High Court'], ['मद्रास उच्च न्यायालय', 'बॉम्बे उच्च न्यायालय', 'कर्नाटक उच्च न्यायालय'], 'Lakshadweep falls under the territorial jurisdiction of the Kerala High Court located at Ernakulam.', 'लक्षद्वीप का न्यायिक क्षेत्राधिकार केरल उच्च न्यायालय (एर्नाकुलम) के अधीन आता है।'), ('Under the jurisdiction of which High Court does the Union Territory of Puducherry fall?', 'केंद्र शासित प्रदेश पुदुचेरी किस उच्च न्यायालय के क्षेत्राधिकार में आता है?', 'Madras High Court (at Chennai)', 'मद्रास उच्च न्यायालय (चेन्नई)', ['Kerala High Court', 'Andhra Pradesh High Court', 'Karnataka High Court'], ['केरल उच्च न्यायालय', 'आंध्र प्रदेश उच्च न्यायालय', 'कर्नाटक उच्च न्यायालय'], 'Puducherry falls under the jurisdiction of the Madras High Court.', 'पुदुचेरी का न्यायिक प्रशासन मद्रास उच्च न्यायालय के अधिकार क्षेत्र में आता है।'), ('The Bombay High Court has territorial jurisdiction over which States and Union Territories?', 'बॉम्बे उच्च न्यायालय का क्षेत्राधिकार किन राज्यों और केंद्र शासित प्रदेशों पर विस्तृत है?', 'Maharashtra, Goa, and Dadra & Nagar Haveli and Daman & Diu', 'महाराष्ट्र, गोवा, तथा दादरा एवं नगर हवेली और दमन एवं दीव', ['Maharashtra and Gujarat', 'Maharashtra and Karnataka', 'Maharashtra and Madhya Pradesh'], ['महाराष्ट्र और गुजरात', 'महाराष्ट्र और कर्नाटक', 'महाराष्ट्र और मध्य प्रदेश'], 'Bombay HC has benches at Nagpur, Aurangabad, and Panaji (Goa), covering Maharashtra, Goa, and the merged UT of DNHDD.', 'बॉम्बे हाईकोर्ट की पीठ नागपुर, औरंगाबाद और पणजी में है; यह महाराष्ट्र, गोवा और दादरा-दमन को कवर करता है।'), ('The Guwahati High Court originally had common jurisdiction over all seven northeastern states; today it has jurisdiction over how many states?', 'गुवाहाटी उच्च न्यायालय वर्तमान में पूर्वोत्तर के कुल कितने राज्यों का साझा उच्च न्यायालय है?', '4 States (Assam, Nagaland, Mizoram, and Arunachal Pradesh)', '4 राज्य (असम, नागालैंड, मिजोरम एवं अरुणाचल प्रदेश)', ['7 States', '3 States', '5 States'], ['7 राज्य', '3 राज्य', '5 राज्य'], 'After separate High Courts were set up for Manipur, Meghalaya, and Tripura in 2013, Guwahati HC retains jurisdiction over Assam, Nagaland, Mizoram, and Arunachal.', '2013 में मणिपुर, मेघालय और त्रिपुरा के अलग हाईकोर्ट बनने के बाद गुवाहाटी हाईकोर्ट अब 4 राज्यों (असम, नागालैंड, मिजोरम, अरुणाचल) का साझा कोर्ट है।'), ('Who appoints the Judges of the High Courts under Article 217?', 'अनुच्छेद 217 के अनुसार उच्च न्यायालयों के न्यायाधीशों की नियुक्ति किसके द्वारा की जाती है?', 'The President of India (after consultation with CJI, Governor of State, and Chief Justice of that High Court)', 'भारत के राष्ट्रपति द्वारा (CJI, राज्य के राज्यपाल तथा उस हाईकोर्ट के मुख्य न्यायाधीश से परामर्श के बाद)', ['The Governor of the State alone', 'The Chief Minister of the State', 'The Chief Justice of High Court alone'], ['केवल राज्य के राज्यपाल द्वारा', 'राज्य के मुख्यमंत्री द्वारा', 'केवल हाईकोर्ट के मुख्य न्यायाधीश द्वारा'], 'High Court judges are appointed by the President under the Collegium System (CJI + 2 seniormost SC judges consulting the Governor and HC Chief Justice).', 'हाईकोर्ट के जजों की नियुक्ति राष्ट्रपति द्वारा मुख्य न्यायाधीश (CJI) और राज्यपाल से सलाह के बाद कॉलेजियम की सिफारिश पर की जाती है।'), ('Who administers the Oath of Office to a newly appointed High Court Judge under Article 219?', 'अनुच्छेद 219 के तहत उच्च न्यायालय के नवनियुक्त न्यायाधीश को पद की शपथ कौन दिलाते हैं?', 'The Governor of the State (or person appointed by him)', 'संबंधित राज्य के राज्यपाल (या उनके द्वारा नियुक्त व्यक्ति)', ['The Chief Justice of India', 'The President of India', 'The Chief Minister of the State'], ['भारत के मुख्य न्यायाधीश', 'भारत के राष्ट्रपति', 'राज्य के मुख्यमंत्री'], 'Although appointed by the President, a High Court judge takes oath before the Governor of the concerned State under the Third Schedule.', 'नियुक्ति राष्ट्रपति करते हैं, किंतु हाईकोर्ट के जज को शपथ संबंधित राज्य के राज्यपाल द्वारा दिलाई जाती है।'), ('Under Article 222, who has the power to transfer a Judge from one High Court to another?', 'अनुच्छेद 222 के अनुसार किसी न्यायाधीश का एक उच्च न्यायालय से दूसरे उच्च न्यायालय में स्थानांतरण (Transfer) कौन करता है?', 'The President of India (after consultation with the Chief Justice of India)', 'भारत के राष्ट्रपति (भारत के मुख्य न्यायाधीश से परामर्श के पश्चात)', ['The Governors of both States jointly', 'The Union Law Minister', 'The Supreme Court Bar Association'], ['दोनों राज्यों के राज्यपाल संयुक्त रूप से', 'केंद्रीय विधि मंत्री', 'सुप्रीम कोर्ट बार एसोसिएशन'], 'Transfers are made by the President on the binding recommendation of the SC Collegium (CJI + 4 seniormost judges plus consulting judges).', 'हाईकोर्ट के जजों का तबादला राष्ट्रपति द्वारा मुख्य न्यायाधीश (CJI) की अध्यक्षता वाले कॉलेजियम की सिफारिश पर किया जाता है।'), ('What is the major difference between writ jurisdiction of Supreme Court (Art 32) and High Courts (Art 226)?', 'अनुच्छेद 32 (सुप्रीम कोर्ट) और अनुच्छेद 226 (हाईकोर्ट) के रिट क्षेत्राधिकार में सबसे बड़ा अंतर क्या है?', 'Supreme Court can issue writs ONLY for Fundamental Rights; High Courts can issue writs for Fundamental Rights AND ordinary legal rights', 'सुप्रीम कोर्ट केवल मूल अधिकारों के लिए रिट जारी कर सकता है; जबकि हाईकोर्ट मूल अधिकारों के साथ-साथ सामान्य कानूनी अधिकारों के लिए भी रिट जारी कर सकता है', ['High Courts cannot issue Habeas Corpus', 'Supreme Court can issue writs only in criminal cases', 'There is no difference'], ['हाईकोर्ट बंदी प्रत्यक्षीकरण नहीं जारी कर सकता', 'सुप्रीम कोर्ट केवल आपराधिक मामलों में रिट देता है', 'दोनों में कोई अंतर नहीं है'], "Article 226 uses the phrase 'for the enforcement of fundamental rights and for any other purpose', giving High Courts wider writ scope.", "अनुच्छेद 226 में 'अन्य किसी प्रयोजन हेतु' शब्द शामिल होने के कारण हाईकोर्ट का रिट क्षेत्र सुप्रीम कोर्ट से अधिक व्यापक है।"), ('Under Article 227, the High Court possesses the power of superintendence over', 'संविधान के अनुच्छेद 227 के तहत उच्च न्यायालय को किसके ऊपर अधीक्षण (Superintendence) की शक्ति प्राप्त है?', 'All subordinate courts and tribunals throughout the territories in relation to which it exercises jurisdiction', 'अपने प्रादेशिक क्षेत्राधिकार के भीतर सभी अधीनस्थ न्यायालयों एवं न्यायाधिकरणों (Tribunals) पर', ['The State Legislative Assembly', 'The State Council of Ministers', 'Military Armed Forces Courts-Martial'], ['राज्य विधानसभा पर', 'राज्य की मंत्रिपरिषद पर', 'सैन्य अदालत (कोर्ट मार्शल) पर'], 'Article 227 gives High Courts administrative and judicial superintendence over all subordinate district courts and tribunals (except armed forces tribunals).', 'अनुच्छेद 227 हाईकोर्ट को अपने राज्य की सभी निचली अदालतों, फैमिली कोर्ट, लेबर कोर्ट आदि की निगरानी और अधीक्षण की व्यापक शक्ति देता है।'), ('Which Article of the Constitution provides for the appointment of District Judges in States?', 'संविधान का कौन सा अनुच्छेद राज्यों में जिला न्यायाधीशों (District Judges) की नियुक्ति का प्रावधान करता है?', 'Article 233', 'अनुच्छेद 233', ['Article 214', 'Article 226', 'Article 235'], ['अनुच्छेद 214', 'अनुच्छेद 226', 'अनुच्छेद 235'], 'Article 233 provides that appointments, posting, and promotion of district judges shall be made by the Governor in consultation with the High Court.', 'अनुच्छेद 233 के अनुसार जिला जजों की नियुक्ति राज्यपाल द्वारा उच्च न्यायालय के परामर्श से की जाती है।'), ('Under Article 235, the administrative control over district courts and subordinate courts is vested in the', 'अनुच्छेद 235 के अनुसार जिला अदालतों और अन्य अधीनस्थ न्यायालयों पर प्रशासनिक नियंत्रण किसमें निहित है?', 'The High Court of the State', 'राज्य के उच्च न्यायालय (High Court) में', ['The State Law Ministry', 'The State Public Service Commission', 'The District Magistrate'], ['राज्य के विधि मंत्रालय में', 'राज्य लोक सेवा आयोग में', 'जिला मजिस्ट्रेट (DM) में'], 'Article 235 vests complete control over subordinate judicial officers (postings, promotions, disciplinary actions) in the High Court, protecting separation of powers.', 'निचली अदालतों के जजों के तबादले, प्रमोशन और अनुशासन का पूरा नियंत्रण राज्य के हाईकोर्ट के पास होता है, सरकार के पास नहीं।'), ("In which historic judgment of 24 April 1973 did the Supreme Court establish the 'Basic Structure Doctrine'?", "24 अप्रैल 1973 को किस ऐतिहासिक फैसले में सर्वोच्च न्यायालय ने 'मूल ढांचा सिद्धांत' (Basic Structure Doctrine) प्रतिपादित किया था?", 'Kesavananda Bharati v. State of Kerala (1973)', 'केशवानंद भारती बनाम केरल राज्य (1973)', ['Golaknath case (1967)', 'Shankari Prasad case (1951)', 'Sajjan Singh case (1965)'], ['गोलकनाथ मामला (1967)', 'शंकरी प्रसाद मामला (1951)', 'सज्जन सिंह मामला (1965)'], 'A 13-judge bench (largest in Indian history) ruled by a 7:6 majority that Parliament has broad power to amend the Constitution, but CANNOT alter its Basic Structure.', '13 जजों की सबसे बड़ी पीठ ने 7:6 के बहुमत से फैसला दिया कि संसद संविधान में संशोधन कर सकती है, किंतु उसके मूल ढांचे (Basic Structure) को नष्ट नहीं कर सकती।'), ('Who was the Chief Justice of India who headed the historic 13-judge bench in Kesavananda Bharati case?', 'केशवानंद भारती मामले की ऐतिहासिक 13 सदस्यीय संविधान पीठ की अध्यक्षता किस मुख्य न्यायाधीश ने की थी?', 'Chief Justice S.M. Sikri (Sarv Mittra Sikri)', 'मुख्य न्यायाधीश एस.एम. सीकरी (S.M. Sikri)', ['Justice A.N. Ray', 'Justice P.B. Gajendragadkar', 'Justice K. Subba Rao'], ['न्यायमूर्ति ए.एन. रे', 'न्यायमूर्ति गजेंद्रगडकर', 'न्यायमूर्ति के. सुब्बाराव'], 'Chief Justice S.M. Sikri retired on 25 April 1973, one day after delivering the monumental Kesavananda judgment.', 'मुख्य न्यायाधीश सर्व मित्र सीकरी ने अपने कार्यकाल के अंतिम दिन 24 अप्रैल 1973 को यह ऐतिहासिक फैसला सुनाया था।'), ("Which prominent advocate argued the petitioner's case in Kesavananda Bharati, defending the inviolability of Fundamental Rights?", 'केशवानंद भारती मामले में याचिकाकर्ता की ओर से मूल अधिकारों और संविधान के मूल ढांचे की ऐतिहासिक वकालत किस वरिष्ठ अधिवक्ता ने की थी?', 'Nani Ardeshir Palkhivala (Nani Palkhivala)', 'नानी पालकीवाला (Nani Palkhivala)', ['Fali S. Nariman', 'Ram Jethmalani', 'Soli Sorabjee'], ['फली एस. नरीमन', 'राम जेठमलानी', 'सोली सोराबजी'], 'Nani Palkhivala argued brilliantly for 68 days before the 13-judge bench, persuading the court to place judicial limits on parliamentary amending power.', 'महान न्यायविद नानी पालकीवाला ने लगातार 68 दिनों तक जोरदार बहस कर संविधान के मूल ढांचे के सिद्धांत को स्थापित करवाया।'), ('In Minerva Mills v. Union of India (1980), the Supreme Court struck down Section 55 of 42nd Amendment which sought to give Parliament', 'मिनर्वा मिल्स मामले (1980) में सुप्रीम कोर्ट ने 42वें संशोधन की धारा 55 को क्यों रद्द किया, जिसने संसद को क्या शक्ति देने की कोशिश की थी?', 'Unlimited amending power free from any judicial review', 'बिना किसी न्यायिक समीक्षा के असीमित संविधान संशोधन शक्ति', ['Power to increase Supreme Court judge strength', 'Power to create new High Courts', 'Power to dissolve municipal corporations'], ['सुप्रीम कोर्ट के जज बढ़ाने की शक्ति', 'नए हाईकोर्ट बनाने की शक्ति', 'नगर निगमों को भंग करने की शक्ति'], 'The Supreme Court held that Parliament cannot expand its limited amending power under Article 368 into an absolute power to destroy the Constitution.', 'सुप्रीम कोर्ट ने कहा कि संसद को संविधान संशोधन की सीमित शक्ति है; वह स्वयं को संविधान का संहारक (असीमित शक्ति संपन्न) नहीं बना सकती।'), ("In S.R. Bommai v. Union of India (1994), a 9-judge bench ruled that which principles are part of the 'Basic Structure'?", "एस.आर. बोम्मई बनाम भारत संघ (1994) में 9 जजों की पीठ ने किन सिद्धांतों को संविधान का 'मूल ढांचा' घोषित किया?", 'Secularism and Federalism', 'पंथनिरपेक्षता (Secularism) एवं संघवाद (Federalism)', ['Absolute presidential discretion and unitary state', 'Two-party political democracy', 'Monopoly of state industries'], ['राष्ट्रपति का एकाधिकार व एकात्मक राज्य', 'द्विदलीय व्यवस्था', 'सरकारी कंपनियों का एकाधिकार'], 'The court held Secularism and Federalism are basic features; anti-secular actions by a state government justify Article 356 proclamation.', 'बोम्मई मामले में धर्मनिरपेक्षता और संघवाद को संविधान का मूल ढांचा माना गया और अनुच्छेद 356 के दुरुपयोग पर कड़ी न्यायिक शर्तें लगाई गईं।'), ('In L. Chandra Kumar v. Union of India (1997), a 7-judge bench declared that the power of Judicial Review under Articles 32 and 226 is', 'एल. चंद्र कुमार मामले (1997) में 7 जजों की पीठ ने अनुच्छेद 32 और 226 के तहत न्यायिक समीक्षा की शक्ति को क्या माना?', 'An integral and untransgressable part of the Basic Structure of the Constitution', 'संविधान के मूल ढांचे का एक अनिवार्य एवं अनुल्लंघनीय अंग (Part of Basic Structure)', ['A subordinate statutory power that can be excluded by Tribunals', 'Permissible only in tax appeals', 'Applicable only to central ministries'], ['एक सामान्य शक्ति जिसे न्यायाधिकरण हटा सकते हैं', 'केवल कर अपीलों में लागू', 'केवल केंद्रीय मंत्रालयों पर लागू'], 'The Supreme Court held that administrative tribunals (CAT, SAT) are subject to the writ jurisdiction of Division Benches of High Courts.', 'सुप्रीम कोर्ट ने माना कि हाईकोर्ट और सुप्रीम कोर्ट की न्यायिक समीक्षा की शक्ति मूल ढांचा है, जिसे ट्रिब्यूनल बनाकर भी नहीं छीना जा सकता।'), ("What is the concept of 'Curative Petition' in the Supreme Court of India, established in Rupa Ashok Hurra v. Ashok Hurra (2002)?", "रूपा अशोक हुर्रा मामले (2002) में सुप्रीम कोर्ट द्वारा शुरू की गई 'क्युरेटिव पिटीशन' (उपचारात्मक याचिका) क्या है?", 'The final judicial remedy available after a review petition has been dismissed, to cure gross miscarriage of justice or bias', 'पुनर्विचार याचिका (Review) खारिज होने के बाद भी न्याय की गंभीर विफलता या पूर्वाग्रह को दूर करने हेतु उपलब्ध अंतिम न्यायिक उपाय', ['An emergency medical petition for ailing prisoners', 'A petition to cure typographical errors in court registry', 'A petition to cancel advocate registration'], ['बीमार कैदियों के इलाज की याचिका', 'टाइपिंग गलतियां सुधारने की याचिका', 'वकील का लाइसेंस रद्द करने की याचिका'], 'A 5-judge bench established that even after review dismissal, a curative petition signed by a Senior Advocate can be heard by CJI and 3 seniormost judges.', 'सुप्रीम कोर्ट में पुनर्विचार याचिका खारिज होने के बाद भी यदि प्राकृतिक न्याय का घोर हनन हुआ हो, तो क्युरेटिव पिटीशन अंतिम उपाय होती है।'), ('Can the Supreme Court of India review its own judgments under Article 137?', "क्या संविधान के अनुच्छेद 137 के तहत सर्वोच्च न्यायालय को अपने ही निर्णयों का 'पुनरावलोकन' (Review) करने की शक्ति प्राप्त है?", 'Yes, subject to provisions of any law made by Parliament or rules under Article 145', 'हां, संसद की विधि या सुप्रीम कोर्ट के नियमों के अधीन अपने पूर्व निर्णयों की समीक्षा कर सकता है', ['No, a Supreme Court judgment can never be revisited', 'Only if directed in writing by the President', 'Only with unanimous vote of Lok Sabha'], ['नहीं, सुप्रीम कोर्ट का फैसला कभी नहीं बदल सकता', 'केवल राष्ट्रपति के लिखित आदेश पर', 'लोकसभा के सर्वसम्मत वोट पर'], 'Article 137 expressly empowers the Supreme Court to review any judgment pronounced or order made by it (e.g. overruling Gopalan in Maneka Gandhi).', 'अनुच्छेद 137 सुप्रीम कोर्ट को अपने पूर्व फैसलों को बदलने या सुधारने (रिव्यू) की पूरी शक्ति देता है।')]

slot_q119_bodies = [('Article 148 of the Constitution of India provides for the independent office of the', 'भारतीय संविधान का अनुच्छेद 148 किस स्वतंत्र संवैधानिक पद का उपबंध करता है?', 'Comptroller and Auditor General of India (CAG / भारत का नियंत्रक एवं महालेखापरीक्षक)', 'भारत के नियंत्रक एवं महालेखापरीक्षक (CAG)', ['Attorney General for India', 'Chief Election Commissioner', 'Finance Commission Chairman'], ['भारत के महान्यायवादी', 'मुख्य चुनाव आयुक्त', 'वित्त आयोग के अध्यक्ष'], 'Dr. Ambedkar described the CAG as the most important officer in the Constitution, guardian of the public purse.', 'डॉ. आंबेडकर ने कैग (CAG) को संविधान का सबसे महत्वपूर्ण अधिकारी और जनता के धन का संरक्षक बताया था।'), ('What is the tenure and retirement age of the Comptroller and Auditor General (CAG) under statutory law?', 'कानून के अनुसार भारत के नियंत्रक एवं महालेखापरीक्षक (CAG) का कार्यकाल और सेवानिवृत्ति आयु कितनी होती है?', '6 Years or up to 65 Years of age, whichever is earlier', '6 वर्ष या 65 वर्ष की आयु, जो भी पहले हो (6 Years or 65 Years)', ['5 Years or up to 65 Years of age', '6 Years or up to 62 Years of age', '5 Years or up to 70 Years of age'], ['5 वर्ष या 65 वर्ष की आयु', '6 वर्ष या 62 वर्ष की आयु', '5 वर्ष या 70 वर्ष की आयु'], 'Under the CAG (Duties, Powers and Conditions of Service) Act 1971, the CAG holds office for 6 years or until age 65.', 'कैग का कार्यकाल 6 वर्ष अथवा 65 वर्ष की आयु तक होता है।'), ('How can the Comptroller and Auditor General (CAG) be removed from office under Article 148(1)?', 'अनुच्छेद 148(1) के अनुसार नियंत्रक एवं महालेखापरीक्षक (CAG) को पद से कैसे हटाया जा सकता है?', 'In like manner and on like grounds as a Judge of the Supreme Court (proved misbehaviour or incapacity by special majority in Parliament)', 'उसी रीति से और उन्हीं आधारों पर जैसे सर्वोच्च न्यायालय के न्यायाधीश को हटाया जाता है (संसद में विशेष बहुमत द्वारा)', ['By presidential decree on the advice of Prime Minister alone', 'By a resolution of Lok Sabha by simple majority', 'By the Finance Minister on misconduct charges'], ['प्रधानमंत्री की सलाह पर राष्ट्रपति के आदेश से', 'लोकसभा के साधारण बहुमत से', 'वित्त मंत्री के आदेश पर'], 'To guarantee complete independence, the CAG enjoys security of tenure identical to a Supreme Court judge.', 'कैग की स्वतंत्रता सुनिश्चित करने के लिए उन्हें सुप्रीम कोर्ट के जज की तरह संसद के विशेष बहुमत से ही हटाया जा सकता है।'), ('Under Article 148(4), is the CAG eligible for further office under the Government of India or the Government of any State after retirement?', 'अनुच्छेद 148(4) के अनुसार क्या कैग (CAG) सेवानिवृत्ति के पश्चात भारत सरकार या राज्य सरकार के अधीन किसी पद के पात्र होते हैं?', 'No, strictly ineligible for further office under the Union or State governments', 'नहीं, केंद्र या राज्य सरकार के अधीन किसी भी पद पर पुनः नियुक्ति के लिए पूर्णतः अपात्र होते हैं', ['Yes, can be appointed as State Governor', 'Yes, can become an ambassador to foreign nations', 'Eligible after a cooling-off period of two years'], ['हां, राज्यपाल बन सकते हैं', 'हां, राजदूत बन सकते हैं', '2 साल बाद पात्र होते हैं'], 'Article 148(4) ensures impartiality by disqualifying the CAG from holding any post under the Union or States after demitting office.', 'अनुच्छेद 148(4) के अनुसार कैग पद से हटने के बाद केंद्र या राज्य सरकार में कोई अन्य पद धारण नहीं कर सकते।'), ('Under Article 151, to whom does the CAG submit his annual audit reports relating to the accounts of the Union?', 'अनुच्छेद 151 के अनुसार कैग संघ के खातों से संबंधित अपनी वार्षिक ऑडिट रिपोर्ट किसे सौंपते हैं?', 'The President of India (who causes them to be laid before each House of Parliament)', 'भारत के राष्ट्रपति को (जो उन्हें संसद के प्रत्येक सदन के समक्ष रखवाते हैं)', ['The Union Finance Minister', 'The Speaker of the Lok Sabha directly', 'The Public Accounts Committee Chairman'], ['केंद्रीय वित्त मंत्री को', 'सीधे लोकसभा अध्यक्ष को', 'लोक लेखा समिति के अध्यक्ष को'], 'The CAG submits Union reports to the President (placed in Parliament) and State reports to Governors (placed in State Legislatures).', 'कैग अपनी रिपोर्ट राष्ट्रपति को देते हैं, जो उसे संसद में रखवाते हैं; जहां पीएसी (PAC) इसकी जांच करती है।'), ('Article 324 of the Constitution provides for the superintendence, direction, and control of elections to be vested in an', 'संविधान का अनुच्छेद 324 निर्वाचनों के अधीक्षण, निदेशन और नियंत्रण की शक्ति किसमें निहित करता है?', 'Election Commission of India (ECI / भारत निर्वाचन आयोग)', 'भारत निर्वाचन आयोग (Election Commission of India)', ['Union Ministry of Law and Justice', 'National Electoral Council', 'Delimitation Commission of India'], ['केंद्रीय विधि एवं न्याय मंत्रालय में', 'राष्ट्रीय निर्वाचन परिषद में', 'भारत के परिसीमन आयोग में'], 'Article 324 vests all superintendence, direction, and control of elections to Parliament, State Legislatures, and President/VP in the ECI.', 'अनुच्छेद 324 संसद, राज्य विधानमंडलों, राष्ट्रपति एवं उपराष्ट्रपति के चुनावों के संचालन हेतु निर्वाचन आयोग की स्थापना करता है।'), ('Does the Election Commission of India conduct elections to local Panchayats and Municipalities?', 'क्या भारत निर्वाचन आयोग (ECI) स्थानीय पंचायतों और नगरपालिकाओं के चुनाव भी आयोजित करता है?', 'No, local body elections are conducted exclusively by State Election Commissions under Articles 243K and 243ZA', "नहीं, स्थानीय निकायों के चुनाव अनु. 243ट एवं 243य क के तहत स्वतंत्र 'राज्य निर्वाचन आयोग' कराते हैं", ['Yes, ECI conducts all elections from Panchayat to Parliament', 'ECI conducts elections only in Union Territory Panchayats', 'Conducted jointly by ECI and State Home Department'], ['हां, पंचायत से संसद तक सभी चुनाव कराता है', 'केवल केंद्र शासित प्रदेशों में कराता है', 'गृह विभाग के साथ मिलकर कराता है'], 'Local body elections are strictly the constitutional domain of the State Election Commission (SEC) created by the 73rd and 74th Amendments.', 'पंचायतों और नगरपालिकाओं के चुनाव कराने का दायित्व राज्यों के स्वतंत्र राज्य निर्वाचन आयोग (SEC) का होता है, ECI का नहीं।'), ('What is the current composition of the Election Commission of India?', 'वर्तमान समय में भारत निर्वाचन आयोग की संरचना क्या है?', 'Chief Election Commissioner (CEC) and 2 Election Commissioners (multi-member body)', 'मुख्य चुनाव आयुक्त (CEC) तथा 2 अन्य चुनाव आयुक्त (तीन सदस्यीय निकाय)', ['Single Chief Election Commissioner only', 'CEC and 4 Election Commissioners', '5 Full-time Election Commissioners'], ['केवल एक मुख्य चुनाव आयुक्त', 'CEC एवं 4 चुनाव आयुक्त', '5 पूर्णकालिक चुनाव आयुक्त'], 'Made a multi-member commission permanently on 1 October 1993, consisting of the CEC and two Election Commissioners with equal voting power.', '1 अक्टूबर 1993 से चुनाव आयोग स्थायी रूप से तीन सदस्यीय निकाय (1 मुख्य चुनाव आयुक्त + 2 चुनाव आयुक्त) बन गया है।'), ('What is the tenure and retirement age of the Chief Election Commissioner and Election Commissioners?', 'मुख्य चुनाव आयुक्त और अन्य चुनाव आयुक्तों का कार्यकाल और सेवानिवृत्ति आयु कितनी होती है?', '6 Years or up to 65 Years of age, whichever is earlier', '6 वर्ष या 65 वर्ष की आयु, जो भी पहले हो (6 Years or 65 Years)', ['5 Years or up to 65 Years of age', '6 Years or up to 62 Years of age', '5 Years or up to 70 Years of age'], ['5 वर्ष या 65 वर्ष की आयु', '6 वर्ष या 62 वर्ष की आयु', '5 वर्ष या 70 वर्ष की आयु'], 'The CEC and Election Commissioners hold office for 6 years or until age 65, enjoying status and salary equal to Supreme Court judges.', 'चुनाव आयुक्तों का कार्यकाल 6 वर्ष अथवा 65 वर्ष की आयु तक होता है; उन्हें सुप्रीम कोर्ट के जजों के समान दर्जा मिलता है।'), ('Under the second proviso to Article 324(5), how can the Chief Election Commissioner (CEC) be removed from office?', 'अनुच्छेद 324(5) के अनुसार मुख्य चुनाव आयुक्त (CEC) को पद से कैसे हटाया जा सकता है?', 'In like manner and on like grounds as a Judge of the Supreme Court', 'उसी रीति से और उन्हीं आधारों पर जैसे सर्वोच्च न्यायालय के न्यायाधीश को हटाया जाता है', ['By the President on the advice of the Prime Minister alone', 'By a resolution passed by Lok Sabha alone', 'By the Union Law Minister for dereliction of duty'], ['प्रधानमंत्री की सलाह पर सीधे राष्ट्रपति द्वारा', 'केवल लोकसभा के प्रस्ताव द्वारा', 'विधि मंत्री के आदेश पर'], 'The CEC enjoys security of tenure like a Supreme Court judge; other Election Commissioners can be removed by the President on the recommendation of the CEC.', 'मुख्य चुनाव आयुक्त को केवल संसद के विशेष बहुमत से महाभियोग की तरह हटाया जा सकता है; अन्य आयुक्तों को CEC की सिफारिश पर हटाया जा सकता है।'), ('In Anoop Baranwal v. Union of India (2023), a 5-judge Constitution Bench held that the selection committee for CEC and ECs should consist of', 'अनूप बरनवाल मामले (2023) में सुप्रीम कोर्ट की 5 जजों की पीठ ने चुनाव आयुक्तों के चयन पैनल में किन्हें शामिल करने का आदेश दिया था?', 'Prime Minister, Leader of Opposition in Lok Sabha, and the Chief Justice of India', 'प्रधानमंत्री, लोकसभा में विपक्ष के नेता, तथा भारत के मुख्य न्यायाधीश (CJI)', ['Prime Minister, Home Minister, and Law Minister', 'President, Vice-President, and Speaker', 'Chief Justice of India and two seniormost judges'], ['प्रधानमंत्री, गृह मंत्री एवं विधि मंत्री', 'राष्ट्रपति, उपराष्ट्रपति एवं अध्यक्ष', 'मुख्य न्यायाधीश एवं दो वरिष्ठ जज'], 'The Supreme Court ruled that until Parliament passed a law, the committee should include the PM, LoP, and CJI to ensure neutrality.', 'सुप्रीम कोर्ट ने निष्पक्षता हेतु प्रधानमंत्री, विपक्ष के नेता और मुख्य न्यायाधीश (CJI) की तीन सदस्यीय चयन समिति का आदेश दिया था।'), ('Who was the first Chief Election Commissioner of independent India?', 'स्वतंत्र भारत के पहले मुख्य चुनाव आयुक्त (CEC) कौन थे?', 'Sukumar Sen (supervised 1951-52 and 1957 general elections)', 'सुकुमार सेन (Sukumar Sen)', ['K.V.K. Sundaram', 'S.P. Sen Verma', 'T.N. Seshan'], ['के.वी.के. सुंदरम', 'एस.पी. सेन वर्मा', 'टी.एन. शेषन'], "Sukumar Sen (ICS) served as CEC from 1950 to 1958, conducting India's first two mammoth democratic general elections.", 'सुकुमार सेन भारत के पहले मुख्य चुनाव आयुक्त थे जिन्होंने 1951-52 के पहले आम चुनावों का ऐतिहासिक सफल आयोजन किया।'), ('Who was the only female Chief Election Commissioner of India to date?', 'भारत की अब तक की एकमात्र महिला मुख्य चुनाव आयुक्त कौन रही हैं?', 'V.S. Ramadevi (served in Nov-Dec 1990)', 'वी.एस. रमादेवी (V.S. Ramadevi)', ['Fathima Beevi', 'Leila Seth', 'Anna Chandy'], ['फातिमा बीवी', 'लीला सेठ', 'अन्ना चांडी'], 'V.S. Ramadevi served as CEC from 26 November 1990 to 11 December 1990 before T.N. Seshan took office.', 'वी.एस. रमादेवी 1990 में भारत की पहली और एकमात्र महिला मुख्य चुनाव आयुक्त बनी थीं।'), ('Article 315 of the Constitution provides for the establishment of a', 'संविधान का अनुच्छेद 315 किसके गठन का प्रावधान करता है?', 'Union Public Service Commission (UPSC) and State Public Service Commissions (SPSCs)', 'संघ लोक सेवा आयोग (UPSC) तथा राज्य लोक सेवा आयोगों (SPSCs) का', ['Central Vigilance Commission', 'Staff Selection Commission', 'National Recruitment Agency'], ['केंद्रीय सतर्कता आयोग', 'कर्मचारी चयन आयोग (SSC)', 'राष्ट्रीय भर्ती एजेंसी'], 'Article 315 establishes UPSC for the Union and a State PSC for each State (or a Joint PSC for two or more states under Art 315(2)).', 'अनुच्छेद 315 केंद्र के लिए संघ लोक सेवा आयोग (UPSC) और राज्यों के लिए राज्य लोक सेवा आयोग (जैसे BPSC) का गठन करता है।'), ('Under Article 316, what is the term of office and retirement age of the Chairman and members of the UPSC?', 'अनुच्छेद 316 के अनुसार UPSC के अध्यक्ष और सदस्यों का कार्यकाल और सेवानिवृत्ति आयु कितनी होती है?', '6 Years or up to 65 Years of age, whichever is earlier', '6 वर्ष या 65 वर्ष की आयु, जो भी पहले हो (6 Years or 65 Years)', ['5 Years or up to 65 Years of age', '6 Years or up to 62 Years of age', '5 Years or up to 62 Years of age'], ['5 वर्ष या 65 वर्ष की आयु', '6 वर्ष या 62 वर्ष की आयु', '5 वर्ष या 62 वर्ष की आयु'], 'UPSC members serve for 6 years or until age 65; State PSC members serve for 6 years or until age 62.', 'UPSC के सदस्य 6 वर्ष या 65 वर्ष की आयु तक पद पर रहते हैं (जबकि राज्य लोक सेवा आयोग में 62 वर्ष की सीमा है)।'), ('Under Article 317, how can the Chairman or a member of the UPSC be removed from office on grounds of misbehaviour?', 'अनुच्छेद 317 के अनुसार कदाचार के आधार पर UPSC के अध्यक्ष या सदस्य को कैसे हटाया जा सकता है?', 'By the President, after the Supreme Court on a reference conducts an inquiry and recommends removal', 'राष्ट्रपति द्वारा, सर्वोच्च न्यायालय द्वारा जांच किए जाने और हटाने की सिफारिश किए जाने के बाद', ['By impeachment resolution in Parliament', 'By the Prime Minister on Cabinet resolution', 'By the Central Vigilance Commissioner'], ['संसद में महाभियोग प्रस्ताव द्वारा', 'कैबिनेट प्रस्ताव पर प्रधानमंत्री द्वारा', 'केंद्रीय सतर्कता आयुक्त द्वारा'], 'Under Article 317(1), the President refers the matter to the Supreme Court; the SC inquiry finding is BINDING on the President.', 'राष्ट्रपति मामले को सुप्रीम कोर्ट भेजते हैं; सुप्रीम कोर्ट की जांच रिपोर्ट राष्ट्रपति पर बाध्यकारी होती है।'), ('Under Article 280 of the Constitution, who constitutes the Finance Commission of India, and at what interval?', 'संविधान के अनुच्छेद 280 के अनुसार वित्त आयोग (Finance Commission) का गठन कौन और कितने अंतराल पर करता है?', 'The President of India, at the expiration of every fifth year (or earlier)', 'भारत के राष्ट्रपति द्वारा, प्रत्येक 5 वर्ष की समाप्ति पर (या आवश्यकतानुसार उससे पहले)', ['The Union Finance Minister every year', 'The Parliament of India every ten years', 'The NITI Aayog every three years'], ['केंद्रीय वित्त मंत्री द्वारा प्रति वर्ष', 'संसद द्वारा हर 10 वर्ष में', 'नीति आयोग द्वारा हर 3 वर्ष में'], 'Article 280 mandates the President to constitute a Finance Commission every 5 years to recommend tax devolution between Union and States.', 'अनुच्छेद 280 के तहत राष्ट्रपति हर 5 वर्ष पर केंद्र और राज्यों के बीच करों के बंटवारे हेतु वित्त आयोग का गठन करते हैं।'), ('What is the composition of the Finance Commission under Article 280(1)?', 'अनुच्छेद 280(1) के अनुसार वित्त आयोग की संरचना क्या होती है?', 'A Chairman and 4 other Members (total 5 members)', 'एक अध्यक्ष तथा 4 अन्य सदस्य (कुल 5 सदस्य)', ['A Chairman and 2 Members', 'A Chairman and 6 Members', 'A Chairman and 10 Members'], ['एक अध्यक्ष एवं 2 सदस्य', 'एक अध्यक्ष एवं 6 सदस्य', 'एक अध्यक्ष एवं 10 सदस्य'], 'Under the Finance Commission (Miscellaneous Provisions) Act 1951, the Commission consists of a Chairman and 4 members appointed by the President.', 'वित्त आयोग में राष्ट्रपति द्वारा नियुक्त एक अध्यक्ष और 4 अन्य सदस्य (कुल 5 सदस्य) होते हैं।'), ('Who was the Chairman of the First Finance Commission of India constituted in 1951?', '1951 में गठित भारत के प्रथम वित्त आयोग के अध्यक्ष कौन थे?', 'K.C. Neogy (Kshitish Chandra Neogy)', 'के.सी. नियोगी (K.C. Neogy)', ['K. Santhanam', 'A.K. Chanda', 'Dr. P.V. Rajamannar'], ['के. संथानम', 'ए.के. चंदा', 'डॉ. पी.वी. राजमन्नार'], 'K.C. Neogy headed the 1st Finance Commission (1952-1957).', 'के.सी. नियोगी प्रथम वित्त आयोग के अध्यक्ष थे।'), ('Who served as the Chairman of the 15th Finance Commission of India (for 2021-2026)?', '15वें वित्त आयोग (2021-2026) के अध्यक्ष कौन थे?', 'N.K. Singh (Nand Kishore Singh)', 'एन.के. सिंह (N.K. Singh)', ['Dr. Y.V. Reddy', 'Dr. Vijay Kelkar', 'Dr. C. Rangarajan'], ['डॉ. वाई.वी. रेड्डी', 'डॉ. विजय केलकर', 'डॉ. सी. रंगराजन'], 'N.K. Singh chaired the 15th Finance Commission, which recommended 41% tax devolution to states (1% adjusted for J&K UT).', 'एन.के. सिंह 15वें वित्त आयोग के अध्यक्ष थे, जिसने राज्यों को केंद्रीय करों का 41% हिस्सा देने की सिफारिश की।'), ('Who is the Chairman of the 16th Finance Commission constituted by the Government in December 2023?', 'दिसंबर 2023 में गठित 16वें वित्त आयोग के अध्यक्ष कौन नियुक्त किए गए हैं?', 'Dr. Arvind Panagariya (former Vice-Chairman of NITI Aayog)', 'डॉ. अरविंद पनगढ़िया (Dr. Arvind Panagariya)', ['N.K. Singh', 'Bibek Debroy', 'Raghuram Rajan'], ['एन.के. सिंह', 'विवेक देबरॉय', 'रघुराम राजन'], 'Dr. Arvind Panagariya was appointed Chairman of the 16th Finance Commission in Dec 2023 to submit recommendations for 2026-2031.', 'नीति आयोग के पूर्व उपाध्यक्ष डॉ. अरविंद पनगढ़िया को 16वें वित्त आयोग का अध्यक्ष नियुक्त किया गया है।'), ('Under Article 338, which constitutional body oversees safeguards for Scheduled Castes?', 'संविधान के अनुच्छेद 338 के तहत अनुसूचित जातियों के संवैधानिक संरक्षण की निगरानी कौन सा आयोग करता है?', 'National Commission for Scheduled Castes (NCSC)', 'राष्ट्रीय अनुसूचित जाति आयोग (NCSC)', ['National Human Rights Commission', 'Minorities Commission', 'Social Justice Tribunal'], ['राष्ट्रीय मानवाधिकार आयोग', 'अल्पसंख्यक आयोग', 'सामाजिक न्याय अधिकरण'], 'Originally a joint commission, the 89th Amendment 2003 bifurcated it into NCSC (Art 338) and NCST (Art 338A).', '89वें संशोधन (2003) द्वारा अनुच्छेद 338 के तहत राष्ट्रीय अनुसूचित जाति आयोग का अलग गठन किया गया।'), ('Article 338A provides for which separate constitutional body for Scheduled Tribes?', 'अनुच्छेद 338क के तहत अनुसूचित जनजातियों के लिए किस अलग संवैधानिक आयोग की स्थापना की गई है?', 'National Commission for Scheduled Tribes (NCST)', 'राष्ट्रीय अनुसूचित जनजाति आयोग (NCST)', ['Tribal Development Advisory Council', 'National Forest Rights Authority', 'Backward Classes Commission'], ['जनजातीय सलाहकार परिषद', 'राष्ट्रीय वन अधिकार प्राधिकरण', 'पिछड़ा वर्ग आयोग'], 'Article 338A was inserted by the 89th Amendment Act 2003, creating a dedicated constitutional commission for Scheduled Tribes.', '89वें संशोधन (2003) द्वारा अनुच्छेद 338क जोड़कर राष्ट्रीय अनुसूचित जनजाति आयोग बनाया गया।'), ('Which Constitutional Amendment Act granted constitutional status to the National Commission for Backward Classes (NCBC) under Article 338B?', 'किस संविधान संशोधन अधिनियम द्वारा अनुच्छेद 338ख जोड़कर राष्ट्रीय पिछड़ा वर्ग आयोग (NCBC) को संवैधानिक दर्जा दिया गया?', '102nd Constitutional Amendment Act, 2018', '102वां संविधान संशोधन अधिनियम (2018)', ['101st Amendment Act, 2016', '103rd Amendment Act, 2019', '99th Amendment Act, 2014'], ['101वां संशोधन (2016)', '103वां संशोधन (2019)', '99वां संशोधन (2014)'], 'The 102nd Amendment Act 2018 elevated NCBC from a statutory body to a full constitutional body under Article 338B.', '102वें संशोधन (2018) द्वारा राष्ट्रीय पिछड़ा वर्ग आयोग को अनुच्छेद 338ख के तहत संवैधानिक दर्जा प्रदान किया गया।'), ('Is NITI Aayog (National Institution for Transforming India) a constitutional body, a statutory body, or an extra-constitutional body?', 'नीति आयोग (NITI Aayog) किस प्रकार की संस्था है?', 'A non-constitutional, non-statutory body created by an Executive Resolution of the Union Cabinet', 'गैर-संवैधानिक एवं गैर-वैधानिक संस्था (मंत्रिमंडल के कार्यपालिका प्रस्ताव द्वारा स्थापित)', ['A constitutional body under Article 300B', 'A statutory body created by an Act of Parliament', 'A judicial advisory tribunal'], ['अनुच्छेद 300ख के तहत संवैधानिक संस्था', 'संसद के कानून द्वारा बनी वैधानिक संस्था', 'न्यायिक सलाहकार न्यायाधिकरण'], 'NITI Aayog was established on 1 January 2015 by a cabinet resolution replacing the 65-year-old Planning Commission.', 'नीति आयोग का गठन 1 जनवरी 2015 को केंद्रीय मंत्रिमंडल के एक साधारण प्रस्ताव द्वारा योजना आयोग के स्थान पर किया गया था।'), ('Who serves as the Ex-Officio Chairman of NITI Aayog?', 'नीति आयोग के पदेन अध्यक्ष (Ex-Officio Chairman) कौन होते हैं?', 'The Prime Minister of India', 'भारत के प्रधानमंत्री (Prime Minister of India)', ['The Union Finance Minister', 'The President of India', 'The Chief Economic Advisor'], ['केंद्रीय वित्त मंत्री', 'भारत के राष्ट्रपति', 'मुख्य आर्थिक सलाहकार'], 'The Prime Minister of India is the ex-officio Chairperson of NITI Aayog.', 'भारत के प्रधानमंत्री नीति आयोग के पदेन अध्यक्ष होते हैं।'), ('Is the National Human Rights Commission (NHRC) a constitutional body or a statutory body?', 'राष्ट्रीय मानवाधिकार आयोग (NHRC) किस प्रकार का निकाय है?', 'A Statutory Body established under the Protection of Human Rights Act, 1993', 'एक वैधानिक निकाय (संसद के मानवाधिकार संरक्षण अधिनियम, 1993 द्वारा स्थापित)', ['A constitutional body under Article 350', 'A private autonomous NGO', 'A wing of the Supreme Court Registry'], ['अनुच्छेद 350 के तहत संवैधानिक निकाय', 'एक निजी गैर-सरकारी संगठन (NGO)', 'सुप्रीम कोर्ट रजिस्ट्री का अंग'], 'NHRC was created in October 1993 by an Act of Parliament (Protection of Human Rights Act, 1993); it is not mentioned in the Constitution.', 'राष्ट्रीय मानवाधिकार आयोग संविधान में नहीं है; यह 1993 में संसद द्वारा कानून बनाकर स्थापित एक वैधानिक संस्था है।'), ('Who heads the Selection Committee for the appointment of the Chairperson and Members of the National Human Rights Commission (NHRC)?', 'राष्ट्रीय मानवाधिकार आयोग (NHRC) के अध्यक्ष व सदस्यों की नियुक्ति हेतु चयन समिति की अध्यक्षता कौन करता है?', 'The Prime Minister of India', 'भारत के प्रधानमंत्री (Prime Minister of India)', ['The Chief Justice of India', 'The President of India', 'The Union Home Minister'], ['भारत के मुख्य न्यायाधीश', 'भारत के राष्ट्रपति', 'केंद्रीय गृह मंत्री'], 'The 6-member committee consists of PM (Chair), Speaker Lok Sabha, Deputy Chairman Rajya Sabha, Leaders of Opposition in both Houses, and Union Home Minister.', 'प्रधान मंत्री की अध्यक्षता वाली 6 सदस्यीय समिति (जिसमें गृह मंत्री, स्पीकर, डिप्टी चेयरमैन और दोनों सदनों के विपक्ष के नेता होते हैं) सिफारिश करती है।'), ('Under Article 352 of the Constitution, on what three grounds can the President proclaim a National Emergency?', 'संविधान के अनुच्छेद 352 के तहत राष्ट्रपति किन तीन आधारों पर राष्ट्रीय आपातकाल की घोषणा कर सकते हैं?', 'War, External Aggression, or Armed Rebellion (सशस्त्र विद्रोह)', 'युद्ध, बाह्य आक्रमण, अथवा सशस्त्र विद्रोह (Armed Rebellion)', ['Internal disturbance, economic crisis, general strikes', 'Political corruption, state elections, mass rallies', 'Foreign debt default, inflation, famine'], ['आंतरिक अशांति, आर्थिक संकट, हड़ताल', 'राजनीतिक भ्रष्टाचार, चुनाव, रैलियां', 'विदेशी कर्ज, महंगाई, अकाल'], "The 44th Amendment Act 1978 substituted 'Armed Rebellion' for the ambiguous phrase 'Internal Disturbance'.", "44वें संशोधन (1978) द्वारा 'आंतरिक अशांति' शब्द को हटाकर उसके स्थान पर 'सशस्त्र विद्रोह' (Armed Rebellion) शब्द जोड़ा गया।"), ("Which Constitutional Amendment Act replaced the term 'Internal Disturbance' with 'Armed Rebellion' in Article 352?", "किस संविधान संशोधन अधिनियम द्वारा अनुच्छेद 352 में 'आंतरिक अशांति' के स्थान पर 'सशस्त्र विद्रोह' शब्द प्रतिस्थापित किया गया?", '44th Constitutional Amendment Act, 1978', '44वां संविधान संशोधन अधिनियम (1978)', ['42nd Amendment Act, 1976', '52nd Amendment Act, 1985', '38th Amendment Act, 1975'], ['42वां संशोधन (1976)', '52वां संशोधन (1985)', '38वां संशोधन (1975)'], "To prevent misuse (like the 1975 Emergency declared on 'internal disturbance'), the 44th Amendment restricted grounds to war, external aggression, or armed rebellion.", "1975 के दुरुपयोग को रोकने के लिए 44वें संशोधन (1978) ने 'आंतरिक गड़बड़ी' शब्द हटाकर 'सशस्त्र विद्रोह' अनिवार्य किया।"), ('Under Article 352(3), can the President declare a National Emergency on the oral advice of the Prime Minister alone?', 'अनुच्छेद 352(3) के अनुसार क्या राष्ट्रपति केवल प्रधानमंत्री की मौखिक सलाह पर राष्ट्रीय आपातकाल लगा सकते हैं?', 'No, only after receiving the WRITTEN decision of the Union Cabinet (PM + Cabinet rank ministers)', 'नहीं, केवल केंद्रीय मंत्रिमंडल (कैबिनेट) के लिखित निर्णय की सूचना मिलने के बाद ही', ["Yes, PM's telephonic verbal request is sufficient", 'Yes, if endorsed by the Home Minister', 'Only after Supreme Court gives prior approval'], ['हां, प्रधानमंत्री का फोन ही काफी है', 'हां, यदि गृह मंत्री सहमत हों', 'केवल सुप्रीम कोर्ट की पूर्व अनुमति से'], 'Added by the 44th Amendment in 1978: the President can issue a proclamation only upon the written recommendation of the Union Cabinet.', '44वें संशोधन ने नियम बनाया कि पूरे मंत्रिमंडल (कैबिनेट) की लिखित सिफारिश के बिना राष्ट्रपति आपातकाल नहीं लगा सकते।'), ('Within what period must a Proclamation of National Emergency under Article 352 be approved by both Houses of Parliament?', 'अनुच्छेद 352 के तहत राष्ट्रीय आपातकाल की घोषणा को संसद के दोनों सदनों द्वारा कितने समय के भीतर अनुमोदित किया जाना अनिवार्य है?', 'Within 1 Month (reduced from 2 months by 44th Amendment, 1978)', '1 माह के भीतर (44वें संशोधन द्वारा 2 माह से घटाकर 1 माह किया गया)', ['Within 2 Months', 'Within 14 Days', 'Within 6 Months'], ['2 माह के भीतर', '14 दिन के भीतर', '6 माह के भीतर'], 'Originally 2 months, reduced to 1 month by the 44th Amendment; requires approval by a special majority in both Houses.', 'आपातकाल जारी होने के 1 महीने के अंदर संसद के दोनों सदनों से विशेष बहुमत से पास होना जरूरी है।'), ('What majority in Parliament is required to approve or extend a National Emergency under Article 352?', 'राष्ट्रीय आपातकाल के अनुमोदन अथवा विस्तार के लिए संसद में किस बहुमत की आवश्यकता होती है?', 'A Special Majority (majority of total membership of each House AND not less than 2/3rds of members present and voting)', 'विशेष बहुमत (सदन की कुल सदस्य संख्या का बहुमत तथा उपस्थित व मतदान करने वालों का 2/3 बहुमत)', ['Simple majority of members present and voting', 'Unanimous vote of Lok Sabha', 'Absolute majority without debate'], ['उपस्थित सदस्यों का साधारण बहुमत', 'लोकसभा की सर्वसम्मति', 'बिना बहस पूर्ण बहुमत'], 'The 44th Amendment introduced the requirement of a Special Majority to approve and extend emergency every 6 months.', '44वें संशोधन के बाद आपातकाल को संसद द्वारा विशेष बहुमत से ही मंजूरी दी जा सकती है।'), ('How many times has a National Emergency been proclaimed in India under Article 352?', 'भारत में अब तक कुल कितनी बार अनुच्छेद 352 के तहत राष्ट्रीय आपातकाल की घोषणा की गई है?', '3 Times (1962 Chinese aggression, 1971 Indo-Pak war, and 1975 Internal Disturbance)', '3 बार (1962 भारत-चीन युद्ध, 1971 भारत-पाक युद्ध, एवं 1975 आंतरिक अशांति)', ['Only Once (1975)', '2 Times (1962 and 1971)', '5 Times'], ['केवल एक बार (1975)', '2 बार (1962 और 1971)', '5 बार'], 'Proclaimed 3 times: October 1962 (Chinese aggression, revoked 1968), December 1971 (Bangladesh Liberation War), and June 1975 (revoked March 1977).', 'भारत में तीन बार राष्ट्रीय आपातकाल लगा: 1962 में चीन युद्ध, 1971 में पाकिस्तान युद्ध और 1975 में आंतरिक अशांति के नाम पर।'), ('Under Article 358, which Fundamental Right is automatically suspended across India as soon as an emergency is proclaimed on grounds of war or external aggression?', 'अनुच्छेद 358 के अनुसार युद्ध या बाह्य आक्रमण के आधार पर आपातकाल लगते ही कौन सा मूल अधिकार स्वतः निलंबित हो जाता है?', 'Article 19 (Six Fundamental Freedoms)', 'अनुच्छेद 19 (छह मौलिक स्वतंत्रताएं)', ['Article 14 (Equality)', 'Article 21 (Right to Life)', 'Article 32 (Constitutional Remedies)'], ['अनुच्छेद 14 (समानता)', 'अनुच्छेद 21 (जीवन का अधिकार)', 'अनुच्छेद 32 (संवैधानिक उपचार)'], 'Article 358 automatically suspends Article 19 freedoms during war or external aggression (the 44th Amendment barred suspension during armed rebellion).', 'युद्ध या बाह्य आक्रमण होते ही अनुच्छेद 19 स्वतः स्थगित हो जाता है (किंतु सशस्त्र विद्रोह में यह स्थगित नहीं होता)।'), ('Article 356 of the Constitution deals with the proclamation of', 'संविधान का अनुच्छेद 356 किस प्रावधान से संबंधित है?', "President's Rule (Failure of constitutional machinery in States / राज्य में राष्ट्रपति शासन)", "राष्ट्रपति शासन (राज्य में संवैधानिक तंत्र की विफलता / President's Rule)", ['National Emergency', 'Financial Emergency', 'Martial Law'], ['राष्ट्रीय आपातकाल', 'वित्तीय आपातकाल', 'मार्शल लॉ (सैन्य शासन)'], "Article 356 empowers the President to impose President's Rule if satisfied that governance in a State cannot be carried on in accordance with the Constitution.", 'राज्यपाल की रिपोर्ट पर या स्वतः संतुष्ट होने पर यदि राज्य में संवैधानिक तंत्र विफल हो जाए, तो राष्ट्रपति शासन लगाया जाता है।'), ('Under Article 365, failure of a State to comply with or give effect to lawful directions from the Union Government is deemed to be', 'अनुच्छेद 365 के अनुसार यदि कोई राज्य केंद्र सरकार के वैध निर्देशों का पालन करने में विफल रहता है, तो उसे क्या माना जाएगा?', "Failure of constitutional machinery in the State, empowering President's Rule under Article 356", 'राज्य में संवैधानिक तंत्र की विफलता, जिसके आधार पर अनुच्छेद 356 के तहत राष्ट्रपति शासन लगाया जा सकता है', ['A military declaration of rebellion', 'An economic boycott by the Union', 'Ground for dismissing the Supreme Court'], ['विद्रोह की सैन्य घोषणा', 'केंद्र द्वारा आर्थिक बहिष्कार', 'सुप्रीम कोर्ट को बर्खास्त करने का आधार'], 'Article 365 provides that non-compliance with Union directions allows the President to hold that governance cannot be carried on under the Constitution.', 'यदि राज्य केंद्र के निर्देशों की अवहेलना करे, तो अनुच्छेद 365 के तहत माना जाता है कि राज्य में संविधान विफल हो गया है।'), ("Within what time period must a Proclamation of President's Rule under Article 356 be approved by Parliament?", 'अनुच्छेद 356 के तहत राष्ट्रपति शासन की उद्घोषणा को संसद द्वारा कितने समय के भीतर अनुमोदित किया जाना चाहिए?', 'Within 2 Months by a Simple Majority in each House', '2 माह के भीतर (दोनों सदनों में साधारण बहुमत द्वारा)', ['Within 1 Month by Special Majority', 'Within 14 Days by 2/3rd majority', 'Within 6 Months'], ['1 माह में विशेष बहुमत से', '14 दिन में दो-तिहाई बहुमत से', '6 माह के भीतर'], 'Article 356(3) mandates parliamentary approval within 2 months by a simple majority; once approved, it continues for 6 months.', 'संसद के दोनों सदनों को 2 महीने के भीतर साधारण बहुमत से राष्ट्रपति शासन को मंजूरी देनी होती है।'), ("What is the normal maximum period that President's Rule under Article 356 can remain in force in a State?", 'किसी राज्य में अनुच्छेद 356 के तहत राष्ट्रपति शासन अधिकतम कितने समय तक बढ़ाया जा सकता है?', 'Maximum 3 Years (approved every 6 months by Parliament)', 'अधिकतम 3 वर्ष (हर 6 माह पर संसद के अनुमोदन से)', ['Maximum 1 Year', 'Maximum 5 Years', 'Indefinitely without any limit'], ['अधिकतम 1 वर्ष', 'अधिकतम 5 वर्ष', 'अनिश्चितकाल तक'], 'Article 356 can be extended 6 months at a time up to a maximum of 3 years (beyond 1 year requires Election Commission certificate or national emergency).', 'संसद से हर 6 महीने में पास कराकर राष्ट्रपति शासन अधिकतम 3 साल तक ही बढ़ाया जा सकता है।'), ('Which landmark judgment of 1994 placed stringent constitutional limits on the arbitrary use of Article 356?', '1994 के किस ऐतिहासिक फैसले ने अनुच्छेद 356 (राष्ट्रपति शासन) के मनमाने दुरुपयोग पर कड़े संवैधानिक अंकुश लगाए?', 'S.R. Bommai v. Union of India (1994)', 'एस.आर. बोम्मई बनाम भारत संघ (1994)', ['Minerva Mills case', 'Golaknath case', 'ADM Jabalpur case'], ['मिनर्वा मिल्स मामला', 'गोलकनाथ मामला', 'एडीएम जबलपुर मामला'], 'A 9-judge bench held that presidential proclamation under Article 356 is subject to judicial review, and the floor of the Assembly is the only place to test majority.', 'बोम्मई मामले में सुप्रीम कोर्ट ने माना कि राष्ट्रपति शासन न्यायिक समीक्षा के अधीन है और सरकार के बहुमत का परीक्षण केवल विधानसभा के पटल (Floor Test) पर ही होगा।'), ('In the S.R. Bommai case, the Supreme Court ruled that a State Legislative Assembly cannot be dissolved by the President until', 'बोम्मई मामले में सर्वोच्च न्यायालय ने फैसला दिया कि राष्ट्रपति किसी राज्य विधानसभा को तब तक भंग नहीं कर सकते जब तक कि', 'Parliament approves the Article 356 proclamation within two months', 'संसद दो महीने के भीतर अनुच्छेद 356 की घोषणा को मंजूरी न दे दे', ['The Governor submits a handwritten affidavit', 'The Chief Minister voluntarily signs his resignation', 'New elections are officially notified by ECI'], ['राज्यपाल लिखित हलफनामा न दें', 'मुख्यमंत्री इस्तीफा न दे दें', 'चुनाव आयोग तारीख तय न कर दे'], 'The Assembly can only be kept under suspended animation initially; it can be dissolved only AFTER Parliament approves the proclamation under Art 356.', 'संसद की मंजूरी मिलने से पहले विधानसभा को केवल निलंबित (Suspended) रखा जा सकता है, भंग (Dissolve) नहीं किया जा सकता।'), ("Which Indian State has experienced President's Rule under Article 356 the maximum number of times?", 'भारत के किस राज्य में अनुच्छेद 356 के तहत सर्वाधिक बार राष्ट्रपति शासन लगाया गया है?', 'Manipur (10 times) and Uttar Pradesh (9 times) / Punjab (first in 1951)', 'मणिपुर (10 बार) एवं उत्तर प्रदेश (9 बार) / पंजाब (पहली बार 1951 में)', ['Bihar (only 2 times)', 'Tamil Nadu (15 times)', 'Gujarat (12 times)'], ['बिहार (केवल 2 बार)', 'तमिलनाडु (15 बार)', 'गुजरात (12 बार)'], "President's Rule was first imposed in Punjab in 1951; Manipur and UP have seen the highest frequency of Article 356 proclamations.", 'सबसे पहली बार 1951 में पंजाब में राष्ट्रपति शासन लगा था; मणिपुर और उत्तर प्रदेश में सर्वाधिक बार इसका प्रयोग हुआ है।'), ('Article 360 of the Constitution empowers the President to proclaim a', 'संविधान का अनुच्छेद 360 राष्ट्रपति को किस प्रकार के आपातकाल की घोषणा करने का अधिकार देता है?', 'Financial Emergency (वित्तीय आपातकाल)', 'वित्तीय आपातकाल (Financial Emergency)', ['National Emergency', 'Constitutional Emergency', 'Agricultural Emergency'], ['राष्ट्रीय आपातकाल', 'संवैधानिक आपातकाल', 'कृषि आपातकाल'], 'If the President is satisfied that a situation has arisen whereby the financial stability or credit of India or any part thereof is threatened.', 'यदि देश की वित्तीय स्थिरता या साख को खतरा हो, तो राष्ट्रपति अनुच्छेद 360 के तहत वित्तीय आपातकाल लगा सकते हैं।'), ('During a Financial Emergency under Article 360, whose salaries and allowances can the President direct to be reduced?', 'अनुच्छेद 360 के तहत वित्तीय आपातकाल के दौरान राष्ट्रपति किनके वेतन और भत्तों में कटौती का निर्देश दे सकते हैं?', 'All or any class of persons serving the Union and States, INCLUDING Judges of the Supreme Court and High Courts', 'केंद्र और राज्यों की सेवा में लगे सभी कर्मचारियों, तथा सर्वोच्च व उच्च न्यायालय के न्यायाधीशों के वेतन में भी', ['Only private sector factory employees', 'Only municipal sanitation workers', 'Only armed forces jawans'], ['केवल निजी कर्मचारियों के', 'केवल सफाईकर्मियों के', 'केवल सैनिकों के'], 'Article 360(4)(b) explicitly permits reducing the salaries and allowances of all Union/State servants, including Supreme Court and High Court judges.', 'वित्तीय आपातकाल में सुप्रीम कोर्ट और हाईकोर्ट के न्यायाधीशों सहित सभी सरकारी कर्मचारियों के वेतन में कटौती की जा सकती है।'), ('How many times has a Financial Emergency been proclaimed in India under Article 360 since independence?', 'स्वतंत्रता के बाद से भारत में आज तक कितनी बार अनुच्छेद 360 के तहत वित्तीय आपातकाल घोषित किया गया है?', 'Never (Zero times)', 'कभी नहीं (शून्य बार)', ['Once during the 1991 balance of payments crisis', 'Twice (1966 and 1991)', 'Three times'], ['एक बार (1991 के आर्थिक संकट में)', 'दो बार (1966 और 1991 में)', 'तीन बार'], 'Even during the severe balance-of-payments crisis in 1991, India never invoked Article 360; it has never been proclaimed so far.', '1991 के गंभीर विदेशी मुद्रा संकट के समय भी भारत में कभी वित्तीय आपातकाल नहीं लगाया गया; यह आज तक कभी लागू नहीं हुआ।'), ('Which Article of the Constitution imposes a duty on the Union to protect every State against external aggression and internal disturbance?', 'संविधान का कौन सा अनुच्छेद केंद्र पर यह कर्तव्य डालता है कि वह बाह्य आक्रमण और आंतरिक अशांति से प्रत्येक राज्य की रक्षा करे?', 'Article 355', 'अनुच्छेद 355', ['Article 352', 'Article 356', 'Article 365'], ['अनुच्छेद 352', 'अनुच्छेद 356', 'अनुच्छेद 365'], 'Article 355 states: It shall be the duty of the Union to protect every State against external aggression and internal disturbance and ensure governance in accordance with the Constitution.', 'अनुच्छेद 355 केंद्र को राज्यों की सुरक्षा करने और यह देखने का दायित्व सौंपता है कि राज्य सरकार संविधान के अनुसार चले।'), ('Under Article 359, who has the power to suspend the right to move any court for the enforcement of specified Fundamental Rights?', 'अनुच्छेद 359 के तहत मूल अधिकारों को लागू कराने के लिए अदालत जाने के अधिकार को निलंबित करने का आदेश कौन जारी कर सकता है?', 'The President of India by Presidential Order (EXCEPT Articles 20 and 21)', 'भारत के राष्ट्रपति (राष्ट्रपति के आदेश द्वारा — अनुच्छेद 20 और 21 को छोड़कर)', ['The Chief Justice of India', 'The Union Home Minister', 'The Lok Sabha Speaker'], ['भारत के मुख्य न्यायाधीश', 'केंद्रीय गृह मंत्री', 'लोकसभा अध्यक्ष'], 'Article 359 suspends the enforcement of rights (not the rights themselves) as specified in the presidential order, but cannot touch Arts 20 and 21.', 'अनुच्छेद 359 के तहत राष्ट्रपति आदेश जारी कर अधिकारों के प्रवर्तन को रोक सकते हैं, किंतु 44वें संशोधन के बाद अनुच्छेद 20 व 21 पर रोक नहीं लगाई जा सकती।'), ('Is a proclamation of National Emergency under Article 352 subject to judicial review by courts?', 'क्या अनुच्छेद 352 के तहत राष्ट्रीय आपातकाल की उद्घोषणा की न्यायालय द्वारा न्यायिक समीक्षा की जा सकती है?', 'Yes, in Minerva Mills (1980), the Supreme Court held that proclamation of emergency can be challenged on grounds of mala fide or absurd grounds', 'हां, मिनर्वा मिल्स मामले (1980) में सुप्रीम कोर्ट ने माना कि दुर्भावनापूर्ण या फर्जी आधारों पर लगाए गए आपातकाल को अदालत में चुनौती दी जा सकती है', ['No, presidential emergency is completely immune from courts forever', 'Only after five years have elapsed', 'Only if approved by the Attorney General'], ['नहीं, आपातकाल पर कोर्ट कभी विचार नहीं कर सकता', 'केवल 5 साल बीतने के बाद', 'केवल अटॉर्नी जनरल की मंजूरी से'], 'The 38th Amendment (1975) made emergency non-justiciable; the 44th Amendment (1978) deleted this clause, and Minerva Mills confirmed judicial review against mala fides.', '38वें संशोधन की रोक को 44वें संशोधन ने हटा दिया; अतः यदि दुर्भावना से आपातकाल लगाया जाए तो सुप्रीम कोर्ट उसकी समीक्षा कर सकता है।')]

slot_q120_local_amend = [('Which Constitutional Amendment Act granted constitutional recognition and status to Panchayati Raj Institutions in India?', 'किस संविधान संशोधन अधिनियम द्वारा भारत में पंचायती राज संस्थाओं को संवैधानिक मान्यता और दर्जा प्रदान किया गया?', '73rd Constitutional Amendment Act, 1992', '73वां संविधान संशोधन अधिनियम (1992)', ['74th Amendment Act, 1992', '42nd Amendment Act, 1976', '64th Amendment Bill, 1989'], ['74वां संशोधन (1992)', '42वां संशोधन (1976)', '64वां संशोधन (1989)'], 'Passed in December 1992 and came into force on 24 April 1993, inserting Part IX and the 11th Schedule.', 'पी.वी. नरसिंह राव सरकार के समय 73वां संशोधन पारित हुआ और 24 अप्रैल 1993 को लागू हुआ, जिसे राष्ट्रीय पंचायती राज दिवस मनाया जाता है।'), ('On which date did the 73rd Constitutional Amendment Act, 1992 come into legal force across India?', '73वां संविधान संशोधन अधिनियम, 1992 पूरे भारत में किस तिथि को प्रभावी (लागू) हुआ था?', '24 April 1993 (celebrated nationwide as National Panchayati Raj Day)', '24 अप्रैल 1993 (राष्ट्रीय पंचायती राज दिवस के रूप में मान्य)', ['2 October 1992', '26 January 1993', '15 August 1993'], ['2 अक्टूबर 1992', '26 जनवरी 1993', '15 अगस्त 1993'], 'Came into effect on 24 April 1993; celebrated every year on 24 April as National Panchayati Raj Day.', "24 अप्रैल 1993 को लागू होने के उपलक्ष्य में प्रतिवर्ष 24 अप्रैल को 'राष्ट्रीय पंचायती राज दिवस' मनाया जाता है।"), ('Which Part and which Schedule were added to the Constitution by the 73rd Constitutional Amendment Act?', '73वें संविधान संशोधन द्वारा संविधान में कौन सा भाग तथा कौन सी अनुसूची जोड़ी गई थी?', 'Part IX and the 11th Schedule', 'भाग IX एवं 11वीं अनुसूची (Part IX and 11th Schedule)', ['Part IXA and 12th Schedule', 'Part VIII and 10th Schedule', 'Part IXB and 9th Schedule'], ['भाग IXक एवं 12वीं अनुसूची', 'भाग VIII एवं 10वीं अनुसूची', 'भाग IXख एवं 9वीं अनुसूची'], 'The 73rd Amendment added Part IX containing Articles 243 to 243-O, and the Eleventh Schedule.', '73वें संशोधन ने संविधान में भाग 9 (अनुच्छेद 243 से 243-ण) और 11वीं अनुसूची को अंतःस्थापित किया।'), ('How many functional items are listed in the Eleventh Schedule of the Constitution for Panchayats under Article 243G?', 'अनुच्छेद 243छ के तहत संविधान की 11वीं अनुसूची में पंचायतों के कार्यक्षेत्र के लिए कुल कितने विषय दिए गए हैं?', '29 Functional Subjects', '29 कार्यात्मक विषय (29 Subjects)', ['18 Subjects', '21 Subjects', '33 Subjects'], ['18 विषय', '21 विषय', '33 विषय'], 'The 11th Schedule contains 29 functional items (agriculture, minor irrigation, animal husbandry, rural roads, drinking water, poverty alleviation, etc.).', '11वीं अनुसूची में पंचायतों को सौंपे जाने वाले कुल 29 विषयों (कृषि, पेयजल, ग्रामीण सड़कें, प्राथमिक शिक्षा आदि) की सूची है।'), ('Which was the first state in independent India to establish Panchayati Raj on 2 October 1959?', 'स्वतंत्र भारत में 2 अक्टूबर 1959 को सर्वप्रथम पंचायती राज की स्थापना किस राज्य में की गई थी?', 'Rajasthan (at Nagaur district by PM Jawaharlal Nehru)', 'राजस्थान (नागौर जिले में पंडित नेहरू द्वारा)', ['Andhra Pradesh', 'Uttar Pradesh', 'Bihar'], ['आंध्र प्रदेश', 'उत्तर प्रदेश', 'बिहार'], 'Inaugurated by Prime Minister Nehru at Nagaur, Rajasthan on Gandhi Jayanti 1959; Andhra Pradesh followed second.', '2 अक्टूबर 1959 को राजस्थान के नागौर में प्रधानमंत्री जवाहरलाल नेहरू ने पहली त्रिस्तरीय पंचायत का उद्घाटन किया; दूसरा राज्य आंध्र प्रदेश था।'), ('The landmark Community Development Programme (CDP) was launched in India in which year?', "भारत में ऐतिहासिक 'सामुदायिक विकास कार्यक्रम' (CDP) किस वर्ष प्रारंभ किया गया था?", '1952 (launched on 2 October 1952)', '1952 में (2 अक्टूबर 1952 को)', ['1948', '1950', '1956'], ['1948 में', '1950 में', '1956 में'], 'Launched on 2 October 1952 with US Ford Foundation assistance to promote rural self-help; its operational shortcomings led to the Balwant Rai Mehta Committee.', 'ग्रामीण विकास हेतु 1952 में शुरू हुआ यह कार्यक्रम जनसहभागिता की कमी के कारण विफल रहा, जिसकी समीक्षा हेतु मेहता समिति बनी।'), ("Which Committee recommended the establishment of a three-tier Panchayati Raj system based on 'Democratic Decentralisation' in 1957?", "1957 में 'लोकतांत्रिक विकेंद्रीकरण' पर आधारित त्रिस्तरीय पंचायती राज व्यवस्था की सिफारिश किस समिति ने की थी?", 'Balwant Rai Mehta Committee', 'बलवंत राय मेहता समिति (Balwant Rai Mehta Committee)', ['Ashok Mehta Committee', 'L.M. Singhvi Committee', 'G.V.K. Rao Committee'], ['अशोक मेहता समिति', 'एल.एम. सिंघवी समिति', 'जी.वी.के. राव समिति'], 'Balwant Rai Mehta recommended a 3-tier structure: Gram Panchayat (village), Panchayat Samiti (block), and Zila Parishad (district).', 'बलवंत राय मेहता समिति ने ग्राम स्तर पर ग्राम पंचायत, प्रखंड स्तर पर पंचायत समिति और जिला स्तर पर जिला परिषद की त्रिस्तरीय व्यवस्था सुझाई।'), ("Who is widely regarded as the 'Architect of Panchayati Raj' in India?", "भारत में 'पंचायती राज के वास्तुकार / शिल्पकार' के रूप में किन्हें जाना जाता है?", 'Balwant Rai Mehta', 'बलवंत राय मेहता (Balwant Rai Mehta)', ['Ashok Mehta', 'P.K. Thungon', 'L.M. Singhvi'], ['अशोक मेहता', 'पी.के. थुंगन', 'एल.एम. सिंघवी'], 'Balwant Rai Mehta laid the foundational blueprint of democratic decentralization and panchayati raj in 1957.', 'बलवंत राय मेहता को भारत में लोकतांत्रिक विकेंद्रीकरण और पंचायती राज का जनक/वास्तुकार माना जाता है।'), ('Which Committee appointed by the Janata Government in 1977 recommended a TWO-TIER Panchayati Raj system?', "1977 में जनता पार्टी सरकार द्वारा नियुक्त किस समिति ने 'द्वि-स्तरीय' (Two-Tier) पंचायती राज व्यवस्था की सिफारिश की थी?", 'Ashok Mehta Committee (1977-1978)', 'अशोक मेहता समिति (Ashok Mehta Committee)', ['Balwant Rai Mehta Committee', 'G.V.K. Rao Committee', 'Sarkaria Commission'], ['बलवंत राय मेहता समिति', 'जी.वी.के. राव समिति', 'सरकारिया आयोग'], 'Ashok Mehta recommended replacing the 3-tier system with a 2-tier model: Zila Parishad at district level and Mandal Panchayat for a group of villages.', 'अशोक मेहता समिति ने ब्लॉक स्तर को हटाकर केवल जिला परिषद और मंडल पंचायत की द्वि-स्तरीय व्यवस्था की सिफारिश की थी।'), ('Which Committee appointed in 1986 first recommended that Panchayati Raj Institutions should be given Constitutional Recognition?', "1986 में गठित किस समिति ने पहली बार पंचायतों को 'संवैधानिक दर्जा' (Constitutional Recognition) देने की जोरदार सिफारिश की थी?", 'L.M. Singhvi Committee (1986)', 'एल.एम. सिंघवी समिति (L.M. Singhvi Committee)', ['Balwant Rai Mehta Committee', 'Ashok Mehta Committee', 'Dantwala Committee'], ['बलवंत राय मेहता समिति', 'अशोक मेहता समिति', 'दांतवाला समिति'], 'The L.M. Singhvi Committee appointed by Rajiv Gandhi recommended constitutional amendment, regular elections, and Nyaya Panchayats.', 'लक्ष्मी मल्ल (एल.एम.) सिंघवी समिति ने पंचायतों को संविधान में संरक्षित करने और ग्राम सभा को मजबूत करने की सिफारिश की थी।'), ('Under Article 243D, what is the minimum mandatory reservation for women in Panchayats at all three levels?', 'अनुच्छेद 243घ के अनुसार पंचायतों के तीनों स्तरों पर महिलाओं के लिए न्यूनतम कितना आरक्षण अनिवार्य है?', 'Not less than One-Third (1/3rd or 33%) of the total seats and offices of chairpersons', 'कुल सीटों और अध्यक्ष पदों का कम से कम एक-तिहाई (1/3 या 33%)', ['One-Half (50%) in all states mandatory', 'One-Fourth (25%)', 'Ten percent (10%)'], ['सभी राज्यों में अनिवार्य 50%', 'एक-चौथाई (25%)', 'दस प्रतिशत (10%)'], 'The Constitution mandates at least 33% reservation for women; states like Bihar, MP, and Rajasthan have raised it to 50% through state laws.', 'संविधान कम से कम 33% (1/3) आरक्षण अनिवार्य करता है; कई राज्यों ने इसे बढ़ाकर 50% किया है।'), ('Which was the first State in India to provide 50% reservation for women in Panchayati Raj institutions in 2006?', '2006 में पंचायती राज संस्थाओं में महिलाओं को 50% आरक्षण देने वाला भारत का पहला राज्य कौन सा था?', 'Bihar (under the Bihar Panchayat Raj Act, 2006)', 'बिहार (बिहार पंचायत राज अधिनियम, 2006 के तहत)', ['Madhya Pradesh', 'Rajasthan', 'Kerala'], ['मध्य प्रदेश', 'राजस्थान', 'केरल'], 'Bihar was the pioneer state to enact 50% reservation for women in Panchayats in 2006 under Chief Minister Nitish Kumar.', 'बिहार 2006 में पंचायतों में महिलाओं को 50% आरक्षण देने वाला देश का पहला अग्रणी राज्य बना था।'), ('What is the constitutionally mandated term of office for Panchayats under Article 243E?', 'अनुच्छेद 243ङ के अनुसार पंचायतों का संवैधानिक कार्यकाल कितना निर्धारित है?', '5 Years from the date appointed for its first meeting', 'अपनी पहली बैठक की नियत तारीख से 5 वर्ष', ['6 Years', '4 Years', 'Permanent tenure'], ['6 वर्ष', '4 वर्ष', 'स्थायी कार्यकाल'], 'Every Panchayat continues for 5 years unless dissolved earlier; elections must be completed before the expiry of the 5-year duration.', 'पंचायतों का कार्यकाल 5 वर्ष होता है; 5 वर्ष पूरे होने से पहले ही चुनाव कराना अनिवार्य है।'), ('If a Panchayat is dissolved before its 5-year term expires, within what period must fresh elections be conducted under Article 243E(3)?', 'यदि कोई पंचायत 5 वर्ष पूरे होने से पूर्व भंग कर दी जाती है, तो कितने समय के भीतर नए चुनाव कराना अनिवार्य है?', 'Within 6 Months from the date of its dissolution', 'भंग होने की तारीख से 6 माह के भीतर', ['Within 1 Year', 'Within 3 Months', 'Within 30 Days'], ['1 वर्ष के भीतर', '3 माह के भीतर', '30 दिन के भीतर'], 'Fresh elections must be held within 6 months; the newly elected Panchayat serves only for the remaining unexpired remainder of the 5-year term.', 'भंग होने पर 6 महीने के अंदर चुनाव कराना आवश्यक है; नई पंचायत केवल शेष बचे हुए कार्यकाल के लिए ही काम करती है।'), ('What is the minimum age required to contest elections to a Panchayat under Article 243F?', 'अनुच्छेद 243च के अनुसार पंचायत का चुनाव (मुखिया, वार्ड सदस्य) लड़ने के लिए न्यूनतम आयु कितनी होनी चाहिए?', '21 Years of age', '21 वर्ष की आयु (21 Years)', ['18 Years', '25 Years', '30 Years'], ['18 वर्ष', '25 वर्ष', '30 वर्ष'], 'Article 243F(1)(b) specifies that no person shall be disqualified on grounds of age if he has attained the age of 21 years (voting age is 18).', 'मतदान की आयु 18 वर्ष है, किंतु पंचायत का चुनाव लड़ने के लिए न्यूनतम आयु 21 वर्ष पूरी होनी चाहिए।'), ('Under Article 243K, who is responsible for the superintendence, direction, and conduct of Panchayat elections?', 'अनुच्छेद 243ट के अनुसार पंचायत चुनावों के संचालन, मतदाता सूची तैयार करने और नियंत्रण की शक्ति किसमें निहित है?', 'State Election Commission (headed by State Election Commissioner appointed by Governor)', 'राज्य निर्वाचन आयोग (राज्यपाल द्वारा नियुक्त राज्य निर्वाचन आयुक्त)', ['Election Commission of India (ECI)', 'District Magistrate alone', 'State Panchayati Raj Minister'], ['भारत निर्वाचन आयोग (ECI)', 'जिलाधिकारी (DM)', 'राज्य के पंचायती राज मंत्री'], 'Article 243K vests complete electoral authority for local bodies in the independent State Election Commission.', "पंचायत चुनावों के लिए स्वतंत्र 'राज्य निर्वाचन आयोग' का गठन किया गया है, जिसके आयुक्त को हाईकोर्ट जज की तरह हटाया जाता है।"), ('Under Article 243I, who constitutes a State Finance Commission every 5 years to review the financial position of Panchayats?', "अनुच्छेद 243झ के अनुसार पंचायतों की वित्तीय स्थिति की समीक्षा हेतु प्रत्येक 5 वर्ष में 'राज्य वित्त आयोग' का गठन कौन करता है?", 'The Governor of the State', 'संबंधित राज्य के राज्यपाल (Governor of the State)', ['The Chief Minister of the State', 'The President of India', 'The State Finance Minister'], ['राज्य के मुख्यमंत्री', 'भारत के राष्ट्रपति', 'राज्य के वित्त मंत्री'], 'The Governor constitutes a State Finance Commission every five years to recommend tax devolution and grant principles from the Consolidated Fund of the State.', 'राज्यपाल हर 5 वर्ष में राज्य वित्त आयोग बनाते हैं, जो राज्य के करों में पंचायतों की हिस्सेदारी तय करता है।'), ('Article 243A of the Constitution defines which grassroots direct democracy body in rural India?', 'संविधान का अनुच्छेद 243क ग्रामीण भारत में प्रत्यक्ष लोकतंत्र की किस आधारभूत संस्था का उपबंध करता है?', 'Gram Sabha (ग्राम सभा - consisting of all registered voters in the village)', 'ग्राम सभा (गाँव के सभी पंजीकृत मतदाताओं से मिलकर बनी सभा)', ['Gram Kachehri', 'Block Advisory Council', 'District Vigilance Committee'], ['ग्राम कचहरी', 'प्रखंड सलाहकार परिषद', 'जिला निगरानी समिति'], 'Gram Sabha is the foundation of the Panchayati Raj system, comprising all persons registered in electoral rolls relating to a village.', 'ग्राम सभा गांव के उन सभी वयस्कों की सभा है जिनका नाम मतदाता सूची में दर्ज होता है; यह प्रत्यक्ष लोकतंत्र का सबसे जीवंत उदाहरण है।'), ('The Provisions of the Panchayats (Extension to the Scheduled Areas) Act, 1996 (PESA Act) applies to which Areas?', 'पंचायत (अनुसूचित क्षेत्रों में विस्तार) अधिनियम, 1996 (PESA Act) किन क्षेत्रों पर लागू होता है?', 'Fifth Schedule Areas across 10 States, safeguarding tribal self-rule and customary rights', '10 राज्यों के 5वीं अनुसूची वाले जनजातीय क्षेत्रों में (आदिवासी स्वशासन हेतु)', ['Sixth Schedule Areas in the North East', 'All Urban Municipal Corporations', 'Centrally protected wildlife tiger reserves'], ['पूर्वोत्तर के 6वीं अनुसूची क्षेत्रों में', 'शहरी नगर निगमों में', 'बाघ अभयारण्यों में'], 'Enacted on the recommendations of the Bhuria Committee (1995) to empower tribal communities through Gram Sabhas over minor forest produce and land.', 'दिलीप सिंह भूरिया समिति की सिफारिश पर बना पेसा (PESA) कानून 5वीं अनुसूची के आदिवासी क्षेत्रों में ग्राम सभा को स्वशासन का अधिकार देता है।'), ('Which Constitutional Amendment Act granted constitutional recognition and status to Urban Local Bodies (Municipalities)?', 'किस संविधान संशोधन अधिनियम द्वारा शहरी स्थानीय निकायों (नगरपालिकाओं / नगर निगमों) को संवैधानिक दर्जा दिया गया?', '74th Constitutional Amendment Act, 1992', '74वां संविधान संशोधन अधिनियम (1992)', ['73rd Amendment Act, 1992', '65th Amendment Act, 1990', '52nd Amendment Act, 1985'], ['73वां संशोधन (1992)', '65वां संशोधन (1990)', '52वां संशोधन (1985)'], 'Passed in December 1992 and came into force on 1 June 1993, adding Part IXA and the 12th Schedule.', '74वां संशोधन 1 जून 1993 को लागू हुआ, जिसने संविधान में भाग 9क और 12वीं अनुसूची को जोड़कर शहरी निकायों को सशक्त किया।'), ('Which Part and which Schedule were added to the Constitution by the 74th Constitutional Amendment Act?', '74वें संविधान संशोधन द्वारा संविधान में कौन सा भाग तथा कौन सी अनुसूची अंतःस्थापित की गई?', 'Part IXA (Articles 243P to 243ZG) and the 12th Schedule', 'भाग IXक (अनुच्छेद 243त से 243यछ) एवं 12वीं अनुसूची', ['Part IX and 11th Schedule', 'Part IXB and 10th Schedule', 'Part X and 8th Schedule'], ['भाग IX एवं 11वीं अनुसूची', 'भाग IXख एवं 10वीं अनुसूची', 'भाग X एवं 8वीं अनुसूची'], "The 74th Amendment added Part IXA titled 'The Municipalities' and the Twelfth Schedule.", '74वें संशोधन ने भाग 9क (नगरपालिकाएं) और 12वीं अनुसूची जोड़ी।'), ('How many functional items are listed in the Twelfth Schedule of the Constitution for Municipalities under Article 243W?', 'अनुच्छेद 243ब के तहत संविधान की 12वीं अनुसूची में नगरपालिकाओं के कार्यक्षेत्र के लिए कुल कितने विषय दिए गए हैं?', '18 Functional Subjects', '18 कार्यात्मक विषय (18 Subjects)', ['29 Subjects', '21 Subjects', '12 Subjects'], ['29 विषय', '21 विषय', '12 विषय'], 'The 12th Schedule specifies 18 functional items (urban planning, regulation of land-use, roads and bridges, water supply, public health, fire services, solid waste).', '12वीं अनुसूची में नगर निकायों को सौंपे जाने वाले कुल 18 विषयों (शहरी नियोजन, जलापूर्ति, अग्निशमन, ठोस कचरा प्रबंधन आदि) का उल्लेख है।'), ('Under Article 243Q, what three types of Municipalities are constituted in urban areas?', 'अनुच्छेद 243थ के अनुसार शहरी क्षेत्रों में किन तीन प्रकार की नगरपालिकाओं का गठन किया जाता है?', 'Nagar Panchayat (transitional area), Municipal Council (smaller urban area), and Municipal Corporation (larger urban area)', 'नगर पंचायत (संक्रमणशील क्षेत्र), नगर परिषद (छोटे शहरी क्षेत्र), एवं नगर निगम (बड़े शहरी क्षेत्र / महानगर)', ['Town Board, Cantonment, Port Trust', 'Zila Parishad, Block Committee, Gram Sabha', 'Metropolitan Planning Board only'], ['टाउन बोर्ड, छावनी, पोर्ट ट्रस्ट', 'जिला परिषद, प्रखंड, ग्राम सभा', 'केवल महानगर बोर्ड'], 'Three types based on population, density, and revenue: Nagar Panchayat (rural to urban transition), Municipal Council (small city), Municipal Corporation (large metro).', 'आबादी के आधार पर तीन स्तर हैं: नगर पंचायत (कस्बा), नगर परिषद (छोटा शहर), और नगर निगम (बड़ा महानगर)।'), ('Which was the first Municipal Corporation established in India in 1687-88?', '1687-88 में भारत में स्थापित होने वाला पहला नगर निगम कौन सा था?', 'Madras Municipal Corporation (Chennai)', 'मद्रास नगर निगम (चेन्नई)', ['Bombay Municipal Corporation', 'Calcutta Municipal Corporation', 'Patna Municipal Corporation'], ['बॉम्बे नगर निगम', 'कलकत्ता नगर निगम', 'पटना नगर निगम'], 'The Madras Municipal Corporation was set up by the British East India Company by royal charter in 1687, functioning from 1688.', 'भारत का सबसे पहला नगर निगम 1687 में मद्रास में ब्रिटिश ईस्ट इंडिया कंपनी द्वारा स्थापित किया गया था।'), ('Under Article 243ZD, which body must be constituted at the district level to consolidate plans prepared by Panchayats and Municipalities?', 'अनुच्छेद 243यघ के अनुसार पंचायतों और नगरपालिकाओं की विकास योजनाओं को समेकित करने हेतु जिला स्तर पर कौन सी समिति बनती है?', 'District Planning Committee (DPC / जिला योजना समिति)', 'जिला योजना समिति (District Planning Committee - DPC)', ['State Planning Board', 'Zila Vikas Council', 'Regional Development Authority'], ['राज्य योजना बोर्ड', 'जिला विकास परिषद', 'क्षेत्रीय विकास प्राधिकरण'], 'Article 243ZD mandates a District Planning Committee in every district; at least 4/5ths of its members must be elected by elected members of Zila Parishad and Municipalities.', 'जिला योजना समिति (DPC) जिले के ग्रामीण और शहरी क्षेत्रों के संतुलित विकास के लिए समग्र विकास योजना तैयार करती है।'), ('Which Article of the Constitution embodies the formal procedure for Constitutional Amendment?', 'संविधान संशोधन की औपचारिक प्रक्रिया किस अनुच्छेद में दी गई है?', 'Article 368 (in Part XX)', 'अनुच्छेद 368 (भाग XX में)', ['Article 356', 'Article 370', 'Article 360'], ['अनुच्छेद 356', 'अनुच्छेद 370', 'अनुच्छेद 360'], 'Part XX, Article 368 contains the constituent power of Parliament to amend the Constitution.', 'संविधान के भाग 20 के अनुच्छेद 368 में संविधान संशोधन की विस्तृत प्रक्रिया दी गई है।'), ("From which country's Constitution did India borrow the procedure for amending the Constitution under Article 368?", 'भारतीय संविधान में अनुच्छेद 368 के तहत संविधान संशोधन की प्रक्रिया किस देश के संविधान से ली गई है?', 'Constitution of South Africa', 'दक्षिण अफ्रीका के संविधान से (South Africa)', ['Constitution of USA', 'Constitution of Australia', 'Constitution of Switzerland'], ['संयुक्त राज्य अमेरिका से', 'ऑस्ट्रेलिया से', 'स्विट्जरलैंड से'], 'The framers borrowed the amendment procedure of Article 368 from the Constitution of South Africa.', 'संविधान संशोधन की प्रक्रिया दक्षिण अफ्रीका के संविधान से प्रेरित होकर भारतीय संविधान में शामिल की गई।'), ('Can a Constitutional Amendment Bill under Article 368 be introduced in State Legislative Assemblies?', 'क्या अनुच्छेद 368 के तहत संविधान संशोधन विधेयक किसी राज्य विधानसभा में प्रस्तुत किया जा सकता है?', 'No, it can be introduced ONLY in either House of Parliament (Lok Sabha or Rajya Sabha)', 'नहीं, यह केवल संसद के किसी भी सदन (लोकसभा या राज्यसभा) में ही पेश किया जा सकता है', ['Yes, can be introduced in any State Assembly', 'Yes, with permission of the Governor', 'Only in State Legislative Councils'], ['हां, किसी भी विधानसभा में', 'हां, राज्यपाल की मंजूरी से', 'केवल विधान परिषदों में'], 'Constitutional Amendment Bills can originate strictly in Parliament, not in state legislatures.', 'संविधान संशोधन विधेयक केवल संसद में ही पेश हो सकता है; राज्य विधानसभाओं को इसमें विधेयक पेश करने का कोई अधिकार नहीं है।'), ('Does a Constitutional Amendment Bill under Article 368 require the prior recommendation of the President before introduction?', 'क्या संविधान संशोधन विधेयक को संसद में पेश करने से पूर्व राष्ट्रपति की पूर्व सिफारिश आवश्यक है?', 'No, prior recommendation of the President is NOT required', 'नहीं, राष्ट्रपति की पूर्व अनुमति की आवश्यकता नहीं होती', ['Yes, mandatory prior sanction required', 'Required only for bills amending Fundamental Rights', 'Required only if introduced by a private member'], ['हां, अनिवार्य पूर्व सहमति चाहिए', 'केवल मूल अधिकार संशोधन में चाहिए', 'केवल गैर-सरकारी विधेयक में चाहिए'], 'Unlike Money Bills, an amendment bill can be introduced by any minister or private member without prior presidential recommendation.', 'संविधान संशोधन विधेयक पेश करने के लिए राष्ट्रपति की पूर्व मंजूरी की जरूरत नहीं होती।'), ('In case of disagreement between Lok Sabha and Rajya Sabha on a Constitutional Amendment Bill, can a Joint Sitting be summoned?', 'संविधान संशोधन विधेयक पर दोनों सदनों में असहमति होने पर क्या राष्ट्रपति दोनों सदनों की संयुक्त बैठक बुला सकते हैं?', 'No, there is NO provision for a joint sitting on an Amendment Bill (each House must pass it separately)', 'नहीं, संशोधन विधेयक पर संयुक्त बैठक का कोई प्रावधान नहीं है (दोनों सदनों द्वारा अलग-अलग पास होना अनिवार्य है)', ['Yes, summoned by Speaker', 'Yes, summoned by President', 'Referred to Supreme Court'], ['हां, स्पीकर द्वारा', 'हां, राष्ट्रपति द्वारा', 'सुप्रीम कोर्ट को भेजा जाता है'], 'Each House must pass the bill separately by special majority under Art 368; disagreement kills the bill.', 'यदि एक सदन भी संविधान संशोधन विधेयक को अस्वीकार कर दे, तो विधेयक समाप्त हो जाता है; संयुक्त बैठक नहीं हो सकती।'), ('What majority is required under Article 368(2) to pass a Constitutional Amendment Bill affecting federal provisions?', 'अनुच्छेद 368(2) के तहत संघीय ढांचे को प्रभावित करने वाले संशोधनों के लिए किस प्रकार के बहुमत की आवश्यकता होती है?', 'A Special Majority of each House AND ratification by the legislatures of not less than HALF of the States by simple majority', 'संसद के प्रत्येक सदन का विशेष बहुमत तथा कम से कम आधे (1/2) राज्यों के विधानमंडलों का साधारण बहुमत से अनुसमर्थन', ['Special Majority of Parliament and 2/3rd of States', 'Simple majority of Parliament only', 'Unanimous consent of all States'], ['संसद और 2/3 राज्यों का विशेष बहुमत', 'संसद का साधारण बहुमत', 'सभी राज्यों की सर्वसम्मति'], 'Federal amendments (election of President, powers of Supreme Court/High Courts, 7th Schedule, representation in Parliament, Art 368 itself) require 50% state ratification.', 'संघीय ढांचे (जैसे जीएसटी, राष्ट्रपति चुनाव, न्यायपालिका) में बदलाव के लिए संसद के विशेष बहुमत के साथ आधे राज्यों की विधानसभाओं की सहमति आवश्यक है।'), ('Which was the 1st Constitutional Amendment Act, enacted in 1951?', '1951 में पारित पहला संविधान संशोधन अधिनियम (1st Amendment Act) किससे संबंधित था?', 'Added the Ninth Schedule and Article 31B to protect land reform laws from judicial review', 'भूमि सुधार और जमींदारी उन्मूलन कानूनों को सुरक्षा देने हेतु 9वीं अनुसूची और अनुच्छेद 31ख जोड़ा गया', ['Created the state of Andhra Pradesh', 'Abolished the Privy Purses', 'Introduced anti-defection law'], ['आंध्र प्रदेश राज्य बनाया', 'प्रिवी पर्स समाप्त किया', 'दल-बदल विरोधी कानून बनाया'], 'Passed by the Provisional Parliament in 1951, inserting the Ninth Schedule, Art 31A, 31B, and restrictions on speech in Art 19(2).', 'पहले संविधान संशोधन (1951) द्वारा 9वीं अनुसूची बनाई गई तथा वाक् स्वतंत्रता पर लोक व्यवस्था जैसे युक्तियुक्त प्रतिबंध लगाए गए।'), ("Which Constitutional Amendment Act is famously known as the 'Mini-Constitution' due to its sweeping changes?", "किस संविधान संशोधन अधिनियम को अपने व्यापक और ऐतिहासिक बदलावों के कारण 'लघु संविधान' (Mini-Constitution) कहा जाता है?", '42nd Constitutional Amendment Act, 1976', '42वां संविधान संशोधन अधिनियम (1976)', ['44th Amendment Act, 1978', '24th Amendment Act, 1971', '73rd Amendment Act, 1992'], ['44वां संशोधन (1978)', '24वां संशोधन (1971)', '73वां संशोधन (1992)'], 'Enacted during Emergency in 1976 based on Swaran Singh recommendations; amended Preamble, added Fundamental Duties, altered executive and judicial powers.', '42वें संशोधन (1976) ने प्रस्तावना में बदलाव किया, मौलिक कर्तव्य जोड़े, तथा संविधान के कई महत्वपूर्ण भागों में परिवर्तन किए।'), ('The 52nd Constitutional Amendment Act of 1985 introduced which landmark constitutional provision?', '1985 के 52वें संविधान संशोधन अधिनियम द्वारा कौन सा ऐतिहासिक प्रावधान संविधान में जोड़ा गया था?', 'Anti-Defection Law (दलबदल विरोधी कानून) and the Tenth Schedule', 'दलबदल विरोधी कानून (Anti-Defection Law) एवं 10वीं अनुसूची', ['Right to Education in Article 21A', 'Goods and Services Tax', 'National Judicial Appointments Commission'], ['शिक्षा का अधिकार (21क)', 'वस्तु एवं सेवा कर (GST)', 'राष्ट्रीय न्यायिक नियुक्ति आयोग'], "Enacted under Rajiv Gandhi to curb political floor-crossing ('Aaya Ram, Gaya Ram'), adding the 10th Schedule disqualifying defecting MPs/MLAs.", 'राजीव गांधी सरकार द्वारा 52वें संशोधन (1985) के तहत 10वीं अनुसूची जोड़कर सांसदों और विधायकों के दलबदल पर रोक लगाई गई।'), ('Under the Tenth Schedule (Anti-Defection Law), who decides the question of disqualification of a member of a House?', '10वीं अनुसूची (दलबदल कानून) के तहत किसी सदस्य की अयोग्यता का फैसला करने का अधिकार किसे है?', 'The Presiding Officer of that House (Speaker of Lok Sabha or Chairman of Rajya Sabha)', 'उस सदन के पीठासीन अधिकारी को (लोकसभा अध्यक्ष अथवा राज्यसभा के सभापति)', ['The Election Commission of India', 'The President of India on Cabinet advice', 'The Supreme Court of India directly'], ['भारत निर्वाचन आयोग को', 'कैबिनेट की सलाह पर राष्ट्रपति को', 'सीधे सर्वोच्च न्यायालय को'], "The Chairman or Speaker decides disqualification; in Kihoto Hollohan (1992), the Supreme Court ruled the Speaker's decision is subject to judicial review.", 'दलबदल पर अयोग्यता का निर्णय स्पीकर या सभापति करते हैं; किहोतो होलोहन मामले (1992) में माना गया कि स्पीकर का फैसला कोर्ट की समीक्षा के अधीन है।'), ('By which Constitutional Amendment Act was the voting age reduced from 21 years to 18 years?', 'किस संविधान संशोधन अधिनियम द्वारा नागरिकों की मतदान की आयु 21 वर्ष से घटाकर 18 वर्ष की गई थी?', '61st Constitutional Amendment Act, 1988 (effective 1989)', '61वां संविधान संशोधन अधिनियम (1988 — 1989 से प्रभावी)', ['52nd Amendment Act, 1985', '44th Amendment Act, 1978', '73rd Amendment Act, 1992'], ['52वां संशोधन (1985)', '44वां संशोधन (1978)', '73वां संशोधन (1992)'], 'Amended Article 326 under PM Rajiv Gandhi, lowering the voting age for Lok Sabha and State Legislative Assemblies from 21 to 18 years.', 'राजीव गांधी सरकार ने 61वें संशोधन द्वारा अनुच्छेद 326 में संशोधन कर युवाओं को 18 वर्ष की आयु में वोट देने का अधिकार दिया।'), ('The 69th Constitutional Amendment Act, 1991 granted special status to the Union Territory of Delhi by designating it as', '1991 के 69वें संविधान संशोधन अधिनियम द्वारा दिल्ली को कौन सा विशेष दर्जा दिया गया?', 'National Capital Territory of Delhi (NCT) with a Legislative Assembly and Council of Ministers', 'राष्ट्रीय राजधानी क्षेत्र दिल्ली (NCT) — विधानसभा एवं मंत्रिपरिषद सहित', ['Full-fledged 29th State of India', 'Directly ruled territory by Union Home Ministry', 'Autonomous Tribal Region under 6th Schedule'], ['भारत का पूर्ण 29वां राज्य', 'सीधे गृह मंत्रालय का क्षेत्र', '6वीं अनुसूची का स्वायत्त क्षेत्र'], 'Inserted Article 239AA, providing Delhi with a 70-member Legislative Assembly and a 7-member Council of Ministers headed by Chief Minister.', 'अनुच्छेद 239कक जोड़कर दिल्ली को 70 सदस्यीय विधानसभा और मुख्यमंत्री के नेतृत्व में मंत्रिपरिषद दी गई (पुलिस, जमीन, लोक व्यवस्था केंद्र के पास रही)।'), ('Which Constitutional Amendment Act introduced the Goods and Services Tax (GST) across India in 2017?', "किस संविधान संशोधन अधिनियम द्वारा पूरे देश में 'वस्तु एवं सेवा कर' (GST) लागू किया गया?", '101st Constitutional Amendment Act, 2016 (effective 1 July 2017)', '101वां संविधान संशोधन अधिनियम (2016 — 1 जुलाई 2017 से प्रभावी)', ['100th Amendment Act, 2015', '102nd Amendment Act, 2018', '103rd Amendment Act, 2019'], ['100वां संशोधन (2015)', '102वां संशोधन (2018)', '103वां संशोधन (2019)'], "Inserted Article 246A (concurrent taxing powers) and Article 279A (GST Council chaired by Union Finance Minister), creating 'One Nation, One Tax'.", '101वें संशोधन (2016) द्वारा जीएसटी लागू हुआ तथा कर निर्धारण हेतु अनुच्छेद 279क के तहत जीएसटी परिषद (GST Council) बनाई गई।'), ('Who serves as the Chairperson of the Goods and Services Tax (GST) Council under Article 279A?', 'अनुच्छेद 279क के अनुसार जीएसटी परिषद (GST Council) की अध्यक्षता कौन करता है?', 'The Union Finance Minister', 'केंद्रीय वित्त मंत्री (Union Finance Minister)', ['The Prime Minister of India', 'The Governor of Reserve Bank of India', 'The Chairman of the Finance Commission'], ['भारत के प्रधानमंत्री', 'आरबीआई के गवर्नर', 'वित्त आयोग के अध्यक्ष'], 'The Union Finance Minister chairs the GST Council, with State Finance Ministers as voting members.', 'केंद्रीय वित्त मंत्री जीएसटी परिषद के अध्यक्ष होते हैं और राज्यों के वित्त मंत्री इसके सदस्य होते हैं।'), ('Which Constitutional Amendment Act provided 10% reservation in education and public employment for Economically Weaker Sections (EWS)?', 'किस संविधान संशोधन अधिनियम द्वारा सामान्य वर्ग के आर्थिक रूप से कमजोर वर्गों (EWS) को 10% आरक्षण दिया गया?', '103rd Constitutional Amendment Act, 2019', '103वां संविधान संशोधन अधिनियम (2019)', ['102nd Amendment Act, 2018', '104th Amendment Act, 2019', '101st Amendment Act, 2016'], ['102वां संशोधन (2018)', '104वां संशोधन (2019)', '101वां संशोधन (2016)'], 'Inserted Article 15(6) and Article 16(6), providing up to 10% quota for citizens not covered under SC/ST/OBC reservations; upheld by Supreme Court in Janhit Abhiyan (2022).', '103वें संशोधन (2019) ने अनुच्छेद 15(6) और 16(6) जोड़कर सामान्य वर्ग के गरीबों को नौकरियों और शिक्षण संस्थानों में 10% आरक्षण दिया।'), ('Which Constitutional Amendment Act extended SC/ST reservation in Lok Sabha and State Assemblies to 2030, while ending Anglo-Indian nomination?', 'किस संशोधन ने लोकसभा और विधानसभाओं में एससी/एसटी आरक्षण 2030 तक बढ़ाया तथा एंग्लो-इंडियन मनोनयन समाप्त किया?', '104th Constitutional Amendment Act, 2019', '104वां संविधान संशोधन अधिनियम (2019)', ['103rd Amendment Act', '105th Amendment Act', '102nd Amendment Act'], ['103वां संशोधन', '105वां संशोधन', '102वां संशोधन'], 'Amended Article 334, extending SC/ST legislative reservations until 25 January 2030, while allowing Anglo-Indian seats to lapse.', '104वें संशोधन (2019) ने अनुसूचित जातियों व जनजातियों के राजनीतिक आरक्षण को 10 वर्ष आगे बढ़ाया।'), ('The 105th Constitutional Amendment Act, 2021 was enacted to clarify that', '105वां संविधान संशोधन अधिनियम (2021) क्या स्पष्ट करने के लिए पारित किया गया था?', 'State Governments have the constitutional power to identify and maintain their own state lists of Socially and Educationally Backward Classes (SEBCs/OBCs)', 'राज्य सरकारों को अपनी स्वयं की राज्य ओबीसी (SEBC) सूची तैयार करने और जातियों को जोड़ने की शक्ति बनी रहेगी', ['Central government alone can identify OBCs', 'OBC reservation is abolished in municipal elections', 'Creamy layer income ceiling is abolished'], ['केवल केंद्र सरकार ओबीसी पहचान सकती है', 'नगर निगम चुनावों में ओबीसी आरक्षण खत्म', 'क्रीमी लेयर सीमा खत्म'], "Restored states' power to identify OBCs following the Supreme Court's Maratha reservation judgment (Jaishri Laxmanrao Patil case).", 'मराठा आरक्षण फैसले के बाद संसद ने 105वां संशोधन पास कर राज्यों को अपनी ओबीसी सूची बनाने का अधिकार बहाल किया।'), ("The 106th Constitutional Amendment Act, 2023, popularly known as the 'Nari Shakti Vandan Adhiniyam', provides for", "106वां संविधान संशोधन अधिनियम (2023) जिसे 'नारी शक्ति वंदन अधिनियम' कहा गया, क्या प्रावधान करता है?", 'One-Third (33%) reservation for women in the Lok Sabha, State Legislative Assemblies, and Delhi Assembly', 'लोकसभा, राज्य विधानसभाओं तथा दिल्ली विधानसभा में महिलाओं के लिए 33% (एक-तिहाई) आरक्षण', ['50% reservation for women in Central Cabinet', 'Free government transport for women nationwide', 'Equal property inheritance rights in ancestral land'], ['केंद्रीय कैबिनेट में 50% महिला आरक्षण', 'देशभर में महिलाओं को मुफ्त बस यात्रा', 'पैतृक भूमि में समान अधिकार'], 'Inserted Article 330A, 332A, and 239AA(2)(b), reserving 33% seats for women for 15 years, effective after the next delimitation following a census.', '106वें संशोधन द्वारा संसद और विधानसभाओं में महिलाओं के लिए 33% सीटें आरक्षित की गईं (जनगणना और परिसीमन के बाद लागू)।'), ("Which Constitutional Amendment Act is known as the 'Privy Purse Abolition Act' of 1971?", "किस संविधान संशोधन अधिनियम (1971) द्वारा पूर्व देशी रियासतों के राजा-महाराजाओं के 'प्रिवी पर्स' (विशेषाधिकार व भत्ते) समाप्त किए गए थे?", '26th Constitutional Amendment Act, 1971', '26वां संविधान संशोधन अधिनियम (1971)', ['24th Amendment Act, 1971', '25th Amendment Act, 1971', '42nd Amendment Act, 1976'], ['24वां संशोधन (1971)', '25वां संशोधन (1971)', '42वां संशोधन (1976)'], 'Omitted Articles 291 and 362 and inserted Article 363A, terminating all royal privy purses, titles, and privileges of former princely rulers.', 'इंदिरा गांधी सरकार द्वारा 26वें संशोधन (1971) के तहत राजा-महाराजाओं के प्रिवी पर्स और विशेष दर्जे को हमेशा के लिए समाप्त कर दिया गया।'), ('The 86th Constitutional Amendment Act, 2002 made changes in which three parts of the Indian Constitution?', '86वें संविधान संशोधन (2002) ने भारतीय संविधान के किन तीन भागों में एक साथ महत्वपूर्ण बदलाव किए?', 'Part III (Article 21A), Part IV (Article 45), and Part IVA (Article 51A(k))', 'भाग III (अनुच्छेद 21क), भाग IV (अनुच्छेद 45), एवं भाग IVक (अनुच्छेद 51क(ट))', ['Part I, Part II, and Part III', 'Part IV, Part V, and Part VI', 'Part IX, Part IXA, and Part IXB'], ['भाग I, भाग II एवं भाग III', 'भाग IV, भाग V एवं भाग VI', 'भाग IX, भाग IXक एवं भाग IXख'], 'A historic trifecta: created Fundamental Right to education (21A), rephrased DPSP for early childhood (45), and added 11th Fundamental Duty (51A(k)).', '86वें संशोधन ने एक साथ मूल अधिकार (21क), नीति निदेशक तत्व (45), और मूल कर्तव्य (51क) तीनों में शिक्षा संबंधी प्रावधान जोड़े।'), ('Under Article 368, what are the two methods of amendment specified within the article itself?', 'अनुच्छेद 368 के अंतर्गत संशोधन की कौन सी दो विधियां स्वयं उस अनुच्छेद में बताई गई हैं?', 'By Special Majority of Parliament, and by Special Majority of Parliament plus Ratification by half of the States', 'संसद के विशेष बहुमत द्वारा, तथा संसद के विशेष बहुमत एवं आधे राज्यों के विधानमंडलों के अनुसमर्थन द्वारा', ['By simple majority of Parliament, and by presidential decree', 'By national referendum, and by judicial review', 'By Prime Minister order, and by Lok Sabha Speaker'], ['संसद के साधारण बहुमत एवं राष्ट्रपति आदेश से', 'जनमत संग्रह एवं न्यायिक समीक्षा द्वारा', 'प्रधानमंत्री आदेश एवं स्पीकर द्वारा'], 'Article 368 specifically provides for two types: (i) Special Majority of Parliament, and (ii) Special Majority plus ratification by at least half of the state legislatures.', 'अनुच्छेद 368 में संशोधन के दो तरीके हैं: विशेष बहुमत, तथा विशेष बहुमत के साथ कम से कम आधे राज्यों का अनुमोदन।'), ('In Shankari Prasad v. Union of India (1951), the Supreme Court ruled that', 'शंकरी प्रसाद बनाम भारत संघ (1951) में सर्वोच्च न्यायालय ने संसद की संशोधन शक्ति पर क्या निर्णय दिया था?', 'Parliament has the power to amend ANY part of the Constitution, including Fundamental Rights, under Article 368', 'संसद अनुच्छेद 368 के तहत मूल अधिकारों सहित संविधान के किसी भी भाग में संशोधन कर सकती है', ['Fundamental Rights cannot be amended by Parliament', 'Article 368 is unconstitutional', 'Judicial review overrides constitutional amendments'], ['मूल अधिकारों में संसद संशोधन नहीं कर सकती', 'अनुच्छेद 368 असंवैधानिक है', 'न्यायिक समीक्षा संशोधनों से ऊपर है'], "The Supreme Court held that 'law' in Article 13(2) includes only ordinary law, not constituent amendments under Article 368.", 'सुप्रीम कोर्ट ने पहले संशोधन को वैध ठहराते हुए माना कि संसद मूल अधिकारों में भी संशोधन करने की पूरी शक्ति रखती है।'), ('In Golaknath v. State of Punjab (1967), an 11-judge bench overruled earlier rulings and held that', 'गोलकनाथ बनाम पंजाब राज्य (1967) में 11 जजों की पीठ ने अपने पुराने फैसलों को पलटते हुए क्या व्यवस्था दी?', 'Fundamental Rights have a transcendental position and Parliament CANNOT abridge or take away any Fundamental Right under Article 368', 'मूल अधिकार पवित्र एवं अक्षुण्ण हैं तथा संसद अनुच्छेद 368 के तहत किसी भी मूल अधिकार को छीन या कम नहीं कर सकती', ['Parliament has unlimited amending power', 'President can veto constitutional amendments', 'Preamble is not part of the Constitution'], ['संसद के पास असीमित संशोधन शक्ति है', 'राष्ट्रपति संशोधनों को वीटो कर सकते हैं', 'प्रस्तावना संविधान का अंग नहीं है'], "By a 6:5 majority, Chief Justice Subba Rao held that Article 368 merely contained procedure (not power) to amend, and amendments are 'law' under Art 13.", 'गोलकनाथ मामले में 6:5 के बहुमत से सुप्रीम कोर्ट ने संसद द्वारा मूल अधिकारों में कटौती करने पर पूर्ण रोक लगा दी थी।')]

polity_slots = [
    slot_q111_ca,
    slot_q112_preamble,
    slot_q113_fr_part1,
    slot_q114_fr_part2,
    slot_q115_dpsp,
    slot_q116_exec,
    slot_q117_parl,
    slot_q118_jud,
    slot_q119_bodies,
    slot_q120_local_amend,
]

def get_polity_questions(idx):
    # idx: 0 to 47
    qs = []
    for i, slot_pool in enumerate(polity_slots):
        q_num = 111 + i
        item = slot_pool[idx]
        q_en, q_hi, c_en, c_hi, w_en, w_hi, exp_en, exp_hi = item
        ans_idx = (q_num + idx) % 4
        qs.append(make_question(
            q_num, SEC_EN, SEC_HI, U_EN, U_HI,
            q_en, q_hi, c_en, c_hi, w_en, w_hi, exp_en, exp_hi, ans_idx
        ))
    return qs
